      PV(6,14)=ZNO2-1.D0
      PV(5,24)=RMASS(30)
      PV(6,24)=1.D0
      PV(8,24)=30.D0
      PV(5,34)=0.D0
      PV(6,34)=0.D0
      PV(8,34)=1.D0
C
      PV(5,15)=ATOMAS(ATNO2-2.D0,ZNO2-1.D0)
      PV(6,15)=ZNO2-1.D0
      PV(5,25)=RMASS(31)
      PV(6,25)=1.D0
      PV(8,25)=31.D0
      PV(5,35)=0.D0
      PV(6,35)=0.D0
      PV(8,35)=1.D0
C
