      PV(6,19)=ZNO2-2.D0
      PV(5,29)=PV(5,23)
      PV(6,29)=1.D0
      PV(8,29)=14.D0
      PV(5,39)=PV(5,23)
      PV(6,39)=1.D0
      PV(8,39)=14.D0
C
      GOTO 70
   30 PV(5,11)=ATOMAS(ATNO2+1.D0,ZNO2+1.D0)
      PV(6,11)=ZNO2+1.D0
      PV(5,21)=0.D0
      PV(6,21)=0.D0
      PV(8,21)=1.D0
      PV(5,31)=0.D0
      PV(6,31)=0.D0
      PV(8,31)=1.D0
C
      PV(5,12)=ATOMAS(ATNO2   ,ZNO2+1.D0)
      PV(6,12)=ZNO2+1.D0
      PV(5,22)=RMASS(16)
      PV(6,22)=0.D0
      PV(8,22)=16.D0
      PV(5,32)=0.D0
      PV(6,32)=0.D0
      PV(8,32)=1.D0
C
      PV(5,13)=PV(5,2)
      PV(6,13)=PV(6,2)
      PV(5,23)=RMASS(14)
      PV(6,23)=1.D0
      PV(8,23)=14.D0
      PV(5,33)=0.D0
      PV(6,33)=0.D0
      PV(8,33)=1.D0
C
      PV(5,14)=ATOMAS(ATNO2-1.D0,ZNO2   )
      PV(6,14)=ZNO2
      PV(5,24)=RMASS(30)
      PV(6,24)=1.D0
      PV(8,24)=30.D0
      PV(5,34)=0.D0
      PV(6,34)=0.D0
      PV(8,34)=1.D0
C
      PV(5,15)=ATOMAS(ATNO2-2.D0,ZNO2   )
      PV(6,15)=ZNO2
      PV(5,25)=RMASS(31)
      PV(6,25)=1.D0
      PV(8,25)=31.D0
      PV(5,35)=0.D0
      PV(6,35)=0.D0
      PV(8,35)=1.D0
C
      PV(5,16)=ATOMAS(ATNO2-3.D0,ZNO2-1.D0)
      PV(6,16)=ZNO2-1.D0
      PV(5,26)=RMASS(32)
      PV(6,26)=2.D0
      PV(8,26)=32.D0
      PV(5,36)=0.D0
      PV(6,36)=0.D0
      PV(8,36)=1.D0
C
      PV(5,17)=ATOMAS(ATNO2-1.D0,ZNO2+1.D0)
      PV(6,17)=ZNO2+1.D0
      PV(5,27)=PV(5,22)
