      PV(8,27)=16.D0
      PV(5,37)=PV(5,22)
      PV(6,37)=0.D0
      PV(8,37)=16.D0
C
      PV(5,18)=PV(5,14)
      PV(6,18)=PV(6,14)
      PV(5,28)=PV(5,22)
      PV(6,28)=0.D0
      PV(8,28)=16.D0
      PV(5,38)=PV(5,23)
      PV(6,38)=1.D0
      PV(8,38)=14.D0
C
      PV(5,19)=ATOMAS(ATNO2-1.D0,ZNO2-1.D0)
      PV(6,19)=ZNO2-1.D0
      PV(5,29)=PV(5,23)
      PV(6,29)=1.D0
      PV(8,29)=14.D0
      PV(5,39)=PV(5,23)
      PV(6,39)=1.D0
      PV(8,39)=14.D0
