      NOPT=10
      GOTO 70
   40 PV(5,11)=ATOMAS(ATNO2+2.D0,ZNO2+1.D0)
      PV(6,11)=ZNO2+1.D0
      PV(5,21)=0.D0
      PV(6,21)=0.D0
      PV(8,21)=1.D0
      PV(5,31)=0.D0
      PV(6,31)=0.D0
      PV(8,31)=1.D0
C
      PV(5,12)=ATOMAS(ATNO2+1.D0,ZNO2+1.D0)
      PV(6,12)=ZNO2+1.D0
      PV(5,22)=RMASS(16)
