      PV(5,22)=RMASS(16)
      PV(6,22)=0.D0
      PV(8,22)=16.D0
      PV(5,32)=0.D0
      PV(6,32)=0.D0
      PV(8,32)=1.D0
C
      PV(5,13)=ATOMAS(ATNO2+2.D0,ZNO2   )
      PV(6,13)=ZNO2
      PV(5,23)=RMASS(14)
      PV(6,23)=1.D0
      PV(8,23)=14.D0
      PV(5,33)=0.D0
