c-----------------------------------------------------------------------
      subroutine IniFluka
c-----------------------------------------------------------------------
c Primary initialization for FLUKA
c-----------------------------------------------------------------------
#if !__CXCORSIKA__ && !__CORSIKA8__

      INCLUDE '(DBLPRC)'  !
      INCLUDE '(DIMPAR)'  !
      INCLUDE '(IOUNIT)'  !
c      INCLUDE '(FLKCMP)'  !
C      INCLUDE '(FHEAVY)'
C      INCLUDE '(GENSTK)'
      INCLUDE '(FLKAVR)'
c      INCLUDE '(FLKMAT)'  !
C      INCLUDE '(NUCDAT)'
C      INCLUDE '(NUCGEO)'
C      INCLUDE '(PAPROP)'
c      INCLUDE '(PAREVT)'  !
C      INCLUDE '(PART2)'
c      INCLUDE '(PHNCCM)'  !
C      INCLUDE '(RESNUC)'
c      INCLUDE '(CTITLE)'  !
      INTEGER MXCKMT, MXCKEL, NMATFL, NELMFL, MTFLKA, IZELFL,
     &        MXELFL, IFLXYZ
      LOGICAL LPRINT
      DOUBLE PRECISION WFELFL, PPTMAX, EF2DP3, DF2DP3
      CHARACTER CRVRCK*8
*  Maximum number of Fluka materials (change as you wish)
      PARAMETER ( MXCKMT =  5 )
*  Cumulative maximum number of elements in the Fluka materials
      PARAMETER ( MXCKEL = 10 )
      DIMENSION NELMFL (MXCKMT), MTFLKA (MXCKMT), IZELFL (MXCKEL),
     &          WFELFL (MXCKEL)
C  FLUKA 2011.2 BLOCK DATA PROGRAMS
      EXTERNAL BDINPT,BDTRNS,BDHDR1,BDHDR2,BDHDR3,BDPART,BDPRDC,
     &         BDNOPT,BDEVAP,BDPREE

      DIMENSION        WHAT (6)
      DATA             WHAT / 6 * ZERZER /
#endif

c CONEX includes
#include "conex.h"
#include "conex.incnex"
      data init/0/
      save init

      if(init.ge.1)return
      init=init+1
#ifdef __CXDEBUG__
      call utisx1('inifluka  ',4)
      write(*,'(a)')'initialize FLUKA ...'
#endif

#if !__CXCORSIKA__ && !__CORSIKA8__

C open fluka output/error files
      OPEN(UNIT=LUNOUT,FORM='FORMATTED',STATUS='UNKNOWN',
     *     FILE=fnck(1:nfnck-5)//'fkout')
      OPEN(UNIT=LUNERR,FORM='FORMATTED',STATUS='UNKNOWN',
     *     FILE=fnck(1:nfnck-5)//'fkerr')



C  SET UP VARIABLES IN COMMON FLKMAT:
* Define tree materials  (Air is defined as MMAT=3 in FLUKA)
        NMATFL     = 4

*  Air:
        NELMFL (1) = 3
        IZELFL (1) = 7
        IZELFL (2) = 8
        IZELFL (3) =18
*  Weight fractions:
        WFELFL (1) = 0.92561D-03
        WFELFL (2) = 0.28361D-03
        WFELFL (3) = 0.15776D-04

        NELMFL (2) = 1
        IZELFL (4) = 7
*  Weight fraction:
        WFELFL (4) = 1.D+00

        NELMFL (3) = 1
        IZELFL (5) = 8
*  Weight fraction:
        WFELFL (5) = 1.D+00

        NELMFL (4) = 1
        IZELFL (6) = 18
*  Weight fraction:
        WFELFL (6) = 1.D+00

*       Total number of components for all materials:
        MXELFL     = 6
        
C
*  Maximum momentum (GeV/c) for Fluka initializations
      PPTMAX     = 1.D+11
*  Transition energy between Fluka (Peanut) and Dpmjet3 for hA
*  interactions (0 leaves at the Fluka default ~ 10 TeV)
      EF2DP3     = 0.D+00
*  Smearing (GeV/c) of the transition energy between Fluka (Peanut)
*  and Dpmjet3 for hA interactions (-1 leaves at the Fluka default,
*  0 is accepted, as well as positive values)
      DF2DP3     =-1.D+00
*  Iflxyz must be consistent in all calls, to Stpxyz, Sgmxyz, Evtxyz
*    Iflxyz =  1 -> only inelastic
*    Iflxyz = 10 -> only elastic
*    Iflxyz = 11 -> inelastic + elastic
*    Iflxyz =100 -> only emd
*    Iflxyz =101 -> inelastic + emd
*    Iflxyz =110 -> elastic + emd
*    Iflxyz =111 -> inelastic + elastic + emd
      IFLXYZ     = 11
      LPRINT     = .TRUE.
*  Simple check to verify the `right' Fluka is linked:
      ICHECK = NINT ( AMPRMU * 1.D+12 - 1.0072D+12 )
      WRITE ( CRVRCK, '(I8)' ) ICHECK
*  End check
      CALL STPXYZ ( NMATFL, NELMFL, IZELFL, WFELFL, MXELFL,
     &              PPTMAX, EF2DP3, DF2DP3, IFLXYZ, LPRINT,
     &              MTFLKA, CRVRCK )
*  Simple check to verify the `right' Fluka is linked:
      IF ( CRVRCK .NE. CRVRFL )
     &   CALL FLABRT ( 'CORSIKA INI', 'MISMATCHED FLUKA VERSION' )
* End check
      IFLKVER = MJFLVR*100000+MNFLVR*100+MRFLVR
*  Initialization of rm48 is done in start
      WRITE(ifmt,'(A,I10,/)')
     &             ' FLUINI: INITIALIZATION DONE, VERSION:',IFLKVER

#endif


      xsegymin=0.01d0

#ifdef __CXDEBUG__
      call utisx2
#endif
      end

c-----------------------------------------------------------------------
      subroutine IniEvtFlu
c-----------------------------------------------------------------------
c Initialization for each type of event (for given proj, targ and egy)
c-----------------------------------------------------------------------
      implicit double precision (a-h,o-z)
#include "conex.h"
#include "conex.incnex"
      double precision fflucrse


      if(maprojxs.gt.1)
     &  call cxstop('Mass too big for Fluka (Mprj=1) !')
      call cxiclass(idprojxs,iclproxs)
#if !__CXCORSIKA__ && !__CORSIKA8__

      xsbmax=10000.d0
      xsfluincs=fflucrse()
#else
      xsbmax=20d0
      xsfluincs=1d20
#endif

      if(xsekin.lt.xsegymin)xsfluincs=0.          !below egymin, no interaction
c      if(iclproxs.eq.3.and.xsekin.lt.0.1d0)xsfluincs=0.     !elastic event for kaons below 100MeV (problem) !


#ifdef __CXDEBUG__
      if(isx.ge.2)write(ifck,*)
     &  'Fluka used with (Ek,idproj,matarg,xs) ',xsekin,idprojxs
     &                                          ,matargxs,xsfluincs
#endif


      return
      end

c-----------------------------------------------------------------------
      subroutine emsflu(iret)
c-----------------------------------------------------------------------
c  call Fluka to simulate interaction
c-----------------------------------------------------------------------
      INCLUDE '(DBLPRC)'   !
      INCLUDE '(DIMPAR)'   !
C      INCLUDE '(IOUNIT)'
      INCLUDE '(EVTFLG)'
C      INCLUDE '(FLKCMP)'
      INCLUDE '(FHEAVY)'
      INCLUDE '(GENSTK)'   !
C      INCLUDE '(FLKMAT)'
C      INCLUDE '(NUCDAT)'
C      INCLUDE '(PAPROP)'
      INCLUDE '(PAREVT)'   !
      INCLUDE '(PAPROP)'
      INCLUDE '(PART2)'    !
C      INCLUDE '(PHNCCM)'
      INCLUDE '(RESNUC)'    !
      DOUBLE PRECISION CUMSGI, CUMSGE, CUMSGM
      DIMENSION CUMSGI (0:NELEMX), CUMSGE (0:NELEMX), CUMSGM (0:NELEMX)
#include "conex.h"
#include "conex.incnex"
      double precision P0(5),P1,EKIN1,PPROJ,TXX,TYY,TZZ,WEE,POO,PRES(4)
      integer MMAT,idtrafocx

      iret=0
      if(abs(xsfluincs).lt.1d-20)goto 1002   !no interaction
#ifdef __CXDEBUG__
      if(isx.ge.4)call cxalist('Determine FLUKA Production&',0,0,0)
#endif
      nptlxs=0


C  CONVERT PARTICLE TYPE TO FLUKA
      KPROJ  = idtrafocx('nxs','flk',idprojxs)
      EKIN1  = xsekin
C  CALCULATE MOMENTUM PPROJ
      PPROJ = SQRT( EKIN1 * (EKIN1 + 2.D00 * AAM(IPTOKP(KPROJ)) ) )
      LEVFIN = .FALSE.
C  TARGET
      if(latargxs.eq.7)then
        MMAT = 4
      elseif(latargxs.eq.8)then
        MMAT = 5
      elseif(latargxs.eq.18)then
        MMAT = 6
      else
        call cxstop('Wrong mass in air component (FLUKA) !')
      endif
C  USE THE FLUKA-INTERNALLY USED DIRECTION COSINES:
      TXX = 0.D0
      TYY = 0.D0
      TZZ = 1.D0
      WEE = ONEONE
      IJ  = KPROJ
C  CALCULATE THE MOMENTUM WITH FLUKA MASSES
      POO = PPROJ
*  Iflxyz must be consistent in all calls, to Stpxyz, Sgmxyz, Evtxyz
*    Iflxyz =  1 -> only inelastic
*    Iflxyz = 10 -> only elastic
*    Iflxyz = 11 -> inelastic + elastic
*    Iflxyz =100 -> only emd
*    Iflxyz =101 -> inelastic + emd
*    Iflxyz =110 -> elastic + emd
*    Iflxyz =111 -> inelastic + elastic + emd
      IFLXYZ = 11
*  Output variables:
*
*     Cumsgi(i) = cumulative macroscopic inelastic cross section
*                 (cm^2/g x rho) for the i_th element of the mmat
*                 material
*     Cumsge(i) = cumulative macroscopic elastic   cross section
*                 (cm^2/g x rho) for the i_th element of the mmat
*                 material
*     Cumsgm(i) = cumulative macroscopic emd       cross section
*                 (cm^2/g x rho) for the i_th element of the mmat
*                 material
C  NOW INTERACTION IS PERFORMED
      CALL EVTXYZ ( IJ    , MMAT  , EKIN1  , POO   , TXX   , TYY   ,
     &              TZZ   , IFLXYZ, CUMSGI, CUMSGE, CUMSGM )
c      write(ifch,*)'target used',ibtar,ichtar,mmmat,ibres
      
      matargxs=IBTAR    !update mass in case of isotope
      
      ist=1
      call cxconre
      call cxconwr(ist)

      nptlini=nptlxs+1

      if(NP.eq.0.and.NPHEAV.eq.0)goto 1001         !no interaction

      ncolxs=1
      nevtxs=1
      xsbimp=0.d0
      xsphi=0.d0

C  NOW TREAT THE REMAINING TARGET NUCLEUS

#ifdef __CXDEBUG__
      if(isx.ge.5)write(ifck,550)IBRES,ICRES,EKRES 
 550  format('FLUKA: remaining nucleus',/,
     *                        '  mass=',I3,' charge=',I3,
     *                             ' ekin=',g9.2)
#endif
      if(IBRES.gt.1)then

        if(IBRES.gt.matargxs)then
          write(ifck,*)'emsflu:more nucleons in target remnant than '
     *                ,'in target ! ... skip event.'
          goto 1001
        endif
        
        ekin1=EKRES/dble(IBRES)
        PRES(4)=sqrt(PXRES*PXRES+PYRES*PYRES+PZRES*PZRES)
        if(PRES(4).gt.0d0)then
          PRES(3)=PZRES/PRES(4) !Pz
          PRES(2)=PYRES/PRES(4) !Py
          PRES(1)=PXRES/PRES(4) !Px
        elseif(abs(ekin1).lt.1d-6)then
          PRES(3)=0.d0 !Pz
          PRES(2)=0.d0 !Py
          PRES(1)=0.d0 !Px
        else         !ekin and momentum not consistent
          write(*,*)'emsflu: ekin and momentum not consistent !'
     *                ,' ... skip event.'
          goto 1001
        endif

        nptlxs=maprojxs+matargxs+1    !register spectators

        do k=1,IBRES
          
c final particle
          nptlxs=nptlxs-1             !go backwards
          istptlxs(nptlxs)=0
          if(nptlxs.gt.mxptlxs)call cxstop('FlUKA: mxptlxs too small')

          if(k.le.ICRES)then   !protons
            id=1120
            P0(5)=AAM(1)        !Mass
          else                  !neutrons
            id=1220
            P0(5)=AAM(8)        !Mass
          endif
            
          P0(4)=ekin1+P0(5)                   !Energy
          P1=sqrt((P0(4)+P0(5))*(P0(4)-P0(5))) !Momentum
          P0(3)=PRES(3)*P1                      !Pz
          P0(2)=PRES(2)*P1                      !Py
          P0(1)=PRES(1)*P1                      !Px

          call flk2cnx(id,P0,1)

        enddo
      endif

      nptlxs=maprojxs+matargxs

#ifdef __CXDEBUG__
        if(isx.ge.5)write(ifck,'(a,i5)')
     $         ' number of particles from Fluka :',NP
#endif
        do 500 k=1,NP

c LLIST is the code of final particle, P - its 4-momentum and mass.
          ic=KPART(k)
          icm=IPTOKP(ic)          !convert to internal FLUKA ID to use AAM
            
#ifdef __CXDEBUG__
          if(isx.ge.7)write(ifck,'(a,i5,a,i5,2a,5(e11.4,1x))')
     $    ' FLUKA particle ',k,' id :',ic,' before conversion'
     $  , ' Ekin, cos and mass :',TKI(k),CXR(k),CYR(k),CZR(k),AAM(icm)
#endif

          if(ic.le.-3)then      !send He-3 in fragments
            NPHEAV=NPHEAV+1
            if(NPHEAV.gt.MXHEAV)goto 1001   !no room left, skip event
            KHEAVY(NPHEAV)=abs(ic)
            TKHEAV(NPHEAV)=TKI(k)
            CXHEAV(NPHEAV)=CXR(k)
            CYHEAV(NPHEAV)=CYR(k)
            CZHEAV(NPHEAV)=CZR(k)
            goto 500
          endif

c final particle
          nptlxs=nptlxs+1
          istptlxs(nptlxs)=0
          if(nptlxs.gt.mxptlxs)call cxstop( 'FLUKA: mxptlxs too small')


          id=idtrafocx('flk','nxs',ic)
#ifdef __CXDEBUG__
          if(isx.ge.7)write(ifck,'(a,i5,a,i5,a)')
     $         ' CONEX particle ',nptlxs,' id :',id,' after conversion'
#endif
            
          P0(5)=AAM(icm)                         !Mass
          P0(4)=TKI(k)+P0(5)                   !Energy
          P1=sqrt((P0(4)+P0(5))*(P0(4)-P0(5))) !Momentum
          P0(3)=CZR(k)*P1                      !Pz
          P0(2)=CYR(k)*P1                      !Py
          P0(1)=CXR(k)*P1                      !Px

          call flk2cnx(id,P0,0)

 500      continue


C  NOW TREAT THE HEAVY FRAGMENTS

#ifdef __CXDEBUG__
        if(isx.ge.5)write(ifck,'(a,i5)')
     $         ' number of fragments from FLUKA :',NPHEAV
#endif

        do j=1,NPHEAV

c LLIST is the code of final particle, P - its 4-momentum and mass.
         ic=KHEAVY(J)
            
#ifdef __CXDEBUG__
         if(isx.ge.7)write(ifck,'(a,i5,a,i5,2a,4(e11.4,1x))')
     $       ' FLUKA fragment ',j,' id :',ic,' before conversion'
     $     , ' Ekin and cos :',TKHEAV(J),CXHEAV(J),CYHEAV(J),CZHEAV(J)
#endif
         IF ( ic .LE. 0 .OR. ic .gt.12 ) THEN
#ifdef __CXDEBUG__
              if (isx .ge.1)WRITE(*,*)
     *          'emsflu: WRONG FRAGMENT: KHEAVY=',KHEAVY(J)
#endif
           GOTO 1001
         ENDIF
         iz  = ICHEAV(ic)
         ia  = IBHEAV(ic)
         
         ekin1=TKHEAV(J)/dble(ia)
         PRES(3)=CZHEAV(J)      !Pz
         PRES(2)=CYHEAV(J)      !Py
         PRES(1)=CXHEAV(J)      !Px

c         if(ia.eq.2.and.iz.eq.1)then       !deuterium
c           id=17
c           P0(5)=AAM(-3)        !Mass
c           ia=1
c           iz=-1                !no to update the id and the mass in the loop
c         elseif(ia.eq.3.and.iz.eq.1)then   !tritium
c           id=18
c           P0(5)=AAM(-4)        !Mass
c           ia=1
c           iz=-1                !no to update the id and the mass in the loop
c         elseif(ia.eq.4.and.iz.eq.2)then   !helium
c           id=19
c           P0(5)=AAM(-6)        !Mass
c           ia=1
c           iz=-1                !no to update the id and the mass in the loop
c         endif                  !other nucleus

         do k=1,ia
c final particle
          nptlxs=nptlxs+1
          if(k.le.iz)then       !protons
            id=1120
            P0(5)=AAM(1)        !Mass
          elseif(iz.ge.0)then   !neutrons
            id=1220
            P0(5)=AAM(8)        !Mass
          endif
            
          istptlxs(nptlxs)=0
          if(nptlxs.gt.mxptlxs)call cxstop('FLUKA: mxptl too small')


#ifdef __CXDEBUG__
          if(isx.ge.7)write(ifck,'(a,i5,a,i5,a)')
     $         ' CONEX particle ',nptlxs,' id :',id,' after conversion'
#endif
            
          P0(4)=ekin1+P0(5)                    !Energy
          P1=sqrt((P0(4)+P0(5))*(P0(4)-P0(5))) !Momentum
          P0(3)=PRES(3)*P1                      !Pz
          P0(2)=PRES(2)*P1                      !Py
          P0(1)=PRES(1)*P1                      !Px

          call flk2cnx(id,P0,0)
          
         enddo

        enddo

c Decay particles with short life time

      np1=nptlini
41    np2=nptlxs
      do 42 ip=np1,np2
        call cxhdecas(ip,iret)
        if(iret.ne.0)goto 1001
42    continue
      np1=np2+1
      if(np1.le.nptlxs)goto 41


1000  return

1001  iret=1 
      goto 1000 

 1002 iret=-1     !elastic
      goto 1000 

      end

c------------------------------------------------------------------------------
      subroutine flk2cnx(id,P0,ir)
c------------------------------------------------------------------------------
c fill EPOS stack with particle from FLUKA
c P0 particle momentum
c id of particle
c ir =1 for remnant
c------------------------------------------------------------------------------
#include "conex.h"
#include "conex.incnex"
      double precision P0(5)

      xsptl(1,nptlxs)=P0(1)  !P_x
      xsptl(2,nptlxs)=P0(2)  !P_y
      xsptl(3,nptlxs)=P0(3)  !P_z
      xsptl(4,nptlxs)=P0(4)  !E
      xsptl(5,nptlxs)=P0(5)  !mass
      ityptlxs(nptlxs)=0
      if(ir.eq.0)then
        iorptlxs(nptlxs)=1
        jorptlxs(nptlxs)=maprojxs+matargxs
      else
        iorptlxs(nptlxs)=-1
        jorptlxs(nptlxs)=0
      endif
      ifrptlxs(1,nptlxs)=0
      ifrptlxs(2,nptlxs)=0
      xsorptl(1,nptlxs)=0.d0
      xsorptl(2,nptlxs)=0.d0
      xsorptl(3,nptlxs)=0.d0
      xsorptl(4,nptlxs)=0.d0
      xstivptl(1,nptlxs)=0.
      xstivptl(2,nptlxs)=0.
      idptlxs(nptlxs)=id
          
c Put particle in cms frame.
c      call cxutlob5(xsyhaha, xsptl(1,nptlxs), xsptl(2,nptlxs)
c     *, xsptl(3,nptlxs), xsptl(4,nptlxs), xsptl(5,nptlxs))
            
#ifdef __CXDEBUG__
      if(isx.ge.5)write(ifck,'(a,i5,a,i5,a,4(e11.4,1x),f6.3)')
     $         ' particle from FLUKA ',nptlxs,' id :',idptlxs(nptlxs)
     $         , ' momentum :',(xsptl(i,nptlxs),i=1,5)
#endif

      return
      end

c------------------------------------------------------------------------------
      double precision function fflucrse()
c------------------------------------------------------------------------------
c hadron-proton particle production cross section with Fluka.
c ekin0 - kinetic energy
c plab0 - particle momentum
c------------------------------------------------------------------------------
#include "conex.incnex"
      double precision EKIN1,PPROJ,SIGREA,SGMXYZ
C-----------------------------------------------------------------------

C  CONVERT PARTICLE TYPE TO FLUKA
      KPROJ  = idtrafocx('nxs','flk',idprojxs)
      EKIN1  = xsekin
      PPROJ = xspnll
C  MATERIAL NUMBER 1 IS CURRENT MATERIAL
      MMAT  = 3
C  GET THE CROSS SECTION: SIGREA IS MICROSCOPIC CROSS SECTION (MB)
C  ZLDUM IS MACROSCOPIC CROSS SECTION (CM^-1)
*  Get the cross section: sigrea is microscopic cross section (mb)
*  Iflxyz must be consistent in all calls, to Stpxyz, Sgmxyz, Evtxyz
*    Iflxyz =  1 -> only inelastic
*    Iflxyz = 10 -> only elastic
*    Iflxyz = 11 -> inelastic + elastic
*    Iflxyz =100 -> only emd
*    Iflxyz =101 -> inelastic + emd
*    Iflxyz =110 -> elastic + emd
*    Iflxyz =111 -> inelastic + elastic + emd
      IFLXYZ = 11
      SIGREA = SGMXYZ ( KPROJ, MMAT, EKIN1, PPROJ, IFLXYZ )
      fflucrse= SIGREA

      return
      end



c------------------------------------------------------------------------------
      double precision function flucrse(ek,mapro,matar,id)
c------------------------------------------------------------------------------
c inelastic cross section of FLUKA
c if id=0, target = air
c ek - kinetic energy in GeV
c maproj - projec mass number     (1<maproj<64)
c matarg - projec mass number
c id - target id (0=air)
c------------------------------------------------------------------------------
      implicit none
#include "conex.h"
#include "conex.incnex"
      double precision ek,SINE,AMPRO,AMTAR
      integer lapro,latar,mapro,matar,id,mt,lt,k,IFLXYZ,MMAT,KPROJ
     .,idtrafocx
      double precision EKIN1,PPROJ,SIGREA,SGMXYZ
      logical ldpm
      flucrse=0d0
      lapro=max(1,mapro/2)
      latar=max(1,matar/2)
      if(mapro.gt.1.and.id.eq.0)then
        do k=1,3
          mt=int(aira(k))
          lt=max(1,mt/2)
          call SIGIAA(lapro,mapro,AMPRO,lt,mt,AMTAR,ek,SINE,ldpm)
          flucrse=flucrse+airw(k)*SINE
        enddo
      elseif(mapro.gt.1.and.matar.gt.1)then
        call SIGIAA(lapro,mapro,AMPRO,latar,matar,AMTAR,ek,SINE
     .      ,ldpm)
        flucrse=SINE
      else
C  CONVERT PARTICLE TYPE TO FLUKA
        KPROJ  = idtrafocx('nxs','flk',idprojxs)
        EKIN1  = ek
        PPROJ = sqrt(max(0.d0,ek*(ek+2d0*xsamproj)))
C MATERIAL NUMBER 1 IS CURRENT MATERIAL
        if(id.eq.0)then
          MMAT  = 3             !for air
        elseif(matar.eq.14)then
          MMAT  = 4             !nitrogen
        elseif(matar.eq.8)then
          MMAT  = 5             !oxygen
        elseif(matar.eq.40)then
          MMAT  = 6             !argon
        else
          call cxstop( "Material not defined for FLUKA")
        endif
          
*  Get the cross section: sigrea is microscopic cross section (mb)
*  Iflxyz must be consistent in all calls, to Stpxyz, Sgmxyz, Evtxyz
*    Iflxyz =  1 -> only inelastic
*    Iflxyz = 10 -> only elastic
*    Iflxyz = 11 -> inelastic + elastic
*    Iflxyz =100 -> only emd
*    Iflxyz =101 -> inelastic + emd
*    Iflxyz =110 -> elastic + emd
*    Iflxyz =111 -> inelastic + elastic + emd
        IFLXYZ = 11
        SIGREA = SGMXYZ ( KPROJ, MMAT, EKIN1, PPROJ, IFLXYZ )
        flucrse=SIGREA
      endif
      return
      end

#if !__CXCORSIKA__ && !__CORSIKA8__

C=======================================================================

      DOUBLE PRECISION FUNCTION FLRNDM()

C-----------------------------------------------------------------------
C  FL(UKA) R(A)ND(O)M (GENERATOR)
C  THIS FUNCTON IS CALLED FROM FLUKA ROUTINES.
C-----------------------------------------------------------------------
      double precision dum,drangen
      flrndm=drangen(dum)

      RETURN
      END
 
