     +  .222D-03,.210D-03,.187D-03 /
      DATA (A(I, 1,10),I=1,10)  / 
     +  .000D+00,.000D+00,.000D+00,.235D-03,.222D-03,.172D-03,.181D-03,
     +  .166D-03,.152D-03,.124D-03 /
      DATA (A(I, 1,11),I=1,10)  / 
