      irecty(4,2)=4
      irecty(5,2)=5
      irecty(6,2)=6
      irecty(7,2)=7
      irecty(8,2)=8
      irecty(9,2)=9
      irecty(10,2)=10
      irecty(11,2)=11
      irecty(12,2)=12
      irecty(13,2)=13
      irecty(14,2)=14

c root

      ifillTree=0 !fill root tree
      iextree=1 !consider tree extensions up to iextree (0 for original format)
      ifemto=0 !analyse root tree (femto)
      ivmd=0   !analyse root tree (vmd)
      idih=0   !analyse root tree (dih)
      mixevt=5
      ifillH2=0 !fill 2d histo
      igrTree=0
      muTree=0

c  other

      gaumx=8    !range for gauss distribution
      nclean=2   !clean /cptl/ if nclean > 0
                 !(not for part with istptl<istmax if nclean=1 (do not change analysis)
                 !not for part with istptl<1 if nclean=2 (do not change decay history)
                 ! for all part with ist.ne.0 if nclean > 2 (particle nb reduce at max))
      istore=0   !0: no storage to data-file
                 !-1: epos full info (fixed format)
                 !1: epos     standard
                 !2: OSC1997A standart
                 !3: OSC1999A standart
                 !4: Les Houches Event Format (LHEF) standart
                 !5: calls routine ustore (modifiable by the user)
      ioidch=1   !id choice for storage to data-file
      iframe=0   !frame specification production run
      jframe=0   !frame specification analysis
      kframe=0   !frame specification analysis (2nd frame)
                 ! 1:total
                 !11:nucleon-nucleon
                 !12:target
                 !21:gamma-nucleon
                 !22:lab
                 !32:sphericity
                 !33:thrust
      irescl=1   !momentum rescaling (1) or not (0)
      ifrade=1   !suppression of fragmentation and decay (0)
      idecay=1   !suppression of decay (0)
      ihdecay=1  !suppression of decay after hadr casc (0)
      jdecay=1   !suppression of cluster decay (0), concerns only ity=60 cluster
      iremn=2    !suppression of multiquark remnant (0) (string end with same flavor) -> reduce remnant excitation and suppress droplet prod. in remnant
                 !or full multiquark remnant (no limitations) (1)
                 !or multiquark remnant with valence quark conservation and inelastic remnant as low mass droplet only (2)
                 !or suppression of multiquark remnant with different string end flavors (3)
      ntrymx=10  !try-again parameter
      istmax=1   !analyse only istptl <= istmax
      istfor=-999 !analyse  forcing ist
      irdmpr=0   !random sign for projectile if 1
      ilprtg=1   !consider leading particle in projectile (1)
                 !or target  (-1) side

      ireadfzo=0
      gbyjmax=0
      qtl=0

      
c  constants

      pi=3.1415927
      pii=1./(2*pi**2)
      hquer=0.197327
      prom=.94
      piom=.14
      ainfin=1e31

c air

      airanxs(1)=14.007
      airznxs(1)=7.
      airwnxs(1)=0.781
      airanxs(2)=15.999
      airznxs(2)=8.
      airwnxs(2)=.21
      airanxs(3)=39.948
      airznxs(3)=18.
      airwnxs(3)=0.009
      airavanxs=airanxs(1)*airwnxs(1)+airanxs(2)*airwnxs(2)
     &         +airanxs(3)*airwnxs(3)
      airavznxs=airznxs(1)*airwnxs(1)+airznxs(2)*airwnxs(2)
     &         +airznxs(3)*airwnxs(3)

c  zero initializations

      jselect=0  
      kselect=0  
      fxsplit=1.
      idooptns=0
      ibeginwrite=0
      macrocurrent=0
      macrocurrentline=0
      macronr=0
c      facpos(1)=1
c      facpos(2)=1
      iSwitchSides=0
      nacc=0
      nrej=0
      ktnbod=-1
c      do i=1,mamx
c      jproj(1,i)=0
c      jtarg(1,i)=0
c      jproj(2,i)=0
c      jtarg(2,i)=0
c      enddo
      do i=1,8
      hdtext(i)='                              '
      enddo
      gefac=1
      istatom=0
      nbarray=0
      nfifac=1
c      do npom=1,mxxpom
c      nfillt(npom)=0
c      enddo
      iexhd=0
      icc20=0
      mcentr=0
      mmxcentr=0
      esollxx=-1
      ranphi=0
      jjeos=0
      jjtb=1
      irootcproot=0
      iboein=0
      ieof=0
      isyst=0
      ihyskip=0
      istateos=0
      istatptl=0
      nofreeze=0
      do i=1,100
      zclass(1,i)=0.
      zclass(2,i)=0.
      zclass(3,i)=0.
      zclass(4,i)=-1.
      zclass(5,i)=-1.
      enddo
      kexit=0
      do i=0,100
      zlimit(i)=0
      enddo
      do i=1,mrclass
      nrclass(i)=0
      enddo
      iopcnt=0
      ncenthy=0
      ixgeometry=0
      ixbDens=0
      ixtau=0
      iEmsB=0
      iEmsBg=0
      iEmsPm=0
      iEmsPx=0
      iEmsPDF=0
      iEmsSe=0
      iEmsDr=0
      iEmsRx=0
      iEmsI2=0
      iEmsI1=0
      iSpaceTime=0
      nemsi=0
      facmss=1.
      nstmax=0
      do 6 i=1,99
      prob(i)=0
      do 6 j=1,2
      icbac(i,j)=0
6     icfor(i,j)=0
      imsg=0
      do j=1,mxjerr
       jerr(j)=0
      enddo
      ntevt=0
      nrevt=0
      naevt=0
      nrstr=0
      nrptl=0
      nptlu=0
      do itau=1,mxtau
      volsum(itau)=0
      vo2sum(itau)=0
      nclsum(itau)=0
      do ivol=1,mxvol
      do ieps=1,mxeps
      clust(itau,ivol,ieps)=0
      enddo
      enddo
      enddo
      iutotc=0
      iutote=0
      nopen=0
      nopenr=0
      knxopen=0
      kchopen=0
      khiopen=0
      kdtopen=0
      klgopen=0
      ifdat=0
      ifncs=0
      xpar1=0.
      xpar2=0.
      xpar3=0.
      xpar4=0.
      xpar5=0.
      xpar6=0.
      xpar7=0.
      xpar8=0.
      xpar9=0.
      xpar10=0.
      xpar11=0.
      xpar12=0.
      xpar13=0.
      xpar14=0.
      xpar15=0.
      xpar16=0.
      xpar17=0.
      xpar98=0.
      xpar99=0.
      if(iop.eq.0)khisto=0
      nrclu=0
      nrnody=0
      do n=1,mxnody
      nody(n)=0
      enddo
      nrpri=0
      ctaumin=-1.
      do n=1,mxpri
      subpri(n)='      '
      ishpri(n)=0
      enddo
      nctcor=0
      ncttim=0
      do n=1,matau
      tauv(n)=0
      enddo
      ncnt=0
      nrnucl(1)=0
      nrnucl(2)=0
      do i=1,mxnucl
      rnucl(i,1)=0
      rnucl(i,2)=0
      rnuclo(i,1)=0
      rnuclo(i,2)=0
      bnucl(i,1)=0
      bnucl(i,2)=0
