        pptl(4,nptl)=sqrt(pptl(3,nptl)**2+pptl(2,nptl)**2
     $       +pptl(1,nptl)**2)
        do k=1,4
          psum(k)=psum(k)+pptl(k,nptl)
        enddo
      endif
      goto 10
