c      taumax=tauhoc(ncentr,ntauhu(ncentr,meta))+2
cc      netahyxx=netahy
c      write(ifhi,'(a)')    '!----------------------------------------'
c      write(ifhi,'(a,i3)') '!     hydro freeze out rad velocity      '
c      write(ifhi,'(a)')    '!----------------------------------------'
c      write(ifhi,'(a)')    '!newpage'
c      do ii=1,3
c        if(ii.eq.1)nphi=2
c        if(ii.eq.2)nphi=1+nphihy/4
c        if(ii.eq.3)nphi=1+nphihy/2
c        write(ifhi,'(a,3i1)')'openhisto htyp lin name y-',meta,nphi,ii
