c-----------------------------------------------------------------------
      subroutine fstrwr(j,ii,jj,k,n)
c-----------------------------------------------------------------------
c take pstg(5,j),pend(4,ii),idend(ii),pend(4,jj),idend(jj)  (/cems/)
c and write it to /cptl/
c-----------------------------------------------------------------------
c  j:     string 1 or 2
c  ii,jj: string end (1,2: proj; 3,4: targ)
c  k:     current collision
c  n:     current pomeron
c-----------------------------------------------------------------------

      include 'epos.inc'
      include 'epos.incems'

      double precision pstg,pend,ptt3!,utpcmd
      common/cems/pstg(5,2),pend(4,4),idend(4)
      common/emsptl/nppr(npommx,kollmx),npproj(mamx),nptarg(mamx)
      double precision  pp(4)
      common/cts/its

      call utpri('fstrwr',ish,ishini,7)

      if(idend(ii).ne.0.and.idend(jj).ne.0)then

        ip=iproj(k)
        it=itarg(k)
        am1=0.
        am2=0.
        ptt3=0.5d0*pstg(5,j)

       call utlob2(1,pstg(1,j),pstg(2,j),pstg(3,j),pstg(4,j),pstg(5,j)
     * ,pend(1,ii),pend(2,ii),pend(3,ii),pend(4,ii),20)
       pp(1)=0d0
       pp(2)=0d0
       pp(3)=ptt3!.5d0*pstg(5,j)
       pp(4)=sqrt(ptt3*ptt3+dble(am1*am1))!.5d0*pstg(5,j)
       call utrot2
     * (-1,pend(1,ii),pend(2,ii),pend(3,ii),pp(1),pp(2),pp(3))
       call utlob2(-1,pstg(1,j),pstg(2,j),pstg(3,j),pstg(4,j),pstg(5,j)
     * ,pp(1),pp(2),pp(3),pp(4),21)

       npom=nppr(n,k)
       if(ifrptl(1,npom).eq.0)ifrptl(1,npom)=nptl+1
       ifrptl(2,npom)=nptl+2
       istptl(npom)=31

       nptl=nptl+1
       pptl(1,nptl)=sngl(pp(1))
       pptl(2,nptl)=sngl(pp(2))
       pptl(3,nptl)=sngl(pp(3))
       pptl(4,nptl)=sngl(pp(4))
       pptl(5,nptl)=am1 !0.
       istptl(nptl)=20
       iorptl(nptl)=npom
       jorptl(nptl)=0
       ifrptl(1,nptl)=0
       ifrptl(2,nptl)=0
       xorptl(1,nptl)=coordpr(1,n,k)
       xorptl(2,nptl)=coordpr(2,n,k)
       xorptl(3,nptl)=coord(3,k)
       xorptl(4,nptl)=coord(4,k)
       tivptl(1,nptl)=xorptl(4,nptl)
       tivptl(2,nptl)=xorptl(4,nptl)
       idptl(nptl)=idend(ii)
       ityptl(nptl)=ityptl(npom)+j
       itsptl(nptl)=its
       rinptl(nptl)=-9999
       qsqptl(nptl)=pstg(4,j)**2
       zpaptl(1,nptl)=0.
       zpaptl(2,nptl)=0.5*(xkolhp(ip)+xkolht(it))

       nptl=nptl+1
       do i=1,4
        pptl(i,nptl)=sngl(pstg(i,j))-pptl(i,nptl-1)
       enddo
       pptl(5,nptl)=am2!0.

       istptl(nptl)=20
       iorptl(nptl)=nppr(n,k)
       jorptl(nptl)=0
       ifrptl(1,nptl)=0
       ifrptl(2,nptl)=0
       xorptl(1,nptl)=coordpr(1,n,k)
       xorptl(2,nptl)=coordpr(2,n,k)
       xorptl(3,nptl)=coord(3,k)
       xorptl(4,nptl)=coord(4,k)
       tivptl(1,nptl)=xorptl(4,nptl)
       tivptl(2,nptl)=xorptl(4,nptl)
       idptl(nptl)=idend(jj)
       ityptl(nptl)=ityptl(npom)+j
       itsptl(nptl)=its
       rinptl(nptl)=-9999
       qsqptl(nptl)=pstg(4,j)**2
       zpaptl(1,nptl)=0.
       zpaptl(2,nptl)=0.5*(xkolhp(ip)+xkolht(it))

       if(ish.ge.7)then
        write(ifch,100)' kink:',(pptl(l,nptl-1),l=1,4),idptl(nptl-1)
        write(ifch,100)' kink:',(pptl(l,nptl),l=1,4),idptl(nptl)
       endif

      elseif(idend(ii).ne.0.and.idend(jj).eq.0)then

c resonance

       npom=nppr(n,k)
       if(ifrptl(1,npom).eq.0)ifrptl(1,npom)=nptl+1
       ifrptl(2,npom)=nptl+1
       istptl(npom)=31

       nptl=nptl+1
       idptl(nptl)=idend(ii)
       pptl(1,nptl)=sngl(pstg(1,j))
       pptl(2,nptl)=sngl(pstg(2,j))
       pptl(3,nptl)=sngl(pstg(3,j))
       pptl(4,nptl)=sngl(pstg(4,j))
       pptl(5,nptl)=sngl(pstg(5,j))
       istptl(nptl)=0
       iorptl(nptl)=npom
       jorptl(nptl)=0
       ifrptl(1,nptl)=0
       ifrptl(2,nptl)=0
       xorptl(1,nptl)=coordpr(1,n,k)
       xorptl(2,nptl)=coordpr(2,n,k)
       xorptl(3,nptl)=coord(3,k)
       xorptl(4,nptl)=coord(4,k)
       tivptl(1,nptl)=coord(4,k)
       call idtau(idptl(nptl),pptl(4,nptl),pptl(5,nptl),taugm)
       tivptl(2,nptl)=tivptl(1,nptl)+taugm*(-alog(rangen()))
       ityptl(nptl)=ityptl(npom)+2+j
       itsptl(nptl)=its
       rinptl(nptl)=-9999
       qsqptl(nptl)=0.
       zpaptl(1,nptl)=0.
       zpaptl(2,nptl)=0.

       if(ish.ge.7)then
        write(ifch,100)'  res:',(pptl(l,nptl),l=1,4),idptl(nptl)
       endif
      elseif(idend(ii).eq.0.and.idend(jj).eq.0)then
       goto1000
      else
       call utstop('error in fstrwr&')
      endif

  100 format(a,4e9.3,i5)

1000  continue
      call utprix('fstrwr',ish,ishini,7)
      return
      end

c-----------------------------------------------------------------------
      subroutine ProReF(ir,m,iretxx)
c-----------------------------------------------------------------------
c  proposes flavor for remnant m for proj (ir=1) or target (ir=-1)
c  and writes remnant into /cptl/ as string or hadron
c   ityptl definitions:
c      51  41  ...  rmn drop
c      52  42  ...  rmn str inel
c      53  43  ...  rmn str diff
c      54  44  ...  rmn str inel with split (or after droplet or hadron split)
c      55  45  ...  rmn res
c      56  46  ...  low mass diff
c      57  47  ...  rmn res active spectators
c      58  48  ...  rmn res from diff
c      59  49  ...  hadron split
c-----------------------------------------------------------------------

      include 'epos.inc'
      include 'epos.incems'
      include 'epos.incsem'

      double precision plc,s   ,ptt1,ptt2,ptt3
      common/cems5/plc,s
      double precision tpro,zpro,ttar,ztar,ttaus,detap,detat
      common/cttaus/tpro,zpro,ttar,ztar,ttaus,detap,detat
      double precision amasmin,amasini,xmdrmax,xmdrmin!,utpcmd
      integer icf(2),icb(2)
      integer jcf(nflav,2),jcval(nflav,2)!,jcdummy(nflav,2)
      logical gdrop, ghadr,gproj,gdiq
      double precision ept(5),ep(4),aa(5),am2t,piq1,piq2,piq3
      common/emsptl/nppr(npommx,kollmx),npproj(mamx),nptarg(mamx)
      common/remn5/zzdrop(mamx,2)
      character c*1,c1*1,c2*1

      call utpri('ProReF',ish,ishini,3)

      iretxx=0

      if(ir.ne.1.and.ir.ne.-1)stop'ProReF: wrong ir'

      irmdropx=irmdrop
 55   idrop=0
      gdrop=.false.
      ghadr=.false.
      iret=0
      dens=epscri(1) !0.0765
      do j=1,2
        do i=1,nflav
          jcf(i,j)=0
        enddo
      enddo

      flow=ainfin                   !to force not to decay here
      mm=0
      if(ir.eq.1)then
c        if(kolp(m).le.0)goto1000
        if(iep(m).le.-1)goto1000
        gproj=.true.
        mm=npproj(m)
        iept=iep(m)
        zz=zzremn(m,1)
        zd=zzdrop(m,1)
        iclpt=iclpro
        isopt=isoproj
        if(iremn.ge.2)then         !number of valence quarks still in proj
          do nnn=1,nrflav
            jcval(nnn,1)=jcpval(nnn,1,m)
            jcval(nnn,2)=jcpval(nnn,2,m)
          enddo
          do nnn=nrflav+1,nflav
            jcval(nnn,1)=0
            jcval(nnn,2)=0
          enddo
        else
          do nnn=1,nflav
            jcval(nnn,1)=0
          enddo
          do nnn=1,nflav
            jcval(nnn,2)=0
          enddo
        endif
      elseif(ir.eq.-1)then
c        if(kolt(m).le.0)goto1000
        if(iet(m).le.-1)goto1000
        gproj=.false.
        mm=nptarg(m)
        iept=iet(m)
        zz=zzremn(m,2)
        zd=zzdrop(m,2)
        iclpt=icltar
        isopt=isotarg
        if(iremn.ge.2)then         !number of valence quarks still in proj
          do nnn=1,nrflav
            jcval(nnn,1)=jctval(nnn,1,m)
            jcval(nnn,2)=jctval(nnn,2,m)
          enddo
          do nnn=nrflav+1,nflav
            jcval(nnn,1)=0
            jcval(nnn,2)=0
          enddo
        else
          do nnn=1,nflav
            jcval(nnn,1)=0
          enddo
          do nnn=1,nflav
            jcval(nnn,2)=0
          enddo
        endif
      else
        call utstop('ProReF: ir ???&')
      endif
      gdiq=iept.eq.5            !qq-aqaq string from empty remnant (to have baryons instead of mesons from droplet (not fast meson in LHCf data)
      if(ish.ge.3)
     &write(ifch,*)'remnant particle index:',mm,m,iclpt,isopt

      if(ish.ge.10)call alist('ProRef&',1,nptl)
      antotre=antotre+1.

      mmini=mm
      nptlini=nptl
      minfra=min(minfra,nptlini)   !for trigger condition

      do l=1,5
       ept(l)=dble(pptl(l,mm))
      enddo

      ifrptl(1,mm)=0
      ifrptl(2,mm)=0

c  initialize forward and backward ic (to transform remnant into string)

      if(gproj)then
        icf(1)=icproj(1,m)
        icf(2)=icproj(2,m)
        if(icf(1).eq.999999)then    !more than 9 quark : use jcpref
          do j=1,2
            do i=1,nrflav
              jcf(i,j)=jcpref(i,j,m)
            enddo
          enddo
        else
          call iddeco(icf,jcf)
        endif
      else                     !gtarg
        icf(1)=ictarg(1,m)
        icf(2)=ictarg(2,m)
        if(icf(1).eq.999999)then    !more than 9 quark : use jctref
          do j=1,2
            do i=1,nrflav
              jcf(i,j)=jctref(i,j,m)
            enddo
          enddo
        else
          call iddeco(icf,jcf)
        endif
      endif
      icb(1)=0
      icb(2)=0

      call idquacjc(jcf,nqu,naq)
c use RemoveHadron if too many c quarks
      if(nrflav.gt.3)then
        nqc=jcf(4,1)+jcf(4,2)
        if(.not.gdiq.and.(nqu.lt.3.and.jcf(4,1).gt.1.or.
     &     naq.lt.3.and.jcf(4,2).gt.1.or.
     &             jcf(4,1)*jcf(4,2).gt.1))nqc=4
      else
        nqc=0
      endif
      if(iremn.ge.2)then
        ier=0
        ires=0
        id=idtra(icf,ier,ires,0)
        if(ier.eq.0)then
          call idspin(id,ispin,jspin,istra)
        else
          ispin=0
          jspin=0
          istra=0
        endif
      endif

c define masses

      amasmin=dble(fremnux(jcf))**2.d0
      if(ept(5).le.0.d0)then
        ept(5)=dble(fremnux(jcf)*(1.+rangen()))
        if(ish.ge.2)then
          call utmsg('ProReF&')
          write(ifch,*)'zero remnant mass -> amasmin'
          call utmsgf
        endif
      endif
      am2t=sqrt(ept(1)**2+ept(2)**2+ept(5)**2)
      if(iLHC.eq.1.and.ept(4).gt.am2t.and.(iept.eq.0.or.iept.eq.6))then
        ept(3)=sign(sqrt((ept(4)+am2t)*(ept(4)-am2t)),ept(3))
      else
        ept(4)=sqrt(ept(3)*ept(3)+ept(2)*ept(2)+ept(1)*ept(1)
     &           +ept(5)*ept(5))
      endif
      am2t=(ept(4)+ept(3))*(ept(4)-ept(3))-(ept(1)**2+ept(2)**2)
      if(ish.ge.2
     &   .and.(am2t.lt.-1d0.or.abs(am2t-ept(5)*ept(5)).gt.ept(5)))then
          write(ifch,*)'Precision problem in ProRef, p:',
     &             (ept(k),k=1,4),ept(5)*ept(5),am2t
      endif

      if(ish.ge.3)then
        if(gproj)then
            write(ifch,'(a,5e11.3,2i7)')' proj:'
     &      ,(sngl(ept(k)) ,k=1,5),(icproj(k,m) ,k=1,2)
        else    !gtarg
           write(ifch,'(a,5e11.3,2i7)')' targ:'
     &      ,(sngl(ept(k)) ,k=1,5),(ictarg(k,m),k=1,2)
         endif
      endif

      amasini=ept(5)*ept(5)

c     QGP ???????????
c      xmdrmin=dble(fremnux(jcf)/min(1.,max(0.0001,zd**2*0.02))
      xmdrmin=dble(fremnux(jcf)
     &     +amdrmin)**2
      
c      xmdrmax=dble(min(1000.,(fremnux(jcf)+amdrmax)*max(0.,zd)))**2
c      xmdrmax=dble(fremnux(jcf)+2.*amdrmin)**2 !for droplets, large masses are not good for eta distributions (too narrow)
      xmdrmax=dble(fremnux(jcf)+amdrmax)**2 !for droplets, large masses are not good for eta distributions (too narrow)
c      if(ioclude.eq.3)xmdrmax=min(xmdrmax,1d4)

      if(ish.ge.4)write(ifch,*)
c      print *,
     &  'remnant masses:',am2t,amasini,amasmin
     &                   ,sqrt(xmdrmin),sqrt(xmdrmax),zz,zd,iept

c.............................exotic ...................................

c      if(amasini.gt.amasmin.and.irmdropx.eq.1)then

c      if(.not.((nqu.eq.3.and.naq.eq.0).or.(nqu.eq.0.and.naq.eq.3)
      if((iept.eq.3.or. !include diffractive remnants !
c     &   (iept.eq.1.and.iremn.eq.3!.and.amasini.le.xmdrmin
c     &    .and.(jcf(4,1)+jcf(4,2).eq.0)).or.
     &   .not.((nqu.eq.3.and.naq.eq.0).or.(nqu.eq.0.and.naq.eq.3)
     &           .or.(nqu.eq.1.and.naq.eq.1))).and.nqc.le.3
     &     .and.amasini.gt.amasmin.and.irmdropx.eq.1.and..not.gdiq)then

c      if((
c     &   .not.((nqu.eq.3.and.naq.eq.0).or.(nqu.eq.0.and.naq.eq.3)
c     &           .or.(nqu.eq.1.and.naq.eq.1)).or.
c     &   (iept.ne.0.and.iept.le.2.and.reminv/ept(5).gt.rangen()))
c     &    .and.amasini.gt.amasmin.and.irmdropx.eq.1)then

         !print*,'-------------------------------------------' !!!
         !print*,jcf
         !print*,icf,sqrt(amasini),sqrt(amasmin),sqrt(xmdrmin)  !!!
         !print*,nqu,naq                                      !!!
c charm not possible in droplet
        if((nqu.eq.3.and.naq.eq.0).or.(nqu.eq.0.and.naq.eq.3)
     &           .or.(nqu.eq.1.and.naq.eq.1))then
          if(amasini.le.xmdrmin.or.iorsdf.ne.3
     &       .or.iept.eq.0.or.iept.eq.4.or.iept.eq.6)then
            goto 500
c          elseif(amasini.ge.xmdrmin.and.iept.le.2)then
c            goto 500
          endif
        endif

        if(iremn.ge.2.and.
     &     (amasini.gt.xmdrmax.or.nqc.ne.0))then
          if(iremn.eq.2)then
         call getdropx(ir,iept,m,icf,jcf,jcval,zz,ept,aa
     &                                          ,gdrop,xmdrmax)
          else
         call getdroplet(ir,iept,icf,jcf,zz,ept,aa,gdrop,xmdrmax)
          endif
          !--------------------------------
          !emit a droplet, update the remnant string flavor and 5-momentum
          ! input
          !     ir ......... 1  projectile, -1  target remnant
          !     ept ........ remnant  5-momentum
          !     jcf ........ remnant jc
          ! output
          !     gdrop ...  .true. = successful droplet emission
          !                          jcf, ept ....... droplet  ic and 5-momentum
          !                          icf, a ......... remnant string jc and 5-momentum
          !               .false. = unsuccessful
          !                          jcf, ept .... unchanged,
          !                          emits hadrons instead of droplet
c         !                          considered as droplet jc and 5-momentum
          !-------------------------------------
        endif

c redefine energy and charm quarks in droplet
        amasini=ept(5)*ept(5)
        nqc=jcf(4,1)+jcf(4,2)
c use remove hadrons if droplet too heavy (should not happen) or charm
c        if(amasini.gt.1e4.or.nqc.ne.0)goto 500
        if(nqc.ne.0)goto 500

        !...........droplet
        !also in case of unsuccessful drop emission, then remnant = droplet !
        idrop=1
        nptl=nptl+1
        t=xorptl(4,mm)
        istptl(mm)=41
        ifrptl(1,mm)=nptl
        ifrptl(2,mm)=nptl
        tivptl(2,mm)=t
c  Remnant volume to have eps=dens GeV/fm3
        radptl(nptl)=sngl(ept(5))/dens
        dezptl(nptl)=0.
        do l=1,5
          pptl(l,nptl)=sngl(ept(l))
        enddo
        if(gdrop)then
          idx=0
        else
          if(iLHC.eq.1)then
            idx=idtra(icf,0,0,0)
          else
            idx=idtra(icf,0,0,3)
          endif
        endif
        if(abs(idx).gt.100)then
         amx=sngl(ept(5))
         call idres(idx,amx,idrx,iadjx,0)
         idx=idrx
        else
         idx=0
        endif
        if(idx.eq.0)then
          istptl(nptl)=10
          call idenct(jcf,idptl(nptl)
     *    ,ibptl(1,nptl),ibptl(2,nptl),ibptl(3,nptl),ibptl(4,nptl))
          if(gproj)then
            ityptl(nptl)=40
          else  !gtarg
            ityptl(nptl)=50
          endif
        else
          istptl(nptl)=0
          idptl(nptl)=idx
          pptl(5,nptl)=amx
          pptl(4,nptl)=sqrt(amx*amx+pptl(1,nptl)*pptl(1,nptl)
     &       +pptl(2,nptl)*pptl(2,nptl)+pptl(3,nptl)*pptl(3,nptl))
          if(gproj)then
            ityptl(nptl)=45
            if(iept.eq.6)ityptl(nptl)=47
          else  !gtarg
            ityptl(nptl)=55
            if(iept.eq.6)ityptl(nptl)=57
          endif
        endif
        iorptl(nptl)=mm
        jorptl(nptl)=0
        ifrptl(1,nptl)=0
        ifrptl(2,nptl)=0
        call updateXor(nptl,nptl)
        do l=1,4
          ibptl(l,nptl)=0
        enddo
        andropl=andropl+1
        if(ish.ge.3)write(ifch,*)'Proref,ept(5),id',ept(5),idptl(nptl)
        !print*,nptl,idptl(nptl),sngl(ept(5)),pptl(5,nptl)  !!!

        !..........remnant update
        if(gdrop)then  !drop emission: new remnant -> ept, icf
          idrop=0
          do l=1,5
            ept(l)=aa(l)
          enddo
          call iddeco(icf,jcf)
          call idquacjc(jcf,nqu,naq)
          if(iret.eq.1)call utstop('Pb in ProRef in strg+drop process&')
          !!!  print*,'new remnant:',icf,ept(5)    !!!
          nptl=nptl+1
          ifrptl(2,mm)=nptl
          do l=1,5
            pptl(l,nptl)=sngl(ept(l))
          enddo
          idptl(nptl)=idptl(mm)
          istptl(nptl)=40
          iorptl(nptl)=mm
          jorptl(nptl)=0
          ifrptl(1,nptl)=0
          ifrptl(2,nptl)=0
          t=xorptl(4,mm)
          xorptl(1,nptl)=xorptl(1,mm)
          xorptl(2,nptl)=xorptl(2,mm)
          xorptl(3,nptl)=xorptl(3,mm)
          xorptl(4,nptl)=t
          tivptl(1,nptl)=t
          tivptl(2,nptl)=t
          if(gproj)then
            ityptl(nptl)=40
          else   !gtarg
            ityptl(nptl)=50
          endif
          do l=1,4
            ibptl(l,nptl)=0
          enddo
        endif

        !........decay mini-droplet......
        mm=nptlini+1
        nptlb=nptl
        if(iabs(idptl(mm)).gt.10**8)then

          iret=0
          if(iorsdf.ne.3!.or.pptl(5,mm).gt.100.
     &       .or.amasini.le.amasmin*dble(flow))then      !decay here only if no fusion or large mass or mass too low for flow

          if(ish.ge.3)write(ifch,*)'Decay remnant droplet...'
          if(nptlb.gt.mxptl-10)call utstop('ProRef: mxptl too small&')

          if(ifrade.gt.0.and.ispherio.eq.0)then
c            print *,'decay in ProReF',amasini,amasmin*flow
c            if(ioclude.eq.3.or.dble(pptl(5,mm)).lt.xmdrmin)then
              call hnbaaa(9,mm,iret)    !remnant decay with higher temperature (for QGP in EAS)
c            else
c              call DropletDecay(mm,iret)!Decay remn
c              iret=0
c            endif
          endif
          if(iret.ne.1.and.nptl.ne.nptlb)then ! ---successful decay---
            istptl(mm)=istptl(mm)+2
            ifrptl(1,mm)=nptlb+1
            ifrptl(2,mm)=nptl
            rini=3./5.*((3.*radptl(mm)/4./pi)**0.3333)**2 !<r**2>=3/5*R**2 for sphere of radius R
            do 21 n=nptlb+1,nptl
              iorptl(n)=mm
              jorptl(n)=0
              istptl(n)=0
              ifrptl(1,n)=0
              ifrptl(2,n)=0
              rini=3./5.*((3.*radptl(mm)/4./pi)**0.3333)**2 !<r**2>=3/5*R**2 for sphere of radius R
              yr=sqrt(rangen())
              phi=2.*pi*rangen()
              radius=1.15*rini*yr
              bex=cos(phi)
              bey=sin(phi)
cc              tau=abs(taurem)+(2.25/sqrt(yr**2+0.04)-1.)   !do not give good result with hacas (probably too large)
c              tau=tauzer1+rangen()
c ------------------------------------------------------------------------
c space-time position based on what is done in hnb
c              call getxorptl(mm,xo1,xo2,xo3,xo4)
c              zeta=sign(ainfin,pptl(3,n))
c              pt2=pptl(1,n)**2+pptl(2,n)**2
c              if(pt2.gt.0)then  
c                pt=sqrt(pt2)
c                pp=sqrt(pt2+pptl(3,n)**2)
c                zeta=sign(1.,pptl(3,n))*log((pp+abs(pptl(3,n)))/pt)
c              endif
c              z=tau*sinh(zeta)
c              t=tau*cosh(zeta)
c              call setxorptl(nptl,xo1-radius*bex,xo2-radius*bey,z,t)
c              call idtau(idptl(n),pptl(4,n),pptl(5,n),taugm)
c              tivptl(1,n)=t
c              r=rangen()
c              tivptl(2,n)=t+taugm*(-alog(r))
c ------------------------------------------------------------------------
c former space-time position 
c              z=xo3+pptl(3,n)/pptl(5,n)*tau
c              t=xo4+pptl(4,n)/pptl(5,n)*tau
              call updateXor(n,n)
              call getxorptl(n,xo1,xo2,xo3,xo4)
              call setxorptl(n,xo1-radius*bex,xo2-radius*bey,xo3,xo4)
c ------------------------------------------------------------------------
c              ityptl(n)=ityptl(n)+1         !already in hnbaaa
              if(iept.eq.6)ityptl(n)=ityptl(n)+5  !6
              radptl(n)=0.
              dezptl(n)=0.
              itsptl(n)=0
              rinptl(n)=-9999
   21       continue
            if(iabs(idptl(nptlb+1)).le.6) then
              call gakli2(0,0)
              if(ish.ge.1)write (ifmt,*)'string from drop:nptlb+1,nptl:'
     *                                 ,nptlb+1,nptl
              istptl(nptlb+1)=1
              do n=nptlb+2,nptl
                istptl(n)=20
                zpaptl(1,n)=0.
                zpaptl(2,n)=0.
              enddo
              call gakfra(0,iret)
              call gakli2(0,0)
            endif
            jerr(4)=jerr(4)+1
          elseif(ifrade.gt.0.and.ispherio.eq.0)then ! Unsuccessful decay
            jerr(5)=jerr(5)+1
            if(ish.ge.4)write(ifch,*)
     *         '***** Unsuccessful remnant cluster decay'
     *             ,' --> do RemoveHadrons instead.'
            mm=mmini
            nptl=nptlini
            irmdropx=0
            goto 55
          endif
        else
          !redefine radptl to be used for flow calculation
          radptl(mm)=log(1.+dens) !being updated in Decaydroplet by avgdens
          dezptl(mm)=10000.
        endif
       endif

        if(idrop.eq.1)goto 1000
        !successful drop decay, no additional string, nothing to do

      endif

c...............................................................

 500  mm=mmini
      if(gdrop)mm=nptlini+2
      istptl(mm)=41
      ifrptl(1,mm)=nptl+1

c........................remove hadrons.........................

      if(.not.((nqu.eq.3.and.naq.eq.0).or.(nqu.eq.0.and.naq.eq.3)
     &     .or.(nqu.eq.1.and.naq.eq.1).or.gdiq))then
        if(irmdropx.eq.irmdrop)then
          jerr(6)=jerr(6)+1
             !call utmsg('ProReF&')
             !write(ifch,*)'***** condition for droplet treatment: '
             !write(ifch,*)'*****  amasini.gt.amasmin.and.irmdropx.eq.1 = '
             !*           ,amasini.gt.amasmin.and.irmdropx.eq.1
             !write(ifch,*)'***** amasini,amasmin,irmdropx:'
             !*                 ,amasini,amasmin,irmdropx
             !write(ifch,*)'***** nqu,naq:',nqu,naq
             !write(ifch,*)'***** call RemoveHadrons'
             !call utmsgf
        endif
       call RemoveHadrons(gproj,ghadr,m,mm,jcf,jcval,icf,ept,iret)
       if(iret.ne.0)then
         iretxx=1
         goto 1000
       endif
      endif

c........................ determine idr (0=string, else=resonance).......

      idr=0
      if(.not.gdiq)then
        if(icf(1).eq.0.and.icf(2).eq.0)then
          id=111                !minimal state is not pi0 but rho0 (from data)
        else
          if(iLHC.eq.1)then
            id=idtra(icf,0,0,0)
          else
            id=idtra(icf,0,0,3)
          endif
        endif
        am=sngl(ept(5))
        call idres(id,am,idr,iadj,0)
c      if(iabs(mod(idr,10)).le.2.and.idr.ne.0)then
c       id=idr
c      else
c       idr=0
c      endif                                !ckeck on-shell mass (see uti)
        if(iadj.ne.0.and.iept.gt.0.and.ept(5).gt.0d0
     &     .and.(dabs((ept(4)+ept(3))*(ept(4)-ept(3))
     $           -ept(2)**2-ept(1)**2-dble(am)**2).gt.0.3d0))idr=0
c      if(ept(5).gt.1.5d0)idr=0
      endif
      
      if(ish.ge.3)then
        write(ifch,'(a,5e11.3)')' updt:',(sngl(ept(k)) ,k=1,5)
        write(ifch,*)'  icf: ',icf,' idr: ',idr,' iept: ',iept
     .               ,' diq: ',gdiq
      endif

c      if(iept.eq.3)stop'ProReF: iept=3 ???'

c...........................................string...................
      if(iept.gt.0.and.iept.ne.6.and.idr.eq.0)then

        !... nqu of remainder string

        anstrg0=anstrg0+1
        if(gdrop)anstrg1=anstrg1+1

c        if(zrminc.lt.0.)stop'ProReF: not supported any more.         '

        !......determine forward momentum ep


        am1=0.
        am2=0.
        ptt1=0d0
        ptt2=0d0
c        if(iLHC.eq.1)then
c          pt=ranptcut(1.)*ptfraqq
c          if(pt.lt.0.5d0*ept(5))then
c            phi=2.*pi*rangen()
c            ptt1=dble(pt*cos(phi))
c            ptt2=dble(pt*sin(phi))
c          endif
c          ptt3=dble(ir)*sqrt((0.5d0*ept(5))**2-ptt1*ptt1-ptt2*ptt2)
c        else
          ptt3=dble(ir)*0.5d0*ept(5)
c        endif

        ep(1)=ptt1
        ep(2)=ptt2
        ep(3)=ptt3
cc        ep(4)=0.5d0*ept(5)
        ep(4)=sqrt(ptt3*ptt3+ptt2*ptt2+ptt1*ptt1+dble(am1*am1))

        call utlob2(-1,ept(1),ept(2),ept(3),ept(4),ept(5)
     *     ,ep(1),ep(2),ep(3),ep(4),25)


        !....determine forward and backward flavor icf, icb
        call iddeco(icf,jcf)
        nqu=0
        nqv=0
        nav=0
        do l=1,nrflav
          nqu=nqu+jcf(l,1)-jcf(l,2)
          nqv=nqv+jcval(l,1)+jcval(l,2)
          nav=nav+jcval(l,2)
        enddo

        if(gdiq)then !qq-aqaq string, simply chose between diquark or antidiquark
          j=min(2,1+int(0.5+rangen()))
          iq1=idraflz(jcf,j)
          iq2=idraflz(jcf,j)
          call uticpl(icf,iq1,3-j,iret) ! subtract quark 1 forward
          call uticpl(icb,iq1,j,iret) ! add quark 1 backward
          call uticpl(icf,iq2,3-j,iret) ! subtract quark 1 forward
          call uticpl(icb,iq2,j,iret) ! add quark 1 backward
          
        else

        xxx=min(1.,sngl(abs(ep(3)/ep(4))))
        qqs=sngl(ept(5)**2)
          
        if(iremn.ge.2)then
          xm3val=9.
          xm2val=3.
          xm1val=1.
          ntryx=0
 33       xx1=0.
          xx2=0.
          xx3=0.
          del=1./(1.-alppar)
          if(nqv.eq.3)then
            xx1=min(1.,ranptcut(xm3val))
            xx2=min(1.,ranptcut(xm3val))
            xx3=min(1.,ranptcut(xm3val))
          elseif(nqv.eq.2)then
            xx1=min(1.,ranptcut(xm2val))
            xx2=min(1.,ranptcut(xm2val))
            xx3=rangen()**del
          elseif(nqv.eq.1)then
            xx1=min(1.,ranptcut(xm1val))
            xx2=rangen()**del
            xx3=rangen()**del
          else
            xx1=rangen()**del
            xx2=rangen()**del
            xx3=rangen()**del
          endif
          if(ntryx.lt.1000)then
            if(xx1+xx2+xx3.gt.1)goto 33
          else
            xx1=rangen()
            xx2=rangen()*(1.-xx1)
            xx3=rangen()*(1.-xx1-xx2)
          endif
          xx1=xxx*xx1
          xx2=xxx*xx2
          xx3=xxx*xx3
          piq1=0d0
          piq2=0d0
          piq3=0d0
          if(iept.eq.4)then
            ireminv=0       !no inversion for very low mass diffraction
          else
c inversion needed for inelatic remnant because of cascade (NA49)
            ireminv=1  
          endif
       if(nqu.eq.3)then      !---baryon---
          c="s"
          if(nqv.ge.1)c="v"
          iq1=idraflx(piq1,xx1,qqs,iclpt,jcf,jcval,1,isopt,c)
          c="s"
          if(nqv.ge.2)c="v"
          iq2=idraflx(piq2,xx2,qqs,iclpt,jcf,jcval,1,isopt,c)
          c="s"
          if(nqv.ge.3)c="v"
          iq3=idraflx(piq3,xx3,qqs,iclpt,jcf,jcval,1,isopt,c)
c rescale x to have heavier quark backward (neutron in ZEUS or lambda in NA49 not forward)
c          if(iept.eq.2)then
c            if(isopt.gt.0)then
c              xx1=xx1/float(iq1)
c              xx2=xx2/float(iq2)
c              xx3=xx3/float(iq3)
c            elseif(isopt.lt.0)then
c              if(iq1.lt.3)then
c                xx1=xx1/float(3-iq1)
c              else
c                xx1=xx1/float(iq1)
c              endif
c              if(iq2.lt.3)then
c                xx2=xx2/float(3-iq2)
c              else
c                xx2=xx2/float(iq2)
c              endif
c              if(iq3.lt.3)then
c                xx3=xx3/float(3-iq3)
c              else
c                xx3=xx3/float(iq3)
c              endif
c            endif
c          endif
          call neworderx(xx3,xx2,xx1,iq3,iq2,iq1)
          if(xx2-xx3.gt.reminv*(xx1-xx2))ireminv=0
c put always strange quarks in diquark (for lambda and cascade (NA49))
          if(iq3.ge.3.and.ireminv.eq.0)ireminv=1 !here inversion only in diffraction except for strange particles (lambda and cascade very central)
c if inversion for diffractive and inelastic
c          if(iq1+iq2.lt.6.and.iq3.ge.3.and.ireminv.eq.0)then
c            iqtmp=iq3
c            if(iq2.eq.3.or.(iq1.ne.3.and.rangen().gt.0.5))then
c              iq3=iq1
c              iq1=iqtmp
c            else
c              iq3=iq2
c              iq2=iqtmp
c            endif
c          endif
          if(ireminv.eq.0)then
            call uticpl(icf,iq3,2,iret) ! antiquark
            call uticpl(icb,iq3,1,iret) ! quark
          else
            call uticpl(icf,iq3,2,iret) ! antiquark
            call uticpl(icb,iq3,1,iret) ! quark
            call uticpl(icf,iq2,2,iret) ! antiquark
            call uticpl(icb,iq2,1,iret) ! quark
          endif
        elseif(nqu.eq.-3)then !---antibaryon---
          c="s"
          if(nqv.ge.1)c="v"
          iq1=idraflx(piq1,xx1,qqs,iclpt,jcf,jcval,2,isopt,c)
          c="s"
          if(nqv.ge.2)c="v"
          iq2=idraflx(piq2,xx2,qqs,iclpt,jcf,jcval,2,isopt,c)
          c="s"
          if(nqv.ge.3)c="v"
          iq3=idraflx(piq3,xx3,qqs,iclpt,jcf,jcval,2,isopt,c)
c rescale x to have heavier quark backward (neutron in ZEUS or lambda in NA49 not forward)
c          if(iept.eq.2)then
c            if(isopt.gt.0)then
c              xx1=xx1/float(iq1)
c              xx2=xx2/float(iq2)
c              xx3=xx3/float(iq3)
c            elseif(isopt.lt.0)then
c              if(iq1.lt.3)then
c                xx1=xx1/float(3-iq1)
c              else
c                xx1=xx1/float(iq1)
c              endif
c              if(iq2.lt.3)then
c                xx2=xx2/float(3-iq2)
c              else
c                xx2=xx2/float(iq2)
c              endif
c              if(iq3.lt.3)then
c                xx3=xx3/float(3-iq3)
c              else
c                xx3=xx3/float(iq3)
c              endif
c            endif
c          endif
          call neworderx(xx3,xx2,xx1,iq3,iq2,iq1)
          if(xx2-xx3.gt.reminv*(xx1-xx2))ireminv=0
c put always strange quarks in diquark
          if(iq3.ge.3.and.ireminv.eq.0)ireminv=1
c          if(iq1+iq2.lt.6.and.iq3.ge.3.and.ireminv.eq.0)then
c            iqtmp=iq3
c            if(iq2.eq.3.or.(iq1.ne.3.and.rangen().gt.0.5))then
c              iq3=iq1
c              iq1=iqtmp
c            else
c              iq3=iq2
c              iq2=iqtmp
c            endif
c          endif
          if(ireminv.eq.0)then
            call uticpl(icf,iq3,1,iret) ! quark
            call uticpl(icb,iq3,2,iret) ! antiquark
          else
            call uticpl(icf,iq1,1,iret) ! quark
            call uticpl(icb,iq1,2,iret) ! antiquark
            call uticpl(icf,iq2,1,iret) ! quark
            call uticpl(icb,iq2,2,iret) ! antiquark
          endif
        elseif(nqu.eq.0)then !---meson---
          xx3=0.    !no third quark
          iq3=0
          if(nqv.eq.2)then
            c1="v"
            c2="v"
            j=min(2,1+int(0.5+rangen()))
          elseif(nav.ne.0)then    !valence antiquark
            c1="v"
            c2="s"
            j=2
          elseif(nqv.ne.0)then    !valence quark
            c1="v"
            c2="s"
            j=1
          else                    !only sea quarks
            c1="s"
            c2="s"
            j=min(2,1+int(0.5+rangen()))
          endif
          iq1=idraflx(piq1,xx1,qqs,iclpt,jcf,jcval,j,isopt,c1)
          iq2=idraflx(piq2,xx2,qqs,iclpt,jcf,jcval,3-j,isopt,c2)
          if(xx1.gt.xx2)ireminv=0
         if(ireminv.eq.1)then
            call uticpl(icf,iq1,3-j,iret) ! subtract quark 1 forward
            call uticpl(icb,iq1,j,iret) ! add quark 1 backward
          else
            call uticpl(icf,iq2,j,iret) ! subtract antiquark 2 forward
            call uticpl(icb,iq2,3-j,iret) ! add antiquark 2 backward
          endif
        else
          call utmsg('ProReF&')
          write(ifch,*)'***** neither baryon nor antibaryon nor meson.'
          write(ifch,*)'*****  number of net quarks:',nqu
          write(ifmt,*)'ProReF: no hadron; ',nqu,' quarks  --> redo'
          iretxx=1
          goto 1000
        endif
        if(ish.ge.3)write(ifch,'(a,2i3,3(i2,e13.6))')' inversion:',isopt
     &         ,ireminv,iq1,xx1,iq2,xx2,iq3,xx3
        else
        ireminv=0
        if(iept.ne.0)then
          if(rangen().lt.reminv)ireminv=1
        endif
        if(nqu.eq.3)then      !---baryon---
          iq=idrafl(iclpt,jcf,1,'v',1,iret)
          call uticpl(icf,iq,2,iret)       ! antiquark
          call uticpl(icb,iq,1,iret)       ! quark
          if(ireminv.eq.1)then
           iq=idrafl(iclpt,jcf,1,'v',1,iret)
           call uticpl(icf,iq,2,iret)       ! antiquark
           call uticpl(icb,iq,1,iret)       ! quark
          endif
        elseif(nqu.eq.-3)then !---antibaryon---
          iq=idrafl(iclpt,jcf,2,'v',1,iret)
          call uticpl(icf,iq,1,iret)       ! quark
          call uticpl(icb,iq,2,iret)       ! antiquark
          if(ireminv.eq.1)then
           iq=idrafl(iclpt,jcf,2,'v',1,iret)
           call uticpl(icf,iq,1,iret)       ! quark
           call uticpl(icb,iq,2,iret)       ! antiquark
          endif
        elseif(nqu.eq.0)then !---meson---
           iq1=idrafl(iclpt,jcf,1,'v',1,iret)
           iq2=idrafl(iclpt,jcf,2,'v',1,iret)
           if(rangen().gt.0.5)then
             call uticpl(icf,iq1,2,iret) ! subtract quark
             call uticpl(icb,iq1,1,iret) ! add quark
           else
             call uticpl(icf,iq2,1,iret) ! subtract antiquark
             call uticpl(icb,iq2,2,iret) ! add antiquark
           endif
c        elseif(nqu.eq.0)then !---meson---
c          if(iept.ne.1.and.iept.ne.6.and.rangen().lt.0.5)then
c           iq=idrafl(iclpt,jcf,1,'v',1,iret)
c           call uticpl(icf,iq,2,iret)       ! subtract quark
c           call uticpl(icb,iq,1,iret)       ! add quark
c          else
cc put quark in forward direction always for inelastic
c           iq=idrafl(iclpt,jcf,2,'v',1,iret)
c           call uticpl(icf,iq,1,iret)       ! subtract antiquark
c           call uticpl(icb,iq,2,iret)       ! add antiquark
c          endif
        else
          if(ish.ge.1)then
          call utmsg('ProReF&')
          write(ifch,*)'***** neither baryon nor antibaryon nor meson.'
          write(ifch,*)'*****  number of net quarks:',nqu
          endif
          write(ifmt,*)'ProReF: no hadron; ',nqu,' quarks  --> redo'
          iretxx=1
          goto 1000
        endif
      endif

      endif !gdiq
      
        !..... forward string end

        nptl=nptl+1
        if(nptl.gt.mxptl)call utstop('ProRef: mxptl too small&')
        pptl(1,nptl)=sngl(ep(1))
        pptl(2,nptl)=sngl(ep(2))
        pptl(3,nptl)=sngl(ep(3))
        pptl(4,nptl)=sngl(ep(4))
        pptl(5,nptl)=am1 !0.
        istptl(nptl)=20
        iorptl(nptl)=mm
c        if(.not.gdrop)istptl(mm)=41
        jorptl(nptl)=0
        if(.not.ghadr.and..not.gdrop)ifrptl(1,mm)=nptl
        ifrptl(2,mm)=nptl
        call updateXor(nptl,nptl)
        idptl(nptl)=idtra(icf,0,0,0)
        if(gproj)then
          if(iep(m).lt.1)stop'ProReF: iep(m)<1     '
          ityptl(nptl)=41+iep(m)  ! =42 =43 =44 =46 =47
          if(iep(m).eq.4)ityptl(nptl)=46
          if(gdrop.and.iep(m).ne.6)ityptl(nptl)=44
          if(ghadr)ityptl(nptl)=44
        else  !gtarg
          if(iet(m).lt.1)stop'ProReF: iet(m)<1     '
          ityptl(nptl)=51+iet(m)  !=52 =53 =54 =56 =57
          if(iet(m).eq.4)ityptl(nptl)=56
          if(gdrop.and.iet(m).ne.6)ityptl(nptl)=54
          if(ghadr)ityptl(nptl)=54
        endif
        itsptl(nptl)=1
        qsqptl(nptl)=qqs
        rinptl(nptl)=-9999
        !write(6,'(a,i9,$)')'     ',idptl(nptl) !======================
        zpaptl(1,nptl)=zz
        if(gproj)then
          zpaptl(2,nptl)=float(kolp(m))
c          zpaptl(2,nptl)=0.
c          if(lproj(m).ge.1)then
c            do l=1,lproj(m)
c              kpair=kproj(m,l)
c              itt=itarg(kpair)
c              zpaptl(2,nptl)=zpaptl(2,nptl)+zzremn(itt,2)
c            enddo
c          endif
        else  !gtarg
          zpaptl(2,nptl)=float(kolt(m))
c          zpaptl(2,nptl)=0.
c          if(ltarg(m).ge.1)then
c            do l=1,ltarg(m)
c              kpair=ktarg(m,l)
c              ipp=iproj(kpair)
c              zpaptl(2,nptl)=zpaptl(2,nptl)+zzremn(ipp,1)
c            enddo
c          endif
        endif
        if(ish.ge.3)then
          write(ifch,'(a,5e11.3,$)')' kink:',(pptl(k,nptl),k=1,5)
          write(ifch,*)' id: ',idptl(nptl)
        endif
        !....... backward string end

        nptl=nptl+1
        if(nptl.gt.mxptl)call utstop('ProRef: mxptl too small&')
        pptl2=0.
        do i=1,3
         pptl(i,nptl)=sngl(ept(i)-ep(i))
         pptl2=pptl2+pptl(i,nptl)*pptl(i,nptl)
        enddo
        pptl(5,nptl)=am2 !0.
        pptl2=pptl2+pptl(5,nptl)*pptl(5,nptl)
        pptl(4,nptl)=sqrt(pptl2)
        pptl2=sngl(ept(4)-ep(4))
        if(ish.ge.1.and.abs(pptl2-pptl(4,nptl)).gt.max(0.1,
     &                                         0.1*abs(pptl2)))then
          write(ifmt,*)
     &    'Warning in ProRef: inconsistent backward string end energy !'
     &    ,pptl(4,nptl),pptl2,abs(pptl2-pptl(4,nptl)),am1,am2,ptt3,ep(4)
          if(ish.ge.2)write(ifch,*)
     &    'Warning in ProRef: inconsistent backward string end energy !'
     &    ,(pptl(kkk,nptl),kkk=1,4),pptl2,abs(pptl2-pptl(4,nptl))
        endif
        istptl(nptl)=20
        iorptl(nptl)=mm
        jorptl(nptl)=0
        ifrptl(2,mm)=nptl
        ifrptl(1,nptl)=0
        ifrptl(2,nptl)=0
        call updateXor(nptl,nptl)
        idptl(nptl)=idtra(icb,0,0,0)
        if(gproj)then
          ityptl(nptl)=41+iep(m)  ! =42 =43 =47
          if(iep(m).eq.4)ityptl(nptl)=46
          if(gdrop.and.iep(m).ne.6)ityptl(nptl)=44
          if(ghadr)ityptl(nptl)=44
        else  !gtarg
          ityptl(nptl)=51+iet(m)  !=52 =53 =57
          if(iet(m).eq.4)ityptl(nptl)=56
          if(gdrop.and.iet(m).ne.6)ityptl(nptl)=54
          if(ghadr)ityptl(nptl)=54
        endif
        itsptl(nptl)=1
        qsqptl(nptl)=qqs
        rinptl(nptl)=-9999
        !write(6,'(a,i9)')'     ',idptl(nptl)
        zpaptl(1,nptl)=0.
        zpaptl(2,nptl)=0.
        if(ish.ge.3)then
          write(ifch,'(a,5e11.3,$)')' kink:',(pptl(k,nptl),k=1,5)
          write(ifch,*)' id: ',idptl(nptl)
        endif

c............................no string = resonance...................
      else

        anreso0=anreso0+1
        if(gdrop)anreso1=anreso1+1

        nptl=nptl+1
        if(idr.ne.0)id=idr
        if(nptl.gt.mxptl)call utstop('ProRef: mxptl too small&')
        if(iept.eq.0.or.iept.eq.6)call idmass(id,am)
        idptl(nptl)=id
        pptl(1,nptl)=sngl(ept(1))
        pptl(2,nptl)=sngl(ept(2))
        am2t=sqrt(ept(2)*ept(2)+ept(1)*ept(1)+dble(am*am))
        if(iLHC.eq.1.and.ept(4).gt.am2t)then   !conserve value of E on not pz
          pptl(4,nptl)=sngl(ept(4))
          pptl(3,nptl)=sngl(sign(sqrt((ept(4)+am2t)*(ept(4)-am2t))
     &                          ,ept(3)))
        else
          pptl(3,nptl)=sngl(ept(3))
          pptl(4,nptl)=sngl(sqrt(ept(3)*ept(3)+am2t))
        endif
        pptl(5,nptl)=am
        istptl(nptl)=0
        iorptl(nptl)=mm
c        if(.not.gdrop)istptl(mm)=41
        jorptl(nptl)=0
        if(.not.ghadr.and..not.gdrop)ifrptl(1,mm)=nptl
        ifrptl(2,mm)=nptl
        ifrptl(1,nptl)=0
        ifrptl(2,nptl)=0
        call updateXor(nptl,nptl)
        if(gproj)then
          ityptl(nptl)=45
          if(gdrop)then
            ityptl(nptl)=44
          elseif(iept.eq.4)then
            ityptl(nptl)=46
          elseif(iept.eq.6)then
            ityptl(nptl)=47
c          elseif(iept.eq.2.or.iept.eq.4)then
          elseif(iept.eq.2)then
            ityptl(nptl)=48
          elseif(ghadr)then
            ityptl(nptl)=49
          else
            mine=0
            mdif=0
            do l=1,lproj(m)
              kp=kproj(m,l)
              if(abs(itpr(kp)).eq.1)mine=1
              if(itpr(kp).eq.2)mdif=1
            enddo
            if(mine.eq.0.and.mdif.eq.1)ityptl(nptl)=48
          endif
        else   !gtarg
          ityptl(nptl)=55
          if(gdrop)then
            ityptl(nptl)=56
          elseif(iept.eq.4)then
            ityptl(nptl)=56
          elseif(iept.eq.6)then
            ityptl(nptl)=57
c          elseif(iept.eq.2.or.iept.eq.4)then
          elseif(iept.eq.2)then
            ityptl(nptl)=58
          elseif(ghadr)then
            ityptl(nptl)=59
          else
            mine=0
            mdif=0
            do l=1,lproj(m)
              kp=kproj(m,l)
              if(abs(itpr(kp)).eq.1)mine=1
              if(itpr(kp).eq.2)mdif=1
            enddo
            if(mine.eq.0.and.mdif.eq.1)ityptl(nptl)=58
          endif
        endif
        itsptl(nptl)=0
        qsqptl(nptl)=0.
        rinptl(nptl)=-9999

        if(ish.ge.3)write(ifch,'(a,5e10.3,i7)')' nucl:'
     *         ,(pptl(i,nptl),i=1,5),idptl(nptl)

      endif
c.......................................................................
c      print *,iep(1),iet(1),ityptl(nptl)
 1000 call utprix('ProReF',ish,ishini,3)
ctp060829        if(ityptl(nptl).gt.60)print*,ityptl(nptl)
      return

      end

c-----------------------------------------------------------------------
      subroutine RemoveHadrons(gproj,ghadr,m,mm,jcf,jcv
     &                        ,icf,ept,iret)
c-----------------------------------------------------------------------
      include 'epos.inc'
      include 'epos.incems'
      integer jcf(nflav,2),jcv(nflav,2),icf(2)
      double precision aa(5),ept(5)
      logical ghadr,gproj
      common/ems6/ivp0,iap0,idp0,isp0,ivt0,iat0,idt0,ist0

      iret=0

      if(iremn.ge.2)then
        if(gproj)then
          idrf=idp(m)
        else
          idrf=idt(m)
        endif
      else
        if(gproj)then
          idrf=idp0
        else
          idrf=idt0
        endif
      endif
      call idquacjc(jcf,nqu,naq)
      if(nqu.eq.naq.and.(nqu.le.2.or.idrf.eq.0))then
        nmes=nqu
        nmes=nmes-1             !string is aq-q
        nbar=0
      elseif(nqu.gt.naq)then
        nmes=naq
        nbar=(nqu-nmes)/3     !nbar baryons
        if(nmes.eq.0.or.idrf.eq.1)then
          nbar=nbar-1        !string is qq-q
        else
          nmes=nmes-1        !string is aq-q
        endif
      elseif(nqu.lt.naq)then
        nmes=nqu
        nbar=(naq-nmes)/3    !nbar antibaryons
        if(nmes.eq.0.or.idrf.eq.1)then
          nbar=nbar-1        !string is aqaq-aq
        else
          nmes=nmes-1        !string is aq-q
        endif
      else
        nbar=nqu/3
        nmes=nqu-3*nbar
        nbar=nbar+naq/3
        nbar=nbar-1             !string is qq-q or aqaq-aq
      endif
      if(ish.ge.5)
     &       write(ifch,*)'RemoveHadron part (nq,na,nb,nm,dq):'
     &                     ,nqu,naq,nbar,nmes,idrf
      if(nmes+nbar.gt.0)ghadr=.true.
c  remove mesons
       if(nmes.gt.0)then
          do mes=1,nmes
            !write(ifch,*)'remove meson',mes,' / ',nmes
            call gethadron(1,idd,aa,jcf,jcv,ept,gproj,iret)
            if(iret.ne.0)goto 1000
              nptl=nptl+1
              if(nptl.gt.mxptl)
     &             call utstop('RemoveHadrons: mxptl too small&')
              idptl(nptl)=idd
              do i=1,5
                pptl(i,nptl)=sngl(aa(i))
              enddo
              iorptl(nptl)=mm
              jorptl(nptl)=0
              if(mes.eq.1)then
                ifrptl(1,mm)=nptl
                ifrptl(2,mm)=nptl
              else
                ifrptl(2,mm)=nptl
              endif
              ifrptl(1,nptl)=0
              ifrptl(2,nptl)=0
              istptl(nptl)=0
              if(gproj)then
                ityptl(nptl)=49
              else   !gtarg
                ityptl(nptl)=59
              endif
              call updateXor(nptl,nptl)
              qsqptl(nptl)=0.
c           deleted: after abstracting a meson,
c           check if the NEW remnant is a H-Dibaryon
          enddo
        endif
c remove (anti)baryons
        call idquacjc(jcf,nqu,naq)
        if(nbar.gt.0)then
          do nb=1,nbar
            !write(ifch,*)'remove baryon',nb,' / ',nbar
            prq=float(nqu/3)
            pra=float(naq/3)
            psum=prq+pra
            if(psum.gt.0.)then
              if(rangen()*psum.le.prq)then      !baryon
                call gethadron(2,idd,aa,jcf,jcv,ept,gproj,iret)
                nqu=nqu-3
              else                              !antibaryon
                call gethadron(3,idd,aa,jcf,jcv,ept,gproj,iret)
                naq=naq-3
             endif
            else
              iret=1
            endif
            if(iret.ne.0)goto 1000
              nptl=nptl+1
              if(nptl.gt.mxptl)
     &             call utstop('RemoveHadron: mxptl too small&')
              idptl(nptl)=idd
              do i=1,5
                pptl(i,nptl)=sngl(aa(i))
              enddo
              iorptl(nptl)=mm
              jorptl(nptl)=0
              if(nmes.eq.0.and.nb.eq.1)then
                ifrptl(1,mm)=nptl
                ifrptl(2,mm)=nptl
              else
                ifrptl(2,mm)=nptl
              endif
              ifrptl(1,nptl)=0
              ifrptl(2,nptl)=0
              istptl(nptl)=0
              if(gproj)then
                ityptl(nptl)=49
              else    !gtarg
                ityptl(nptl)=59
              endif
              call updateXor(nptl,nptl)
              qsqptl(nptl)=0.
c             deleted: after abstracting a (anti)baryon,
c                                  check if the NEW remnant is a H-Dibaryon
          enddo
        endif
        call idenco(jcf,icf,iret)

 1000 return
      end

c------------------------------------------------------------------
         subroutine gethadron(imb,idf,a,jc,jcv,ep,gproj,iret)
c------------------------------------------------------------------
c       goal:  emit a hadron (imb= 1 meson, 2 baryon, 3 antibaryon)
c              update the remnant flavor and 5-momentum
c
c       idf ,a : hadron id and 5-momentum
c       gproj  : T  projectile, F  target remnant
c       jc, ep : remnant flavor and 5-momentum
c       iret   : in case of error, keep correct momentum in remnant
c                and lose the quarks of the (not) emitted hadron
c-----------------------------------------------------------------

        include 'epos.inc'
        include 'epos.incems'
        common/cems5/plc,s
        double precision s,plc
        double precision ep(5),a(5),re(5),p1(5)
        integer jc(nflav,2),jcv(nflav,2),jcini(nflav,2),jcvini(nflav,2)
     &    ,ifh(3),ic(2)
        double precision ptm,qcm,u(3),utpcmd,ptt,phi,sxini,sxini0,strmas
     &                  ,ampt2dro,ampt2str,p5sq,amasex,drangen,xmaxrm
        logical gproj

        call utpri('gethad',ish,ishini,5)

        iret=0
        do i=1,5
          a(i)=0.d0
          re(i)=ep(i)
        enddo
        ic(1)=0
        ic(2)=0
        do j=1,2
          do i=1,nflav
            jcini(i,j)=jc(i,j)
            jcvini(i,j)=jcv(i,j)
          enddo
        enddo

        if(iremn.ge.2)then
          if(ish.ge.5)then
            write(ifch,*)'remnant flavor and 5-momentum:',jc
            write(ifch,*)'                              ',jcv
            write(ifch,*)'momentum :',ep,gproj,imb
          endif
          call idquacjc(jcvini,nqv,nav)
        else
          if(ish.ge.5)
     &       write(ifch,*)'remnant flavor and 5-momentum:',jc,ep,gproj
     &                                                          ,imb
          nqv=0
          nav=0
        endif
       !write(*,'(/a,5f8.3)')'p before: ',ep

        if(gproj)then
          iclpt=iclpro
        else
          iclpt=icltar
        endif

c boost remnant in rest frame
         if(ish.ge.6) write (ifch,*) 'on-shell check'
         do k=1,5
           p1(k)=ep(k)
         enddo
         p1(5)=(p1(4)-p1(3))*(p1(4)+p1(3))-p1(2)**2-p1(1)**2
         if(p1(5).gt.0d0.and.abs(p1(5)-ep(5)*ep(5)).lt.ep(5))then
           p1(5)=sqrt(p1(5))
         else
           if(ish.ge.1)write(ifch,*)'Precision problem in gethad, p:',
     &          (p1(k),k=1,5),ep(5)*ep(5)
           p1(5)=0d0
        endif

c       initial limits
        mamos=4
        ptm=p1(5)
        sxini0=ptm*ptm
        idf=0
c redo

        nredo=0
 777    continue
        nredo=nredo+1
        if(nredo.gt.1)then       !restore initial flavors
          ic(1)=0
          ic(2)=0
          do j=1,2
            do i=1,nflav
              jc(i,j)=jcini(i,j)
              jcv(i,j)=jcvini(i,j)
            enddo
          enddo
          if(iremn.ge.2)then
            call idquacjc(jcvini,nqv,nav)
          endif
          if(ish.ge.7)write(ifch,*)'Restore flavor',idf,jc
          idf=0
          if(ptm.eq.0.or.nredo.gt.20)then
            if(ish.ge.4)write(ifch,*)
     &         'Pb with hadron momentum in Gethad !'
            iret=1
          endif
        endif

c  get the id and mass of hadron, the remnant jc is updated
        iret2=0
          if(imb.eq.1)then              ! a meson
            j=1
            if(nqv.gt.0)then
              i=idraflz(jcv,j)
              jc(i,j)=jc(i,j)-1
              nqv=nqv-1
            else
              i=idrafl(iclpt,jc,j,'v',1,iret2)
              if(iLHC.eq.1.and.iret2.ne.0)goto 77
            endif
            ifq=i
            j=2
            if(nav.gt.0)then
              i=idraflz(jcv,j)
              jc(i,j)=jc(i,j)-1
              nav=nav-1
            else
              i=idrafl(iclpt,jc,j,'v',1,iret2)
              if(iLHC.eq.1.and.iret2.ne.0)goto 77
            endif
            ifa=i
c            write(ifch,*)'ici',ifq,ifa,jc,'| ',jcv
            ic(1)=10**(6-ifq)
            ic(2)=10**(6-ifa)
            ier=0
            idf=idtra(ic,ier,idum,0)
            if(ier.ne.0)then
              if(ifq.le.ifa)then
                idf=ifq*100+ifa*10
              else
                idf=-(ifq*10+ifa*100)
              endif
            endif
            call idmass(idf,amss)
            if(abs(idf).eq.440)goto 777   !exclude j/psi production

          elseif(imb.eq.2)then            ! a baryon
            j=1
            do ik=1,3
              if(nqv.gt.0)then
                i=idraflz(jcv,j)
                jc(i,j)=jc(i,j)-1
                nqv=nqv-1
              else
                i=idrafl(iclpt,jc,j,'v',1,iret2)
              if(iLHC.eq.1.and.iret2.ne.0)goto 77
              endif
              ifh(ik)=i
              ic(j)=ic(j)+10**(6-i)
            enddo
            ier=0
            idf=idtra(ic,ier,idum,0)
            if(ier.ne.0)then
              call neworder(ifh(1),ifh(2),ifh(3))
              idf=ifh(1)*1000+ifh(2)*100+ifh(3)*10
              if(ifh(1).ne.ifh(2).and.ifh(2).ne.ifh(3)
     $             .and.ifh(1).ne.ifh(3))  idf=2130
              if(ifh(1).eq.ifh(2).and.ifh(2).eq.ifh(3))idf=idf+1
            endif
            call idmass(idf,amss)

          elseif(imb.eq.3)then           ! an antibaryon
            j=2
            do ik=1,3
              if(nav.gt.0)then
                i=idraflz(jcv,j)
                jc(i,j)=jc(i,j)-1
                nav=nav-1
              else
                i=idrafl(iclpt,jc,j,'v',1,iret2)
              if(iLHC.eq.1.and.iret2.ne.0)goto 77
              endif
              ifh(ik)=i
              ic(j)=ic(j)+10**(6-i)
            enddo
            ier=0
            idf=idtra(ic,ier,idum,0)
            if(ier.ne.0)then
              call neworder(ifh(1),ifh(2),ifh(3))
              idf=ifh(1)*1000+ifh(2)*100+ifh(3)*10
              if(ifh(1).ne.ifh(2).and.ifh(2).ne.ifh(3)
     $             .and.ifh(1).ne.ifh(3))  idf=2130
              if(ifh(1).eq.ifh(2).and.ifh(2).eq.ifh(3))idf=idf+1
              idf=-idf
            endif
            call idmass(idf,amss)
           else
            call utstop('This imb does not exist in gethad !&')
           endif

   77     if(iret2.ne.0)then
          write(ifmt,*)'warning in gethadron: imb=',imb,'  iclpt:',iclpt
          write(ifmt,*)'   jc: ',jc,'  j: ',j,'   (1=q,2=aq)  --> redo'
          call utmsg('gethad&')
          write(ifch,*)'Not enough quark ??? ... redo event !'
          call utmsgf
          iret=1
          goto 1000
          endif

c fix pt
          amasex=dble(amss)
          strmas=dble(utamnz(jc,mamos))

          ptt=dble(ranpt()*alpdro(2))**2         !pt+pl
          if(iret.ne.0)ptt=min(ptt,sxini0)
          if(ptt.gt.sxini0)goto 777
          sxini=sqrt(sxini0-ptt)



          a(5)=amasex
          re(5)=sxini-a(5)
          if(re(5).lt.strmas)then
            call idquacjc(jc,nq,na)
            if(nq+na.le.3)then
              idtmp=idtra(ic,1,idum,0)
              amtmp=0.
              call idmass(idtmp,amtmp)
              if(re(5).lt.amtmp)then
                if(ish.ge.6)write(ifch,*)
     &           'Pb with initial mass in Gethad, retry',idf
     &       ,amasex,re(5),strmas,sxini,ptm,ptt,amtmp,idtmp,ic,iret
                if(iret.eq.0)then
                  goto 777
                else
                  if(ish.ge.6)write(ifch,*)
     &           'Continue with minimal mass for remnant',re(5)
     &                                                   ,amtmp
                  re(5)=amtmp
                endif
              else
                strmas=amtmp
              endif
            endif
          endif

          ampt2dro=amasex**2d0
          ampt2str=strmas**2d0

c two body decay
          iret2=0
          if(iret.eq.1)then
c If energy to small, then produce a new particle adding the needed missing energy (limited energy violation to avoid stop and corrected in utrescl)
            xmaxrm=a(5)*a(5)+re(5)*re(5)
            if(ptm*ptm-xmaxrm.lt.0d0)then
             ptm=1.1d0*sqrt(2.d0*abs(a(5))*abs(re(5))+xmaxrm)
             p1(5)=ptm
             p1(4)=sqrt(p1(3)*p1(3)+p1(2)*p1(2)+p1(1)*p1(1)+p1(5)*p1(5))
            endif
          endif
          if(ish.ge.6)write(ifch,*)'2 body decay',ptm,a(5),re(5),iret
          qcm=utpcmd(ptm,a(5),re(5),iret2)
          if(iret2.ne.0)then
            if(iret.eq.0)then
             goto 777
            else
c              call utstop('Problem with qcm in gethadron !&')
              if(ish.ge.1)then
                call utmsg('gethad&')
                write(ifch,*)'Problem with qcm  ... redo event !'
                call utmsgf
              endif
              iret=1
              return
            endif
          endif
          u(3)=2.d0*drangen(qcm)-1.d0
          phi=2.d0*dble(pi)*drangen(u(3))
          u(1)=sqrt(1.d0-u(3)**2)*cos(phi)
          u(2)=sqrt(1.d0-u(3)**2)*sin(phi)
          if(u(3).ge.0d0)then          !send always hadron backward
            do j=1,3
              re(j)=qcm*u(j)
              a(j)=-re(j)
            enddo
          else
            do j=1,3
              a(j)=qcm*u(j)
              re(j)=-a(j)
            enddo
          endif

          re(4)=sqrt(qcm**2+re(5)**2)
          a(4)=sqrt(qcm**2+a(5)**2)

          if(ish.ge.6)write(ifch,*)'boost : ',qcm
     &      ,' and momentum in rest frame : ',re,a


c Fix re of remnant

c boost string in collision frame
        call utlob2(-1,p1(1),p1(2),p1(3),p1(4),p1(5)
     $       ,re(1),re(2),re(3),re(4),81)

         p5sq=(re(4)+re(3))*(re(4)-re(3))-(re(1)*re(1)+re(2)*re(2))
         if(p5sq.ge.ampt2str)then
           re(5)=sqrt(p5sq)
         else
           if(ish.ge.6)then
             write(ifch,*)'Pb with remnant mass -> retry'
             write(ifch,*)'   m^2:',p5sq,'  m_min^2:',ampt2str
             write(ifch,*)'   momentum four vector:',(re(ii),ii=1,4)
           endif
           if(iret.eq.0)then
             goto 777
           else
             if(ish.ge.6)write(ifch,*)
     &            'Finish with minimal mass for remnant',re(5)
           endif
         endif

c Fix a of hadron

c boost hadron in collision frame
        call utlob2(-1,p1(1),p1(2),p1(3),p1(4),p1(5)
     $       ,a(1),a(2),a(3),a(4),82)

         p5sq=(a(4)+a(3))*(a(4)-a(3))-(a(1)**2.d0+a(2)**2.d0)
         if(abs(p5sq-ampt2dro).le.0.1)then
           a(5)=sqrt(p5sq)
         else
           if(ish.ge.6)then
             write(ifch,*)'Pb with hadron mass'
             write(ifch,*)'   m^2:',p5sq,'  m_min^2:',ampt2dro
             write(ifch,*)'   momentum four vector:',(a(ii),ii=1,4)
           endif
           a(4)=sqrt(a(5)*a(5)+a(3)*a(3)+a(2)*a(2)+a(1)*a(1))
           if(ish.ge.6)write(ifch,*)'Fix E with M and P:',(a(ii),ii=1,5)
         endif


c        if(iret.eq.1)then      !If problem with momenta do not update remnant
c
c          if(ish.ge.4)
c     *    write(ifch,*)'no hadron emission in gethad'
c
c        else     !update the 3-momentum and energy of remnant: ep

          if(ish.ge.1.and.abs(ep(4)-re(4)-a(4)).gt.1.d-2*ep(4))then
            write(ifmt,*)'Pb with energy conservation in gethad'
            if(ish.ge.6)then
              write(ifch,*)'Pb with energy conservation :'
              write(ifch,*)'   p1_ini:',ep(1),'  p1:',re(1)+a(1)
              write(ifch,*)'   p2_ini:',ep(2),'  p2:',re(2)+a(2)
              write(ifch,*)'   p3_ini:',ep(3),'  p3:',re(3)+a(3)
              write(ifch,*)'   p4_ini:',ep(4),'  p4:',re(4)+a(4)
            endif
          endif

          do i=1,5
            ep(i)=re(i)
          enddo
          if(ish.ge.5)then
            write(ifch,*)'get hadron with id and 5-momentum:',idf, a
          endif

c        endif

        !do i=1,5
        !  sm(i)=ep(i)+a(i)
        !enddo
        !write(*,'(a,5f8.3,i5)')'p after:  ',sm,iret

c      ghost condition
c         if(abs((a(4)+a(3))*(a(4)-a(3))
c     $           -a(2)**2-a(1)**2-a(5)**2).gt.0.3
c     $      .and.  abs(1.-abs(a(3))/a(4)).gt.0.01)print*,iret,dd


        if(ish.ge.5)then
          write(ifch,*)'new remnant flavor and 5-momentum:',jc, ep,iret
        endif
        iret=0
c          write(ifmt,*)'get hadron with id and 5-momentum:',idf, a
c          write(ifmt,*)'new remnant flavor and 5-momentum:',jc, ep

 1000 call utprix('gethad',ish,ishini,5)

      return
      end



c------------------------------------------------------------------
         subroutine getdroplet(ir,iept,ic,jc,z,ep,a,pass,xmdrmax)
c------------------------------------------------------------------
c  emit a droplet, update the remnant string flavor and 5-momentum
c
c input
c       ir ........ 1  projectile, -1  target remnant
c       iept ...... particle excitation
c       ep ........ remnant  5-momentum
c       jc ........ remnant jc
c       z  ........ Z factor from splitting
c output
c       pass ...  .true. = successful droplet emission
c                            jc, ep ....... droplet  ic and 5-momentum
c                            ic, a ........ remnant string jc and 5-momentum
c                 .false. = unsuccessful
c                            jc, ep .... unchanged,
c                            considered as droplet jc and 5-momentum
c-----------------------------------------------------------------

        include 'epos.inc'
        include 'epos.incems'
        double precision ep(5),a(5),p1(5),re(5),eps,amasex,xmdrmax
        double precision xxx,rr,alp,p5sq,xmin,xmax,ampt2str
     &  ,sxini,strmas,xxxmax,xxxmin,ampt2dro,xmdrmaxi
        parameter(eps=1.d-20)
        integer jc(nflav,2),ic(2),icx(2)
        integer jcini(nflav,2),jcfin(nflav,2)
        logical pass
        common/cems5/plc,s
        double precision s,plc,ptm,qcm,u(3),utpcmd,ptt,drangen,phi

        call utpri('getdro',ish,ishini,4)

        iret=0
        iret2=0
        xmdrmaxi=min(50.d0,xmdrmax)
        pass=.true.
        idps=0
        idms=0
        do i=1,nflav
          jcini(i,1)=jc(i,1)
          jcini(i,2)=jc(i,2)
          jcfin(i,1)=0
          jcfin(i,2)=0
        enddo


        call idquacjc(jcini,nqu,naq)

        do i=1,5
          a(i)=0.d0
          re(i)=0.d0
        enddo
        npart=nqu+naq
        nqc=jcini(4,1)+jcini(4,2)

        if(ir.eq.1)then
           iclpt=iclpro
         else
           iclpt=icltar
         endif

         if(ish.ge.5)then
           write(ifch,10)'remnant flavor and 5-momentum:'
     &                    ,jc,ep,nqu,naq,nqc,iept
 10        format(a,/,'jc:',6i3,' |',6i3,/,'ep:',5(e10.3,1x),/,4i4)
         endif

c  get id of string ends, the remnant string jc is updated
         if(iremn.eq.3)then  !  remnant content=string content (droplet empty)

           do i=1,nflav
             jcfin(i,1)=jcini(i,1)
             jcfin(i,2)=jcini(i,2)
             jcini(i,1)=0
             jcini(i,2)=0
           enddo

         else

         if(npart.lt.3.and.ep(5).lt.xmdrmax.and.nqc.eq.0)then !light droplet with few quarks
            pass=.false.
            goto 1000
         elseif(npart.lt.3)then    !few quarks but heavy, add some quarks to extract a q-qbar string (should not exit directly because of the large mass)
           ifq=idrafl(iclpt,jcini,2,'r',3,iret2)
           if(nqu.eq.1.and.naq.eq.1)then
             idps=1
             idms=1
             nqu=2
             naq=2
           else
             call utstop('This should not happen (getdrop) !&')
           endif
         elseif(nqu.eq.2.and.naq.eq.2)then
           idps=1
           idms=1
         elseif(naq.eq.0)then
           idps=5
           idms=1
         elseif(nqu.eq.0)then
           idps=1
           idms=5
         else                 !There is enough q or aq to do qq-q string


           if(jcini(4,1)-jcini(4,2).eq.0)then !if c-cbar

             idps=1
             idms=1

           else

c One chooses the first q or aq

           rrr=rangen()
           npart=nqu+naq
           if(jcini(4,1)+jcini(4,2).ne.0)then !if some charm take it out
             if(jcini(4,1).ne.0)then
               idps=1
               nqu=nqu-1
             else
               idms=1
               naq=naq-1
             endif
           elseif(rrr.gt.float(naq)/float(npart))then
             idps=1
             nqu=nqu-1
           else
             idms=1
             naq=naq-1
           endif

c One chooses the second one

           rrr=rangen()
           npart=nqu+naq
           if(idps.eq.1.and.jcini(4,1).ne.0)then !if some charm take it out
             idps=5
           elseif(idms.eq.1.and.jcini(4,2).ne.0)then !if some charm take it out
             idms=5
           elseif(rrr.gt.float(naq)/float(npart))then
             if(idps.eq.1.and.nqu.ge.2)then
               idps=5
             else
               idps=1
             endif
           else
             if(idms.eq.1.and.naq.ge.2)then
               idms=5
             else
               idms=1
             endif
           endif

c If there is already 2 q or 2 aq as string end, we know that we need
c a third one to complete the string

           if(idps.eq.5)idms=1
           if(idms.eq.5)idps=1
           if(idps.eq.1.and.idms.ne.5)idms=1
           if(idms.eq.1.and.idps.ne.5)idps=1

         endif

         endif

         if(ish.ge.5)then
           write(ifch,*)'remnant string ends :',idps,idms
         endif

          if(idps.ne.5.and.idms.ne.5)then              ! q-aq string
            if(jcini(4,1).eq.1)then
              ifq=idrafl(iclpt,jcini,1,'c',1,iret)
            else
              ifq=idrafl(iclpt,jcini,1,'v',1,iret)
            endif
            if(jcini(4,1).eq.1)then
              ifa=idrafl(iclpt,jcini,2,'c',1,iret)
            else
              ifa=idrafl(iclpt,jcini,2,'v',1,iret)
            endif
            jcfin(ifq,1)=1
            jcfin(ifa,2)=1

          elseif(idps.eq.5)then                       ! qq-q string
            do ik=1,3
              if(jcini(4,1).ne.0)then
                i=idrafl(iclpt,jcini,1,'c',1,iret)
              else
                i=idrafl(iclpt,jcini,1,'v',1,iret)
              endif
              jcfin(i,1)=jcfin(i,1)+1
            enddo

          elseif(idms.eq.5)then                        !aqaq-aq string
            do ik=1,3
              if(jcini(4,2).ne.0)then
                i=idrafl(iclpt,jcini,2,'c',1,iret)
              else
                i=idrafl(iclpt,jcini,2,'v',1,iret)
              endif
              jcfin(i,2)=jcfin(i,2)+1
            enddo
          endif

          endif      !iremn=3

          if(iret.ne.0)call utstop('Not enough quark in getdro ???&')
          if(jcini(4,1)+jcini(4,2).ne.0)
     &         call utstop('There is sitll charm quark in getdro???&')

c string id

         call idenco(jcfin,icx,iret)
         if(iret.eq.1)then
           call utstop('Exotic flavor in getdroplet !&')
         endif


c boost remnant in rest frame
      if(ish.ge.6) write (ifch,*) 'on-shell check'
        do k=1,5
          p1(k)=ep(k)
        enddo
        p1(5)=(p1(4)-p1(3))*(p1(4)+p1(3))-p1(2)**2-p1(1)**2
        if(p1(5).gt.0d0.and.abs(p1(5)-ep(5)*ep(5)).lt.ep(5))then
          p1(5)=sqrt(p1(5))
        else
          if(ish.ge.2)write(ifch,*)'Precision problem in getdro, p:',
     &             (p1(k),k=1,5),ep(5)*ep(5)
          p1(5)=ep(5)
          p1(4)=sqrt(p1(3)*p1(3)+p1(2)*p1(2)+p1(1)*p1(1)+p1(5)*p1(5))
        endif
      if(ish.ge.6) write (ifch,*) 'boost vector:',p1

c limits for momenta

      mamod=4
      mamos=4
      fad=alpdro(1)
      if(iremn.eq.3)fad=fad*(1.+z*zdrinc)
      fad=max(1.5,fad)
      ptm=p1(5)
      amasex=dble(fad*utamnz(jcini,mamod))
      fas=2.
      if(iremn.eq.3)then
        id=idtra(icx,ier,ires,0)
        if(ier.eq.0)then
          call idmass(id,amass)           !minimum is particle mass
          strmas=dble(amass)
        else
          strmas=dble(fas*utamnz(jcfin,mamos))
        endif
      else
        strmas=dble(fas*utamnz(jcfin,mamos))
      endif


c redo

       nredo=0
 777   continue
       nredo=nredo+1
       if(nredo.eq.10)then
          amasex=1.5d0*dble(utamnz(jcini,mamod))
          if(iremn.ne.3)strmas=1.5d0*dble(utamnz(jcfin,mamos))
       elseif(nredo.gt.20)then
          !write(ifch,*)'nredo.gt.20 -> only drop'
         if(ish.ge.4)write(ifch,*)
     &     'Pb with string mass in Getdrop, continue with gethad'
          pass=.false.
         goto 1000
       endif

c fix pt

          sxini=ptm*ptm
          ptt=dble(ranpt()*alpdro(2))**2         !pt
          if(ptt.ge.sxini)goto 777
          sxini=sqrt(sxini-ptt)


          ampt2dro=amasex**2d0
          ampt2str=strmas**2d0
          if(ampt2dro.gt.xmdrmaxi)then
            xmdrmaxi=2d0*ampt2dro
c            write(ifmt,*)'Warning Mmin>Mmax in Getdroplet'
          endif

          xxxmax=min(xmdrmaxi,(sxini-strmas)**2)    !strmas/(strmas+ampt2)
          xxxmin=ampt2dro

          if(xxxmin.gt.xxxmax)then
            !write(ifch,*)'Warning Mmin>sxini -> only drop'
           if(ish.ge.4)write(ifch,*)
     &     'Pb with ampt2 in Getdrop, retry',nredo,ir
     &             ,ampt2dro,ampt2str,xxxmin,xxxmax,sxini,ptt,xmdrmaxi
            goto 777
          endif



c fix mass

            rr=drangen(xxxmax)
            xmax=xxxmax
            xmin=xxxmin
            alp=dble(alpdro(3))
            if(dabs(alp-1.d0).lt.eps)then
              xxx=xmax**rr*xmin**(1d0-rr)
            else
              xxx=(rr*xmax**(1d0-alp)+(1d0-rr)*xmin**(1d0-alp))
     &                                                **(1d0/(1d0-alp))
            endif


c        write(ifch,*)'ini',xmin,xxx,xmax,rr,ampt2dro
c    &                   ,(sxini-sqrt(xxx)),ampt2str,p1(5)



          re(5)=sqrt(xxx)
          a(5)=sxini-re(5)
          if(a(5).lt.strmas)then
            if(ish.ge.6)write(ifch,*)
     &           'Pb with initial mass in Getdrop, retry',ir
     &       ,xmin,xxx,xmax,rr,ampt2dro,ampt2str,a(5)
            goto 777
          endif


c two body decay
          if(ish.ge.6)write(ifch,*)'2 body decay',ptm,re(5),a(5)
          qcm=utpcmd(ptm,re(5),a(5),iret)
          u(3)=2.d0*drangen(qcm)-1.d0
          phi=2.d0*dble(pi)*drangen(u(3))
          u(1)=sqrt(1.d0-u(3)**2)*cos(phi)
          u(2)=sqrt(1.d0-u(3)**2)*sin(phi)
          if(u(3).lt.0d0)then          !send always droplet backward
c          if(u(3).gt.0d0)then          !send always droplet forward     ?????
            do j=1,3
              re(j)=qcm*u(j)
              a(j)=-re(j)
            enddo
          else
            do j=1,3
              a(j)=qcm*u(j)
              re(j)=-a(j)
            enddo
          endif

          re(4)=sqrt(qcm**2+re(5)**2)
          a(4)=sqrt(qcm**2+a(5)**2)

          if(ish.ge.6)write(ifch,*)'momentum in rest frame : ',re,a



c Fix a of string

c boost string in collision frame
        call utlob2(-1,p1(1),p1(2),p1(3),p1(4),p1(5)
     $       ,a(1),a(2),a(3),a(4),71)

         p5sq=(a(4)+a(3))*(a(4)-a(3))-(a(1)**2.d0+a(2)**2.d0)
         if(p5sq.gt.ampt2str)then
           a(5)=sqrt(p5sq)
         else
           if(ish.ge.6)then
             write(ifch,*)'Pb with string mass -> retry'
             write(ifch,*)'   m^2:',p5sq,'  m_min^2:',ampt2str
             write(ifch,*)'   momentum four vector:',(a(ii),ii=1,4)
           endif
           goto 777
         endif

c Fix ep of droplet

c boost droplet in collision frame
        call utlob2(-1,p1(1),p1(2),p1(3),p1(4),p1(5)
     $       ,re(1),re(2),re(3),re(4),72)

         p5sq=(re(4)+re(3))*(re(4)-re(3))-(re(1)*re(1)+re(2)*re(2))
         if(p5sq.gt.ampt2dro)then
           re(5)=sqrt(p5sq)
         else
           if(ish.ge.6)then
             write(ifch,*)'Pb with droplet mass -> retry'
             write(ifch,*)'   m^2:',p5sq,'  m_min^2:',ampt2dro
             write(ifch,*)'   momentum four vector:',(re(ii),ii=1,4)
           endif
           goto 777
         endif


       if(ish.ge.1.and.abs(ep(4)-re(4)-a(4)).gt.1.d-2*ep(4))then
         write(ifmt,*)'Pb with energy conservation in getdro'
         if(ish.ge.6)then
           write(ifch,*)'Pb with energy conservation :'
           write(ifch,*)'   p1_ini:',ep(1),'  p1:',re(1)+a(1)
           write(ifch,*)'   p2_ini:',ep(2),'  p2:',re(2)+a(2)
           write(ifch,*)'   p3_ini:',ep(3),'  p3:',re(3)+a(3)
         endif
       endif

c If OK, save flavors of droplet and string
         do i=1,5
           ep(i)=re(i)
         enddo
         ic(1)=icx(1)
         ic(2)=icx(2)
         do i=1,nflav
           jc(i,1)=jcini(i,1)
           jc(i,2)=jcini(i,2)
         enddo

         if(ish.ge.6)then
           write(ifch,20)'droplet:',jc,ep
           write(ifch,30)'string remnant:',ic,a
         endif
 20      format(a,/,'jc:',6i3,' |',6i3,/,'ep:',5(e10.3,1x))
 30      format(a,/,'ic:',i7,' |',i7,/,'a:',5(e10.3,1x))

 1000    continue
         call utprix('getdro',ish,ishini,4)
         end

c------------------------------------------------------------------
         subroutine getdropx(ir,iept,m,ic,jc,jcv,z,ep,a,pass,xmdrmax)
c------------------------------------------------------------------
c  emit a droplet taken into account momentum fraction without screening,
c  update the remnant string flavor and 5-momentum (to be used with iremn=2)
c
c input
c       ir ........ 1  projectile, -1  target remnant
c       iept ...... particle excitation
c       m  ........ remnant index
c       ep ........ remnant  5-momentum
c       jc ........ remnant jc
c       jcv ....... remnant jc valence quark
c       z  ........ Z factor from splitting
c output
c       pass ...  .true. = successful droplet emission
c                            jc, ep ....... droplet  ic and 5-momentum
c                            ic, a ........ remnant string jc and 5-momentum
c                 .false. = unsuccessful
c                            jc, ep .... unchanged,
c                            considered as droplet jc and 5-momentum
c-----------------------------------------------------------------

        include 'epos.inc'
        include 'epos.incems'
        double precision ep(5),a(5),p1(5),re(5),eps,amasex,xmdrmax
        double precision xxx,rr,alpm,p5sq,xmin,xmax,ampt2str,xmsmax
     &  ,sxini,strmas,xxxmax,xxxmin,ampt2dro,xmdrmaxi,xprmi,xmrmi
     &  ,xprmd,xmrmd,xprms,xmrms,xpti,ypti,xptd,yptd,xpts,ypts,xptt,yptt
        double precision om1xpr,xremd,xrems,freduc
     &       ,atil(ntymi:ntymx),btilp(ntymi:ntymx),btilpp(ntymi:ntymx)
        parameter(eps=1.d-20)
        integer jc(nflav,2),jcv(nflav,2),ic(2),icx(2)
        integer jcvini(nflav,2),jcini(nflav,2)
     &         ,jcfin(nflav,2),jcvfin(nflav,2)
        logical pass
        common/cems5/plc,s
        double precision s,plc,ptm,qcm,u(3),utpcmd,ptt,drangen,phi
        logical strcomp,valqu

        call utpri('getdrx',ish,ishini,4)
        iret=0
        xmdrmaxi=min(100.d20,xmdrmax)
        pass=.true.
        idps=0
        idms=0
        do i=1,nflav
          jcfin(i,1)=0
          jcfin(i,2)=0
          jcvfin(i,1)=0
          jcvfin(i,2)=0
          jcini(i,1)=jc(i,1)
          jcini(i,2)=jc(i,2)
          jcvini(i,1)=jcv(i,1)
          jcvini(i,2)=jcv(i,2)
        enddo

        call idquacjc(jcini,nqu,naq)
        call idquacjc(jcvini,nqv,nav)

        do i=1,5
          a(i)=0.d0
          re(i)=0.d0
        enddo
        nqc=jcini(4,1)+jcini(4,2)

        idrf=0
        if(nqu-naq.ne.0)idrf=1
        if(ir.eq.1)then
           iclpt=iclpro
           if(idrf.eq.0)idrf=idp(m)  !change it only if not 1
           xprmi=xpp(m)
           xmrmi=xmp(m)
           xpti=xxp(m)
           ypti=xyp(m)
           if(lproj3(m).gt.0)then
             nlnk=max(1,nint(z*float(lproj3(m))))
           else
             nlnk=0
           endif
        else
           iclpt=icltar
           if(idrf.eq.0)idrf=idt(m)  !change it only if not 1
           xprmi=xmt(m)
           xmrmi=xpt(m)
           xpti=xxt(m)
           ypti=xyt(m)
           if(ltarg3(m).gt.0)then
             nlnk=max(1,nint(z*float(ltarg3(m))))
           else
             nlnk=0
           endif
         endif
         nlnk=0        !force 2 bodies decay

         if(ish.ge.5)then
           write(ifch,10)'remnant flavor and 5-momentum:'
     &                    ,jc,jcv,ep,nqu,naq,nqv,nav,nqc,idrf,iept,nlnk
 10        format(a,/,'jc:',6i3,' |',6i3,/,'jcv:',6i3,' |',6i3,/
     &            ,'ep:',5(e10.3,1x),/,8i4)
         endif

c check formation conditions

         strcomp=.false.
         valqu=.false.    !if true, valence quark will always be in strings : reduce lambda production
c         if((nqu.eq.3.and.naq.eq.0).or.(nqu.eq.0.and.naq.eq.3)
c     &          .or.(nqu.eq.1.and.naq.eq.1).and.nlnk.ne.0)then 
c not enough quark for the droplet, check mass
           if(iept.ne.5.and.ep(5)*ep(5).lt.xmdrmax.and.nqc.eq.0)then
             pass=.false.       !continue without droplet
             if(ish.ge.4)write(ifch,*)
     &      'Normal remnant in Getdropx, continue only with droplet ...'
             goto 1000
           endif
c create q-aq from sea (but no charm)
         if(nlnk.ne.0)then 
           do n=1,nlnk
             idum=idrafl(iclpt,jcini,1,'r',3,iret)
             nqu=nqu+1
             naq=naq+1
           enddo
           strcomp=.true.
           valqu=.false.
         elseif(mod(nqu-naq,3).ne.0)then
           call utstop('This should not happen (getdropx) !&')
         endif

c  get id of string ends, the remnant string jc is updated

c First remove all charm

         if(nqc.ne.0.and.jcini(4,1)-jcini(4,2).eq.0)then !if c-cbar

           if(jcini(4,1).eq.1)then
             idps=1
             idms=1
           else
             call utstop('getdropx can not manage more than c-cb !&')
           endif

         elseif(nqc.ne.0.and.jcini(4,1)*jcini(4,2).ne.0)then

           call utstop('getdropx can not manage c quarks this way !&')

         else


           if(nqc.ne.0)then !if some charm take it out
             if(jcini(4,1).ne.0)then
               if(nqu.lt.3)then
                 idrf=0         !can not use c in antibaryon
               elseif(jcini(4,1).gt.1)then
                 idrf=1         !more than 1 c quark only in baryon
               endif
             elseif(jcini(4,2).ne.0)then
               if(naq.lt.3)then
                 idrf=0         !can not use cb in baryon
               elseif(jcini(4,2).gt.1)then
                 idrf=1         !more than 1 c antiquark only in antibaryon
               endif
             endif
             if(idrf.ne.0.and.jcini(4,1).gt.0.and.jcini(4,1).le.3)then
               idps=5
               idms=1
         elseif(idrf.ne.0.and.jcini(4,2).gt.0.and.jcini(4,2).le.3)then
               idps=1
               idms=5
             elseif(jcini(4,1).gt.1.or.jcini(4,2).gt.1)then
               call utstop('getdropx can not use more than 3 c/cb !&')
             endif
           endif

c take into account number of diquark in final remnant string

           if(idps.eq.0)then

             if(idrf.ne.0)then  !use a diquark
               if(nqu.gt.naq)then        !qq-q
                 idps=5
                 idms=1
               elseif(nqu.lt.naq)then    !qbqb-qb
                 idps=1
                 idms=5
               endif
             else               !q-qb
               idps=1
               idms=1
             endif

           endif

         endif                  !string end type

         if(ish.ge.5)then
           write(ifch,*)'remnant string ends :',idps,idms
         endif

c choose flavor with priority to valence quark (after charm)

          if(idps.ne.5.and.idms.ne.5)then              ! q-aq string
            j=1
            if(jcini(4,j).gt.0)then
              i=4
              jcini(i,j)=jcini(i,j)-1
              if(jcvini(i,j).gt.0)then
                jcvfin(i,j)=jcvfin(i,j)+1
                jcvini(i,j)=jcvini(i,j)-1
                nqv=nqv-1
              endif
            elseif(valqu.and.nqv.gt.0)then
              i=idraflz(jcvini,j)
              jcvfin(i,j)=jcvfin(i,j)+1
              jcini(i,j)=jcini(i,j)-1
              nqv=nqv-1
            else
              i=idrafl(iclpt,jcini,j,'v',1,iret)
              if(jcini(i,j)-jcvini(i,j).lt.0)then
                jcvini(i,j)=jcvini(i,j)-1
                jcvfin(i,j)=jcvfin(i,j)+1
              endif
            endif
            ifq=i
            j=2
            if(jcini(4,j).gt.0)then
              i=4
              jcini(i,j)=jcini(i,j)-1
              if(jcvini(i,j).gt.0)then
                jcvfin(i,j)=jcvfin(i,j)+1
                jcvini(i,j)=jcvini(i,j)-1
                nav=nav-1
              endif
            elseif(valqu.and.nav.gt.0)then
              i=idraflz(jcvini,j)
              jcvfin(i,j)=jcvfin(i,j)+1
              jcini(i,j)=jcini(i,j)-1
              nav=nav-1
            else
              i=idrafl(iclpt,jcini,j,'v',1,iret)
              if(jcini(i,j)-jcvini(i,j).lt.0)then
                jcvini(i,j)=jcvini(i,j)-1
                jcvfin(i,j)=jcvfin(i,j)+1
              endif
            endif
            ifa=i
            jcfin(ifq,1)=1
            jcfin(ifa,2)=1

          elseif(idps.eq.5)then                       ! qq-q string
            j=1
            do ik=1,3
              if(jcini(4,j).ne.0)then
                i=4
                jcini(i,j)=jcini(i,j)-1
                if(jcvini(i,j).gt.0)then
                  jcvfin(i,j)=jcvfin(i,j)+1
                  jcvini(i,j)=jcvini(i,j)-1
                  nqv=nqv-1
                endif
              elseif(valqu.and.nqv.gt.0)then
                i=idraflz(jcvini,j)
                jcvfin(i,j)=jcvfin(i,j)+1
                jcini(i,j)=jcini(i,j)-1
                nqv=nqv-1
              else
                i=idrafl(iclpt,jcini,j,'v',1,iret)
                if(jcini(i,j)-jcvini(i,j).lt.0)then
                  jcvini(i,j)=jcvini(i,j)-1
                  jcvfin(i,j)=jcvfin(i,j)+1
                endif
              endif
              jcfin(i,j)=jcfin(i,j)+1
            enddo

          elseif(idms.eq.5)then                        !aqaq-aq string
            j=2
            do ik=1,3
              if(jcini(4,j).gt.0)then
                i=4
                jcini(i,j)=jcini(i,j)-1
                if(jcvini(i,j).gt.0)then
                  jcvfin(i,j)=jcvfin(i,j)+1
                  jcvini(i,j)=jcvini(i,j)-1
                  nav=nav-1
                endif
              elseif(valqu.and.nav.gt.0)then
                i=idraflz(jcvini,j)
                jcvfin(i,j)=jcvfin(i,j)+1
                jcini(i,j)=jcini(i,j)-1
                nav=nav-1
              else
                i=idrafl(iclpt,jcini,j,'v',1,iret)
                if(jcini(i,j)-jcvini(i,j).lt.0)then
                  jcvini(i,j)=jcvini(i,j)-1
                  jcvfin(i,j)=jcvfin(i,j)+1
                endif
              endif
              jcfin(i,j)=jcfin(i,j)+1
            enddo

          endif

          if(iret.ne.0)call utstop('Not enough quark in getdropx ???&')
          if(jcini(4,1)+jcini(4,2).ne.0)
     &         call utstop('There is sitll charm quark in getdropx???&')

c string id

         call idenco(jcfin,icx,iret)
         if(iret.eq.1)then
           call utstop('Exotic flavor in getdropx !&')
         endif


c boost remnant in rest frame
      if(ish.ge.6) write (ifch,*) 'on-shell check'
        do k=1,5
          p1(k)=ep(k)
        enddo
        p1(5)=(p1(4)-p1(3))*(p1(4)+p1(3))-p1(2)**2-p1(1)**2
        if(p1(5).gt.0d0.and.abs(p1(5)-ep(5)*ep(5)).lt.ep(5))then
          p1(5)=sqrt(p1(5))
        else
          if(ish.ge.2)write(ifch,*)'Precision problem in getdropx, p:',
     &             (p1(k),k=1,5),ep(5)*ep(5)
          p1(5)=ep(5)
          p1(4)=sqrt(p1(3)*p1(3)+p1(2)*p1(2)+p1(1)*p1(1)+p1(5)*p1(5))
        endif

c limits for momenta

      mamod=4
      mamos=4
      fad=alpdro(1)
      fad=max(1.5,fad*(1.+z*zdrinc))
      ptm=p1(5)
      amasex=dble(fad*utamnz(jcini,mamod))
      fas=2.
      strmas=dble(fas*utamnz(jcfin,mamos))
      ampt2dro=amasex**2d0
      ampt2str=strmas**2d0
      if(ampt2dro.gt.xmdrmaxi)then
        xmdrmaxi=2d0*ampt2dro
c       write(ifmt,*)'Warning Mmin>Mmax in Getdropx'
      endif


c redo

       xxxmin=1d0-xprmi
       if(xxxmin.gt.ampt2dro/(s*xmrmi))then
         xmrmd=ampt2dro/(s*xxxmin)
       else
         nlnk=0
       endif
       nredo=-1
       freduc=1d0
 777   continue
       nredo=nredo+1
       if(strcomp.and.nredo.eq.20)then  !after 19 try and remnant compatible with a string
         pass=.false.         !continue without droplet
         if(ish.ge.4)write(ifch,'(a,2i3,4e12.5)')
     &     'Pb with splitting in Getdropx, continue without split ...'
     &     ,nlnk,nvirt,xxxmax,xxxmin,ep(5)**2,xmdrmax
         goto 1000
       elseif(nredo.eq.10.or.nredo.eq.26)then        !reduce minimum mass
          amasex=1.5d0*dble(utamnz(jcini,mamod))
          strmas=1.5d0*dble(utamnz(jcfin,mamos))
          ampt2dro=amasex**2d0
          ampt2str=strmas**2d0
          xmrmd=ampt2dro/(s*xxxmin)
       elseif(nredo.eq.20)then    !after 19 try, use 2 body decay
         xmrmd=1d0+xmrmi
         if(ish.ge.4)write(ifch,*)
     &     'nredo>20, use 2 body decay ...',nvirt,xxxmax,xxxmin
         amasex=dble(fad*utamnz(jcini,mamod))
         strmas=dble(fas*utamnz(jcfin,mamos))
         ampt2dro=amasex**2d0
         ampt2str=strmas**2d0
         if(ish.ge.6) write (ifch,*) 'boost vector:',p1
       elseif(nredo.ge.30)then
          !write(ifch,*)'nredo.gt.20 -> only drop'
         if(ish.ge.4)write(ifch,*)
     &    'Pb with string mass in Getdropx, continue without split ...'
          pass=.false.
         goto 1000
       endif

       if(xmrmd.lt.xmrmi.and.nlnk.gt.0)then        !kinetic compatibility

         xmrms=xmrmi-xmrmd

c fix the virtual number of collision (no screening)
         iscreensave=iscreen
         iscreen=0
         imin=ntymin
         imax=ntymx
         if(iomega.eq.2)imax=1
         spp=sngl(s)
         nvirt=0
         xxxmax=0d0
         xpts=0d0
         ypts=0d0
         if(ir.eq.1)then
           do l=1,lproj3(m)    !use all pairs attached to remnant
             kp=kproj3(m,l)
             nvirt=nvirt+1
             do i=imin,imax
               call Gfunpar(0.,0.,1,i,bk(kp),spp,alp,bet,betp,epsp,epst
     &                                                       ,epss,gamv)
               atil(i)=dble(alp)
               btilp(i)=dble(bet)
               btilpp(i)=dble(betp)
             enddo
             xprms=1d0-xxxmax
c take x from an "unscreened" Pomeron (reduction factor if too high)
             xxx=om1xpr(atil,btilp,btilpp,xprms,xmrmi,ir)*freduc
             ptt=dble(ranptcut(1.)*alpdro(2))
c             ptt=dble(ranptcut(ptsems)*alpdro(2))
             phi=2d0*dble(pi)*drangen(ptt)
             xprms=1d0-xxxmax-xxx
             xptt=xpts+ptt*cos(phi)
             yptt=ypts+ptt*sin(phi)
             xrems=xprms*xmrms*s-(xpti+xptt)**2-(ypti+yptt)**2
             if(xrems.gt.ampt2str)then
               xxxmax=xxxmax+xxx
               xpts=xptt
               ypts=yptt
             endif
           enddo
         else
           do l=1,ltarg3(m)    !use all pairs attached to remnant
             kt=ktarg3(m,l)
             nvirt=nvirt+1
             do i=imin,imax
               call Gfunpar(0.,0.,1,i,bk(kt),spp,alp,bet,betp,epsp,epst
     &                                                       ,epss,gamv)
               atil(i)=dble(alp)
               btilp(i)=dble(bet)
               btilpp(i)=dble(betp)
             enddo
             xprms=1d0-xxxmax
c take x from an "unscreened" Pomeron (reduction factor if too high)
            xxx=om1xpr(atil,btilp,btilpp,xprms,xmrmi,ir)*freduc
             ptt=dble(ranptcut(1.)*alpdro(2))
c             ptt=dble(ranptcut(ptsems)*alpdro(2))
             phi=2d0*dble(pi)*drangen(ptt)
             xprms=1d0-xxxmax-xxx
             xptt=xpts+ptt*cos(phi)
             yptt=ypts+ptt*sin(phi)
             xrems=xprms*xmrms*s-(xpti+xptt)**2-(ypti+yptt)**2
             if(xrems.gt.ampt2str)then
               xxxmax=xxxmax+xxx
               xpts=xptt
               ypts=yptt
             endif
           enddo
         endif
         iscreen=iscreensave

         if(xxxmax.le.xxxmin)goto 777


c check string mass and energy

         xprms=1d0-xxxmax
         xpts=xpti+xpts
         ypts=ypti+ypts
         xrems=xprms*xmrms*s-xpts*xpts-ypts*ypts
         if(xrems.lt.ampt2str)then
           if(ish.ge.4)write(ifch,*)
     &          'Pb with string mass in Getdropx, retry',nredo,ir
     &          ,ampt2str,xrems,xprms,xmrms,xpts,ypts
           goto 777
         endif

c check droplet mass and energy

c Droplet mass should not exceed to much mdrmaxi. Use random to smooth distrib.
         xmsmax=xmdrmaxi*(1.+drangen(xmdrmaxi))
         xprmd=xprmi-xprms
         xptd=xpti-xpts
         yptd=ypti-ypts
         xremd=xprmd*xmrmd*s-xptd*xptd-yptd*yptd
         if(xremd.lt.ampt2dro)then
c Droplet should not have a mass too low.
           if(ish.ge.4)write(ifch,*)
     &          'Pb with drop mass (low) in Getdropx, retry',nredo,ir
     &          ,ampt2dro,xremd,xprmd,xmrmd,xptd,yptd
           goto 777
         elseif(xremd.ge.xmsmax)then
c Droplet should not have a mass too high.
           if(ish.ge.4)write(ifch,*)
     &          'Pb with drop mass (high) in Getdropx, retry',nredo,ir
     &          ,xremd,xmsmax,xprmd,xmrmd,xptd,yptd
           freduc=freduc*0.5d0
           goto 777
         endif


         re(1)=xptd
         re(2)=yptd
         if(ir.eq.1)then
           re(3)=(xprmd-xmrmd)*plc*0.5d0
         else
           re(3)=(xmrmd-xprmd)*plc*0.5d0
         endif
         re(4)=(xprmd+xmrmd)*plc*0.5d0
         re(5)=sqrt(xremd)

         a(1)=xpts
         a(2)=ypts
         if(ir.eq.1)then
           a(3)=(xprms-xmrms)*plc*0.5d0
         else
           a(3)=(xmrms-xprms)*plc*0.5d0
         endif
         a(4)=(xprms+xmrms)*plc*0.5d0
         a(5)=sqrt(xrems)



       else                     !if xm to small, use two body decay (should be rare if not forced)

         if(ish.ge.6)write (ifch,*)'kinematic limit -> boost vector:',p1

c fix pt

          sxini=ptm*ptm
          ptt=dble(ranpt()*alpdro(2))**2         !pt
          if(ptt.ge.sxini)goto 777
          sxini=sqrt(sxini-ptt)



          xmsmax=xmdrmaxi*(1.+drangen(xmdrmaxi))
          xxxmax=min(xmsmax,(sxini-strmas)**2)    !strmas/(strmas+ampt2)
          xxxmin=ampt2dro

          if(xxxmin.gt.xxxmax)then
            !write(ifch,*)'Warning Mmin>sxini -> only drop'
           if(ish.ge.4)write(ifch,*)
     &     'Pb with ampt2 in Getdropx, retry',nredo,ir
     &             ,ampt2dro,ampt2str,xxxmin,xxxmax,sxini,ptt,xmsmax
            goto 777
          endif



c fix mass

            rr=drangen(xxxmax)
            xmax=xxxmax
            xmin=xxxmin
            alpm=dble(alpdro(3))
            if(dabs(alpm-1.d0).lt.eps)then
              xxx=xmax**rr*xmin**(1d0-rr)
            else
              xxx=(rr*xmax**(1d0-alpm)+(1d0-rr)*xmin**(1d0-alpm))
     &                                                **(1d0/(1d0-alpm))
            endif


c        write(ifch,*)'ini',xmin,xxx,xmax,rr,ampt2dro
c     &                   ,(sxini-sqrt(xxx)),ampt2str,p1(5)



          re(5)=sqrt(xxx)
          a(5)=sxini-re(5)
          if(a(5).lt.strmas)then
            if(ish.ge.6)write(ifch,*)
     &           'Pb with initial mass in Getdropx, retry',ir
     &       ,xmin,xxx,xmax,rr,ampt2dro,ampt2str,a(5)
            goto 777
          endif


c two body decay
          if(ish.ge.6)write(ifch,*)'2 body decay',ptm,re(5),a(5)
          qcm=utpcmd(ptm,re(5),a(5),iret)
c--------------------------------------------
          u(3)=-1.d0 !-drangen(qcm) !2.d0*drangen(qcm)-1.d0   !always forward
c          u(3)=2.d0*drangen(qcm)-1.d0
c--------------------------------------------
c          phi=2.d0*dble(pi)*drangen(u(3))
c          u(1)=sqrt(1.d0-u(3)**2)*cos(phi)
c          u(2)=sqrt(1.d0-u(3)**2)*sin(phi)
c          do j=1,3
c            re(j)=qcm*u(j)
c            a(j)=-re(j)
c         enddo
c--------------------------------------------
          re(1)=0d0
          a(1)=0d0
          re(2)=0d0
          a(2)=0d0
          if(u(3).lt.0d0)then
            do j=3,3
              re(j)=qcm
              a(j)=-re(j)
            enddo
          else
            do j=3,3
              a(j)=qcm
              re(j)=-a(j)
            enddo
          endif
c--------------------------------------------

          re(4)=sqrt(qcm**2+re(5)**2)
          a(4)=sqrt(qcm**2+a(5)**2)

          if(ish.ge.6)write(ifch,*)'momentum in rest frame : ',re,a



c Fix a of string

c boost string in collision frame
        call utlob2(-1,p1(1),p1(2),p1(3),p1(4),p1(5)
     $       ,a(1),a(2),a(3),a(4),73)

         p5sq=(a(4)+a(3))*(a(4)-a(3))-(a(1)**2.d0+a(2)**2.d0)
         if(p5sq.gt.ampt2str)then
           a(5)=sqrt(p5sq)
         else
           if(ish.ge.6)then
             write(ifch,*)'Pb with string mass -> retry'
             write(ifch,*)'   m^2:',p5sq,'  m_min^2:',ampt2str
             write(ifch,*)'   momentum four vector:',(a(ii),ii=1,4)
           endif
           goto 777
         endif

c Fix ep of droplet

c boost droplet in collision frame
        call utlob2(-1,p1(1),p1(2),p1(3),p1(4),p1(5)
     $       ,re(1),re(2),re(3),re(4),74)

         p5sq=(re(4)+re(3))*(re(4)-re(3))-(re(1)*re(1)+re(2)*re(2))
         if(p5sq.gt.ampt2dro)then
           re(5)=sqrt(p5sq)
         else
           if(ish.ge.6)then
             write(ifch,*)'Pb with droplet mass -> retry'
             write(ifch,*)'   m^2:',p5sq,'  m_min^2:',ampt2dro
             write(ifch,*)'   momentum four vector:',(re(ii),ii=1,4)
           endif
           goto 777
         endif

       endif     !test of xm


       if(ish.ge.1.and.abs(ep(4)-re(4)-a(4)).gt.1.e-2*ep(4))then
         write(ifmt,*)'Pb with energy conservation in getdropx'
         if(ish.ge.6)then
           write(ifch,*)'Pb with energy conservation :'
           write(ifch,*)'   p1_ini:',ep(1),'  p1:',re(1)+a(1)
           write(ifch,*)'   p2_ini:',ep(2),'  p2:',re(2)+a(2)
           write(ifch,*)'   p3_ini:',ep(3),'  p3:',re(3)+a(3)
         endif
       endif

c If OK, save flavors of droplet and string
         do i=1,5
           ep(i)=re(i)
         enddo
         ic(1)=icx(1)
         ic(2)=icx(2)
         do i=1,nflav
           jc(i,1)=jcini(i,1)
           jc(i,2)=jcini(i,2)
           jcv(i,1)=jcvfin(i,1)
           jcv(i,2)=jcvfin(i,2)
         enddo

         if(ish.ge.6)then
           write(ifch,20)'droplet:',jc,ep
           write(ifch,30)'string remnant:',ic,a
           write(ifch,'(a)')'valence:'
           write(ifch,'(6i3,4x,6i3)')jcv
         endif
 20      format(a,/,'jc:',6i3,' |',6i3,/,'ep:',5(e10.3,1x))
 30      format(a,/,'ic:',i7,' |',i7,/,'a:',5(e10.3,1x))

 1000    continue
         call utprix('getdrx',ish,ishini,4)
         end

c-----------------------------------------------------
       subroutine neworder(n1, n2, n3)
c-----------------------------------------------------
c make 3 integers ordered like 1 2 3
c------------------------------------------------------
            if(n2.lt.n1)then
              ifb=n2
              n2=n1
              n1=ifb
            endif
            if(n3.lt.n1)then
              ifb=n3
              n3=n2
              n2=n1
              n1=ifb
            elseif(n3.lt.n2)then
              ifb=n3
              n3=n2
              n2=ifb
            endif
         end

c-----------------------------------------------------
       subroutine neworderx(x1,x2,x3,i1,i2,i3)
c-----------------------------------------------------
c make 3 reals ordered like 1 2 3
c------------------------------------------------------
            if(x2.lt.x1)then
              xfb=x2
              x2=x1
              x1=xfb
              ifb=i2
              i2=i1
              i1=ifb
            endif
            if(x3.lt.x1)then
              xfb=x3
              x3=x2
              x2=x1
              x1=xfb
              ifb=i3
              i3=i2
              i2=i1
              i1=ifb
            elseif(x3.lt.x2)then
              xfb=x3
              x3=x2
              x2=xfb
              ifb=i3
              i3=i2
              i2=ifb
            endif
         end

c-----------------------------------------------------------------------
      function idtr2(ic)
c-----------------------------------------------------------------------
c transforms ic to id such that only hadrons have nonzero id
c-----------------------------------------------------------------------
      parameter (nidt=30)
      integer idt(3,nidt),ic(2)
      data idt/
     * 100000,100000, 110   ,100000,010000, 120   ,010000,010000, 220
     *,100000,001000, 130   ,010000,001000, 230   ,001000,001000, 330
     *,100000,000100, 140   ,010000,000100, 240   ,001000,000100, 340
     *,000100,000100, 440
     *,300000,000000,1111   ,210000,000000,1120   ,120000,000000,1220
     *,030000,000000,2221   ,201000,000000,1130   ,111000,000000,1230
     *,021000,000000,2230   ,102000,000000,1330   ,012000,000000,2330
     *,003000,000000,3331   ,200100,000000,1140   ,110100,000000,1240
     *,020100,000000,2240   ,101100,000000,1340   ,011100,000000,2340
     *,002100,000000,3340   ,100200,000000,1440   ,010200,000000,2440
     *,001200,000000,3440   ,000300,000000,4441/

      idtr2=0
      if(ic(1).eq.0.and.ic(2).eq.0)then
       if(rangen().ge.0.5)then
        idtr2=110
        ic(1)=100000
        ic(2)=100000
       else
        idtr2=220
        ic(1)=10000
        ic(2)=10000
       endif
       return
      endif
      do 1 i=1,nidt
       if(ic(2).eq.idt(1,i).and.ic(1).eq.idt(2,i))idtr2=-idt(3,i)
       if(ic(1).eq.idt(1,i).and.ic(2).eq.idt(2,i))idtr2=idt(3,i)
 1    continue
      return
      end

c----------------------------------------------------------------------
      subroutine emsini(e,idpji,idtgi)
c----------------------------------------------------------------------
c  energy-momentum sharing initializations
c----------------------------------------------------------------------
      include 'epos.inc'
      include 'epos.incems'
      include 'epos.incsem'
      common/cemsr5/at(0:1,0:5)
      common/cems5/plc,s
      common/cems10/a(0:ntypmx),b(0:ntypmx),d(0:ntypmx)
      common/ems6/ivp0,iap0,idp0,isp0,ivt0,iat0,idt0,ist0
      double precision d,a,b,plc,s,amd,dcel,xvpr,xdm,at,xdm2
      common/ems3/dcel,ad
      common/cems13/xvpr(0:3)


c parameter test

      if(nflavems.lt.nrflav)
     &   call utstop("nflavems<nrflav : change it in epos-ems !&")


c abreviations

      plc=dble(e)
      s=plc**2
      amd=0.5d0   !dble(delrex) !(large enough in case of strangeness in string end


c alpha (0=0, 1=s, 2=v, 4=d, 8=f)

      a(0)=0d0
      a(1)=dble(alpsea)
      a(2)=dble(alpval)
      a(3)= 0.0d0
      a(4)=dble(alpdiq)
      a(5)=dble(a(4))
      a(6)= 0.0d0
      a(7)= 0.0d0
      a(8)=dble(a(2))
      a(9)= 0.0d0

c beta (0=0, 1=s, 2=v, 4=d, 8=f)

      b(0)=0.0d0
      b(1)=dble(-alpqua)
      b(2)=dble(-alpqua)
      b(3)=0.0d0
      b(4)=0.0d0
      b(5)=0.0d0
      b(6)=0.0d0
      b(7)=0.0d0
      b(8)=dble(-alpqua)
      b(9)=0.0d0


c alpha_trailing and beta_trailing (0=meson, 1=baryon;
c                                   0=no excit, 1=nondiffr, 2=diffr,
c                                   3=nondiffr split, 5=diffr split)

      at(0,0)=0.0d0
      at(0,1)=dble(alpndi(1))
      at(0,2)=dble(alpdi(1))
      at(0,3)=dble(alpdro(3))
      at(0,4)=4d0 !dble(alpndi(1))
      at(0,5)=dble(alpdro(3))
      at(1,0)=0.0d0
      at(1,1)=dble(alpndi(2))
      at(1,2)=dble(alpdi(2))
      at(1,3)=dble(alpdro(3))
      at(1,4)=4d0!dble(alpndi(2))
      at(1,5)=dble(alpdro(3))

c minimal string masses ( i+j, each one: 0=0, 1=s, 2=v, 4=d, 5=d, 8=f)

      ammn(0)=0d0
      ammn(1)=0d0
      ammn(2)=dble(ammsqq)+amd
      ammn(3)=dble(ammsqq)
      ammn(4)=dble(ammsqq)
      ammn(5)=dble(ammsqd)+amd
      ammn(6)=dble(ammsqd)+amd
      ammn(7)=0d0
      ammn(8)=dble(ammsdd)+amd
      ammn(9)=dble(ammsqd)+amd
      ammn(10)=dble(ammsqd)+amd
      ammn(12)=dble(ammsqd)+amd
      ammn(16)=0.14d0

c minimal pomeron masses (0=soft or gg, 1=qg, 2=gq, 3=qq)

      amprmn(0)=ammsqq
      amprmn(1)=dsqrt(4d0*dble(q2min))
      amprmn(2)=amprmn(1)
      amprmn(3)=amprmn(1)

c cutoff for virtual pomeron (0=0, 1=soft Pom, 2=regge, 3=hard)

c      xvpr(0)=0d0
c      xvpr(1)=dble(cumpom**2)/s
c      xvpr(2)=dble(cumpom**2)/s
c      xvpr(3)=0.0d0**2/s

c minimal remnant masses (0=meson, 1=baryon)

      idpj=idpji
      xdm=0.35d0                  !<pt>
      call idmass(idpj,ampj)
      if(iabs(idpj).gt.1000)then
       ampmn(0)=0.14d0+xdm
       ampmn(1)=dble(ampj)+xdm
      else
       ampmn(0)=dble(ampj)+xdm
       ampmn(1)=0.94d0+xdm
      endif
      idtg=idtgi
      if(idtg.eq.0)idtg=1120
      call idmass(idtg,amtg)
      if(iabs(idtg).gt.1000)then
       amtmn(0)=0.14d0+xdm
       amtmn(1)=dble(amtg)+xdm
      else
       amtmn(0)=dble(amtg)+xdm
       amtmn(1)=0.94d0+xdm
      endif

c minimal excitation masses (0=meson, 1=baryon
c                            0=no excit, 1=nondiffr, 2=diffr,
c                                   6=nondiffr but no pomeron)

      xdm2=0.35d0
      amemn(0,0)=0.d0
      amemn(1,0)=0.d0
      amemn(0,4)=0.d0
      amemn(1,4)=0.d0
      amemn(0,6)=0.d0
      amemn(1,6)=0.d0

      amemn(0,1)=xdm2!+dble(delrex)
      amemn(0,2)=2d0*xdm2!+dble(delrex)
      amemn(0,3)=2d0*xdm2!+dble(delrex)
      amemn(0,5)=2d0*(xdm2+dble(delrex)) !remnant excited with qq-aqaq

      amemn(1,1)=xdm2!+dble(delrex)
      amemn(1,2)=xdm2!+dble(delrex)
      amemn(1,3)=2d0*xdm2!+dble(delrex)
      amemn(1,5)=2d0*(xdm2+dble(delrex)) !remnant excited with qq-aqaq

c maximal excitation masses (0=no excit, 1=nondiffr, 2=diffr)

      amemx(0)=2d0*xdm
      amemx(1)=plc
      amemx(2)=plc

      if(idpj.gt.1000)then     ! baryon

c initial quark configuration
       ivp0=3
       iap0=0
       idp0=1
       isp0=1

c no val quark for exotic projectile
       if(iremn.ge.2.and.(idpj.ne.1120.and.idpj.ne.1220))ivp0=0

      elseif(idpj.lt.-1000)then     ! antibaryon

c initial quark configuration
       ivp0=0
       iap0=3
       idp0=1
       isp0=1

c no val quark for exotic projectile
       if(iremn.ge.2.and.(idpj.ne.-1120.and.idpj.ne.-1220))iap0=0

      else      ! meson

c initial quark configuration
       ivp0=1
       iap0=1
       idp0=0
       if(iclpro.eq.1)then
         isp0=0
       else
         isp0=1
       endif

c no val quark for exotic projectile
       if(iremn.ge.2.and.(mod(abs(idpj/100),10).gt.4
     &                 .or.mod(abs(idpj/10),10).gt.4
     &    .or.mod(abs(idpj/100),10)/mod(abs(idpj/10),10).eq.1))then
         ivp0=0
         iap0=0
       endif
      endif

      if(idtg.gt.1000)then    ! baryon

c initial quark configuration
       ivt0=3
       iat0=0
       idt0=1
       ist0=0

c no val quark for exotic target
       if(iremn.ge.2.and.(idtg.ne.1120.and.idtg.ne.1220))ivt0=0

      elseif(idtg.lt.-1000)then   ! antibaryon

c initial quark configuration
       ivt0=0
       iat0=3
       idt0=1
       ist0=0

c no val quark for exotic target
       if(iremn.ge.2.and.(idtg.ne.-1120.and.idtg.ne.-1220))iat0=0

      else       ! meson

c initial quark configuration
       ivt0=1
       iat0=1
       if(icltar.eq.1)then
         idt0=0
       else
         idt0=1
       endif
       ist0=0

c no val quark for exotic target
       if(iremn.ge.2.and.(mod(abs(idtg/100),10).gt.4
     &                 .or.mod(abs(idtg/10),10).gt.4
     &    .or.mod(abs(idtg/100),10)/mod(abs(idtg/10),10).eq.1))then
         ivt0=0
         iat0=0
       endif

      endif


c eikonal parameters

       dcel=dble(chad(iclpro)*chad(icltar))

c counters

      if(.not.chargex)then
       antot=0.
       ansh=0.
       ansf=0.
       antotf=0.
       anshf=0.
       ansff=0.
       pp4max=0.
       pp4ini=0.
       andropl=0.
       anstrg0=0.
       anstrg1=0.
       anreso0=0.
       anreso1=0.
       anghadr=0.
       antotre=0.
       anintdiff=0.
       anintsdif=0.
       anintddif=0.
       anintine=0.
      endif

      return
      end

c-----------------------------------------------------------------------
      subroutine emsigr
c-----------------------------------------------------------------------
c initialize grid
c-----------------------------------------------------------------------

      include 'epos.inc'
      include 'epos.incems'

      common/emsptl/nppr(npommx,kollmx),npproj(mamx),nptarg(mamx)

      call utpri('emsigr',ish,ishini,5)

      do k=1,koll  !----k-loop---->

c determine length of k-th line of grid

       o=max(1.e-5,min(sngl(om1intc(k)),float(npommx)))!if GFF used for propo
        if(ish.ge.7)write(ifch,*)'emsigr:k,o',k,o
       n=0
       if(o.le.50)then
         p=1./(exp(o)-1)
       else
         p=0.
       endif
10     n=n+1
       p=p*o/n
        if(ish.ge.7)write(ifch,*)'emsigr:n,p',n,p
       if((p.gt.1e-4.or.n.lt.int(o)).and.n.lt.npommx
     *.and.n.lt.nprmax)goto 10

       if(ish.ge.5)write(ifch,*)'emsigr:nmax,b',n,bk(k)

       npr(0,k)=n
       nprmx(k)=n
       nprt(k)=0
       do i=1,3
        npr(i,k)=0
       enddo


c initial value for interaction type

       itpr(k)=0

c initial value for nuclear splitting

       do ir=1,2
         knucnt(ir,k)=0
         do ncon=1,mamx
           npnuc(ncon,ir,k)=0
           irnuc(ncon,ir,k)=0
           xxnuc(ncon,ir,k)=0d0
         enddo
       enddo

c initialize grid


       do n=1,nprmx(k)
        call conigr(n,k)
        idpr(n,k)=0
        idfpr(n,k)=0
        ivpr(n,k)=1
        nppr(n,k)=0
        nbkpr(n,k)=0
        nvpr(n,k)=0
        idsppr(n,k)=0
        idstpr(n,k)=0
        idrpr(n,k)=0
        idhpr(n,k)=0
        bhpr(n,k)=0.
        xpr(n,k)=0d0
        ypr(n,k)=0d0
        xppr(n,k)=0d0
        xmpr(n,k)=0d0
        xp1pr(n,k)=0d0
        xp2pr(n,k)=0d0
        xm1pr(n,k)=0d0
        xm2pr(n,k)=0d0
        xp1pr(n,k)=0d0
        xp2pr(n,k)=0d0
        xm1pr(n,k)=0d0
        xm2pr(n,k)=0d0
        idp1pr(n,k)=0
        idp2pr(n,k)=0
        idm1pr(n,k)=0
        idm2pr(n,k)=0
        xxp1pr(n,k)=0d0
        xyp1pr(n,k)=0d0
        xxp2pr(n,k)=0d0
        xyp2pr(n,k)=0d0
        xxm1pr(n,k)=0d0
        xym1pr(n,k)=0d0
        xxm2pr(n,k)=0d0
        xym2pr(n,k)=0d0
       enddo

      enddo !  <----k-loop-----

      call utprix('emsigr',ish,ishini,5)
      return
      end

c-----------------------------------------------------------------------
      subroutine emsipt
c-----------------------------------------------------------------------
c initialize projectile and target
c-----------------------------------------------------------------------

      include 'epos.inc'
      include 'epos.incems'

      common/emsptl/nppr(npommx,kollmx),npproj(mamx),nptarg(mamx)
      common/cems5/plc,s
      common/ems3/dcel,ad
      common/ems6/ivp0,iap0,idp0,isp0,ivt0,iat0,idt0,ist0

      double precision dcel,s,plc

c initialize projectile

      do i=1,maproj
       idp(i)=idp0
       ivp(i)=ivp0+iap0
       iap(i)=iap0
       isp(i)=isp0
       iep(i)=-1
       ifp(i)=0
       kolp(i)=0
       xkolhp(i)=0d0
       npp(i)=0
       npproj(i)=0
       xxp(i)=0d0
       xyp(i)=0d0
       xpmn(i)=(amemn(idp(i),0)+ampmn(isp(i)))**2/s
       xpmx(i)=dmin1(1d0,(amemx(0)+ampmn(isp(i)))**2/s)
       xpos(i)=0.9d0*(amemx(0)+ampmn(isp(i)))**2/s
       xppmx(i)=0.5d0/(1d0+1d0/dble(maproj)**0.3d0)!1d0-dsqrt(xpmn(i))/maproj
       xmpmx(i)=0.5d0/(1d0+1d0/dble(matarg)**0.3d0)!1d0-dsqrt(xpmn(i))/matarg
       xmpmn(i)=xpmn(i)/xppmx(i)
       xppmn(i)=xpmn(i)/xmpmx(i)
       xpp(i)=1d0
       xmp(i)=0d0
       xppst(i)=0.d0
       xmpst(i)=0.d0
       xposst(i)=0.d0
      enddo

c initialize target

      do j=1,matarg
       idt(j)=idt0
       ivt(j)=ivt0+iat0
       iat(j)=iat0
       ist(j)=ist0
       iet(j)=-1
       ift(j)=0
       kolt(j)=0
       xkolht(j)=0d0
       npt(j)=0
       nptarg(j)=0
       xxt(j)=0d0
       xyt(j)=0d0
       xtmn(j)=(amemn(idt(j),0)+amtmn(ist(j)))**2/s
       xtmx(j)=dmin1(1d0,(amemx(0)+amtmn(ist(j)))**2/s)
       xtos(j)=0.9d0*(amemx(0)+amtmn(ist(j)))**2/s
       xmtmx(j)=0.5d0/(1d0+1d0/dble(matarg)**0.3d0)!1d0-dsqrt(xtmn(j))/matarg
       xptmx(j)=0.5d0/(1d0+1d0/dble(maproj)**0.3d0)!1d0-dsqrt(xtmn(j))/maproj
       xptmn(j)=xtmn(j)/xmtmx(j)
       xmtmn(j)=xtmn(j)/xptmx(j)
       xmt(j)=1d0
       xpt(j)=0d0
       xmtst(j)=0.d0
       xptst(j)=0.d0
       xtosst(j)=0.d0
      enddo

      return
      end


c-----------------------------------------------------------------------
      subroutine emszz
c-----------------------------------------------------------------------
c     completes /cptl/ for nucleons, checks for no interaction
c     writes   /cevt/
c-----------------------------------------------------------------------
      include 'epos.inc'
      include 'epos.incems'
      common/nucl3/phi,bimp
      common/col3/ncol,kolpt
      integer kolpz(mamx),koltz(mamx)

      call utpri('emszz ',ish,ishini,6)

c     write /cptl/
c     ------------

      if(iokoll.eq.1)then   ! precisely matarg collisions

c nothing to do
        ntg=0
        npj=0
        ncoli=0

      else

c determine ncol

       ncolx=ncol
       ncol=0
       ncoli=0
       do 8 k=1,koll
       if(ish.ge.7)write(ifch,*)'k,itpr,ncol,ncolx',k,itpr(k),ncol,ncolx
         if(itpr(k).eq.0)goto 8
         if(abs(itpr(k)).eq.1)ncoli=ncoli+1
         ncol=ncol+1
         if(itpr(k).ne.3)then   !empty pair, remnant not modified
           i=iproj(k)
           j=itarg(k)
           istptl(i)=1
           iorptl(i)=-1
           tivptl(2,i)=coord(4,k)
           istptl(maproj+j)=1
           iorptl(maproj+j)=-1
           tivptl(2,maproj+j)=coord(4,k)
         endif
8      continue
       if(ncolx.ne.ncol)write(6,*)'ncolx,ncol:', ncolx,ncol
       if(ncolx.ne.ncol)call utstop('********ncolx.ne.ncol********&')
       if(ncol.eq.0)goto1001

c determine npj, ntg

       do ip=1,maproj
        kolpz(ip)=0
       enddo
       do it=1,matarg
        koltz(it)=0
       enddo
      do k=1,koll
       if(itpr(k).ne.0.and.itpr(k).ne.3)then
        ip=iproj(k)
        it=itarg(k)
        kolpz(ip)=kolpz(ip)+1
        koltz(it)=koltz(it)+1
       endif
      enddo
      npj=0
      npglb=0
      do ip=1,maproj
       if(kolpz(ip).gt.0.or.iep(ip).ge.3)npj=npj+1
c       if(lproj(ip).eq.0.or.iep(ip).eq.0)
       if(kolpz(ip).eq.0.and.iep(ip).le.0)
     .  npglb=npglb+1
      enddo
      ntg=0
      ntglb=0
      do it=1,matarg
       if(koltz(it).gt.0.or.iet(it).ge.3)ntg=ntg+1
c       if(ltarg(it).eq.0.or.iet(it).eq.0)
       if(koltz(it).eq.0.and.iet(it).le.0)
     .     ntglb=ntglb+1
      enddo
c      write(6,*)'npj,ntg,npj+ntg,npglb,ntglb:'
c     *     ,npj,ntg,npj+ntg,nppglb,npglb,ntglb,ntg+ntglb

       endif

c     write /cevt/
c     ------------

      nevt=1
      bimevt=bimp
      phievt=phi
      kolevt=ncol
      koievt=ncoli
      kohevt=0      !not yet defined
      npjevt=npj
      ntgevt=ntg
      pmxevt=pnll
      egyevt=engy
      !print*,' ===== ',kolevt,koievt' ====='

c     exit
c     ----

      if(ish.ge.7)then
      do n=1,nptl
      write(ifch,115)iorptl(n),jorptl(n),n,istptl(n)
     *,tivptl(1,n),tivptl(2,n)
      enddo
  115 format(1x,'/cptl/',2i6,2i10,2(1x,e10.3))
      endif

1000  continue
      call utprix('emszz ',ish,ishini,6)
      return

1001  continue
      if(ish.ge.3)then
      write(ifch,*)
      write(ifch,*)'   ***** no interaction!!!'
      write(ifch,*)'   ***** ncol=0 detected in emszz'
      write(ifch,*)
      endif
      goto 1000

      end

c-----------------------------------------------------------------------
      subroutine ProCop(i,ii)
c-----------------------------------------------------------------------
c Propose Coordinates of remnants from active projectile nucleons
c-----------------------------------------------------------------------

      include 'epos.inc'
      include 'epos.incems'
      include 'epos.incsem'

      double precision xmptmp,aproj
      common/cems5/plc,s
      common/emsptl/nppr(npommx,kollmx),npproj(mamx),nptarg(mamx)
      integer icrmn(2),jc(nflav,2),icini(2)
      double precision s,plc

      nptl=nptl+1
      npproj(i)=nptl
      idptl(nptl)=idptl(ii)*100+sign(99,idptl(ii))  !100*10**idp(i)+iep(i)
      istptl(nptl)=40
      ityptl(nptl)=40
      iorptl(nptl)=ii
      jorptl(nptl)=0
      ifrptl(1,nptl)=0
      ifrptl(2,nptl)=0
      do j=1,2
        do k=1,nflav
          jc(k,j)=0
        enddo
      enddo

      istptl(ii)=1

c     determine kolz

      if(lproj(i).gt.1)then
        zmax=-ainfin
        kolz=0
        do l=1,lproj(i)
          k=kproj(i,l)
          z=coord(3,k)
          if(itpr(k).ne.0.and.z.gt.zmax)then
            zmax=z
            kolz=k
          endif
        enddo
      else
        kolz=1
      endif
c      if(kolz.eq.0)call utstop(' kolz=0 (proj)&')
      if(kolz.eq.0)then
        t=0.
      else
        t=coord(4,kolz)
      endif

      xorptl(1,nptl)=xorptl(1,ii)
      xorptl(2,nptl)=xorptl(2,ii)
      xorptl(3,nptl)=xorptl(3,ii)
      xorptl(4,nptl)=t
      tivptl(1,nptl)=t
      tivptl(2,nptl)=t
      naq=0
      nqu=0

      if(iremn.ge.2)then   !update icproj
        idp(i)=min(1,abs(idp(i)))
        k=1
        nqu=0
        do n=1,nrflav
          jc(n,k)=jcpref(n,k,i)
          nqu=nqu+jc(n,k)
        enddo
        k=2
        naq=0
        do n=1,nrflav
          jc(n,k)=jcpref(n,k,i)
          naq=naq+jc(n,k)
        enddo
        isum=nqu+naq
        call idenco(jc,icrmn,iret)
        if(iret.eq.0.and.(isum.le.3.or.iremn.ne.3))then
          icproj(1,i)=icrmn(1)
          icproj(2,i)=icrmn(2)
        elseif(iremn.eq.3)then
      write(ifch,*)'Problem in projectile flavor :',i,' ->',jc,' :',isum
          call utstop('Procop: Problem in projectile flavor !&')
        else     !for iremn=2 and large number of quark define icproj=999999
          icproj(1,i)=999999
          icproj(2,i)=999999
        endif
      endif

      icrmn(1)=icproj(1,i)
      icrmn(2)=icproj(2,i)

      if(iremn.ge.1)then      !excited remnant ?
        call idtr6(idptl(ii),icini)
        if(ish.ge.5)write(ifch,*)'Procop icini proj',i,icini,' ->',icrmn
        if((icrmn(1)-icini(1))+(icrmn(2)-icini(2)).ne.0)then
          if(iep(i).eq.6)then
            write(ifch,'(a,d25.15)')
     &'Flavor problem in proj for pseudo-inelastic collision !',seedc
          elseif(iep(i).le.1)then
            iep(i)=1
          endif
        endif

        if(iremn.eq.2)then
          if(nqu.eq.2.and.naq.eq.2.and.abs(idptl(ii)).gt.1000)then
            iep(i)=5
          elseif(.not.((nqu.eq.3.and.naq.eq.0)
     &    .or.(nqu.eq.0.and.naq.eq.3).or.(nqu.eq.1.and.naq.eq.1)))then
            iep(i)=3
          endif
        endif
      endif

      if(ish.ge.5)write(ifch,'(a,i3,a,i3,a,i2)')
     &            'Procop part ',ii,', iep(',i,'): ',iep(i)

      if(iremn.le.1)call iddeco(icrmn,jc)
      if(iep(i).ge.1.and.iep(i).ne.6)then
        aproj=dble(max(amproj,fremnux(jc)))
      else
        aproj=dble(max(amproj,fremnux2(jc)))
      endif
c      aprojex=max(ampmn(isp(i))+amemn(idp(i),iep(i))
c     &           ,dble(fremnux(jc)))
      xmptmp=(aproj**2+xxp(i)*xxp(i)+xyp(i)*xyp(i))
     &       /(xpp(i)*s)
      xpos(i)=xpp(i)*xmptmp
      if(ish.ge.5)write(ifch,*)'Procop mass : ',nptl,aproj,xpos(i)*s
      if(xmptmp.gt.1.d0)then
        xmptmp=0.d0
      if(ish.ge.1)write(ifmt,*)'Warning in ProCop, Remnant mass too low'
      endif

      pptl(1,nptl)=sngl(xxp(i))
      pptl(2,nptl)=sngl(xyp(i))
      pptl(3,nptl)=sngl((xpp(i)-xmptmp)*plc/2d0)
      pptl(4,nptl)=sngl((xpp(i)+xmptmp)*plc/2d0)
      pptl(5,nptl)=aproj

c      write(ifmt,*)'ProCop',i,nptl

      return

      end

c-----------------------------------------------------------------------
      subroutine ProCot(j,jj)
c-----------------------------------------------------------------------
c Propose Coordinates of remnants from active targets nucleons
c-----------------------------------------------------------------------

      include 'epos.inc'
      include 'epos.incems'
      include 'epos.incsem'

      double precision xpttmp,atarg
      common/cems5/plc,s
      common/emsptl/nppr(npommx,kollmx),npproj(mamx),nptarg(mamx)
      integer icrmn(2),jc(nflav,2),icini(2)
      double precision s,plc

      nptl=nptl+1
      nptarg(j)=nptl

      idptl(nptl)=idptl(jj)*100+sign(99,idptl(jj))   !100*10**idt(j)+iet(j)
      istptl(nptl)=40
      ityptl(nptl)=50
      iorptl(nptl)=jj
      jorptl(nptl)=0
      ifrptl(1,nptl)=0
      ifrptl(2,nptl)=0
      do k=1,2
        do i=1,nflav
          jc(i,k)=0
        enddo
      enddo

      istptl(jj)=1

c     determine kolz

      if(ltarg(j).gt.1)then
        zmin=ainfin
        kolz=0
        do l=1,ltarg(j)
          k=ktarg(j,l)
          z=coord(3,k)
          if(itpr(k).ne.0.and.z.lt.zmin)then
            zmin=z
            kolz=k
          endif
        enddo
      else
        kolz=1
      endif
c      if(kolz.eq.0)call utstop(' kolz=0 (targ)&')
      if(kolz.eq.0)then
        t=0.
      else
        t=coord(4,kolz)
      endif

      xorptl(1,nptl)=xorptl(1,jj)
      xorptl(2,nptl)=xorptl(2,jj)
      xorptl(3,nptl)=xorptl(3,jj)
      xorptl(4,nptl)=t
      tivptl(1,nptl)=t
      tivptl(2,nptl)=t
      naq=0
      nqu=0

      if(iremn.ge.2)then   !update ictarg
        idt(j)=min(1,abs(idt(j)))
        k=1
        nqu=0
        do n=1,nrflav
          jc(n,k)=jctref(n,k,j)
          nqu=nqu+jc(n,k)
        enddo
        k=2
        naq=0
        do n=1,nrflav
          jc(n,k)=jctref(n,k,j)
          naq=naq+jc(n,k)
        enddo
        isum=nqu+naq
        call idenco(jc,icrmn,iret)
        if(iret.eq.0.and.(isum.le.3.or.iremn.ne.3))then
          ictarg(1,j)=icrmn(1)
          ictarg(2,j)=icrmn(2)
        elseif(iremn.eq.3)then
      write(ifch,*)'Problem in projectile flavor :',j,' ->',jc,' :',isum
          call utstop('Procot: Problem in target flavor !&')
        else     !for iremn=2 and large number of quark define ictarg=999999
          ictarg(1,j)=999999
          ictarg(2,j)=999999
        endif
      endif

      icrmn(1)=ictarg(1,j)
      icrmn(2)=ictarg(2,j)

      if(iremn.ge.1)then      !excited remnant ?
        call idtr6(idptl(jj),icini)
        if(ish.ge.5)write(ifch,*)'Procot icini targ',j,icini,' ->',icrmn
        if((icrmn(1)-icini(1))+(icrmn(2)-icini(2)).ne.0)then
          if(iet(j).eq.6)then
            write(ifch,'(a,d25.15)')
     &'Flavor problem in targ for pseudo-inelastic collision !',seedc
          elseif(iet(j).le.1)then
            iet(j)=1
          endif
        endif

        if(iremn.eq.2)then
          if(nqu.eq.2.and.naq.eq.2.and.abs(idptl(jj)).gt.1000)then
            iet(j)=5
          elseif(.not.((nqu.eq.3.and.naq.eq.0)
     &    .or.(nqu.eq.0.and.naq.eq.3).or.(nqu.eq.1.and.naq.eq.1)))then
            iet(j)=3
          endif
        endif
      endif
      
      if(ish.ge.5)write(ifch,'(a,i3,a,i3,a,i2)')
     &            'Procot part ',jj,', iet(',j,'): ',iet(j)

      if(iremn.le.1)call iddeco(icrmn,jc)
      if(iet(j).ge.1.and.iet(j).ne.6)then
        atarg=dble(max(amtarg,fremnux(jc)))
      else
        atarg=dble(max(amtarg,fremnux2(jc)))
      endif
c      atargex=max(amtmn(ist(j))+amemn(idt(j),iet(j))
c     &           ,dble(fremnux(jc)))
      xpttmp=(atarg**2+xxt(j)*xxt(j)+xyt(j)*xyt(j))
     &       /(xmt(j)*s)
      xtos(j)=xpttmp*xmt(j)
      if(ish.ge.5)write(ifch,*)'Procot mass : ',nptl,atarg,xtos(j)*s
      if(xpttmp.gt.1.d0)then
        xpttmp=0.d0
      if(ish.ge.1)write(ifch,*)'Warning in ProCot, Remnant mass too low'
      endif

      pptl(1,nptl)=sngl(xxt(j))
      pptl(2,nptl)=sngl(xyt(j))
      pptl(3,nptl)=sngl((xpttmp-xmt(j))*plc/2d0)
      pptl(4,nptl)=sngl((xpttmp+xmt(j))*plc/2d0)
      pptl(5,nptl)=atarg

c      write(ifmt,*)'ProCot',j,nptl

      return
      end

c-----------------------------------------------------------------------
      subroutine emswrp(i,ii)
c-----------------------------------------------------------------------

      include 'epos.inc'
      include 'epos.incems'

      double precision p5sq
      common/cems5/plc,s
      common/emsptl/nppr(npommx,kollmx),npproj(mamx),nptarg(mamx)
      double precision s,plc
      parameter(eps=1.e-5)

      mm=npproj(i)
      if(mm.eq.0)then
        write(*,*)'emswrp i ii',i,ii
        call utstop('emswrp with npproj=0 should never happen !&')

c        t=xorptl(4,kolp(i))
c        istptl(ii)=1
c        iorptl(ii)=-1
c        tivptl(2,ii)=t
c        nptl=nptl+1
c        npproj(i)=nptl
c        idptl(nptl)=idptl(ii)*100+99 !100*10**idp(i)+iep(i)
c        istptl(nptl)=40
c        ityptl(nptl)=40
c        iorptl(nptl)=ii
c        jorptl(nptl)=kolp(i)
c        ifrptl(1,nptl)=0
c        ifrptl(2,nptl)=0
c        xorptl(1,nptl)=xorptl(1,ii)
c        xorptl(2,nptl)=xorptl(2,ii)
c        xorptl(3,nptl)=xorptl(3,ii)
c        xorptl(4,nptl)=t
c        tivptl(1,nptl)=t
c        tivptl(2,nptl)=t
c        mm=nptl
c        kolp(i)=1
      endif
      if(iLHC.eq.1.and.(iep(i).eq.0.or.iep(i).eq.6))
     &xmp(i)=min(1d0-xpp(i),xmp(i))
      pptl(1,mm)=sngl(xxp(i))
      pptl(2,mm)=sngl(xyp(i))
      pptl(3,mm)=sngl((xpp(i)-xmp(i))*plc/2d0)
      pptl(4,mm)=sngl((xpp(i)+xmp(i))*plc/2d0)
      if(pptl(4,mm).lt.-eps)call utstop('E pro<0 !&')
      p5sq=xpp(i)*xmp(i)*s-xxp(i)*xxp(i)-xyp(i)*xyp(i)
      if(p5sq.gt.1.d-10)then
        pptl(5,mm)=sngl(sqrt(p5sq))
      elseif(iep(i).eq.0)then
        pptl(5,mm)=pptl(5,ii)
      else
        if(ish.ge.2)then
          write(ifch,*)'problem with mass for projectile, '
     &         ,'continue with zero mass'
          write(ifch,*)i,mm,xxp(i),xyp(i),xpp(i),xmp(i),p5sq
        endif
        pptl(5,mm)=0.
      endif
      if(ish.ge.8)
     &  write(ifch,*)'Update projectile mass:',mm,iep(i),pptl(5,mm)

      do l=1,4
       ibptl(l,mm)=0
      enddo

      return

      end

c-----------------------------------------------------------------------
      subroutine emswrt(j,jj)
c-----------------------------------------------------------------------

      include 'epos.inc'
      include 'epos.incems'

      double precision p5sq
      common/cems5/plc,s
      common/emsptl/nppr(npommx,kollmx),npproj(mamx),nptarg(mamx)
      double precision s,plc
      parameter(eps=1.e-5)

      mm=nptarg(j)
      if(mm.eq.0)then

        write(*,*)'emswrt j jj',j,jj
        call utstop('emswrt with nptarg=0 should never happen !&')

c        t=xorptl(4,kolt(j))
c        istptl(jj)=1
c        iorptl(jj)=-1
c        tivptl(2,jj)=t
c        nptl=nptl+1
c        nptarg(j)=nptl
c        idptl(nptl)=idptl(jj)*100+99 !100*10**idp(i)+iep(i)
c        istptl(nptl)=40
c        ityptl(nptl)=50
c        iorptl(nptl)=jj
c        jorptl(nptl)=kolt(j)
c        ifrptl(1,nptl)=0
c        ifrptl(2,nptl)=0
c        xorptl(1,nptl)=xorptl(1,jj)
c        xorptl(2,nptl)=xorptl(2,jj)
c        xorptl(3,nptl)=xorptl(3,jj)
c        xorptl(4,nptl)=t
c        tivptl(1,nptl)=t
c        tivptl(2,nptl)=t
c        mm=nptl
c        kolt(j)=1
      endif
      if(iLHC.eq.1.and.(iet(j).eq.0.or.iet(j).eq.6))
     &xpt(j)=min(1d0-xmt(j),xpt(j))
      pptl(1,mm)=sngl(xxt(j))
      pptl(2,mm)=sngl(xyt(j))
      pptl(3,mm)=sngl((xpt(j)-xmt(j))*plc/2d0)
      pptl(4,mm)=sngl((xpt(j)+xmt(j))*plc/2d0)
      if(pptl(4,mm).lt.-eps)call utstop('E targ<0 !&')
      p5sq=xpt(j)*xmt(j)*s-xxt(j)*xxt(j)-xyt(j)*xyt(j)
      if(p5sq.gt.1.d-10)then
        pptl(5,mm)=sngl(sqrt(p5sq))
      elseif(iet(j).eq.0)then
        pptl(5,mm)=pptl(5,jj)
      else
        if(ish.ge.2)then
          write(ifch,*)'problem with mass for target, '
     &            ,'continue with zero mass'
          write(ifch,*)j,mm,xxt(j),xyt(j),xpt(j),xmt(j),p5sq
        endif
        pptl(5,mm)=0.
      endif
      if(ish.ge.8)
     &  write(ifch,*)'Update   target   mass:',mm,iet(j),pptl(5,mm)

      do l=1,4
       ibptl(l,mm)=0
      enddo

      return
      end

c-----------------------------------------------------------------------
      subroutine emswrpom(k,i,j)
c-----------------------------------------------------------------------

      include 'epos.inc'
      include 'epos.incems'

      common/cems5/plc,s
      common/emsptl/nppr(npommx,kollmx),npproj(mamx),nptarg(mamx)
      double precision s,px,py,plc

      do 30 n=1,nprmx(k)
       if(idpr(n,k).eq.0.or.ivpr(n,k).eq.0)goto30
       nptl=nptl+1
       nppr(n,k)=nptl
       px=xxp1pr(n,k)+xxp2pr(n,k)+xxm1pr(n,k)+xxm2pr(n,k)
       py=xyp1pr(n,k)+xyp2pr(n,k)+xym1pr(n,k)+xym2pr(n,k)
       pptl(1,nptl)=sngl(px)
       pptl(2,nptl)=sngl(py)
       pptl(3,nptl)=sngl(dsqrt(xpr(n,k))*dsinh(ypr(n,k))*plc)
       pptl(4,nptl)=sngl(dsqrt(xpr(n,k))*dcosh(ypr(n,k))*plc)
       pptl(5,nptl)=sngl(dsqrt(xpr(n,k)*s-px*px-py*py))
   !    print*,pptl(5,nptl)/plc
       idptl(nptl)=idpr(n,k)*10000
     &     +idp1pr(n,k)*1000
     &     +idp2pr(n,k)*100
     &     +idm1pr(n,k)*10
     &     +idm2pr(n,k)
       idptl(nptl)=idptl(nptl)*100+99
       istptl(nptl)=30
       iorptl(nptl)=i
       jorptl(nptl)=j
       ifrptl(1,nptl)=0
       ifrptl(2,nptl)=0
       xorptl(1,nptl)=coordpr(1,n,k)
       xorptl(2,nptl)=coordpr(2,n,k)
       xorptl(3,nptl)=coord(3,k)
       xorptl(4,nptl)=coord(4,k)
       tivptl(1,nptl)=coord(4,k)
       tivptl(2,nptl)=coord(4,k)
       if(idpr(n,k).eq.1)then
        ityptl(nptl)=20
        if(itpr(k).gt.0)ityptl(nptl)=25
      elseif(idpr(n,k).eq.2)then
        ityptl(nptl)=21
        if(itpr(k).gt.0)ityptl(nptl)=26
       elseif(idpr(n,k).eq.3)then
        ityptl(nptl)=30
        if(itpr(k).gt.0)ityptl(nptl)=35
       else
        call utstop('emswrpom: unknown id&')
       endif
       do l = 1,4
        ibptl(l,nptl)=0
       enddo
30    continue

      return
      end

c-----------------------------------------------------------------------
      subroutine emsPzGrey(iret)
c-----------------------------------------------------------------------
c     attribute pz momentum to spectators with iept=6 (ityptl=47/57)
c     sum should be null but introduce fluctuations in slow nucleon
c     distribution (coming from intranuclear cascade which is not treated
c     explicitely).
c-----------------------------------------------------------------------

      include 'epos.inc'
      include 'epos.incems'
      include 'epos.incsem'
      DOUBLE PRECISION PFRZ,SPFRZ,RANNORM!,eini,esum,delta
      common /cfragm/rminfrg,emaxfrg,facgrey,p3grey
      
      iret=0
      IF(ish.ge.5)WRITE(ifch,*) 'emsPzGrey : i, ityp, pfrz, p3'

      SPFRZ=0d0
      jfin=0
      eini=0d0
      fac=0.1*min(pnullx,10.)
      DO  i = maproj+matarg+1, nptl       
        IF(ITYPTL(i).eq.47.or.ITYPTL(i).eq.57)THEN
          PFRZ= dble(0.33*p3grey*fac)
          if(ITYPTL(i).eq.47)PFRZ=-PFRZ
          PFRZ= RANNORM(PFRZ,dble(p3grey*fac))
          SPFRZ=SPFRZ+PFRZ
          jfin=jfin+1
          eini=eini+pptl(4,i)
          pptl(3,i)=sngl(dble(pptl(3,i))*(1d0+PFRZ/dble(pptl(3,i))))
          IF(ish.ge.5)WRITE(ifch,*) i,ITYPTL(i),SNGL(PFRZ),SNGL(SPFRZ)
        ENDIF
      ENDDO

      if(jfin.ge.1)then
        
C  CORRECT MOMENTA FOR MOMENTUM CONSERVATION
      SPFRZ = SPFRZ / JFIN
      DO  i = maproj+matarg+1, nptl       
        IF(ITYPTL(i).eq.47.or.ITYPTL(i).eq.57)THEN
          pptl(3,i)=sngl(dble(pptl(3,i))*(1d0-SPFRZ/dble(pptl(3,i))))
          pptl(4,i)=sqrt(pptl(1,i)**2+pptl(2,i)**2
     &                    +pptl(3,i)**2+pptl(5,i)**2)   !energy conservation restored in utresc

          esum=esum+pptl(4,i)
       ENDIF
      ENDDO

      endif

      end

      
c-----------------------------------------------------------------------
      subroutine emsfrag(iqq,iret)
c-----------------------------------------------------------------------
c     ?????? Time not properly define if we want to use spectators in hacas ????
c ----> to be updated !      
c-----------------------------------------------------------------------

      include 'epos.inc'
      include 'epos.incems'
      common/nucl3/phi,bimp
      double precision pfrx(mamxx),pfry(mamxx),pfrz(mamxx),xmean,ymean
     &     ,zmean,spec,esum
      dimension xyzs(mamxx,4)
      integer   ityp(mamxx)

      iret=0
      nptl0=nptl
      bx=0.
      by=0.

c Projectile fragment(s)

      if(iqq.eq.1)then          !mark spectators to be used after hacas
        do is=1,maproj
          if(istptl(is).eq.0)then
            if ( iorptl(is) .eq. 0 ) then
              ityptl(is)=4
              if(ihacas.ne.0)then  !copy spectators to be used by hacas
                nptl=nptl+1
                if(nptl.gt.mxptl)then
                  iret=2
                  goto 1000
                endif
                call utrepl(nptl,is)
                istptl(is)=1
                ifrptl(1,is)=nptl
                ifrptl(2,is)=nptl
                istptl(nptl)=0
                iorptl(nptl)=is
              endif
            endif
          endif
        enddo
        if(ihacas.ne.0.or.infragm.eq.0)goto 100
      elseif(iqq.eq.2)then
c  copy spectators at the end of the list (necessary for hepmc interface)
        do is=1,nptl
          pt2=pptl(1,is)**2+pptl(2,is)**2  !spectator pt should be 0
          if(istptl(is).eq.0.and.pt2.le.0.)then
            if ( ityptl(is).eq.4 .or. ityptl(is).eq.5) then
              nptl=nptl+1
              if(nptl.gt.mxptl)then
                iret=2
                goto 1000
              endif
              call utrepl(nptl,is)
              istptl(is)=1
              ifrptl(1,is)=nptl
              ifrptl(2,is)=nptl
              istptl(nptl)=0
              ityptl(nptl)=0
              iorptl(nptl)=is
              if(is.gt.0)iorptl(nptl)=iorptl(is)
            endif
          endif
        enddo
        goto 1000
      elseif(infragm.eq.0)then
        goto 1000
      endif

      bx=cos(phi)*bimp
      by=sin(phi)*bimp

      irest = maproj*100+abs(laproj)
      inew=0
      idrest=0
      mapro=maproj
      xmean=0d0
      ymean=0d0
      zmean=0d0
      spec=0d0
      amrest=0.
      imin=maproj
      imax=1
      
      do is=1,nptl
        
        if(ityptl(is).eq.4)then
          pt2=pptl(1,is)**2+pptl(2,is)**2  !spectator pt should be 0
          if(istptl(is).eq.0.and.pt2.le.0d0)then
c           compose projectile spectators to remaining nucleus
            spec=spec+1d0
            xyzs(nint(spec),1)=xorptl(1,is)-bx/2
            xyzs(nint(spec),2)=xorptl(2,is)-by/2
            xyzs(nint(spec),3)=xorptl(3,is)
            tivptl(2,is)=0.
            xmean=xmean+xorptl(1,is)
            ymean=ymean+xorptl(2,is)
            zmean=0d0
            amrest=amrest+pptl(5,is)
            imin=min(imin,is)
            imax=max(imax,is)
            istptl(is)=1
            ifrptl(1,is)=nptl+1
            ifrptl(2,is)=nptl+1
            idrest = is
            id=idptl(is)
            if     ( abs(id) .eq. 1120 ) then
              xyzs(nint(spec),4)=101
              inew  = inew + 101
              irest = irest - 101
            elseif ( abs(id) .eq. 1220 ) then
              xyzs(nint(spec),4)=100
              inew  = inew + 100
              irest = irest - 100
            endif
          endif
        elseif( is.le.maproj .and. iorptl(is) .le. 0
     .                       .and. istptl(is) .eq. 1 ) then
          if( iorptl(is) .eq. 0 )jorptl(is)=1
          mapro=mapro-1
        endif
        
      enddo

      if(inew.eq.0)goto 100

      xmean=xmean/spec
      ymean=ymean/spec
      zmean=zmean/spec
      nptla=nptl
c prepare intermediate particle to produce nuclear fragment
      nptl=nptl+1
      if(nptl.gt.mxptl)then
        iret=1
        goto 1000
      endif

      if( inew .eq. 100 .or. inew .eq. 101 ) then
c  remaining nucleus is single neutron or proton
        call utrepl(nptl,idrest)
        ifrptl(1,idrest)=nptl
        ifrptl(2,idrest)=nptl
        istptl(nptl)=0
        iorptl(nptl)=idrest
        goto 100

      else

c intermediate particles for father/mother relationship
        idptl(nptl)=800000000+inew
        ea = float(inew/100)*pptl(4,idrest)
c  momenta squared
        ptm = sqrt(max(0.,(ea-amrest)*(ea+amrest)))
        istptl(nptl)=51
        pptl(1,nptl)=0.
        pptl(2,nptl)=0.
        pptl(3,nptl)=ptm
        pptl(4,nptl)=sqrt(pptl(1,nptl)**2+pptl(2,nptl)**2
     *                     +pptl(3,nptl)**2+amrest**2)
        pptl(5,nptl)=amrest         !mass
        ityptl(nptl)=94
        iorptl(nptl)=imax
        jorptl(nptl)=imax
        ifrptl(1,nptl)=nptl+1
        ifrptl(2,nptl)=0
        xorptl(1,nptl)=0.
        xorptl(2,nptl)=0.
        xorptl(3,nptl)=0.
        xorptl(4,nptl)=0.
        tivptl(1,nptl)=0.
        tivptl(2,nptl)=0.

        if ( infragm .ge. 2 ) then
c  remaining nucleus is evaporating nucleons and alpha particles
         nmin=nptl+1
         nloop=0 
         is=1
         jfin  = 0
         itheo=inew/100 !npglb            !lowest mass spectator nucleus
c         print *,irest,inew,itheo
 50      call epovapor(is*maproj,inew,itheo,xyzs,jfin
     .                ,ityp,pfrx,pfry,pfrz) 
         if ( jfin .eq. 0 )then   !something failed
           iret=1
           goto 1000
         endif
c loop to treat the remnants of the desintegrated fragment
         mfragmaxp=0
         esum = 0d0
         npart = 0
         do  135  j = 1, jfin
c           print *,j,ityp(j)
          if(ityp(j).lt.0.)then
            idnucl=-ityp(j)
            inucl= idnucl/100
            if(idnucl.eq.402)then   !helium (alpha)
              idnucl=19
            elseif(idnucl.eq.301)then   !tritium
              idnucl=18
            elseif(idnucl.eq.201)then   !deuterium
              idnucl=17
            else
              iprot= mod(idnucl,100)
              idnucl=1000000000+iprot*10000+inucl*10 !PDG code for nucleus
            endif
          else
            inucl=1
            idnucl=ityp(j)
            npart=npart+1
          endif
          mfragmaxp=max(mfragmaxp,inucl)
          ea = float(inucl)*pptl(4,idrest)
c  momenta squared
          call idmass(idnucl,am)
          ptm = ( ea - am ) * ( ea + am )
          pt2 = sngl( pfrx(j)**2 + pfry(j)**2 )
          if(ish.ge.6)write(ifch,*) 'pro fragment: j,id,ea,ptm,pt2=',
     *                                       j,idnucl,ea,ptm,pt2
          if ( pt2 .ge. ptm ) then
            if(nloop.lt.1000)then
              nloop=nloop+1
              is=-1
              if(mod(nloop,100).eq.0)is=1
              nptl=nmin-1
              goto 50
            else
              write(ifmt,*)'Pb in emsfrag p :',nloop
              call utmsg("emsfrag: problem with grey particles (1) !&")
              call utmsgf
              iret=1
              goto 1000
            endif
c            if (ish.ge.2) write(ifch,*) 'emsfrag: pt reject particle',j
c            nnn=0
c            is=0
c            do while (is.lt.maproj.and.nnn.lt.inucl)
c              is=is+1
c              if(istptl(is).eq.1
c     &             .and.jorptl(is).eq.0.and.iorptl(is).eq.0)then
c                nnn=nnn+1
cc  copy spectators at the end of the list (necessary for hepmc interface)
c                nptl=nptl+1
c                if(nptl.gt.mxptl)then
c                  iret=1
c                  goto 1000
c                endif
c                call utrepl(nptl,is)
c                jorptl(is)=1
c                ifrptl(1,is)=nptl
c                ifrptl(2,is)=nptl
c                istptl(nptl)=0
c                iorptl(nptl)=is
c              endif
c            enddo
c            goto 135
          else
            plong = sqrt(ptm-pt2)
          endif
          nptl=nptl+1
          mfragmaxp=max(mfragmaxp,inucl)
          if(nptl.gt.mxptl)then
            iret=1
            goto 1000
          endif
          idnucl=sign(idnucl,idproj)
          istptl(nptl)=0
          pptl(1,nptl)=sngl(pfrx(j))
          pptl(2,nptl)=sngl(pfry(j))
          pptl(3,nptl)=plong+sngl(pfrz(j))
          pptl(4,nptl)=sqrt(pptl(1,nptl)**2+pptl(2,nptl)**2
     *                     +pptl(3,nptl)**2+am**2)
          pptl(5,nptl)=am    !mass
          ityptl(nptl)=94
          iorptl(nptl)=nptla+1
          jorptl(nptl)=0
          ifrptl(1,nptl)=0
          ifrptl(2,nptl)=0
          xorptl(1,nptl)=sngl(xmean)
          xorptl(2,nptl)=sngl(ymean)
          xorptl(3,nptl)=sngl(zmean)
          xorptl(4,nptl)=sngl(zmean)
          tivptl(1,nptl)=sngl(zmean)
          tivptl(2,nptl)=tivptl(2,idrest)
          idptl(nptl)=idnucl
          if(inucl.eq.1)esum=esum+pptl(4,nptl)
 135    continue

c       restore energy/momentum conservation
c        if(npart.ne.0)then
c          call utrfrag(1,nmin,iret2)
c          if(iret2.ne.0)then
c            if(nloop.lt.1000)then
c              nloop=nloop+1
c              is=-1
c              if(mod(nloop,100).eq.0)is=1
c              nptl=nmin-1
c              goto 50
c            else
c              write(ifmt,*)'Pb in emsfrag p :',nloop
c              call utmsg("emsfrag: problem with grey particles (2) !&")
c              call utmsgf
c              iret=1
c              goto 1000
c            endif
c          endif
c        endif

        elseif ( infragm .eq. 1 ) then
c  remaining nucleus is one fragment
          nptl=nptl+1
          if(nptl.gt.mxptl)then
            iret=1
            goto 1000
          endif
          istptl(nptl)=0
          pptl(1,nptl)=0.d0
          pptl(2,nptl)=0.d0
          pptl(4,nptl)=0.d0
          inucl=0
          do is=1,maproj
            if(iorptl(is).eq.0.and.jorptl(is).eq.0)then
              inucl=inucl+1
              pptl(4,nptl)=pptl(4,nptl)+pptl(4,is)
            endif
          enddo
          mfragmaxp=inucl
          if(inucl.ne.inew/100)call utstop('Pb in emsfrag !&')
          idnucl=1000000000+mod(inew,100)*10000+(inew/100)*10
          call idmass(idnucl,am)
          idnucl=sign(idnucl,idproj)
          pptl(5,nptl)=am    !mass
          ptot=(pptl(4,nptl)+am)*(pptl(4,nptl)-am)
          pptl(3,nptl)=sqrt(ptot)
          ityptl(nptl)=94
          istptl(nptl)=0
          iorptl(nptl)=nptla+1
          jorptl(nptl)=0
          ifrptl(1,nptl)=0
          ifrptl(2,nptl)=0
          xorptl(1,nptl)=sngl(xmean)
          xorptl(2,nptl)=sngl(ymean)
          xorptl(3,nptl)=sngl(zmean)
          xorptl(4,nptl)=sngl(zmean)
          tivptl(1,nptl)=sngl(zmean)
          tivptl(2,nptl)=tivptl(2,idrest)
          idptl(nptl)=idnucl
        endif
        ifrptl(2,nptla+1)=nptl
        if(ifrptl(1,nptla+1).gt.ifrptl(2,nptla+1))then
          ifrptl(1,nptla+1)=0
          ifrptl(2,nptla+1)=0
        endif
      endif

c possible decay of fragments
c      call decayall(nptla+1)

      do is=nptla+1,nptl
          if(ish.ge.5)write(ifch,'(a,i5,a,i10,a,4(e10.4,1x),f6.3)')
     $       ' Projectile fragments ',is,' id :',idptl(is)
     $  , ' momentum :',(pptl(k,is),k=1,5)
      enddo

 100  continue

c Target fragment(s)

      if(iqq.eq.1)then          !mark spectators to be used after hacas
        do is=maproj+1,maproj+matarg
          if(istptl(is).eq.0)then
            if ( iorptl(is) .eq. 0 ) then
              ityptl(is)=5
              if(ihacas.ne.0)then  !copy spectators to be used by hacas
                nptl=nptl+1
                if(nptl.gt.mxptl)then
                  iret=2
                  goto 1000
                endif
                call utrepl(nptl,is)
                istptl(is)=1
                ifrptl(1,is)=nptl
                ifrptl(2,is)=nptl
                istptl(nptl)=0
                iorptl(nptl)=is
              endif
            endif
          endif
        enddo
        if(ihacas.ne.0.or.infragm.eq.0)goto 1000
      endif

      irest = matarg*100+abs(latarg)
      inew=0
      matar=matarg
      xmean=0d0
      ymean=0d0
      zmean=0d0
      spec=0d0
      amrest=0.
      imin=maproj+matarg
      imax=maproj+1

      do is=maproj+1,nptl
        
        if(ityptl(is).eq.5)then
          pt2=pptl(1,is)**2+pptl(2,is)**2  !spectator pt should be 0
          if(istptl(is).eq.0.and.pt2.le.0.)then
c  compose projectile spectators to remaining nucleus
            spec=spec+1d0
            xyzs(nint(spec),1)=xorptl(1,is)+bx/2
            xyzs(nint(spec),2)=xorptl(2,is)+by/2
            xyzs(nint(spec),3)=xorptl(3,is)
            tivptl(2,is)=0.
            xmean=xmean+xorptl(1,is)
            ymean=ymean+xorptl(2,is)
            zmean=0d0
            amrest=amrest+pptl(5,is)
            imin=min(imin,is)
            imax=max(imax,is)
            istptl(is)=1
            ifrptl(1,is)=nptl+1
            ifrptl(2,is)=nptl+1
            idrest = is
            id=idptl(is)
            if     ( id .eq. 1120 ) then
              xyzs(nint(spec),4)=101
              inew  = inew + 101
              irest = irest - 101
            elseif ( id .eq. 1220 ) then
              xyzs(nint(spec),4)=100
              inew  = inew + 100
              irest = irest - 100
            endif
          endif
          
        elseif( is.le.maproj+matarg+1 .and. iorptl(is) .le. 0
     .                                .and. istptl(is) .eq. 1 ) then
          if( iorptl(is) .eq. 0 ) jorptl(is)=1
          matar=matar-1
        endif
        
      enddo

      if(inew.eq.0)goto 1000

      xmean=xmean/spec
      ymean=ymean/spec
      zmean=zmean/spec
      nptla=nptl
c prepare intermediate particle to produce nuclear fragment
      nptl=nptl+1
      if(nptl.gt.mxptl)then
        iret=1
        goto 1000
      endif

      if( inew .eq. 100 .or. inew .eq. 101 ) then
c  remaining nucleus is single neutron or proton
        call utrepl(nptl,idrest)
        ifrptl(1,idrest)=nptl
        ifrptl(2,idrest)=nptl
        istptl(nptl)=0
        iorptl(nptl)=idrest
        goto 1000

      else

c intermediate particles for father/mother relationship
        idptl(nptl)=800000000+inew
        ea = float(inew/100)*pptl(4,idrest)
c  momenta squared
        ptm = sqrt(max(0.,(ea-amrest)*(ea+amrest)))
        istptl(nptl)=51
        pptl(1,nptl)=0.
        pptl(2,nptl)=0.
        pptl(3,nptl)=-ptm
        pptl(4,nptl)=sqrt(pptl(1,nptl)**2+pptl(2,nptl)**2
     *                     +pptl(3,nptl)**2+amrest**2)
        pptl(5,nptl)=amrest         !mass
        ityptl(nptl)=95
        iorptl(nptl)=imax
        jorptl(nptl)=imax
        ifrptl(1,nptl)=nptl+1
        ifrptl(2,nptl)=0
        xorptl(1,nptl)=0.
        xorptl(2,nptl)=0.
        xorptl(3,nptl)=0.
        xorptl(4,nptl)=0.
        tivptl(1,nptl)=0.
        tivptl(2,nptl)=0.

        if ( infragm .ge. 2 ) then
c  remaining nucleus is evaporating nucleons and alpha particles
         nmin=nptl+1
         nloop=0 
         is=1
         jfin  = 0
         itheo=inew/100         !ntglb  !lowest mass spectator nucleus
 150     call epovapor(is*matarg,inew,itheo,xyzs
     .                ,jfin,ityp,pfrx,pfry,pfrz) 
         if ( jfin .eq. 0 )then   !something failed
           iret=1
           goto 1000
         endif
c loop to treat the remnants of the desintegrated fragment
         mfragmaxt=0
         npart = 0
         do  235  j = 1, jfin
          if(ityp(j).lt.0.)then
            idnucl=-ityp(j)
            inucl= idnucl/100
            if(idnucl.eq.402)then   !helium (alpha)
              idnucl=19
            elseif(idnucl.eq.301)then   !tritium
              idnucl=18
            elseif(idnucl.eq.201)then   !deuterium
              idnucl=17
            else
              iprot= mod(idnucl,100)
              idnucl=1000000000+iprot*10000+inucl*10 !PDG code for nucleus
            endif
          else
            inucl=1
            idnucl=ityp(j)
            npart=npart+1
          endif
          ea = float(inucl)*pptl(4,idrest)
c  momenta squared
          call idmass(idnucl,am)
          ptm = ( ea - dble(am) ) * ( ea + dble(am) )
          pt2 = sngl( pfrx(j)**2 + pfry(j)**2 )
          if(ish.ge.6)write(ifch,*) 'tar fragment: j,id,ea,ptm,pt2,am=',
     *                                       j,idnucl,ea,ptm,pt2,am
          if ( pt2 .ge. ptm ) then
            if(nloop.lt.1000)then
              nloop=nloop+1
              is=-1
              if(mod(nloop,100).eq.0)is=1
              nptl=nmin-1
              goto 150
            else
              write(ifmt,*)'Pb in emsfrag t :',nloop
              call utmsg("emsfrag: problem with grey particles (1) !&")
              call utmsgf
              iret=1
              goto 1000
            endif
c            if (ish.ge.2) write(ifch,*) 'emsfrag: pt reject particle',j
c            nnn=0
c            is=maproj
c            do while (is.lt.maproj+matarg.and.nnn.lt.inucl)
c              is=is+1
c              if(istptl(is).eq.1
c     &             .and.jorptl(is).eq.0.and.iorptl(is).eq.0)then
c                nnn=nnn+1
cc  copy spectators at the end of the list (necessary for hepmc interface)
c                nptl=nptl+1
c                if(nptl.gt.mxptl)then
c                  iret=1
c                  goto 1000
c                endif
c                call utrepl(nptl,is)
c                jorptl(is)=1
c                ifrptl(1,is)=nptl
c                ifrptl(2,is)=nptl
c                istptl(nptl)=0
c                iorptl(nptl)=is
c              endif
c            enddo
c            goto 235
          else
            plong=-sqrt(ptm-pt2)
          endif
          nptl=nptl+1
          mfragmaxt=max(mfragmaxt,inucl)
          if(nptl.gt.mxptl)then
            iret=1
            goto 1000
          endif
          istptl(nptl)=0
          pptl(1,nptl)=sngl(pfrx(j))
          pptl(2,nptl)=sngl(pfry(j))
          pptl(3,nptl)=plong+sngl(pfrz(j))
          pptl(4,nptl)=sqrt(pptl(1,nptl)**2+pptl(2,nptl)**2
     *                     +pptl(3,nptl)**2+am**2)
          pptl(5,nptl)=am    !mass
          ityptl(nptl)=95
          iorptl(nptl)=nptla+1
          jorptl(nptl)=0
          ifrptl(1,nptl)=0
          ifrptl(2,nptl)=0
          xorptl(1,nptl)=sngl(xmean)
          xorptl(2,nptl)=sngl(ymean)
          xorptl(3,nptl)=sngl(zmean)
          xorptl(4,nptl)=sngl(zmean)
          tivptl(1,nptl)=sngl(zmean)
          tivptl(2,nptl)=tivptl(2,idrest)
          idptl(nptl)=idnucl
 235    continue

c       restore energy/momentum conservation
c        if(npart.ne.0)then
c          call utrfrag(2,nmin,iret2)
c          if(iret2.ne.0)then
c            if(nloop.lt.1000)then
c              nloop=nloop+1
c              is=-1
c              if(mod(nloop,100).eq.0)is=1
c              nptl=nmin-1
c              goto 150
c            else
c              write(ifmt,*)'Pb in emsfrag t :',nloop
c              call utmsg("emsfrag: problem with grey particles (2) !&")
c              call utmsgf
c              iret=1
c              goto 1000
c            endif
c          endif
c        endif

        elseif ( infragm .eq. 1 ) then
c  remaining nucleus is one fragment
          nptl=nptl+1
          if(nptl.gt.mxptl)then
            iret=1
            goto 1000
          endif
          istptl(nptl)=0
          pptl(1,nptl)=0.d0
          pptl(2,nptl)=0.d0
          pptl(4,nptl)=0.d0
          inucl=0
          do is=maproj+1,maproj+matarg
            if(iorptl(is).eq.0.and.jorptl(is).eq.0)then
              inucl=inucl+1
              pptl(4,nptl)=pptl(4,nptl)+pptl(4,is)
            endif
          enddo
          mfragmaxt=inucl
          if(inucl.ne.inew/100)call utstop('Pb in emsfrag !&')
          idnucl=1000000000+mod(inew,100)*10000+(inew/100)*10
          call idmass(idnucl,am)
          pptl(5,nptl)=am    !mass
          ptot=(pptl(4,nptl)+am)*(pptl(4,nptl)-am)
          pptl(3,nptl)=-sqrt(ptot)
          ityptl(nptl)=95
          istptl(nptl)=0
          iorptl(nptl)=nptla+1
          jorptl(nptl)=0
          ifrptl(1,nptl)=0
          ifrptl(2,nptl)=0
          xorptl(1,nptl)=sngl(xmean)
          xorptl(2,nptl)=sngl(ymean)
          xorptl(3,nptl)=sngl(zmean)
          xorptl(4,nptl)=sngl(zmean)
          tivptl(1,nptl)=sngl(zmean)
          tivptl(2,nptl)=tivptl(2,idrest)
          idptl(nptl)=idnucl
        endif
        ifrptl(2,nptla+1)=nptl
        if(ifrptl(1,nptla+1).gt.ifrptl(2,nptla+1))then
          ifrptl(1,nptla+1)=0
          ifrptl(2,nptla+1)=0
        endif
      endif

c possible decay of fragments
c      call decayall(nptla+1)

      do is=nptla+1,nptl
          if(ish.ge.5)write(ifch,'(a,i5,a,i10,a,4(e10.4,1x),f6.3)')
     $       ' Target fragments ',is,' id :',idptl(is)
     $  , ' momentum :',(pptl(k,is),k=1,5)
      enddo


 1000 continue

      if(iret.eq.1)then         !failed to produce fragments, keep spectators only
        iret=0
        nptl=nptl0
      endif
      
      end


      subroutine IniChargex
***************************************************************
*
*  initialization to call Chargex subroutine
*
***************************************************************
      implicit none
      include 'epos.inc'

c      double precision CS,face
c     integer i,imax
c      integer jspin,ind,ifl(3),istra
      real efac,rexchrgpro,rexchrgtar

      if(chargex)return

      pnullx0=dble(pnullx)

      ichargex=ichargexin
      if(ichargex.ne.0)then
        rexchrgpro=rexchrg(iclpro)*rexdif(iclpro) !to make it decreasing as SD
        rexchrgtar=rexchrg(icltar)*rexdif(icltar)
c      call idflav(idprojin,ifl(1),ifl(2),ifl(3),jspin,ind)
c      istra=abs(ifl(1))+abs(ifl(2))
c      if(ifl(3).ne.0)then
c        istra=istra+abs(ifl(3))
c      else
c        istra=istra+3
c      endif
c      if(istra.ge.9)then
        if(abs(idproj).ne.1120.and.abs(idproj).ne.1220
     +  .and.abs(idproj).ne.120.and.abs(idproj)/10.ne.11)rexchrgpro=0.
        if(abs(idtarg).ne.1120.and.abs(idtarg).ne.1220)rexchrgtar=0.
        if(rexchrgpro+rexchrgtar.le.0.)then
          if(ish.ge.1)write(ifmt,*)
     +  'Warning : no charge exchange without u or d quark : '
     +       ,idproj,idtarg
          xschargex(0)=0.
          return
        endif

        efac=1.!/log10(engy)  !small energy dependence from data
        xschargex(0)=efac*rexchrgpro+efac*rexchrgtar
     +     +efac*rexchrgpro*efac*rexchrgtar
        if(xschargex(0).gt.0)then
          xschargex(1)=efac*rexchrgpro/xschargex(0) !single charge exchange probability proj
          xschargex(2)=efac*rexchrgtar/xschargex(0) !single charge exchange probability targ
          xschargex(3)=efac*rexchrgpro*efac*rexchrgtar
     +         /xschargex(0)    !double charge exchange
        endif
      else
         xschargex(0)=0.
         xschargex(1)=0.
         xschargex(2)=0.
         xschargex(3)=0.
      endif
c      print *,xschargex,rexchrg,xschargex(1)+xschargex(2)+xschargex(3)
      end


***************************************************************

      subroutine emschargex(iqq,iret)

***************************************************************
*
*     interface to call Chargex subroutine
*     iqq>0 first call to set the new collision system
*           and save initial one (11=charge exchange, 20 or 02
*           for SD, 22 for DD, and 00 for CD)
*     iqq<0 second call to restore initial projectile and target
*           and add particles from the pion-nucleon collision
*           in proper frame
*     iret - return status
***************************************************************
      include 'epos.inc'
      include 'epos.incems'
      common/nucl3/phi,bimp
      real phi,bimp
      common/emsptl/nppr(npommx,kollmx),npproj(mamx),nptarg(mamx)
      integer nppr,npproj,nptarg


c     Input values
      double precision pframe(5)
      integer istart(2),n1,n2,ispin,ispin0,idresch,ITYPR,nbeam,idbeam
      logical LCE(2)

      integer iqq,iret,ipart,n,k,i,ior,idbaryon,ntry,i1,i2,is,nptl0,iept
     .        ,nppd,nptd,itp,npd,ma!,ifl(3),jspin,ind
      real   m(2),m3,xran,xsratio!,chrg
      double precision e1,e2,pproj,ptarg,mp,decms,fac
      DOUBLE PRECISION PRR(5),PNN(5),P(5,2),PTR,PHIR,ESUM,PSUM,pbeam
      double precision drangen,rannorm

      real engysave,bimpsave,phisave,pnllsave,qsqevtsave,typevtsave
      integer noebinsave,maprojsave,laprojsave,matargsave,latargsave
     .     ,idprojinsave,idtarginsave,ic(2),isave,idprojsave,idtargsave
     .     ,iomegasave,nglevtsave,ng1evtsave,ng2evtsave,ng11evtsave
     .     ,ng12evtsave,eglevtsave,fglevtsave,rglevtsave,sglevtsave
     .     ,irdmprsave
      save noebinsave,maprojsave,laprojsave,matargsave,latargsave,LCE
     .     ,idprojinsave,idtarginsave,engysave,isave,pframe,istart
     .     ,bimpsave,phisave,pnllsave,idprojsave,idtargsave,qsqevtsave
     .     ,iomegasave,nglevtsave,ng1evtsave,ng2evtsave,ng11evtsave
     .     ,ng12evtsave,eglevtsave,fglevtsave,rglevtsave,sglevtsave
     .     ,typevtsave,irdmprsave,P

      if(ish.ge.2)write(ifch,*)'Start emschargex - ',iqq,iret

      if(iqq.ge.0)then
c       first call, save initial conditions
        noebinsave=noebin
        engysave=engy
        maprojsave=maproj
        matargsave=matarg
        laprojsave=laproj
        latargsave=latarg
        idprojinsave=idprojin
        idtarginsave=idtargin
        idprojsave=idproj
        idtargsave=idtarg
        iomegasave=iomega
        irdmprsave=irdmpr
        bimpsave=bimp
        phisave=phi
        pnllsave=pnll
        qsqevtsave=qsqevt
        typevtsave=typevt
        nglevtsave=nglevt
        ng1evtsave=ng1evt
        ng2evtsave=ng2evt
        ng11evtsave=ng11evt
        ng12evtsave=ng12evt
        ng1evtsave=ng1evt
        eglevtsave=eglevt
        fglevtsave=fglevt
        rglevtsave=rglevt
        sglevtsave=sglevt
        chargex=.true.          !before ainit and definition of iret in case of problem to properly restore proj/target ids
        irdmpr=0           !no random charge for projectile

        if(ish.ge.8)
     .call alistc("List after Markov&",1,nptl)

        itp=0
        nppd=0
        nptd=0
        if(iqq.ne.11)then
          nppd=npproj(iproj(kchargex))
          nptd=nptarg(itarg(kchargex))
c       hide particles from original interaction
          if(iqq.eq.0)then
            do n=maproj+matarg+1,nptl
              if(ityptl(n)/10.ne.4.and.ityptl(n)/10.ne.5)
     .             istptl(n)=istptl(n)+101
            enddo
          else
            if(pptl(5,nppd).le.pptl(5,nptd))then
              itp=4
            else
              itp=5
            endif
            do n=maproj+matarg+1,nptl
              if(ityptl(n)/10.ne.itp)istptl(n)=istptl(n)+101
            enddo
          endif
        endif
       
      nptl0=nptl
      ntry=0
 10   ntry=ntry+1
      nptl=nptl0
      

c     then save projectile and target type of pair with CE
      ic(1)=icproj(1,iproj(kchargex))
      ic(2)=icproj(2,iproj(kchargex))
      idprojin=idtra(ic,0,0,0)
      ic(1)=ictarg(1,itarg(kchargex))
      ic(2)=ictarg(2,itarg(kchargex))
      idtargin=idtra(ic,0,0,0)


c     Select single or double charge exchange
      LCE(1)=.true.     !CD
      LCE(2)=.true.
      if(itp.eq.5)then !SD pro or DD
        LCE(1)=.false.
      elseif(itp.eq.4)then !SD tar or DD
        LCE(2)=.false.
      elseif(iqq.ne.0)then  !charge exchange
        xran=rangen()
        if(xran.le.xschargex(1))then
          LCE(2)=.false.        !exchange only on projectile side
        elseif(xran.le.xschargex(1)+xschargex(2))then
          LCE(1)=.false.        !exchange only on target side
        endif
      endif

c     Offset for beam particles
      if(ish.ge.5)write(ifch,*)'index:',nptl,itp
     .             ,kchargex,iproj(kchargex),itarg(kchargex),LCE

c     LOOP on both side
      istart(1)=nptl+4
      istart(2)=nptl+4
      i1=1
      i2=2
      is=1
      if(LCE(1).and.LCE(2))then
        istart(1)=nptl+3
        istart(2)=nptl+6
c        if(rangen().lt.0.5)then
c          i1=2
c          i2=1
c          is=-1
c        endif
      elseif(LCE(2))then    !to keep the same order for produced particles
        i1=2
        i2=1
        is=-1
      endif
      if(iqq.ne.11)then     !for diffraction, we keep original emitting beam remnant, so no need to produce a new one
        istart(1)=istart(1)-1
        istart(2)=istart(2)-1
      endif
      ESUM=0d0
      PSUM=0d0
      pbeam=pnullx0
      do i=i1,i2,is

        if(i.eq.1)then
          idbeam=idprojin
          nbeam=iproj(kchargex)
          n1=1
          n2=maproj
          isave=1
          iept=40
          npd=nppd
        else
          idbeam=idtargin
          nbeam=itarg(kchargex)+maproj
          n1=maproj+1
          n2=maproj+matarg
          isave=-1
          iept=50
          npd=nptd
        endif
        if(iqq.ne.11)then
          nbeam=npd
          n1=nbeam
          n2=nbeam
        endif
        
        if(LCE(i))then
   
c     Initialize conditions for Chargex
          ITYPR=1               !pion (or pi-pi)  for pion exchange
c          if(rangen().lt.0.1)ITYPR=2 !check LHCf pi0 data
c          if(abs(idbeam).lt.1000.or.iqq.ne.11)ITYPR=2 !rho for mesons or diffraction
          if(iqq.ne.11)then
            ITYPR=2             !rho for diffraction
c          elseif(rangen().lt.1.)then
c            ITYPR=2             !check LHCf pi0 data
          endif
c          call idflav(idbeam,ifl(1),ifl(2),ifl(3),jspin,ind)
          
c         Call Chargex to get momentum of resonance (PRR) and neutron (PNN)
          ispin0=0
          ipart=110
          if(iqq.eq.11)then
            if(abs(idbeam).lt.1000)then
              if(idbeam.eq.110.or.rangen().lt.0.5)ipart=120 !can only carry one charge type so 0.5 and not 0.6666
              ispin0=1
            else                !Baryon
              if(rangen().lt.0.33333)ispin0=1 !delta resonance in 1/3 of the cases
              if(ispin0.eq.0)then
                ITYPR=2         !check LHCf pi0 data   !to have resonance state while keeping nucleon
                if(rangen().lt.0.66666)ipart=120
              else
                rrr=rangen()
                if(rrr.lt.0.16666)then
                  ipart=120
                elseif(rrr.lt.0.66666)then
                  ipart=-120
                endif
              endif
              if(abs(ipart).eq.120)then
                if(abs(idbeam).eq.1220)ipart=-ipart
                if(idbeam.lt.0)ipart=-ipart
              endif
            endif
          endif
          if(ITYPR.eq.2)ipart=sign(abs(ipart)+1,ipart)
          ispin=ispin0+mod(abs(idbeam),10)    !spin of remnant (resonance) after pion/rho emission
     
        
c 20       continue
          call idmass(ipart,m(i))
          PRR(5)=dble(m(i))
          if(iqq.eq.11)then
 20         continue
c           PNN(3)=RANNORM(0.88d0,0.15d0) !tune to LHCf and HERA
            if(abs(idbeam).lt.1000)then
c              PNN(3)=RANNORM(1.d0,0.35d0)  !tune to NA61
              PNN(3)=RANNORM(0.9d0,0.25d0)  !tune to NA61
            else
c              PNN(3)=RANNORM(1.d0,0.2d0)   !tune to LHCf and HERA and pp400
              PNN(3)=RANNORM(0.9d0,0.25d0)   !tune to LHCf and HERA and pp400
            endif
            if(drangen(PNN(3)).lt.
     .        (PNN(3)/(1d0-dble(0.5*egymin/engy)))**3)goto 20
            PNN(3)=PNN(3)*pnullx0
            PTR=0.2d0*dble(ranptcut(5.))
            PHIR=dble(2.*pi)*drangen(PTR)
            PNN(1)=PTR*cos(PHIR)
            PNN(2)=PTR*sin(PHIR)
            idbaryon=idresch(ipart,idbeam)
            if(abs(idbeam).lt.1000)
     .      idbaryon=sign(abs(idbaryon-mod(idbaryon,10))+ispin,idbaryon)
            call idmass(idbaryon,m3)          
            MP=dble(m3)
            PNN(5)=MP
            PNN(4)=SQRT(PNN(5)**2+PNN(3)**2+PNN(2)**2+PNN(1)**2)
            PRR(1)=-PNN(1)
            PRR(2)=-PNN(2)
            PRR(3)=pnullx0-PNN(3)
            PRR(4)=SQRT(PRR(5)**2+PRR(3)**2+PRR(2)**2+PRR(1)**2)
            fac=0.5d0*dble(engy)/(PRR(4)+PNN(4))
            if(ish.ge.8)write(ifch,*)'pion fac',fac
            do k=1,3
              PNN(k)=PNN(k)*fac
              PRR(k)=PRR(k)*fac
            enddo
            PNN(4)=SQRT(PNN(5)**2+PNN(3)**2+PNN(2)**2+PNN(1)**2)
            PRR(4)=SQRT(PRR(5)**2+PRR(3)**2+PRR(2)**2+PRR(1)**2)
          else
            do k=1,5
              PNN(k)=dble(pptl(k,npd))
            enddo
            PNN(3)=abs(PNN(3))
c            MP=sqrt(PNN(1)**2+PNN(2)**2+PNN(5)**2)
c           PNN(3)=PNN(4)*sqrt((1d0-MP/PNN(4))*(1d0+MP/PNN(4)))     !to have a better precision than pptl(3) which is single precision) (always positive because sign is given back later
            call idmass(idbeam,m3)          
            MP=dble(m3)
            PRR(4)=sqrt(pnullx0**2+MP**2)-PNN(4)
            PRR(1)=-PNN(1)
            PRR(2)=-PNN(2)
            MP=sqrt(PRR(1)**2+PRR(2)**2+PRR(5)**2)
            PRR(3)=(1d0-MP/PRR(4))*(1d0+MP/PRR(4))
            if(PRR(3).gt.0d0)then
              PRR(3)=PRR(4)*sqrt(PRR(3))
              if(ish.ge.8)then
                pbeam=PRR(3)+PNN(3)
                write(ifch,*)'masses,pbeam',pptl(5,nppd),pptl(5,nptd)
     .                                     ,pbeam
                write(ifch,*)'PNN,PRR',PNN,PRR
     .  ,sqrt((PNN(4)-PNN(3))*(PNN(4)+PNN(3))-PNN(1)**2-PNN(2)**2)
              endif
            else
              PRR(3)=-PRR(4)*sqrt(abs(PRR(3)))
              if(ish.ge.1)
     .             write(ifmt,*)'Energy too low in Pomeron exchange ! '
     .                         ,'(xmindiff too low)'
              if(ish.ge.2)then
                write(ifch,*)'masses',pptl(5,nppd),pptl(5,nptd)
                write(ifch,*)'PRR',PRR,
     .  sqrt((PNN(4)-PNN(3))*(PNN(4)+PNN(3))-PNN(1)**2-PNN(2)**2)
                write(ifch,*)'Energy too low in Pom exchange, skip !'
              endif
              iret=1
              return
            endif
            fac=0.5d0*dble(engy)/(PRR(4)+PNN(4))
            if(ish.ge.8)write(ifch,*)'diff fac',fac
            do k=1,3
              PNN(k)=PNN(k)*fac
              PRR(k)=PRR(k)*fac
            enddo
            PNN(4)=SQRT(PNN(5)**2+PNN(3)**2+PNN(2)**2+PNN(1)**2)
            PRR(4)=SQRT(PRR(5)**2+PRR(3)**2+PRR(2)**2+PRR(1)**2)
            idbaryon=idbeam
          endif
        
          IF(i.eq.2) THEN       !for target
            k=3
            PNN(k)=-PNN(k)
            PRR(k)=-PRR(k)
            idtargin=ipart
          ELSE
            idprojin=ipart
          ENDIF

          do k=1,5
            P(k,i)=PRR(k)
          enddo
          
          
c     copy projectile (beam, resonance and neutron) at the end of final stack (temporary)

          ior=0
c         original beam
          do n=n1,n2
            if(nbeam.eq.n)then  !modified nucleon
              if(istptl(n).eq.0)then
                istptl(n)=1
                iorptl(n)=-1
                jorptl(n)=0
              endif
              ior=n             !origin of resonance
              if(iqq.eq.11)then
                if(LCE(1).and.LCE(2))then
                  ifrptl(1,n)=istart(i)-2
                  ifrptl(2,n)=istart(i)-1
                else
                  ifrptl(1,n)=istart(i)-3
                  ifrptl(2,n)=istart(i)-2
                endif
              endif
            endif
          enddo
      
c         produced resonance (for tagging)      
          nptl=nptl+1
          call utrepla(nptl,ior)
          idptl(nptl)=sign(9900000+abs(ipart),ipart)
          pptl(1,nptl)=sngl(P(1,i))
          pptl(2,nptl)=sngl(P(2,i))
          pptl(3,nptl)=sngl(P(3,i))
          pptl(4,nptl)=sngl(P(4,i))
          pptl(5,nptl)=sngl(P(5,i))
          istptl(nptl)=41
          ityptl(nptl)=iept
          iorptl(nptl)=ior
          if(i.eq.1.or.LCE(1))then
            ifrptl(1,nptl)=istart(2)+i
            ifrptl(2,nptl)=istart(2)+i
          else
            ifrptl(1,nptl)=istart(2)+maproj+1
            ifrptl(2,nptl)=istart(2)+maproj+1
          endif
          xorptl(1,nptl)=coord(1,kchargex)
          xorptl(2,nptl)=coord(2,kchargex)
          xorptl(3,nptl)=coord(3,kchargex)
          xorptl(4,nptl)=coord(4,kchargex)
          tivptl(1,nptl)=xorptl(4,nptl)
          tivptl(2,nptl)=xorptl(4,nptl)
          PSUM=PSUM+P(3,i)
          ESUM=ESUM+P(4,i)

c         produced baryon (for tagging)
          nptl=nptl+1
          call utrepla(nptl,ior)
          idptl(nptl)=sign(9900000+abs(idbaryon),idbaryon)
          pptl(1,nptl)=sngl(PNN(1))
          pptl(2,nptl)=sngl(PNN(2))
          pptl(3,nptl)=sngl(PNN(3))
          pptl(4,nptl)=sngl(PNN(4))
          pptl(5,nptl)=sngl(PNN(5))
          istptl(nptl)=41
          ityptl(nptl)=iept
          iorptl(nptl)=ior
          if(iqq.eq.11)then
            ifrptl(1,nptl)=nptl+1
            ifrptl(2,nptl)=nptl+1
          else
            ifrptl(1,nptl)=ifrptl(1,ior)
            ifrptl(2,nptl)=ifrptl(2,ior)
            ifrptl(1,ior)=istart(i)-2
            ifrptl(2,ior)=istart(i)-1
          endif
          xorptl(1,nptl)=coord(1,kchargex)
          xorptl(2,nptl)=coord(2,kchargex)
          xorptl(3,nptl)=coord(3,kchargex)
          xorptl(4,nptl)=coord(4,kchargex)
          tivptl(1,nptl)=xorptl(4,nptl)
          tivptl(2,nptl)=xorptl(4,nptl)
          PSUM=PSUM+PNN(3)
          ESUM=ESUM+PNN(4)


          if(iqq.eq.11)then
c         produced baryon (final)
          nptl=nptl+1
          call utrepla(nptl,nptl-1)
          idptl(nptl)=idbaryon
          istptl(nptl)=0
          ityptl(nptl)=iept+8
          iorptl(nptl)=nptl-1
          ifrptl(1,nptl)=0
          ifrptl(2,nptl)=0
          call updateXor(nptl,nptl)
          endif
      
      else

c       Momentum of new target (original one) and projectile (resonance)
          call idmass(idbeam,m(i)) !target mass = proton
          MP=dble(m(i))
          P(5,i)=MP  
          P(1,i)=0.0d0
          P(2,i)=0.0d0
          P(3,i)=isave*pbeam
          P(4,i)=sqrt(P(3,i)**2+MP**2)
          PSUM=PSUM+P(3,i)
          ESUM=ESUM+P(4,i)

          ior=0
c         original beam
          do n=n1,n2
            if(nbeam.eq.n)then  !modified nucleon
              if(istptl(n).eq.0)then
                istptl(n)=1
                iorptl(n)=-1
                jorptl(n)=0
              endif
              nptl=nptl+1
              call utrepla(nptl,n)
              pptl(1,nptl)=sngl(P(1,i))
              pptl(2,nptl)=sngl(P(2,i))
              pptl(3,nptl)=sngl(P(3,i))
              pptl(4,nptl)=sngl(P(4,i))
              pptl(5,nptl)=sngl(P(5,i))
              idptl(nptl)=sign(9900000+abs(idbeam),idbeam)
              istptl(nptl)=41
              ityptl(nptl)=iept
              iorptl(nptl)=n
              if((i.eq.1.and.maproj.eq.1)
     .       .or.(i.eq.2.and.matarg.eq.1))then
                ifrptl(1,nptl)=istart(i)+i
                ifrptl(2,nptl)=istart(i)+i
              else
                ifrptl(1,nptl)=0
                ifrptl(2,nptl)=0
              endif
              ifrptl(1,n)=nptl
              ifrptl(2,n)=nptl
              xorptl(1,nptl)=coord(1,kchargex)
              xorptl(2,nptl)=coord(2,kchargex)
              xorptl(3,nptl)=coord(3,kchargex)
              xorptl(4,nptl)=coord(4,kchargex)
              tivptl(1,nptl)=xorptl(4,nptl)
              tivptl(2,nptl)=xorptl(4,nptl)
            endif
           enddo

        endif

      enddo

      if(ish.ge.5)write(ifch,*)'Check before',PSUM,ESUM-dble(engy)
        
c     Frame Momentum in cms frame of detector
      do k=1,5
        pframe(k)=0d0
      enddo
      do n=1,2
        do k=1,4
          pframe(k)=pframe(k)+P(k,n)
        enddo
      enddo
      pframe(5)=sqrt(max(0d0,(pframe(4)+pframe(3))
     .  *(pframe(4)-pframe(3))+pframe(1)*pframe(1)+pframe(2)*pframe(2)))

      ptarg=-sqrt(P(3,2)**2+P(2,2)**2+P(1,2)**2) !target
      pproj=sqrt(P(3,1)**2+P(2,1)**2+P(1,1)**2) !projectile
      
      
c     Calculations of energy of the center-of-mass in the detector frame


      e1=dsqrt(dble(m(1))**2+pproj**2)
      e2=dsqrt(dble(m(2))**2+ptarg**2)
      decms=dsqrt(((e1+e2)+(pproj+ptarg))*((e1+e2)-(pproj+ptarg)))

c      if(iqq.eq.11)print *,
      if(ish.ge.5)write(ifch,*)
     .           'Chargex input',ipart,idbaryon,idprojin,idtargin
     .                                 ,decms,pproj,ptarg,m,pframe(5)
      if(decms.lt.dble(egymin))then
        if(ntry.lt.100)then
          goto 10
        else
          if(ish.ge.2)
     .     write(ifch,*)'Energy too low in charge exchange, skip !'
          iret=1
          return
        endif
      endif
      if(abs(pframe(5)**2-((pframe(4)+pframe(3))*(pframe(4)-pframe(3))
     .     +pframe(1)*pframe(1)+pframe(2)*pframe(2)))
     .                                      .gt.1d-5*pframe(5)**2)then
        if(ish.ge.2)
     .       write(ifch,*)'Problem with energy in pion exchange, skip !'
     .      ,pframe
        iret=1
        return
      endif
      
      if(ish.ge.5)
     .call alistc("List before pion-nucleon interaction&",1,nptl)


c     Update some parameters value to run correctly
      if(iqq.ne.11)iomega=2     !no diffraction for hard diffraction
      if(LCE(1))maproj=1
      if(LCE(2))matarg=1
      if(LCE(1))laproj=-1               !<0 means any hadron
      if(LCE(2))latarg=-1
      noebin=1
      ecms=-1      !energy
      elab=-1      !energy lab
      ekin=-1      !energy kinetic
      pnll=-1      !momentum
      engy=sngl(decms)          !center of mass energy in GeV/c2

      ichargex=0

      
c     Initialization for newly define cms energy and projectile/target
      call ainit

      istart(2)=nptl
      do n=1,nptl
        call utrepla(mxptl-n,n) !copy at the end
      enddo

      if(sigtotaa.gt.0.)then
        xsratio=sigineaa/sigtotaa
      else
        xsratio=sigine/sigtot
      endif
      if(ish.ge.5)write(ifch,*)'call model',engy,xsratio,idproj,idtargin
     .     ,laproj,maproj,latarg,matarg
      
      if(iqq.ne.11.or.rangen().lt.xsratio)then   !inelastic pion interaction or diffraction
      
        iret=0
        
      else        !elastic pion interaction, nothing done (just resonance emission)
        maproj=1     !to simplify spectator treatment
        laproj=-1
        matarg=1
        latarg=-1
        iret=-1
        call conre     !define projectile and target (elastic scattering)
        call conwr
        typevt=0
        nevt=1
        if(ish.ge.5)write(ifch,*)'elastic pion interaction !'
        
      endif
      
      else                      !event between resonance and baryon was successfull ----------

        if(iret.eq.0)then

c     Update typevt to indicate charge exchange by adding "10"
          if(iomega.ne.2)then
            typevt=sign(abs(typevt)+10,typevt)
          else
            typevt=typevtsave
          endif

c Define origin of virtual beam particle, update indices and boost back in original CMS frame
        ESUM=pframe(4)
        PSUM=pframe(3)
        if(maproj.gt.1)then
          ma=maproj-1
          ESUM=ESUM+ma*P(4,1)
          PSUM=PSUM+ma*P(3,1)
        elseif(matarg.gt.1)then
          ma=matarg-1
          ESUM=ESUM+ma*P(4,2)
          PSUM=PSUM+ma*P(3,2)
        endif
        if(ish.ge.8)call alistc("before boost",1,nptl)
        do i=1,nptl
          if(i.gt.maproj+matarg)iorptl(i)=iorptl(i)+istart(2)
          if(jorptl(i).gt.0)jorptl(i)=jorptl(i)+istart(2)
          if(ifrptl(1,i).gt.0)ifrptl(1,i)=ifrptl(1,i)+istart(2)
          if(ifrptl(2,i).gt.0)ifrptl(2,i)=ifrptl(2,i)+istart(2)
c        write(*,'(i6,i10,1x,4(e12.6,1x))')i,idptl(i),(xorptl(k,i),k=1,4)
c        write(*,'(i5,3x,i2,2x,2i5,2x,2i5)')i,istptl(i)
c     *        ,iorptl(i),jorptl(i),ifrptl(1,i),ifrptl(2,i)
c         write(*,'(i10,1x,4(e12.6,1x))')idptl(i),(pptl(k,i),k=1,4)
c         boost particles to original cms frame
        call utlob4(-1,pframe(1),pframe(2),pframe(3),pframe(4),pframe(5)
     +           ,xorptl(1,i),xorptl(2,i),xorptl(3,i),xorptl(4,i))
        call utlob4(-1,pframe(1),pframe(2),pframe(3),pframe(4),pframe(5)
     +       , pptl(1,i), pptl(2,i), pptl(3,i), pptl(4,i))
c      write(*,'(i10,1x,4(e12.6,1x))')idptl(i),(xorptl(k,i),k=1,4)
c         write(*,'(i5,3x,i2,2x,2i5,2x,2i5)')i,istptl(i)
c     *        ,iorptl(i),jorptl(i),ifrptl(1,i),ifrptl(2,i)
c       write(*,'(i10,1x,4(e12.6,1x))')idptl(i),(pptl(k,i),k=1,4)
        if(mod(istptl(i),10).eq.0)then
          ESUM=ESUM-pptl(4,i)
          PSUM=PSUM-pptl(3,i)
        endif
      enddo
      if(ish.ge.8)call alistc("after boost",1,nptl)
c      call alistf('list after exchange&')
      if(ish.ge.5)write(ifch,*)'Check after',PSUM,ESUM

c     define status of new particle beam
      do i=1,maproj
        if(typevt.ne.10.and.maproj.gt.1)then    !if not elastic only copy new nucleus into old one
          call utrepla(mxptl-i,i)
          if(istptl(mxptl-i).eq.0)then !pt of spectator should be 0
            pptl(1,mxptl-i)=0.
            pptl(2,mxptl-i)=0.
            pptl(4,mxptl-i)=sqrt(pptl(3,mxptl-i)**2+pptl(5,mxptl-i)**2)
          endif
          iorptl(i)=i         
        endif
        if(istptl(i).ne.0.or.maproj.gt.1)then
          idptl(i)=sign(9900000+abs(idptl(i)),idptl(i))
          istptl(i)=41
        endif
        if(iomega.ne.2)then
          ityptl(i)=48
        else
          ityptl(i)=45
        endif
        if(LCE(1).and.LCE(2))then
          iorptl(i)=istart(1)-2
        elseif(LCE(1))then
          iorptl(i)=istart(1)-3
        elseif(typevt.eq.10)then
          iorptl(i)=istart(1)
          ifrptl(1,mxptl-iorptl(i))=iorptl(i)+1
          ifrptl(2,mxptl-iorptl(i))=iorptl(i)+1
        elseif(maproj.eq.1)then
          iorptl(i)=istart(1)
        endif
      enddo
      do i=maproj+1,maproj+matarg
        if(typevt.ne.10.and.matarg.gt.1)then    !if not elastic only copy new nucleus into old one
          call utrepla(mxptl-i,i)
          if(istptl(mxptl-i).eq.0)then !pt of spectator should be 0
            pptl(1,mxptl-i)=0.
            pptl(2,mxptl-i)=0.
            pptl(4,mxptl-i)=sqrt(pptl(3,mxptl-i)**2+pptl(5,mxptl-i)**2)
          endif
          iorptl(i)=i         
        endif
        if(istptl(i).ne.0.or.matarg.gt.1)then
          idptl(i)=sign(9900000+abs(idptl(i)),idptl(i))
          istptl(i)=41
        endif
        if(iomega.ne.2)then
          ityptl(i)=58
        else
          ityptl(i)=55
        endif
        if(LCE(1).and.LCE(2))then
          iorptl(i)=istart(2)-2
        elseif(LCE(2))then
          iorptl(i)=istart(2)-3
        elseif(typevt.eq.10)then
          iorptl(i)=istart(2)
          ifrptl(1,mxptl-iorptl(i))=iorptl(i)+2
          ifrptl(2,mxptl-iorptl(i))=iorptl(i)+2
        elseif(matarg.eq.1)then
          iorptl(i)=istart(2)
        endif
      enddo
        
       
c     Copy new particles before the initial beam particles in reversed order at the end of the stack
      do n=1,nptl
        call utrepla(mxptl-istart(2)-n,n)    !copy at the end
      enddo

c     Copy back from the end to the beginning of the stack
      nptl=nptl+istart(2)
      do n=1,nptl
        call utrepla(n,mxptl-n)    !copy at the beginning
      enddo

c      call alistc("List after pion-nucleon interaction&",1,nptl)
      
c      do i=1,nptl
c
c      write(*,'(i10,1x,4(e12.6,1x))')idptl(i),(xorptl(k,i),k=1,4)
c         write(*,'(i5,3x,i2,2x,2i5,2x,2i5)')i,istptl(i)
c     *        ,iorptl(i),jorptl(i),ifrptl(1,i),ifrptl(2,i)
c       write(*,'(i10,1x,4(e12.6,1x))')idptl(i),(pptl(k,i),k=1,4)
c        
c     enddo

      endif
      
c     update /cevt/
c     ------------

        bimevt=bimpsave
        phievt=phisave
        pmxevt=pnllsave
        egyevt=engysave
        
c     second call, restore initial conditions
        ichargex=1
        irdmpr=irdmprsave
        noebin=noebinsave
        engy=engysave
        maproj=maprojsave
        matarg=matargsave
        laproj=laprojsave
        latarg=latargsave
        iomega=iomegasave
        idprojin=idprojinsave
        idtargin=idtarginsave
        idproj=idprojsave
        idtarg=idtargsave
        nglevt=nglevtsave
        ng1evt=ng1evtsave
        ng2evt=ng2evtsave
        ng11evt=ng11evtsave
        ng12evt=ng12evtsave
        ng1evt=ng1evtsave
        eglevt=eglevtsave
        fglevt=fglevtsave
        rglevt=rglevtsave
        sglevt=sglevtsave
        if(noebin.lt.0)qsqevt=qsqevtsave
        ecms=-1
        elab=-1
        ekin=-1
        pnll=-1
        call ainit              !restore normal run

        chargex=.false.         !after ainit to avoid print out


      endif

      end

c--------------------------------------------------------------------
      integer function idresch(ipart,idbeam)
c--------------------------------------------------------------------
c  returns new particle id when idbeam emit ipart
c--------------------------------------------------------------------
      real rangen
      integer ipart,ic(2),iqu,iqd,i,k

      ic(1)=0
      ic(2)=0
      idresch=0
      if(abs(ipart)/10.eq.12)then
        iqu=1
        iqd=-1
        if(ipart.lt.0.)then !could be the antiparticle
          iqu=-iqu
          iqd=-iqd
        endif
        call idtr6(idbeam,ic)
        if(abs(idbeam).gt.1000)then
          i=1
          if(idbeam.lt.0)i=2
          if(ic(i)/100000-iqu.ge.0.and.mod(ic(i)/10000,10)-iqd.ge.0)then
            ic(i)=ic(i)-iqu*100000-iqd*10000
          else
            ipart=-ipart
            iqu=-iqu
            iqd=-iqd
            ic(i)=ic(i)-iqu*100000-iqd*10000
          endif
        else
          i=1
          k=2
          iqu=1
          iqd=-1
          if(rangen().lt.0.5)then !could be pi+ or pi-
            ipart=-ipart
            i=2
            k=1
          endif
          if(ic(i)/100000-iqu.ne.0.and.mod(ic(k)/10000,10)-iqd.ne.0
     .       .and.ic(i)/10000-ic(k)/10000.ne.0)then
            ipart=-ipart
            if(ipart.lt.0)then
              i=2
              k=1
            else
              i=1
              k=2
            endif
          endif
          if(mod(ic(k)/10000,10)-abs(iqd).eq.0)then
            ic(k)=100000
          elseif(ic(i)/100000-abs(iqu).eq.0)then
            ic(i)=10000
          endif
        endif
        idresch=idtr2(ic)
      elseif(ipart/10.eq.11)then
        idresch=idbeam
      else
        print *,'should not be',idbeam,ic,iqu,iqd,ipart
        call utstop ("idresch: ipart not allowed !&")
      endif
      if(abs(idresch).lt.20)then
        print *,'should not be',idbeam,ic,iqu,iqd,ipart
        call utstop ("idresch: result not allowed !&")
      endif

      return
      end

        

      
