c      subroutine hnbrt2old(c,s,c2,s2,pr,i)
cc-------------------------------------------------------------------
cc  formerly subr rotes2 from cernlib
cc  this subr now does two rotations (xy and xz)
cc-------------------------------------------------------------------
c      parameter(maxp=6000)
c      dimension pr(5*maxp)
c      k1 = 5*i - 4
c      k2 = k1 + 1
c      sa = pr(k1)
c      sb = pr(k2)
c      a      = sa*c - sb*s
c      pr(k2) = sa*s + sb*c
c      k2 = k2 + 1
c      b = pr(k2)
c      pr(k1) = a*c2 - b*s2
c      pr(k2) = a*s2 + b*c2
c      return
c      end
c
c-------------------------------------------------------------------
      subroutine hnbrt2(c,s,c2,s2,pr,i)
c-------------------------------------------------------------------
c  formerly subr rotes2 from cernlib
c  this subr now does two rotations (xy and xz)
c-------------------------------------------------------------------
      parameter(maxp=6000)
      dimension pr(5,maxp)
      k1 = 5*i - 4
      k2 = k1 + 1
      sa = pr(1,i)
      sb = pr(2,i)
      a      = sa*c - sb*s
      pr(2,i) = sa*s + sb*c
      k2 = k2 + 1
      b = pr(3,i)
      pr(1,i) = a*c2 - b*s2
      pr(3,i) = a*s2 + b*c2
      return
      end

