c------------------------------------------------------------------------------
      integer function idtrafo(code1,code2,idi)
c------------------------------------------------------------------------------
c wrapper for idtrafo to catch if ID not found
      character*3 code1,code2
      integer istatus=0
      idtrafo = idtrafostatus(code1,code2,idi,istatus)
c      if (istatus.ne.0) then
c         print *,'idtrafo: ',code1,' -> ', code2,idi,' not found.'
c         stop
c      endif
      return
      end

c------------------------------------------------------------------------------
      integer function idtrafostatus(code1,code2,idi,istatus)
     +     result(idtrafo)
c------------------------------------------------------------------------------
c.....tranforms id of code1 (=idi) into id of code2 (=idtrafo)
c.....supported codes:
c.....'nxs' = epos
c.....'pdg' = PDG 1996 (DPMJET)
c.....'qgs' = QGSJet
c.....'III' = QGSJetIII
c.....'ghe' = Gheisha
c.....'sib' = Sibyll
c.....'cor' = Corsika (GEANT)
c.....'flk' = Fluka

c.....returns status 0 if ID could be converted and 1 if it was not found in table

C --- ighenex(I)=EPOS CODE CORRESPONDING TO GHEISHA CODE I ---

      common /ighnx/ ighenex(35)
      data ighenex/
     $               10,   11,   -12,    12,   -14,    14,   120,   110,
     $             -120,  130,    20,   -20,  -130,  1120, -1120,  1220,
     $            -1220, 2130, -2130,  1130,  1230,  2230, -1130, -1230,
     $            -2230, 1330,  2330, -1330, -2330,    17,    18,    19,
     $            3331, -3331,  30/

C --- DATA STMTS. FOR GEANT/GHEISHA PARTICLE CODE CONVERSIONS ---
C --- KIPART(I)=GHEISHA CODE CORRESPONDING TO GEANT   CODE I ---
C --- IKPART(I)=GEANT   CODE CORRESPONDING TO GHEISHA CODE I ---
      DIMENSION        KIPART(48)!,IKPART(35)
      DATA KIPART/
     $               1,   3,   4,   2,   5,   6,   8,   7,
     $               9,  12,  10,  13,  16,  14,  15,  11,
     $              35,  18,  20,  21,  22,  26,  27,  33,
     $              17,  19,  23,  24,  25,  28,  29,  34,
     $              35,  35,  35,  35,  35,  35,  35,  35,
     $              35,  35,  35,  35,  30,  31,  32,  35/

c      DATA IKPART/
c     $               1,   4,   2,   3,   5,   6,   8,   7,
c     $               9,  11,  16,  10,  12,  14,  15,  13,
c     $              25,  18,  26,  19,  20,  21,  27,  28,
c     $              29,  22,  23,  30,  31,  45,  46,  47,
c     $              24,  32,  48/
      INTEGER          ICFTABL(200),IFCTABL(-6:100)
C  ICTABL CONVERTS CORSIKA PARTICLES INTO FLUKA PARTICLES
C  FIRST TABLE ONLY IF CHARMED PARTICLES CAN BE TREATED
      DATA ICFTABL/
     *   7,   4,   3,   0,  10,  11,  23,  13,  14,  12,  ! 10
     *  15,  16,   8,   1,   2,  19,   0,  17,  21,  22,  ! 20
     *  20,  34,  36,  38,   9,  18,  31,  32,  33,  34,  ! 30
     *  37,  39,  24,  25, 6*0,
     *  0,    0,   0,   0,  -3,  -4,  -6,  -5,   0,   0,  ! 50
     *  10*0,
     *   0,   0,   0,   0,   0,   5,   6,  27,  28,   0,  ! 70
     *  10*0,
     *  10*0,
     *  10*0,                                             !100
     *  10*0,
     *   0,   0,   0,   0,   0,  47,  45,  46,  48,  49,  !120
     *  50,   0,   0,   0,   0,   0,   0,   0,   0,   0,  !130
     *  41,  42,  43,  44,   0,   0,  51,  52,  53,   0,  !140
     *   0,   0,  54,  55,  56,   0,   0,   0,  57,  58,  !150
     *  59,   0,   0,   0,  60,  61,  62,   0,   0,   0,  !160
     *  40*0/
C  IFCTABL CONVERTS FLUKA PARTICLES INTO CORSIKA PARTICLES
      DATA IFCTABL/
     *                402, 302, 301, 201,   0,   0,   0,
     *  14,  15,   3,   2,  66,  67,   1,  13,  25,   5,
     *   6,  10,   8,   9,  11,  12,  18,  26,  16,  21,
     *  19,  20,   7,  33,  34,   0,  68,  69,   0,   0,
     *  27,  28,  29,  22,  30,  23,  31,  24,  32,   0,
     * 131, 132, 133, 134, 117, 118, 116, 119, 120, 121,
     * 137, 138, 139, 143, 144, 145, 149, 150, 151, 155,
     * 156, 157,   0,   0,   36*0/
c-------------------------------------------------------------------------------
      include 'epos.inc'

      integer istatus
      character*3 code1,code2
c      double precision drangen,dummy !gs unused after correction with mutbl
      
      istatus=0
      idtrafo=0
      id1=idi
      if(code1.eq.'nxs')then
        i=1
      elseif(code1.eq.'pdg')then
        i=2
      elseif(code1.eq.'qgs')then
        i=3
        if(id1.eq.-10)id1=18
        if(abs(id1).eq.7.or.abs(id1).eq.8)id1=id1*10
      elseif(code1.eq.'III')then
        i=3
      elseif(code1.eq.'cor')then
        i=4
      elseif(code1.eq.'sib')then
        i=5
        if(abs(id1).eq.99)id1=sign(100,id1)
      elseif(code1.eq.'ghe')then
        id1=ighenex(id1)
        i=1
      elseif(code1.eq.'flk')then
        id1=IFCTABL(id1)          !convert to corsika code
        i=4
      else
        stop "unknown code in idtrafo"
      endif
      if(code2.eq.'nxs')then
        j=1
        ji=j
        if(i.eq.2.and.id1.gt.1000000000)then   !nucleus from PDG
          idtrafo=id1
          return
        elseif(i.eq.4.and.id1.gt.402)then               !nucleus from Corsika
          idtrafo=1000000000+mod(id1,100)*10000+(id1/100)*10
          return
        elseif(i.eq.5.and.id1.gt.1004)then               !nucleus from Sibyll
          id1=(id1-1000)
          idtrafo=1000000000+id1/2*10000+id1*10
          return
        elseif(id1.eq.130.and.i.eq.2)then
          idtrafo=-20
          return
        endif
      elseif(code2.eq.'pdg')then
        j=2
        ji=j
        if(i.eq.1.and.id1.gt.1000000000)then !nucleus from NEXUS
          idtrafo=id1
          return
        elseif(i.eq.4.and.id1.gt.402)then               !nucleus from Corsika
          idtrafo=1000000000+mod(id1,100)*10000+(id1/100)*10
          return
        elseif(i.eq.5.and.id1.gt.1004)then               !nucleus from Sibyll
          id1=(id1-1000)
          idtrafo=1000000000+id1/2*10000+id1*10
          return
        elseif(id1.eq.-20.and.i.eq.1)then
          idtrafo=130
          return
        endif
       elseif(code2.eq.'qgs')then
        j=3
        ji=j
       elseif(code2.eq.'III')then
        j=3
        ji=j
      elseif(code2.eq.'cor')then
        j=4
        ji=j
      elseif(code2.eq.'sib')then
        j=5
        ji=j
      elseif(code2.eq.'ghe')then
        j=4
        ji=6
      elseif(code2.eq.'flk')then
        j=4
        ji=7
       else
        stop "unknown code in idtrafo"
      endif
      if(i.eq.4)then !corsika  id always >0 so convert antiparticles
        iadtr=id1
        if(iadtr.eq.25)then
          id1=-13
        elseif(iadtr.eq.15)then
          id1=-14
        elseif(iadtr.ge.26.and.iadtr.le.32)then
          id1=-iadtr+8
        elseif(iadtr.ge.58.and.iadtr.le.61)then
          id1=-iadtr+4
        elseif(iadtr.ge.149.and.iadtr.le.157)then
          id1=-iadtr+12
        elseif(iadtr.ge.171.and.iadtr.le.173)then
          id1=-iadtr+10
        elseif(iadtr.ge.190.and.iadtr.le.195)then
          id1=-iadtr+6
        endif
      endif
      iad1=abs(id1)
      isi=sign(1,id1)

      if(i.ne.j)then
c      nidtmx=max(nidtmxx(i),nidtmxx(j))
       do n=1,nidtmxx(i)
c        write(ifch,*)idtbl(i,n)
c         print *,i,j,n,id1,idtbl(i,n),idtbl(j,n)
        if(id1.eq.idtbl(i,n))then
          idtrafo=idtbl(j,n)
          if(abs(idtrafo).eq.99.and.abs(id1).ne.3340)then
            !print(ifch,*)
            !.      'unknown '//code2//'_id for '//code1//'_id ',idi
            idtrafo=0
          endif
          if(idtrafo.lt.0.and.j.eq.4)then           !corsika  id always >0
            iadtr=abs(idtrafo)
            if(iadtr.eq.13)then
              idtrafo=25
            elseif(iadtr.eq.14)then
              idtrafo=15
            elseif(iadtr.ge.18.and.iadtr.le.24)then
              idtrafo=iadtr+8
            elseif(iadtr.ge.54.and.iadtr.le.57)then
              idtrafo=iadtr+4
            elseif(iadtr.ge.137.and.iadtr.le.145)then
              idtrafo=iadtr+12
            elseif(iadtr.ge.161.and.iadtr.le.163)then
              idtrafo=iadtr+10
            elseif(iadtr.ge.184.and.iadtr.le.189)then
              idtrafo=iadtr+6
            else
              idtrafo=iadtr
            endif
          elseif(abs(idtrafo).eq.100.and.j.eq.5)then
            idtrafo=sign(99,idtrafo)
          elseif(idtrafo.eq.17.and.code2.eq.'qgs')then
            idtrafo=-10
          elseif(abs(idtrafo).eq.80
     .       .or.abs(idtrafo).eq.70.and.code2.eq.'qgs')then
            idtrafo=idtrafo/10
          endif
          if(j.ne.ji)goto 100
          return
        elseif(mutbl(n).eq.2.and.id1.eq.-idtbl(i,n))then
          idtrafo=-idtbl(j,n)
          if(abs(idtrafo).eq.99)then
            !print(ifch,*)
            !.      'unknown '//code2//'_id for '//code1//'_id ',idi
            idtrafo=0
          endif
          if(idtrafo.lt.0.and.j.eq.4)then           !corsika  id always >0
            iadtr=abs(idtrafo)
            if(iadtr.eq.13)then
              idtrafo=25
            elseif(iadtr.eq.14)then
              idtrafo=15
            elseif(iadtr.ge.18.and.iadtr.le.24)then
              idtrafo=iadtr+8
            elseif(iadtr.ge.54.and.iadtr.le.57)then
              idtrafo=iadtr+4
            elseif(iadtr.ge.137.and.iadtr.le.145)then
              idtrafo=iadtr+12
            elseif(iadtr.ge.161.and.iadtr.le.163)then
              idtrafo=iadtr+10
            elseif(iadtr.ge.184.and.iadtr.le.189)then
              idtrafo=iadtr+6
            else
              idtrafo=iadtr
            endif
          elseif(abs(idtrafo).eq.100.and.j.eq.5)then
            idtrafo=sign(99,idtrafo)
          elseif(idtrafo.eq.17.and.code2.eq.'qgs')then
            idtrafo=-10
          elseif(abs(idtrafo).eq.80
     .       .or.abs(idtrafo).eq.70.and.code2.eq.'qgs')then
            idtrafo=idtrafo/10
         endif
          if(j.ne.ji)goto 100
          return
        endif
       enddo
      else
        idtrafo=id1
        if(j.ne.ji)goto 100
        return
      endif

      istatus=1
c      idtrafocx=0
      return

 100  if(j.eq.4)then            !corsika
        if(idtrafo.eq.201)then
          idtrafo=45
        elseif(idtrafo.eq.301)then
          idtrafo=46
        elseif(idtrafo.eq.402)then
          idtrafo=47
        elseif(idtrafo.eq.302)then
          idtrafo=48
        endif
        if(idtrafo.ne.0)then      !air
          if(ji.eq.6)then
            idtrafo=kipart(idtrafo)
          elseif(ji.eq.7)then
            idtrafo=ICFTABL(idtrafo)
          endif
        endif
        return
      else
        call utstop('Should not happen in idtrafo !&')
      endif

      end

c-------------------------------------------------------------------------
      subroutine id_epostopdg(idepos,idpdg)
c-------------------------------------------------------------------------
c tranforms id from EPOS to PDG
c extracted from function idtrafo
c-------------------------------------------------------------------------
      include 'epos.inc'

      if(idepos.gt.1000000000)then !nucleus from NEXUS
        idpdg=idepos
        return
      elseif(idepos.eq.-20)then
        idpdg=130
        return
      endif
      do n=1,nidtmxx(1)
        if(idepos.eq.idtbl(1,n))then
          idpdg=idtbl(2,n)
          if(abs(idpdg).eq.99)then
            !print(ifch,*)
            !.      'unknown '//code2//'_id for '//code1//'_id ',idi
            idpdg=0
          endif
        elseif(mutbl(n).eq.2.and.idepos.eq.-idtbl(1,n))then
          idpdg=-idtbl(2,n)
          if(abs(idpdg).eq.99)then
            !print(ifch,*)
            !.      'unknown '//code2//'_id for '//code1//'_id ',idi
            idpdg=0
          endif
        endif
      enddo
      return

      end

c-----------------------------------------------------------------------
      subroutine idwidth(id,wi)
c     returns the width of the particle with ident code id.
c-----------------------------------------------------------------------

      include 'epos.inc'
                  
      if(id.ge.-9900.and.id.le.9900)then
        nl=0
        if(id.gt.-700)nl=nlidtbl(id)
        if(nl.eq.0)nl=nlidtbl(abs(id))
        wi=witbl(nl)
        return
      endif       
      
      !treat the rare cases outside range -9900 - 9900
      do nl=1,nidtmxx(1)
        if(idtbl(1,nl).eq.id)then
          wi=amtbl(nl)
          return
        endif
      enddo

      !nothing found
      wi=.197/1.0  !tau=1
      return

      end

c-----------------------------------------------------------------------
      subroutine idmass(idi,amass)
c     returns the mass of the particle with ident code id.
c     (deuteron, triton and alpha mass come from Gheisha ???)
c-----------------------------------------------------------------------

      include 'epos.inc'

      id=idi
      if(id.eq.0)then  !?????id????? please change this !!!!!!!!!!!!!
        id=1120                 !for air target
      elseif(abs(id).ge.1000000000)then   !?????id??????????? change this
      !------------------->  LOOK FOR ALL "?????id?????" also in xan
c        print*,id
        goto 600                !nucleus
      endif
            
      if(id.ge.-9900.and.id.le.9900)then
        nl=nlidtbl(abs(id))
        amass=amtbl(nl)  !nl=0 -> should crash with backtrace
c         print*,'Check mass',id,nl,amass
        if(nl.eq.0)stop'ERROR 07072016' 
        return
      endif       
      
      !treat the rare cases outside range -9900 - 9900
      do nl=1,nidtmxx(1)
        if(idtbl(1,nl).eq.id)then
          amass=amtbl(nl)
          return
        endif
      enddo

      !nothing found
      amass=0
      return
      !stop'####### ERROR 17072016b #######'

600   continue !nuclei
      nbrpro=mod(abs(id/10000),1000)
      nbrneu=mod(abs(id/10),1000)-nbrpro
c        print*,'nuclei',id,nbrpro,nbrneu
      amass=nbrpro*amtbl(nlidtbl(1120))+nbrneu*amtbl(nlidtbl(1220))
      return
      end

c-----------------------------------------------------------------------
      subroutine idflav(id,ifl1,ifl2,ifl3,jspin,idu)
c-----------------------------------------------------------------------
c returns ifl1,ifl2,ifl3,jspin for given id
c  ifl1,ifl2,ifl3: quark flavors
c   baryons: ifl1,ifl2,ifl3
c   mesons: ifl2,ifl3  
c   quarks: ifl3  
c  jspin: excitation counter (0,1,2,3...)
c  idu: dummy (may be used for test purposes)
c-----------------------------------------------------------------------
      
      include 'epos.inc'

      ida=iabs(id)
      idu0=idu !avoid warning
      
      if(ida.le.9900)then
        nl=nlidtbl(abs(id))
        if(nl.eq.0)then
           !~~~~~~~~~~~~~~~~~~~~~~~~ 
           !idu2=iorptl(idu)   !use particle index when calling idflav
           !idu3=iorptl(idu2)
           !print*,'pb idflav',idu,idptl(idu),istptl(idu),ityptl(idu)
           !print*,'         ',idu2,idptl(idu2),istptl(idu2),ityptl(idu2)
           !print*,'         ',idu3,idptl(idu3),istptl(idu3),ityptl(idu3)
           !print*,'             ',ifrptl(1,idu2),ifrptl(2,idu2)
           !~~~~~~~~~~~~~~~~~~~~~~~~
           stop'ERROR 11072016e'
        endif 
        goto 999
      endif  

      !treat the rare cases outside range -9900 - 9900
      do nlx=1,nidtmxx(1)
        if(idtbl(1,nlx).eq.id)then
          nl=nlx
          ida=0 ! to avoid the if... at the end
          goto 999
        endif
      enddo

      !nothing found
      ifl1=0
      ifl2=0
      ifl3=0
      jspin=0
      return

 999  continue

      ifl1=ifl1tbl(nl)
      ifl2=ifl2tbl(nl)
      ifl3=ifl3tbl(nl)
      jspin=jspintbl(nl)
 
      if(id.eq.-ida)then
        ifl1=-ifl1tbl(nl)
        ifl2=-ifl2tbl(nl)
        ifl3=-ifl3tbl(nl)
        jspin=jspintbl(nl)
c        print*,'Check flav 2',id,ifl1,ifl2,ifl3,jspin
      endif       
      
      end

c-------------------------------------------------------------
      subroutine idtr6(id,ic) !id -> ic for via idflav / idt.dt
c-------------------------------------------------------------
      parameter (nflav=6)
      integer jc(nflav,2),ic(2),ifl(3)
      ic(1)=000000
      ic(2)=000000
      if(mod(abs(id),100).eq.99)return !not a particle
      if(iabs(id).gt.16.and.iabs(id).lt.20)then
        if(id.eq.17)then
          ic(1)=330000
          ic(2)=000000
        elseif(id.eq.-17)then
          ic(1)=000000
          ic(2)=330000
        elseif(id.eq.18)then
          ic(1)=450000
          ic(2)=000000
        elseif(id.eq.-18)then
          ic(1)=000000
          ic(2)=450000
        elseif(id.eq.19)then
          ic(1)=660000
          ic(2)=000000
        elseif(id.eq.-19)then
          ic(1)=000000
          ic(2)=660000
        endif
        return
      endif
      if(id.eq.30)then
         ic(1)=222000
         ic(2)=000000
         return
      elseif(id.eq.-30)then
         ic(1)=000000
         ic(2)=222000
         return
      endif
      if(mod(id/10**8,10).eq.8)then
        ic(1)=mod(id,10**8)/10000*100
        ic(2)=mod(id,10**4)*100
        return
      elseif(id/10**9.eq.1.and.mod(id,10).eq.0)then   !nuclei
        nstr=mod(id,10**8)/10000000
        npro=mod(id,10**7)/10000
        nneu=mod(id,10**4)/10
        ic(1)=(2*npro+nneu)*10**5+(2*nneu+npro)*10**4+nstr*10**3
        ic(2)=0
        return
      endif
      do i=1,nflav
        jc(i,1)=0
        jc(i,2)=0
      enddo
      call idflav(id,ifl(1),ifl(2),ifl(3),jspin,idu)
      do j=1,3
         if(ifl(j).gt.0)jc(ifl(j),1)=jc(ifl(j),1)+1
         if(ifl(j).lt.0)jc(-ifl(j),2)=jc(-ifl(j),2)+1
      enddo
      call idenco(jc,ic,iret)
      !print*,'idtr6',idxx,'  ',ifl,'   ',ic
      end

c-----------------------------------------------------------------------
      subroutine idqufl(n,id,nqu,nqd,nqs,nqc)
c     unpacks the ident code of particle (n) and give the number of
c     quarks of each flavour(only u,d,s,c)
c-----------------------------------------------------------------------
      include 'epos.inc'
      include 'epos.incems'
      parameter (nflavt=6)
      integer jc(nflavt,2),ic(2)

      nqu=0
      nqd=0
      nqs=0
      if(iabs(id).ge.7.and.iabs(id).lt.100.and.iabs(id).ne.20)return
      if(iabs(id)/10.eq.11.or.iabs(id)/10.eq.22)return
      if(iabs(id).eq.20)then
        if(iorptl(n).gt.0)then
          if(idptl(iorptl(n)).gt.0)then
            nqd=1
            nqs=-1
          else
            nqd=-1
            nqs=1
          endif
        else
          if(ish.ge.4)write(ifch,*)'Cannot count the number of quark'
        endif
        return
      endif
      if(id.ne.0.and.mod(id,100).eq.0.and.id.le.10**8) goto 300
      if(id/10**8.ne.7)then
        call idtr6(id,ic)
        call iddeco(ic,jc)
      else
        call idtrb(ibptl(1,n),ibptl(2,n),ibptl(3,n),ibptl(4,n),jc)
      endif
      nqu=jc(1,1)-jc(1,2)
      nqd=jc(2,1)-jc(2,2)
      nqs=jc(3,1)-jc(3,2)
      nqc=jc(4,1)-jc(4,2)
      return
 300  i=iabs(id)/1000
      j=mod(iabs(id)/100,10)
      ifl1=isign(i,id)
      ifl2=isign(j,id)
      if(iabs(ifl1).eq.1)nqu=isign(1,ifl1)
      if(iabs(ifl1).eq.2)nqd=isign(1,ifl1)
      if(iabs(ifl1).eq.3)nqs=isign(1,ifl1)
      if(iabs(ifl2).eq.1)nqu=nqu+isign(1,ifl2)
      if(iabs(ifl2).eq.2)nqd=nqd+isign(1,ifl2)
      if(iabs(ifl2).eq.3)nqs=nqs+isign(1,ifl2)
c      write(ifch,*)'id',id,ifl1,ifl2,nqu,nqd,nqs,nqc
      return
      end

c-----------------------------------------------------------------------
      function idlabl(id)
c     returns the character*8 label for the particle id
c-----------------------------------------------------------------------
      include 'epos.inc'
      character*8 idlabl
      real crash(2)
      icrash=3

      nl=0
      ii=0
      if(id.ge.-9900.and.id.le.9900)then
        if(id.ge.-700.and.id.le.9900)then
          nl=nlidtbl(id)
          ii=1
        elseif(id.ge.-9900.and.id.lt.-700)then
          nl=nlidtbl(abs(id))
          ii=2
        endif
        if(nl.eq.0)then
          print*,'id = ',id,nlidtbl(id)
          xx=crash(icrash) !to force crash
        endif
        goto 999
      endif !treat the rare cases outside range -9900 - 9900

      do nlx=1,nidtmxx(1)
        if(idtbl(1,nlx).eq.id)then
          nl=nlx
          ii=1
          goto 999
        endif
      enddo
 
      !nothing found
      idlabl='unknown '
      return

 999  continue

      idlabl=nametbl(nl)(1:8) 
      if(ii.eq.2)idlabl(8:8)='-'//idlabl(1:7)
      length=index(nametbl(nl),' ')-1  !length of string
      if(length.gt.9-ii)idlabl(8:8)='$'  !symbol for truncated

      end

c-----------------------------------------------------------------------
      subroutine idchrg(iii,id,chrg)
c     computes charge of particle with ident code id
c     ichrg must be dimensioned nqlep+12
c-----------------------------------------------------------------------

      include 'epos.inc'

      ida=abs(id)

      if(ida.le.9900)then
        nl=nlidtbl(ida)
        if(nl.eq.0)then
          if(iii.ne.998)then
            print*,'ERROR 11072016c id =',id,' not in list.',iii
            stop
          else
            chrg=1e30
            return
          endif
        endif
        chrg=chrgtbl(nl)
        !print*,'idchrg using table ',id,chrg
        if(id.eq.-ida)chrg=-chrg 
        return
      endif

      !treat the rare cases outside range -9900 - 9900
      do nl=1,nidtmxx(1)
        if(idtbl(1,nl).eq.id)then
          chrg=chrgtbl(nl)
          return
        endif
      enddo

      chrg=0
      !stop'ERROR 12072016c'

      end

c-----------------------------------------------------------------------
      subroutine idresi
c-----------------------------------------------------------------------
c  Initializes /crema/
c  Masses are limits between two states (their average)
c-----------------------------------------------------------------------
c  The former idresi including the data part plus some code to extract
c  The extended table is idresi.dt
c-----------------------------------------------------------------------

      include 'epos.inc'

      real delmrho,delpeta
      integer irasym
      common /cuncertmu/delmrho,delpeta,irasym
      parameter (mxindx=9900,mxremax=100,mxmamax=30,mxmxmax=30)
      common/crema/indy(mxindx),rema(mxremax,mxmamax),
     * rewi(mxremax,mxmamax),icre2(mxremax,mxmamax)
     *,idre(mxremax,mxmamax),icre1(mxremax,mxmamax)
     *,mxre,mxma,mxmx 
      character line*175

      write(ifmt,'(2a)')'load ',fnnx(1:nfnnx)//'/idresi.dt'
      open (98,file= fnnx(1:nfnnx)//'/idresi.dt')

      do i=1,mxindx
        indy(i)=0
      enddo
      do  k=1,mxre
        do  m=1,mxmamax
          rema(k,m)=0
          icre1(k,m)=0
          icre2(k,m)=0
          rewi(k,m)=0
          idre(k,m)=0 
        enddo
      enddo
      
      itab=0
      ntab=0
      mxmx=0
      mxre=0
      mxma=0
      kmx=0

      do
 998    continue
        read(98,'(a)', end=999)line
        if(line(1:7).eq.'!tables')ntab=1
        if(line(1:1).eq.'!')goto 998

        if(ntab.eq.1)then
          
          jj=0 !count number of words in line
          do j=1,150 !up to number of character in one line
            if(line(j+1:j+1).eq.'!')exit
            if(line(j:j).eq.' '.and.line(j+1:j+1).ne.' ')jj=jj+1
          enddo
          if(jj.eq.0)goto 998 
          if(jj.gt.mxmamax-1)stop'ERROR mxmamax too small'           
c          print*,'jj', jj,line
          
          itab=itab+1
          mxre=(itab-1)/3+1
          mtab=mod(itab-1,3)+1
          
          if(mxre.gt.mxremax)stop'ERROR mxremax too small'

          if(mtab.eq.1)then !icre

            read(line,*)ix,ic1,ic2
            if(ix.lt.1.or.ix.gt.mxindx)
     *      stop'idresi: ix out of range.&' 

            do j=2,mxmamax
              icre1(mxre,j)=ic1
              icre2(mxre,j)=ic2
            enddo 
              
            if((ix.eq.111.or.ix.eq.222
     *      .or.ix.eq.333.or.ix.eq.444
     *      .or.ix.eq.555))then !xxx0 does not exist
               icre1(mxre,2)=0
            endif 
          
          elseif (mtab.eq.2)then !idmx

            kmx=0
            if(jj.gt.1)then
              kmx=1
              mxma=max(mxma,jj+1)
              read(line,*)(idre(mxre,j+1),j=1,jj)
              idre(mxre,1)=ix
              do j=1,jj
                if(idre(mxre,j+1).ne.0)then
                  !print*,'idresiA', idre(mxre,j+1),mxre,j+1
                  indy( idre(mxre,j+1) )=mxre
                endif
              enddo
            endif

          elseif (mtab.eq.3)then !rema
            mxma=max(mxma,jj+1)
            read(line,*)(rema(mxre,j+1),j=1,jj)
c           different masses for rho
            if(irasym.eq.0)then
              if(ix.eq.11.or.ix.eq.12)rema(mxre,2)=rema(mxre,2)+delmrho !better to use low mass for rho -> more rhos means less eta in better agreement with e+e- data
            else  !create rho mass asymmetry to get eta, eta' and pion OK without hacas
              if(ix.eq.11)rema(mxre,2)=rema(mxre,2)-delmrho
              if(ix.eq.12)rema(mxre,2)=rema(mxre,2)+delmrho
            endif
            !print*,'rema', ix,(rema(mxre,j+1),mxre,j+1,j=1,jj)
            if(kmx.eq.0)then
              idre(mxre,1)=ix
              do j=1,jj
                idre(mxre,j+1)=idre(mxre,1)*10+j-1
                !print*,'idresiB', idre(mxre,j+1),mxre,j+1
                indy( idre(mxre,j+1) )=mxre
              enddo
            endif

c----------------------------------
c          elseif(mtab.eq.4)then !rewi
c            read(line,*)(rewi(mxre,j+1),j=1,jj)
c---------------------------------
          else
            stop'ERROR mtab too big'
          endif

        endif

      enddo

999   continue
      close(98)

      return
      end


 
c Original File :  epos-int-cnx.f
c-----------------------------------------------------------------------
      subroutine bjinta(ier)
c-----------------------------------------------------------------------
c  fin. state interactions and decays
c-----------------------------------------------------------------------
      include 'epos.inc'
      double precision tpro,zpro,ttar,ztar,ttaus,detap,detat
      common/cttaus/tpro,zpro,ttar,ztar,ttaus,detap,detat /ctimel/ntc
      common/col3/ncol,kolpt
      double precision ttaun,ttau0,rcproj,rctarg
      common/cttaun/ttaun /cttau0/ttau0 /geom1/rcproj,rctarg
      logical go,lclean

      call utpri('bjinta',ish,ishini,4)

      ier=0

      if(ncol.eq.0.and.iappl.eq.2)goto1000
      if(nevt.ne.1.or.ifrade.eq.0)goto1000

      if(iappl.eq.4.or.iappl.eq.9)then
        goto5000
      endif

      !if(iappl.eq.1)then
      !  tauxx=0.7+0.94*max(radnuc(maproj),radnuc(matarg))/(0.5*engy)
      !else
      !  tauxx=0.
      !endif
      !print*,'====',tauzer,tauxx,tauzz
      !ttaus=dble(tauzz)
      ttaus=tauzer
      ttau0=dsqrt(rcproj*rctarg)
      call jtauin   ! initialize hyperbola

      if(iappl.ne.1)goto 5000


c     no-secondary-interactions or parton-ladder-fusion
c     -------------------------------------------------
      if(iorsce.eq.0.and.iorsdf.eq.0.and.iorshh.eq.0
     &      .or.iorsdf.eq.3)then
        if(iorsdf.eq.3)then
          lclean=.false.
c          if(nclean.gt.0.and.nptl.gt.mxptl/5)then
c            ! if nptl already very big, clean up useless particles in cptl list.
c            !(do not use it when gakstr() is called (some information lost)
c            nptli=maproj+matarg+1
c            do iii=nptli,nptl
c              go=.true.
c              if(nclean.eq.1.and.istptl(iii).le.istmax)go=.false.
c              if(go.and.mod(istptl(iii),10).ne.0)istptl(iii)=99
c            enddo
c            nptl0=nptl
c            call utclea(nptli,nptl0)
c            lclean=.true.
c          endif
          nptlbpo=nptl
          if(ish.ge.2)call alist('core and droplets&',nptlbpo+1,nptl)
          call jintpo(lclean,iret)  !core and clustering from overlapping Pomerons
          if(iret.eq.1)goto 1001
          if(iret.ne.1000)then
            call decaydroplets(nptlbpo,iret)
            if(iret.eq.1)goto 1001
          endif
        endif
        goto 5000
      else
        stop'bjinta: not supported any more (310305).     '
      endif

5000  continue
      if(ish.ge.8)call alistf('after jintpo&')

      do i=1,nptl
        if(ityptl(i).ne.61.and.idptl(i).eq.331)call utphiBW(i)  !BW mass smearing
        if(ityptl(i).eq.61.and.idptl(i).eq.333)call utphiBW(i)  !BW mass smearing
      enddo 

      nptlbd=nptl

      if(iappl.eq.1.and.irescl.eq.1)then
        call utghost(iret)
        if(iret.gt.0)goto 1001
        call utresc(iret)   !before decay because decay conserve energy and not to spoil invariant masses
c        call utrescxx(iret,0)   !before decay because decay conserve energy and not to spoil invariant masses
        if(iret.gt.0)goto 1001
      endif

      call xSpaceTime

      if(ifrade.eq.0)goto779  !skip decay
      if(idecay.eq.0)goto779  !skip decay


      if(ish.ge.2)call alist('final decay&',0,0)
      if(iappl.eq.4.or.iappl.eq.7.or.iappl.eq.9)then
        nptli=1
      else
        nptli=maproj+matarg+1
      endif
      np1=nptli
41    np2=nptl
      nptli=np1
      ip=np1-1
      nnnpt=0
      do while (ip.lt.np2)
      ip=ip+1
      if(istptl(ip).eq.0)then
      call hdecas(ip,iret)
      if(iret.eq.1)goto 1001
      if(iret.eq.-1)goto 42
c remove useless particles if not enough space
      if(nclean.gt.0.and.nptl.gt.mxptl/(2+4*min(1,abs(ihacas)))
     .                                          .and.nnnpt.eq.0)then
        nnnip=0
        do iii=maproj+matarg+1,np2
          go=.true.
          if(nclean.eq.1.and.istptl(iii).le.istmax)go=.false.
          if(nclean.eq.2.and.istptl(iii).le.1)go=.false.
          if(go.and.mod(istptl(iii),10).ne.0)then
            istptl(iii)=99
            nnnpt=nnnpt+1
            if(iii.le.ip)nnnip=nnnip+1
          endif
        enddo
        if(nnnpt.gt.0)then
          nptl0=nptl
          call utclea(1,nptl0)
          np2=np2-nnnpt
          ip=ip-nnnip
          nptli=nptl
          if(ish.ge.1)write(ifch,*)"clean bjinta ->",nptl,nnnpt,ip,np2
        else
          if(ish.ge.1)write(ifch,*)"no part. for clean bjinta !"
          nnnpt=-1
        endif
c          print *,"clean bjinta ->",nptl,nnnpt,ip,np2
      endif
      endif
42    continue
      enddo
      nptli=max(nptli,np1)
      np1=np2+1
      if(np1.le.nptl)then
      if(ish.ge.2)then
      call alist('partial list&',0,0)
      do 6 ip=np1,nptl
        call alist('&',ip,ip)
6     continue
      endif
      goto 41
      endif
  779 continue

c      if(ish.ge.2)call alist('complete list&',1,nptl)

c     on shell check
c     --------------
c      if(iappl.eq.1)call jresc

1000  continue
      call utprix('bjinta',ish,ishini,4)
      return

1001  continue
      ier=1
      goto 1000

      end

c----------------------------------------------------------------------
      subroutine decaydroplets(nptla,iret)
c----------------------------------------------------------------------
c  cut and paste from jintpo version 3236
c-----------------------------------------------------------------------
c Decay droplets not included in clusters
c----------------------------------------------------------------------
      include "epos.inc"
      include "epos.incems"
      include "epos.incico"
      common/cdelzet/delzet,delsce /cvocell/vocell,xlongcell
      real aminclust
      common/jintpoc4/aminclust
      iret=0
      delzet=0.
      xlongcell=0.
      do mm=1,nptla
        nptlb=nptl
        if(istptl(mm).eq.10)then
          if(ish.ge.5)write(ifch,*)'Decay remaining droplet :',mm
          if(avgdens.eq.1..and.avgmass.eq.1.)then
            radptl(mm)=0.       !no core so no radial flow should be applied
          else
            radptl(mm)=avgdens  !to follow flow increase in AA collisions
          endif
          if(nptlb.gt.mxptl-10)
     &    call utstop('decaydroplets: mxptl too small (2)&')
         !~~~~~~~~~~~~~~~~~~~~~~~
          if(pptl(5,mm).gt.max(amdrmin,amdrmax-aminclust))then
            call hnbaaa(3,mm,iret) ! 3 = include flow because not used in core so apply it here
          else
            call hnbaaa(9,mm,iret) ! 9 = remnant droplets
          endif
         !~~~~~~~~~~~~~~~~~~~~~~~
          if(iret.eq.0.and.nptl.ne.nptlb)then ! ---successful decay---
            istptl(mm)=istptl(mm)+1
            ifrptl(1,mm)=nptlb+1
            ifrptl(2,mm)=nptl
c            t=tivptl(2,mm)
c            x=xorptl(1,mm)+(t-xorptl(4,mm))*pptl(1,mm)/pptl(4,mm)
c            y=xorptl(2,mm)+(t-xorptl(4,mm))*pptl(2,mm)/pptl(4,mm)
c            z=xorptl(3,mm)+(t-xorptl(4,mm))*pptl(3,mm)/pptl(4,mm)
c            do 21 n=nptlb+1,nptl
c              iorptl(n)=mm
c              jorptl(n)=0
c              istptl(n)=0
c              ifrptl(1,n)=0
c              ifrptl(2,n)=0
c              radius=0.8*sqrt(rangen())
c              phi=2*pi*rangen()
c              ti=t
c              zi=z
c              xorptl(1,n)=x + radius*cos(phi)
c              xorptl(2,n)=y + radius*sin(phi)
c              xorptl(3,n)=zi
c              xorptl(4,n)=ti
c              tivptl(1,n)=ti
c              call idtau(idptl(n),pptl(4,n),pptl(5,n),taugm)
c              r=rangen()
c              tivptl(2,n)=ti+taugm*(-alog(r))
c              radptl(n)=0.
c              dezptl(n)=0.
c              itsptl(n)=0
c              rinptl(nptl)=-9999
c   21       continue
          else                  ! Unsuccessful decay
            if(ish.ge.1)write(ifch,*)
     *         '***** Unsuccessful remnant cluster decay'
     *             ,' --> redo event.'
          endif
        endif
      enddo
c     make sure all final particles are on-shell
      do mm=1,nptl
        if(istptl(mm).eq.0)then
          pptl(4,mm)=sqrt(pptl(1,mm)**2+pptl(2,mm)**2+pptl(3,mm)**2
     *                   +pptl(5,mm)**2)
        endif
      enddo

      end

c----------------------------------------------------------------------
      subroutine index2521(i,i25first,i21last)
c----------------------------------------------------------------------
      include 'epos.inc'
      i25first=0
      i21last=0
c      return
c not yet defined here ??????????????
      call getSystemABE(ia,ib,e)
      if(ia.eq.0.or.ib.eq.0)return
      call getistptl(i,isti)
      call getityptl(i,ityi)
      if(ityi/10.ne.3)return
      if(isti.eq.31.or.isti.eq.32)return
      if(isti.eq.29)return
      if(isti.eq.26)return
      if(isti.eq.99)return
      call getidptl(i,idi)
      if(idi.eq.9995)return !non isol pi0
      if(idi.eq.9996)return !isol pi0
      if(idi.eq.9997)return !non isol photon
      if(idi.eq.9998)return !isol photon
      if(idi.eq.9999)return !jet
      if(mod(abs(idi),100).eq.88)return !energy lost in core
      if(i.le. nptlpt)return
      call getiorptl(i,iori)
      call getjorptl(i,jori)
      !print*,iori,jori,i,idi,isti
      ioriOld=i
  77  continue
      if(iori.le.0)then
        if(nclean.gt.0.and.ioriOld.gt.nptlpt)return       !may happen if event is cleaned
        print*,'i id ist ity ior = ',i,idi,isti,ityi,iori
        call utstop('ERROR index2521  iori LE 0&')
      endif
      call getistptl(iori,isto)
      if(isto.eq.1)then
        ioriOld=iori
        call getjorptl(iori,joroOld)
        call getidptl(iori,idoOld)
        istoOld=isto
        call getiorptl(iori,iori)
        !print*,iori,joroOld,ioriOld,idoOld,istoOld
        goto 77
      endif
      if(isto.ne.29)then
        print*,'i id ist ity ist(iori) = ',i,idi,isti,ityi
     .  ,isto
        call utstop('ERROR index2521  ist(iori) NE 29&')
      endif  
      call getiorptl(iori,ioro)
      call getjorptl(iori,joro)
      call getidptl(iori,ido)
      !print*,ioro,joro,iori,ido,isto
      i1parton=ioro
      i2parton=joro
      istring=iori
      i25=i1parton
      call getiorptl(i25,ior25)
      call getjorptl(i25,jor25)
      call getidptl(i25,id25)
      call getistptl(i25,ist25)
      !print*,ior25,jor25,i25,id25,ist25
  78  i25=i25-1
      call getiorptl(i25,ior25)
      call getjorptl(i25,jor25)
      call getidptl(i25,id25)
      call getistptl(i25,ist25)
      !print*,ior25,jor25,i25,id25,ist25
      if(i25.eq.1)call utstop('ERROR 18062012b&')
      if(ist25.ne.25)goto 78
      call getistptl(i25-1,ist25m1)
      if(ist25m1.ne.25)
     . call utstop('ERROR 18062012c&')
      call getiorptl(i25-1,ior25m1)
      call getiorptl(i1parton,ior1parton)

      !print*,ior25m1,ior1parton,i1parton
      if(ior25m1.ne.ior1parton.and.ior25m1.ne.0)
     . call utstop('ERROR 18062012d&')
      !index25second=i25
      i25first=i25-1
      i21last=i2parton
      iii=0
      do k=i25first+2,i21last
        call getistptl(k,istk)
        if(istk.eq.21)then
          iii=iii+1
          if(iii.eq.1)kref=k  
          call getiorptl(k,iork)
          call getiorptl(kref,iorkref)
          if(iork.ne.iorkref)then
            call getiorptl(i25first,ior25first)
            print*,i,istring,i25first,k, iork,ior25first
            call utstop('####### ERROR 29042017 #######&')
          endif
        endif
      enddo
      end

c----------------------------------------------------------------------
      subroutine jet2521(i,ibig,phi,rap,pp)
c----------------------------------------------------------------------
      include "epos.inc"
      ibig=0
      phi=0
      rap=0
      if(istptl(i).ne.21.and.istptl(i).ne.25)return
      pt=max(1e-6, sqrt(pptl(1,i)**2+pptl(2,i)**2))
      if(pt.ge.1.0)ibig=1
      pp=sqrt(pt**2+pptl(3,i)**2)
      phi=polar( pptl(1,i) , pptl(2,i) )
      rap=sign(1.,pptl(3,i))*log((pp+abs(pptl(3,i)))/pt)
      end

cc----------------------------------------------------------------------
c      subroutine jintcs(i,j,ecm,bij,nq,jc,ics)
cc----------------------------------------------------------------------
cc compare hadron distance with energy dependent cross section
cc data taken from particle data group, durham and juelich
cc input:
cc   i,j: particle indices
cc   ecm: center-of-mass energy
cc   bij: impact parameter
cc   nq: net quark number of fused object
cc   jc: jc of fused object
cc output:
cc   ics=0 if distance larger than sqrt(sig(E_CMS)/pi)
cc   ics=1 else
cc The data are from HEPDATA,
cc the formulas from Rev. Particle Properties 1995
cc----------------------------------------------------------------------
c      include 'epos.inc'
c      integer jci(nflav,2),jcj(nflav,2),jc(nflav,2),kc(nflav)
c     *,kci(nflav),kcj(nflav)
c      common/cxyzt/xptl(mxptl),yptl(mxptl),zptl(mxptl),tptl(mxptl)
c     *,optl(mxptl),uptl(mxptl),sptl(mxptl),rptl(mxptl,3)
c      parameter(npp=249,napp=205,npn=411,napn=31,npip=441)
c      parameter(npim=578,nkmp=299,nkmn=41,nkpp=172,nkpn=91)
cc      parameter(npim=578,nkmp=299,nkmn=41,nkpp=172,nkpn=91,nlp=35)
c      parameter(npi1=12,npi2=12,npi3=18,npi4=21,npi5=9)
cc      real ppecm(npp)
c      real ppbmx(npp)
c      real appecm(napp),appbmx(napp)
c      real pnecm(npn),pnbmx(npn)
c      real apnecm(napn),apnbmx(napn)
c      real pipecm(npip),pipbmx(npip)
c      real pimecm(npim),pimbmx(npim)
c      real kmpecm(nkmp),kmpbmx(nkmp)
c      real kmnecm(nkmn),kmnbmx(nkmn)
c      real kppecm(nkpp),kppbmx(nkpp)
c      real kpnecm(nkpn),kpnbmx(nkpn)
cc      real lpecm(nlp),lpbmx(nlp)
c      real pi1ecm(npi1),pi1bmx(npi1)
c      real pi2ecm(npi2),pi2bmx(npi2)
c      real pi3ecm(npi3),pi3bmx(npi3)
c      real pi4ecm(npi4),pi4bmx(npi4)
c      real pi5ecm(npi5),pi5bmx(npi5)
c
cc      data ppecm/
cc     *    1.8812,   1.8855,   1.8910,   1.8963,   1.9073
cc     *,   1.9108,   1.9145,   1.9224,   1.9244,   1.9352
cc     *,   1.9466,   1.9468,   1.9542,   1.9592,   1.9636
cc     *,   1.9772,   1.9860,   1.9945,   2.0032,   2.0052
cc     *,   2.0070,   2.0272,   2.0275,   2.0302,   2.0333
cc     *,   2.0402,   2.0427,   2.0586,   2.0608,   2.0692
cc     *,   2.0702,   2.0708,   2.0715,   2.0718,   2.0751
cc     *,   2.0797,   2.0813,   2.0829,   2.0843,   2.0846
cc     *,   2.0935,   2.1062,   2.1113,   2.1123,   2.1170
cc     *,   2.1173,   2.1184,   2.1268,   2.1289,   2.1357
