c          if(p.lt.0.8)then
c           sig=23.5+1000.*(0.7-p)**4
c          elseif(p.lt.1.5)then
c           sig=23.5+24.6/(1+exp(-(p-1.2)/0.1))
c          elseif(p.lt.5)then
c           sig=41.+60.*(p-0.9)*exp(-1.2*p)
c          else
c           sig=48+.522*(alog(p)**2)-4.51*alog(p)
c          endif
c          bmx=sqrt(sig/10./pi)
c         endif
c        endif
