c          call utindx(napn,apnecm,ecm,iecm)
c          bmx=apnbmx(iecm)
c         else
c          p=ecm*sqrt((ecm**2/4./.94**2)-1.)
c          sig=133.6*p**(-.7)-1.22*(alog(p)**2)+13.7*alog(p)
