c        endif
c
c       elseif(nq.eq.3)then !----------baryon-meson ---->
c
c        if(kc(3).eq.0)then
cc no kaons involved(except for K-L)
c         if(kc(1).eq.0.or.kc(2).eq.0)then
cc pip
c          if(ish.ge.7)write(ifch,*)'sig_pip chosen'
