c          endif
c         endif
c        elseif(kc(3).eq.1)then
cc strange particles involved
c         if(kc(1).eq.0.or.kc(2).eq.0)then
cc kmn
c          if(ish.ge.7)write(ifch,*)'sig_kmn chosen'
c          if(ecm.lt.2.5)then
c           call utindx(nkmn,kmnecm,ecm,iecm)
