c110     continue
c
c       else !something else involved, strange etc.
c
c        bmx=0.6  ! approx.  sig=10mb
c
c       endif
c
cc --------------------------------
c      endif
cc --------------------------------
c
c      if(bij.le.bmx)ics=1
c      if(ish.ge.7)then
c      write(ifch,*)'b_mx:',bmx,' b_ij:',bij,' ics:',ics
c      endif
