      rat=0
      if(jjtot(j).gt.0.)rat=float(jjtot(j)-jjjnt(j,ntauc))/jjtot(j)
      write(ifhi,'(4e12.4)')bimmax-bim,rat,0.,float(jjtot(j))
      enddo
      write(ifhi,'(a)')       '  endarray'
