      write(ifhi,'(a)')       'openhisto'
      write(ifhi,'(a)')       'htyp ldo xmod lin ymod lin'
      write(ifhi,'(a)')       'columnweight 4 column c4 = ( 0 ) '
      write(ifhi,'(a)')       'array 4'
      do j=mxbim,1,-1
      bim=(j-0.5)*bimmax/mxbim
      rat=0
