      write(ifhi,'(a)')       'openhisto'
      write(ifhi,'(a)')       'set fmsc 1.0'
      write(ifhi,'(a)')       'column c1 = ( 11.9 - c1  )'
      write(ifhi,'(a)')       'column c2 = ( c2 * 0.019 )'
      write(ifhi,'(a)')       'input na50 ratio-b plot 0'
      else
      write(ifhi,'(a)')       ' closehisto plot 0'
      endif
