c----------------------------------------------------------------------
      double precision function Hrst(s,b,xp,xm)   !test
c----------------------------------------------------------------------
      include 'epos.inc'
      include 'epos.incems'
      include 'epos.incsem'
      include 'epos.incpar'
      parameter(idxD2=8)
      double precision GbetUni,GbetpUni,HbetUni,HbetpUni,HalpUni
      common/DGamUni/GbetUni(  idxD0:idxD2),HbetUni(  idxD0:idxD2),
     &               GbetpUni(idxD0:idxD2),HbetpUni(idxD0:idxD2),
     &               HalpUni(idxD0:idxD2)
      double precision al(idxD0:idxD2),betp(idxD0:idxD2)
     *,z,xJrst!,ffacto
      double precision zp(idxD0:idxD2),Htmp,betpp(idxD0:idxD2)
     *,yp,ym,xp,xm
      dimension ipr(idxD0:idxD2),imax(idxD0:idxD2)

      if(idxD0.ne.0.or.idxD1.ne.2) stop "Problem in Hrst"
      Htmp=0.d0
      do i=idxD0,idxD2
        imax(i)=0
        ipr(i)=0
        zp(i)=1.d0
        al(i)=0.d0
      enddo

      if(xp.ge.0.d0.and.xm.ge.0.d0.and.xp.lt.1.d0.and.xm.le.1.d0)then

      imax0=idxD1
      if(iomega.eq.2)imax0=1
      imax1=idxD2
      if(iomega.eq.2)imax1=imax1-1

      do i=idxDmin,imax1
        imax(i)=max(2,int(log10(100.*s)/3.))
c        if(i.ge.2)imax(i)=imax(i)*2
        if(b.ge.1.5)imax(i)=2   !max(2,imax(i)/2)
        imax(i)=min(30,imax(i))
        if(i.gt.imax0)then
          if((zzpUni*zztUni.lt.1.d-6)
     &   .or.(xp.lt.0.1d0.and.xm.lt.0.1d0))then
            imax(i)=0
          else
            imax(i)=1     !imax(i)/3
          endif
        endif
      enddo

      Htmp=0.d0
        do i=idxDmin,imax1
          betp(i)=HbetUni(i)
          betpp(i)=HbetpUni(i)
          al(i)=HalpUni(i)
        enddo

        do ipr0=0,imax(0)
c          write(ifmt,*)'Hrst ipr0,xp,xm :',ipr0,xp,xm
           ipr(0)=ipr0
           zp(0)=1.d0
           if (ipr(0).ne.0) zp(0)=al(0)**ipr(0)*facto(ipr(0))
         do ipr1=0,imax(1)
            ipr(1)=ipr1
            zp(1)=1.d0
            if (ipr(1).ne.0) zp(1)=al(1)**ipr(1)*facto(ipr(1))
         do ipr2=0,imax(2)
            ipr(2)=ipr2
            zp(2)=1.d0
            if (ipr(2).ne.0) zp(2)=al(2)**ipr(2)*facto(ipr(2))
         do ipr3=0,imax(3)
            ipr(3)=ipr3
            zp(3)=1.d0
            if (ipr(3).ne.0) zp(3)=al(3)**ipr(3)*facto(ipr(3))
         do ipr4=0,imax(4)
            ipr(4)=ipr4
            zp(4)=1.d0
            if (ipr(4).ne.0) zp(4)=al(4)**ipr(4)*facto(ipr(4))
         do ipr5=0,imax(5)
            ipr(5)=ipr5
            zp(5)=1.d0
            if (ipr(5).ne.0) zp(5)=al(5)**ipr(5)*facto(ipr(5))
         do ipr6=0,imax(6)
            ipr(6)=ipr6
            zp(6)=1.d0
            if (ipr(6).ne.0) zp(6)=al(6)**ipr(6)*facto(ipr(6))
         do ipr7=0,imax(7)
            ipr(7)=ipr7
            zp(7)=1.d0
            if (ipr(7).ne.0) zp(7)=al(7)**ipr(7)*facto(ipr(7))
         do ipr8=0,imax(8)
            ipr(8)=ipr8
            zp(8)=1.d0
            if (ipr(8).ne.0) zp(8)=al(8)**ipr(8)*facto(ipr(8))
           if (ipr(0)+ipr(1)+ipr(2)+ipr(3)+ipr(4)+ipr(5)
     &        +ipr(6)+ipr(7)+ipr(8).ne.0) then
             yp=0.d0
             ym=0.d0
             z=1.d0
             do i=idxDmin,imax1
               yp=yp+dble(ipr(i))*betp(i)
               ym=ym+dble(ipr(i))*betpp(i)
               z=z*zp(i)
             enddo
             z=z*xJrst(xp,yp,GbetUni,ipr)
             z=z*xJrst(xm,ym,GbetpUni,ipr)
             Htmp=Htmp+z
           endif
          enddo
         enddo
       enddo
          enddo
         enddo
       enddo
          enddo
         enddo
       enddo

      endif

      Hrst=Htmp

      return
      end

c----------------------------------------------------------------------
      double precision function HrstI(s,b,xp,xm)   !test
c----------------------------------------------------------------------
      include 'epos.inc'
      include 'epos.incems'
      include 'epos.incsem'
      include 'epos.incpar'
      parameter(idxD2=8)
      double precision GbetUni,GbetpUni,HbetUni,HbetpUni,HalpUni
      common/DGamUni/GbetUni(  idxD0:idxD2),HbetUni(  idxD0:idxD2),
     &               GbetpUni(idxD0:idxD2),HbetpUni(idxD0:idxD2),
     &               HalpUni(idxD0:idxD2)
      double precision al(idxD0:idxD2),betp(idxD0:idxD2)
     *,z,xJrstI!,ffacto
      double precision zp(idxD0:idxD2),Htmp,betpp(idxD0:idxD2)
     *,yp,ym,xp,xm
      dimension ipr(idxD0:idxD2),imax(idxD0:idxD2)

      if(idxD0.ne.0.or.idxD1.ne.2) stop "Problem in HrstI"
      Htmp=0d0
      do i=idxD0,idxD2
        imax(i)=0
        ipr(i)=0
        zp(i)=1.d0
        al(i)=0.d0
      enddo


      if(xp.ge.0.d0.and.xm.ge.0.d0.and.xp.lt.1.d0.and.xm.le.1.d0)then


      imax0=idxD1
      if(iomega.eq.2)imax0=1
      imax1=idxD2
      if(iomega.eq.2)imax1=imax1-1

      do i=idxDmin,imax1
        imax(i)=max(3,int(log10(s)/2.))
c        if(i.ge.2)imax(i)=imax(i)*2
        if(b.ge.1.5)imax(i)=max(2,imax(i)/2)
        imax(i)=min(30,imax(i))
        if(i.gt.imax0)then
          if((zzpUni*zztUni.lt.1.d-6)
     &   .or.(xp.lt.0.1d0.and.xm.lt.0.1d0))then
            imax(i)=0
          else
            imax(i)=1   !imax(i)/3
          endif
        endif
      enddo

      Htmp=0.d0
        do i=idxDmin,imax1
          betp(i)=HbetUni(i)
          betpp(i)=HbetpUni(i)
          al(i)=HalpUni(i)
        enddo
        do ipr0=0,imax(0)
           ipr(0)=ipr0
           zp(0)=1.d0
           if (ipr(0).ne.0) zp(0)=al(0)**ipr(0)*facto(ipr(0))
         do ipr1=0,imax(1)
            ipr(1)=ipr1
            zp(1)=1.d0
            if (ipr(1).ne.0) zp(1)=al(1)**ipr(1)*facto(ipr(1))
         do ipr2=0,imax(2)
            ipr(2)=ipr2
            zp(2)=1.d0
            if (ipr(2).ne.0) zp(2)=al(2)**ipr(2)*facto(ipr(2))
         do ipr3=0,imax(3)
            ipr(3)=ipr3
            zp(3)=1.d0
            if (ipr(3).ne.0) zp(3)=al(3)**ipr(3)*facto(ipr(3))
         do ipr4=0,imax(4)
            ipr(4)=ipr4
            zp(4)=1.d0
            if (ipr(4).ne.0) zp(4)=al(4)**ipr(4)*facto(ipr(4))
         do ipr5=0,imax(5)
            ipr(5)=ipr5
            zp(5)=1.d0
            if (ipr(5).ne.0) zp(5)=al(5)**ipr(5)*facto(ipr(5))
         do ipr6=0,imax(6)
            ipr(6)=ipr6
            zp(6)=1.d0
            if (ipr(6).ne.0) zp(6)=al(6)**ipr(6)*facto(ipr(6))
         do ipr7=0,imax(7)
            ipr(7)=ipr7
            zp(7)=1.d0
            if (ipr(7).ne.0) zp(7)=al(7)**ipr(7)*facto(ipr(7))
         do ipr8=0,imax(8)
            ipr(8)=ipr8
            zp(8)=1.d0
            if (ipr(8).ne.0) zp(8)=al(8)**ipr(8)*facto(ipr(8))
           if (ipr(0)+ipr(1)+ipr(2)+ipr(3)+ipr(4)+ipr(5)
     &        +ipr(6)+ipr(7)+ipr(8).ne.0) then
             yp=0.d0
             ym=0.d0
             z=1.d0
             do i=idxDmin,imax1
               yp=yp+dble(ipr(i))*betp(i)
               ym=ym+dble(ipr(i))*betpp(i)
               z=z*zp(i)
             enddo
             z=z*xJrstI(xp,yp,GbetUni,ipr)
             z=z*xJrstI(xm,ym,GbetpUni,ipr)
             Htmp=Htmp+z
           endif
          enddo
         enddo
       enddo
          enddo
         enddo
       enddo
          enddo
         enddo
       enddo

      endif

      HrstI=Htmp

      return
      end



