c----------------------------------------------------------------------
      subroutine xanatest8
c----------------------------------------------------------------------
      include "epos.inc"
      return !comment if needed
      x=fmux(-1.0, 1.00, 0., 1.e10, 1., 1., 0., 0., 0.0, 0.0, 20. ) 
      do i=1,nptl
        ida=abs(idptl(i))
        pt2=pptl(1,i)**2+pptl(2,i)**2
        amt2=pptl(5,i)**2+pt2
        p4=pptl(4,i)
        p3=pptl(3,i)
        if(amt2.gt.0..and.p4+abs(p3).gt.0.d0)then      
          amt=sqrt(amt2)
          ay=log( (p4+abs(p3)) / amt ) 
        else
          ay=1e30
        endif 
        if(ay.lt.0.5.and.pt2.gt.8**2.and.pt2.lt.12**2
     .  .and.(ida.eq.240.or.ida.eq.140.or.ida.eq.241))then
          !if(x.gt.50 .and. x.lt.60)then
          write(ifch,*)'8888888888888',ida,ay,sqrt(pt2),x
          !endif
        endif
      enddo 
      end

 
c Original File :  epos-xpr-cnx.f
c----------------------------------------------------------------------
      subroutine xAlphaS
c----------------------------------------------------------------------
      include 'epos.inc'
      include 'epos.incsem'
      parameter(nbib=100)

      q1=0.1 !sqrt(qcdlam)
      q2=100000

c************************full-red = Znorm *****************************

      write(ifhi,'(a)')       'openhisto name pssalf'
      write(ifhi,'(a)')       'htyp lru xmod log ymod lin'
      write(ifhi,*)       'xrange ',q1,q2,' yrange 0.05 1.1'
      write(ifhi,'(a)')    'text 0 0 "xaxis  Q (GeV)"'
      write(ifhi,'(a)')    'text 0 0 "yaxis  [a]?s!(Q) "'
      write(ifhi,'(a)')       'array 2'
      do k=0,nbib
        q=q1
        if (k.ne.0) q=q*(q2/q1)**(float(k)/float(nbib))
        qq=q*q
        y=pssalf(qq/qcdlam)*2.*pi
        write(ifhi,*)q,y
      enddo
      write(ifhi,'(a)')    '  endarray'
      write(ifhi,'(a)')    'closehisto plot 0-'
     

c**********************************************************************

      write(ifhi,'(a)')       'openhisto name alphaS'
      write(ifhi,'(a)')       'htyp lba xmod log ymod lin'
      write(ifhi,'(a)')       'array 2'
      qcdl=0.038                 !0.033 !0.04 !0.011 !0.03
      xkap=0.9/(log(log(0.9/qcdl))-log(4.*pi/9.))
      print *,'kappa',sqrt(0.25*xkap),qcdlam
      do k=1,nbib
        q=q1
        if (k.ne.0) q=q*(q2/q1)**(float(k)/float(nbib))
        if(q.lt.sqrt(0.9))then
          qq=q*q/qcdl
          y=exp(-qq/xkap*qcdl)/2./pi
        else
          qlam=qcdl
          if(q.lt.2.*qcmass) then
            nf=3
          else!if(q.lt.qbmass)then
            nf=4
            qlam=qcdl*0.68
c          else
c            nf=5
c            qlam=qcdl*0.38
          endif
          qq=q*q/qlam
          y=2./(11.-nf/1.5)/log(qq)
        endif
c        if(y.lt.0.or.y.gt.0.5/(2.*pi))then
c          y=0.5/(2.*pi)
c        endif
        y=y*2.*pi
        write(ifhi,*)q,y
      enddo
      write(ifhi,'(a)')    '  endarray'
      write(ifhi,'(a)')    'closehisto plot 0-'


      end

c----------------------------------------------------------------------
      double precision function xDfit(zz,i1,i2,s,xp,xm,b)
c----------------------------------------------------------------------

      include 'epos.inc'
      include 'epos.incpar'
      include 'epos.incsem'



      xDfit=0.d0
      do i=max(0,i1),i2
        call GfunPar(zz,zz,1,i,b,s,alp,bet,betp,epsp,epst,epss,gamv)
        if(i1.ge.0)then
          corp=alppar-epsp
          cort=alppar-epst
          cors=-epss
        else
          corp=alppar
          cort=alppar
          cors=0.
        endif
c        write(ifch,*)'xdfit',i,zz,b,s,alp,bet,betp,epsp,epst,epss
        xDfit=xDfit+dble(alp*xp**(bet+corp)*xm**(betp+cort)*s**cors)
      enddo
      return
      end


c----------------------------------------------------------------------
      subroutine xFitD1
