      write(ifhi,'(a)')    'closehisto plot 0-'



c************************* dot = PomIncXUnit **************************
c      nptg=50     !number of point for the graphs

      if (biniDf.lt.1.) then
        k=int(10.*biniDf)
        write(ifhi,'(a,I1)')  'openhisto name PomIncUnit-b0.',k
