 111  continue
      do i=0,51

c.......Exponential

        x=xminDf
        x1=xminDf
        x=x**(1.d0-dble(i)/51.d0)
        x1=x1**(1.d0-dble(i+1)/51.d0)
        if(i.eq.51)then
          x1=1.d0
          x=0.d0
        endif
        histo(i)=histo(i)/dble(n)/(x1-x)*xmr

c.......Linear
c        histo(i)=histo(i)/dble(n)*51.d0
      enddo

      return
      end

c----------------------------------------------------------------------

      subroutine xhistomran10(histo)

c----------------------------------------------------------------------
c.....Make Histogram of om1xrk
c----------------------------------------------------------------------

      include 'epos.incpar'

      double precision histo(0:51),x,x1,om1xrk
      integer*4 n


      n=100000
      do i=0,51
        histo(i)=0.d0
      enddo
      do 111 j=1,n
        if(mod(j,10000).eq.0)write(*,*)"xk",j
        x=om1xrk(1)
        if(x.lt.xminDf)goto 111
c.........Exponential
          k=int((-dlog(x)/dlog(xminDf)+1.d0)*51.d0)
c.........Linear
c.........k=int(x*50.d0)
        histo(k)=histo(k)+1.d0
 111  continue
      do i=0,51

c.......Exponential

        x=xminDf
        x1=xminDf
        x=x**(1.d0-dble(i)/51.d0)
        x1=x1**(1.d0-dble(i+1)/51.d0)
        if(i.eq.51)then
          x1=1.d0
          x=0.d0
        endif
        histo(i)=histo(i)/dble(n)/(x1-x)

c.......Linear
c        histo(i)=histo(i)/dble(n)*51.d0
      enddo

      return
      end


c----------------------------------------------------------------------

      subroutine xhistomran11(histo,xh)

c----------------------------------------------------------------------
c.....Make Histogram of om1yrk
c----------------------------------------------------------------------

      double precision histo(0:51),x,xh,dx,om1yrk,ymax
      integer*4 n

      ymax=-.5D0*dlog(xh)
      dx=ymax/25.d0

      n=100000
      do i=0,50
        histo(i)=0.d0
      enddo
      do j=1,n
        if(mod(j,10000).eq.0)write(*,*)"yk",j
        x=om1yrk(xh)
        k=int((x/ymax+1.d0)*25.d0)
c.......write(*,*)x,k
        histo(k)=histo(k)+1.d0
      enddo
      do i=0,50
        histo(i)=histo(i)/dble(n)/dx
      enddo

      return
      end

c----------------------------------------------------------------------

      subroutine xranptg(histo,xcut,xfact,xadd)

c----------------------------------------------------------------------
c.....Make Histogram of random distribution
c----------------------------------------------------------------------

      include 'epos.incpar'

      parameter (nptg1=501)      !number of point for the graphs
      common /cranpt/conv
      double precision histo(0:nptg1)
      integer*4 n


      n=100000
      do i=0,nptg1
        histo(i)=0.d0
      enddo
      do j=1,n
        if(mod(j,10000).eq.0)write(*,*)"ptg",j
c .........exp(-x**2)
 12   x=sqrt(-log(rangen())/(3.1415927/4.)) !gauss

      if(xcut.gt.0.)then
        if(rangen().lt.x/xcut)goto 12
      endif
      x=x*xfact+xadd
c.........Exponential
c          k=int((-dlog(x)/dlog(xminDf)+1.d0)*51.d0)
c.........Linear
        k=int(x/conv)
        k=min(k,nptg1)
        histo(k)=histo(k)+1.d0
      enddo
      do i=0,nptg1

c.......Exponential

c        x=xminDf
c        x1=xminDf
c        x=x**(1.d0-dble(i)/51.d0)
c        x1=x1**(1.d0-dble(i+1)/51.d0)
c        if(i.eq.51)then
c          x1=1.d0
c          x=0.d0
c        endif
c        histo(i)=histo(i)/dble(n)/(x1-x)

c.......Linear
        histo(i)=histo(i)/dble(n)*float(nptg1)
      enddo

      return
      end

c----------------------------------------------------------------------

      subroutine xranpte(histo,xcut,xfact,xadd)

c----------------------------------------------------------------------
c.....Make Histogram of random distribution
c----------------------------------------------------------------------

      include 'epos.incpar'

      parameter (nptg1=501)      !number of point for the graphs
      common /cranpt/conv
      double precision histo(0:nptg1)
      integer*4 n


      n=100000
      do i=0,nptg1
        histo(i)=0.d0
      enddo
      do j=1,n
        if(mod(j,10000).eq.0)write(*,*)"pte",j
c .........exp(-x)
  12  xmx=50
      r=2.
      x=0.
      do while (r.gt.1.)
  11    x=sqrt(exp(rangen()*log(1+xmx**2))-1)
        if(x.eq.0.)goto11
        r=rangen()  /  ( exp(-x)*(1+x**2) )
      enddo
      x=x/2.

      if(xcut.gt.0.)then
        if(rangen().lt.x/xcut)goto 12
      endif
      x=x*xfact+xadd
c.........Exponential
c          k=int((-dlog(x)/dlog(xminDf)+1.d0)*51.d0)
c.........Linear
        k=int(x/conv)
        k=min(k,nptg1)
        histo(k)=histo(k)+1.d0
      enddo
      do i=0,nptg1

c.......Exponential

c        x=xminDf
c        x1=xminDf
c        x=x**(1.d0-dble(i)/51.d0)
c        x1=x1**(1.d0-dble(i+1)/51.d0)
c        if(i.eq.51)then
c          x1=1.d0
c          x=0.d0
c        endif
c        histo(i)=histo(i)/dble(n)/(x1-x)

c.......Linear
        histo(i)=histo(i)/dble(n)*float(nptg1)
      enddo

      return
      end

c----------------------------------------------------------------------

      subroutine xranpts(histo,xcut,xfact,xadd)

c----------------------------------------------------------------------
c.....Make Histogram of random distribution
c----------------------------------------------------------------------

      include 'epos.incpar'

      parameter (nptg1=501)      !number of point for the graphs
      common /cranpt/conv
      double precision histo(0:nptg1)
      integer*4 n


      n=100000
      do i=0,nptg1
        histo(i)=0.d0
      enddo
      do j=1,n
        if(mod(j,10000).eq.0)write(*,*)"pts",j
c .........exp(-sqrt(x))
 12   xmx=500
      r=2.
      x=0.
      do while (r.gt.1.)
        x=sqrt(exp(rangen()*log(1+xmx**2))-1)
        r=rangen()  /  ( exp(-sqrt(x))*(1+x**2)/5. )
      enddo
      x=x/20.

      if(xcut.gt.0.)then
        if(rangen().lt.x/xcut)goto 12
      endif
      x=x*xfact+xadd
c.........Exponential
c          k=int((-dlog(x)/dlog(xminDf)+1.d0)*51.d0)
c.........Linear
        k=int(x/conv)
        k=min(k,nptg1)
        histo(k)=histo(k)+1.d0
      enddo
      do i=0,nptg1

c.......Exponential

c        x=xminDf
c        x1=xminDf
c        x=x**(1.d0-dble(i)/51.d0)
c        x1=x1**(1.d0-dble(i+1)/51.d0)
c        if(i.eq.51)then
c          x1=1.d0
c          x=0.d0
c        endif
c        histo(i)=histo(i)/dble(n)/(x1-x)

c.......Linear
        histo(i)=histo(i)/dble(n)*float(nptg1)
      enddo

      return
      end

c----------------------------------------------------------------------

      subroutine xranptc(histo,xcut,xfact,xadd)

c----------------------------------------------------------------------
c.....Make Histogram of random distribution
c----------------------------------------------------------------------

      include 'epos.incpar'

      parameter (nptg1=501)      !number of point for the graphs
      common /cranpt/conv
      double precision histo(0:nptg1)
      integer*4 n


      n=100000
      do i=0,nptg1
        histo(i)=0.d0
      enddo
      do j=1,n
        if(mod(j,10000).eq.0)write(*,*)"ptc",j

        x=ranptcut(xcut)*xfact+xadd
c.........Exponential
c          k=int((-dlog(x)/dlog(xminDf)+1.d0)*51.d0)
c.........Linear
        k=int(x/conv)
        k=min(k,nptg1)
        histo(k)=histo(k)+1.d0
      enddo
      do i=0,nptg1

c.......Exponential

c        x=xminDf
c        x1=xminDf
