c-----------------------------------------------------------------------
      subroutine EndEpos
c-----------------------------------------------------------------------
      call hnbdestroy
      end
c-----------------------------------------------------------------------
      subroutine IniEpos
c-----------------------------------------------------------------------
#include "epos.inc"
#include "epos.incems"
      double precision seedp
      parameter (nptj=129)
      common /cptj/xptj(nptj),qptj(nptj),wptj(nptj)
      real delmrho,delpeta
      integer irasym
      common /cuncertmu/delmrho,delpeta,irasym

      external sptj

c Conex common

      double precision EgyHiLoLim
      integer MCModel,MCleModel,ilowegy
      common/cxmodel/EgyHiLoLim,MCModel,MCleModel,ilowegy
      double precision airz,aira,airw,airavz,airava,airi
      common/cxair/airz(3),aira(3),airw(3),airavz,airava,airi(3)
      common/xsfiles/ixsfcx
      character*500 xsfnch,xsfnii,xsfnid,xsfnie,xsfnrj,xsfncs,xsfnhy
     *,xsfnnx
      common/xsfname/  xsfnch, xsfnii, xsfnid, xsfnie, xsfnrj, xsfncs
      common/xsnfname/nxsfnch,nxsfnii,nxsfnid,nxsfnie,nxsfnrj,nxsfncs
      common/xsfname2/ xsfnhy,xsfnnx
      common/xsnfname2/nxsfnhy,nxsfnnx
      double precision xsegymin,xsegymax,xselab,xsecms,xsekin,xspnll
     *,xsengy
      common/xsenrgy/xsegymin,xsegymax,xselab,xsecms,xsekin,xspnll
     *,xsengy
      parameter(mxnodyxs=20)
      common/xsnodcy/nrnodyxs,nodyxs(mxnodyxs)
      common/xsappli/iapplxs,modelxs
      common/xsevent/neventxs,iframexs
      integer ifragm
      common/cxfragm/ifragm
c      data inicnt/0/
      data init/0/
      save init

      if(init.ge.1)return
      init=init+1

#ifdef __CXDEBUG__

      call utisx1('iniepos ',4)
      write(*,'(a)')'initialize EPOS ...'
#endif

      if(ilowegy.ne.1.or.MCleModel.eq.4)xsegymin=dble(0.5*egymin**2)
      if(MCModel.eq.4)xsegymax=min(xsegymax,dble(0.5*egymax**2))
      nrnody=nrnodyxs
      do i=1,nrnody
        nody(i)= nodyxs(i)
      enddo
#if !__CXCORSIKA__ && !__CORSIKA8__

      inicnt=inicnt+1
c      isetcs=2                  ! epos cross-section from tabulated calculation (h-A and AA)
      isetcs=3                  ! epos cross-section from tabulated simulations (h-A and A-A)
      infragm=ifragm
      isigma=0                  !do not print out the cross section on screen
      ionudi=1
c--------------------------------------------------------------------------
#if __HACAS__ || __URQMD__
c     do not use hacas but mimic results (much faster=
        delmrho=0.
#else
        ihacas=-1
#endif
c--------------------------------------------------------------------------

      nfnii=nxsfnii             ! epos file name
      fnii=xsfnii
      nfnid=nxsfnid
      fnid=xsfnid
      nfnie=nxsfnie
      fnie=xsfnie
      nfnrj=nxsfnrj
      fnrj=xsfnrj
      nfncs=nxsfncs
      fncs=xsfncs
      nfnhpf=nxsfnhy
      fnhpf=xsfnhy
      nfnch=nxsfnch
      fnch=xsfnch
      nfnnx=nxsfnnx
      fnnx=xsfnnx

c air

      do i=1,3
        airanxs(i)=sngl(aira(i))
        airznxs(i)=sngl(airz(i))
        airwnxs(i)=sngl(airw(i))
      enddo
      airavanxs=sngl(airava)
      airavznxs=sngl(airavz)

      iappl  = iapplxs
      nevent = neventxs
      iframe = iframexs

      if(fnch(1:nfnch).ne.'none')
     &  open(ifcx,file=fnch(1:nfnch),status='unknown')

      call iclass(idproj,iclpro)
      call iclass(idtarg,icltar)
      if(inicnt.eq.1)then
        call ranfgt(seedp)      !not to change the seed ...
        call readidtable        !should be called early
        call idresi
        call idmass(1,qumass)
        qmass(1)=qumass         !u quark effective mass (for pt distribtions)
        isospin(1)=1
        call idmass(2,qdmass)
        qmass(2)=qdmass         !d quark effective mass (for pt distribtions)
        isospin(2)=-1
        call idmass(3,qsmass)
        qmass(3)=qsmass         !s quark effective mass (for pt distribtions)
        isospin(3)=0
        call idmass(4,qcmass)
        qmass(4)=qcmass         !c quark effective mass (for pt distribtions)
        isospin(4)=0
        call idmass(5,qbmass)
        qmass(5)=qbmass         !b quark effective mass (for pt distribtions)
        isospin(5)=0
        call idmass(6,qtmass)
        qmass(6)=qtmass         !t quark effective mass (for pt distribtions)
        isospin(6)=0
        call hdecin(.false.)
        c=6
        call utquaf(sptj,nptj,xptj,qptj,0.,.33*c,.66*c,c)
        call hnbcreate 
        call hnbspd(iospec)
        ktnbod=0
        call hnbpajini
        if(iclegy2.gt.1)then
          egyfac=(egymax*1.0001/egylow)**(1./float(iclegy2-1))
        else
          egyfac=1.
        endif
        if(ioquen.ne.0)then
c update file names
          fnrj(1:nfnrj+4)=fnrj(1:nfnrj)//".nf"
          nfnrj=nfnrj+4
          fncs(1:nfncs+4)=fncs(1:nfncs)//".nf"
          nfncs=nfncs+4
        endif
      endif
      maproj=mamxx               !to set difnuc up to the maximum mass
      call conini
      call psaini
      call ranfst(seedp)        ! ... after this initialization

#endif

#ifdef __CXDEBUG__
      call utisx2
#endif

      end


c-----------------------------------------------------------------------
      subroutine IniEvtEpo
c-----------------------------------------------------------------------
c Initialization for each type of event (for given proj, targ and egy)
c-----------------------------------------------------------------------
#include "epos.inc"
      common/geom/rmproj,rmtarg,bmax,bkmx
      double precision tpro,zpro,ttar,ztar,ttaus,detap,detat
      common/cttaus/tpro,zpro,ttar,ztar,ttaus,detap,detat /ctain/mtain
      double precision rcproj,rctarg
      common/geom1/rcproj,rctarg
c Conex common
#ifdef __CXDEBUG__
      parameter (mxisx=200)
      character*500 subisx,textisx
      common/cxisx/isx,nisx,subisx(mxisx),isxsub(mxisx)   !also in gheisha_nexus
     &      ,isxsave,isxxsave,textisx
      character*500 fnho,fnck,fnwle,fnwhe,fndkz,fndkl,fndks,fndkm
     &,fnilo,fndke,fndkn,fndkg,fnwgh,fnwgl
      common /cxfiles/fnho,ifho,fnck,ifck,fnwle,ifwle,fnwhe,ifwhe
     &,fndkz,ifdkz,fndkl,ifdkl,fndks,ifdks,fndkm,ifdkm,fnilo,ifilo
     &,fndke,ifdke,fndkn,ifdkn,fndkg,ifdkg,fnwgh,ifwgh
     &,fnwgl,ifwgl
#endif
      double precision xsegymin,xsegymax,xselab,xsecms,xsekin,xspnll
     *,xsengy
      common/xsenrgy/xsegymin,xsegymax,xselab,xsecms,xsekin,xspnll
     *,xsengy
      common/xsnucl1/laprojxs,maprojxs,latargxs,matargxs
      common/xshadr2/idprojxs,idtargxs
      double precision xsamproj,xsamtarg,xsypjtl,xsyhaha,xspnullx
      common/xschadron/xsamproj,xsamtarg,xsypjtl,xsyhaha,xspnullx
      double precision xsrmproj,xsrmtarg,xsbmax,xsbminim,xsbmaxim,xsbkmx
      common/xsgeom/xsrmproj,xsrmtarg,xsbmax,xsbminim,xsbmaxim,xsbkmx
      double precision xsrcproj,xsrctarg
      common/xsgeom1/xsrcproj,xsrctarg
      double precision xstpro,xszpro,xsttar,xsztar,xsttaus
     &,xsdetap,xsdetat
      common/xscttaus/xstpro,xszpro,xsttar,xsztar,xsttaus
     &,xsdetap,xsdetat

#if __URQMD__
      if(ihacas.ne.0)call cxstop("ihacas.ne.0 !!!!")
#endif
      
      maproj=maprojxs
      laproj=laprojxs
      matarg=matargxs
      latarg=latargxs
      idprojin=idprojxs
      idproj=idprojin
      idtargin=idtargxs
      idtarg=idtargin
      if(idtarg.eq.0)idtarg=1120
      amproj=xsamproj
      amtarg=xsamtarg
      call idspin(idproj,ispin,jspin,istra)
      isoproj=sign(1,idproj)*ispin
      call idspin(idtarg,ispin,jspin,istra)
      isotarg=sign(1,idtarg)*ispin
      call setCounters

      engy=sngl(xsengy)
      elab=sngl(xselab)
      ecms=sngl(xsecms)
      ekin=sngl(xsekin)
      pnll=sngl(xspnll)
      pnullx=sngl(xspnullx)
      yhaha=sngl(xsyhaha)
      ypjtl=sngl(xsypjtl)
      detap=xsdetap
      detat=xsdetat
      tpro=xstpro
      zpro=xszpro
      ttar=xsttar
      ztar=xsztar

      if(ish.ge.2)write(ifch,*)"Interaction (engy,proj,targ)"
     .                         ,engy,idproj,maproj,idtargin,matarg

      if(etafac.ne.1.)
     .call cxstop( "etafac.ne.1 not compatible with conex")
c      xsbminim=dble(bminim)     !not needed and can interfer with other MC
c      xsbmaxim=dble(bmaxim)

      call iclass(idproj,iclpro)
      call iclass(idtarg,icltar)
      call emsini(engy,idproj,idtarg)
      call paramini(1)
      bkmxndif=conbmxndif()
      bkmx=conbmx()
      xsbkmx=dble(bkmx)

      if(maproj.gt.1.or.matarg.gt.1)then
        xsbmax=xsrmproj+xsrmtarg
      else
        xsbmax=xsbkmx
      endif

      bimevt=-1
      bmax=sngl(xsbmax)
      rmproj=sngl(xsrmproj)
      rmtarg=sngl(xsrmtarg)
      rcproj=xsrcproj
      rctarg=xsrctarg
      call xsigma                          !set some variable according to xs
      if(idtarg.eq.0)idtarg=1120           !air = nucleus
#ifdef __CXDEBUG__
      if(isx.ge.2)write(ifck,*)
     &  'Epos used with (E,proj,maproj,matarg,bmax)',elab,idproj
     &  ,maproj,matarg,bmax
#endif
      return
      end

c-----------------------------------------------------------------------
      double precision function cxepocrse(ek,mapro,matar,id)
c-----------------------------------------------------------------------
c Epos cross section in double precision
c-----------------------------------------------------------------------
#include "epos.inc"
      double precision ek
      common/xshad10/iclproxs,icltarxs      !in conex.incnex

      iclpro=iclproxs
      icltar=icltarxs

      cxepocrse=dble(eposcrse(sngl(ek),mapro,matar,id))

      end

c-----------------------------------------------------------------------
      subroutine EposInput
c-----------------------------------------------------------------------
#include "epos.inc"
      common/cxsubro/isubin                 !also in conex.inc
      nopen=0
#ifdef __CXSUB__
      ifop=isubin
#else
      ifop=5
#endif
      call aread
      end

c-----------------------------------------------------------------------
      subroutine emsepo(iret)
c-----------------------------------------------------------------------
c  call epos to simulate interaction
c-----------------------------------------------------------------------
c Conex common
      implicit double precision (a-h,o-z)
#include "conex.h"
#include "conex.incnex"

c epos common
      parameter (mxptl=300000)   !max nr of particles in epos particle list
      common/col3/ncol,kolpt
      common/prnt1/iprmpt,ish,ishsub,irandm,irewch,iecho,modsho,idensi
      common/cptl/nptl,pptl(5,mxptl),iorptl(mxptl),idptl(mxptl)
     *,istptl(mxptl),tivptl(2,mxptl),ifrptl(2,mxptl),jorptl(mxptl)
     *,xorptl(4,mxptl),ibptl(4,mxptl),ityptl(mxptl)
      real pptl,xorptl,tivptl,gaumx,wtmini,wtstep
      common/wana2/isphis,ispall,wtmini,wtstep,iwcent,iana,nbdky
      integer      istore,istmax,irescl,ntrymx,nclean,iopdg,ioidch
      common/othe1/istore,istmax,gaumx,irescl,ntrymx,nclean,iopdg,ioidch
      integer      ifop,ifmt,ifch,ifcx,ifhi,ifdt,ifcp,ifdr,ifio
      common/files/ifop,ifmt,ifch,ifcx,ifhi,ifdt,ifcp,ifdr,ifio
      integer        iLHC,ipytune
      common/LHCtune/iLHC,ipytune
      integer       iorsce,iorsdf,iorshh,ionudi,kexit
      common/cjinti/iorsce,iorsdf,iorshh,ionudi,kexit
      logical chargex
      integer ichargex,kchargex
      real xschargex(0:3),rexchrg(4)
      double precision pnullx0
      common/chrgexch/pnullx0,xschargex,rexchrg,ichargex,kchargex
     *               ,ichargexin,chargex
      integer      idlead,ilprtg,mfragmaxp,mfragmaxt
      common/crvar/idlead,ilprtg,mfragmaxp,mfragmaxt
      integer       ihacas
      common/chacas/ihacas
      real        phievt,bimevt,pmxevt,egyevt
     *,xbjevt,qsqevt,zppevt,zptevt
      integer     nevt,kolevt,koievt,kohevt,npjevt
     *,ntgevt,npnevt,nppevt,ntnevt,ntpevt,jpnevt,jppevt,jtnevt,jtpevt
     *,nglevt,minfra,maxfra,npglb,ntglb
      common/cevt/phievt,nevt,bimevt,kolevt,koievt,pmxevt,egyevt,npjevt
     *,ntgevt,npnevt,nppevt,ntnevt,ntpevt,jpnevt,jppevt,jtnevt,jtpevt
     *,xbjevt,qsqevt,nglevt,zppevt,zptevt,minfra,maxfra,kohevt
     *,npglb,ntglb


c      double precision pfrx(mamxs),pfry(mamxs)
c      integer          ityp(mamxs)

      nptlxs=0
      nevtxs=1
      iret=0
      ntry=1
c      irest = maprojxs*100+abs(laprojxs)
c      inew=0

      call utpri('emsepo',ish,ishini,4)

 10   nptl=0
      minfra=mxptl
      maxfra=0
      mfragmaxp=1
      mfragmaxt=1
      call emsaaa(ntry,iret)
      
      if(iret.le.-100.or.chargex)then !chargex (pion exchange)
        if(iret.le.-100)then
          iqq=abs(iret)-100
          call emschargex(iqq,iret)
          if(iret.gt.0)then     !error
            call emschargex(-1,iret)
            goto 1001
          endif
          if(iret.eq.0)then
            goto 10
          else                  !charge exchange with elastic event, call again emschargex
            iret=0
          endif
        endif
        if(iret.lt.0)then       !if elastic event, redo
          ntry=ntry+1
          if(ntry.lt.10000)then
            iret=0
            goto 10
          endif
        endif
        call emschargex(-1,iret)
      endif
      if(iret.ne.0)goto 1001

      ncolxs=ncol

      if(ish.ge.2)call alist('list before fragmentation&',1,nptl)

      iclu=0
      if(iLHC.eq.1.and.iorsdf.eq.3)iclu=1 !in case of fusion, don't use Z first time
      call gakfra(iclu,iret)
      if(iret.gt.0)goto 1001
      maxfra=nptl
      if(ish.ge.4)
     &     call alist('list after fragmentation&',1,nptl)
      if(irescl.eq.1)then
        call utghost(iret)
        if(iret.gt.0)goto 1001
      endif
      call iniCore
c       calculates numbers of spectators:

        npnevt=0
        nppevt=0
        ntnevt=0
        ntpevt=0
        jpnevt=0
        jppevt=0
        jtnevt=0
        jtpevt=0
        if(ish.ge.2)write(ifch,'(/31a1/a/31a1)')('-',l=1,31)
     *       ,'primary and absolute spectators',('-',l=1,31)
        if(ish.ge.3)write(ifch,'(/a//a/)')'projectile nucleons:'
     *       ,'     i    id   ior   ist'
        do i=1,maprojxs
          if(ish.ge.3)write(ifch,'(4i6)')i,idptl(i),iorptl(i),istptl(i)
          io=iorptl(i)
          id=idptl(i)
          is=istptl(i)
          if(io.eq.0.and.id.eq.1220)npnevt=npnevt+1
          if(io.eq.0.and.id.eq.1120)nppevt=nppevt+1
          if(io.eq.0.and.is.eq.0.and.id.eq.1220)jpnevt=jpnevt+1
          if(io.eq.0.and.is.eq.0.and.id.eq.1120)jppevt=jppevt+1
        enddo
        if(ish.ge.3)write(ifch,'(/a//a/)')'target nucleons:'
     *       ,'     i    id   ior   ist'
        do i=maprojxs+1,maprojxs+matargxs
          if(ish.ge.3)write(ifch,'(4i6)')i,idptl(i),iorptl(i),istptl(i)
          io=iorptl(i)
          id=idptl(i)
          is=istptl(i)
          if(io.eq.0.and.id.eq.1220)ntnevt=ntnevt+1
          if(io.eq.0.and.id.eq.1120)ntpevt=ntpevt+1
          if(io.eq.0.and.is.eq.0.and.id.eq.1220)jtnevt=jtnevt+1
          if(io.eq.0.and.is.eq.0.and.id.eq.1120)jtpevt=jtpevt+1
        enddo
        if(ish.ge.2)then
          write(ifch,'(/a/)')'numbers of participants and spectators:'
          write(ifch,'(a,i4,a,i4)')'primary participants:   projectile:'
     *         ,npjevt,'   target:',ntgevt
          write(ifch,'(a,i4,a,i4)')'primary spectators:     projectile:'
     *         ,npnevt+nppevt,'   target:',ntnevt+ntpevt
          write(ifch,'(a,i4,a,i4)')
     *         'primary spectator neutrons:   projectile:',npnevt
     *         ,'   target:',ntnevt
          write(ifch,'(a,i4,a,i4)')
     *         'primary spectator protons:    projectile:',nppevt
     *         ,'   target:',ntpevt
          write(ifch,'(a,i4,a,i4)')'absolute spectators:    projectile:'
     *         ,jpnevt+jppevt,'   target:',jtnevt+jtpevt
        endif

c       Form nuclear fragments
      if(ifragm.gt.0)then
        call emsfrag(1,iret)
        if(iret.gt.0)goto 1001
      endif
      nbdky=nptl
      call bjinta(ier)
      if(ier.eq.1)goto 1001
      if(ish.ge.4)
     &       call alist('list after int/decays&',1,nptl)
c      if(irescl.eq.1)then
c        call utresc(iret)
c        if(ish.ge.4)call alist('list after rescaling&',1,nptl)
c        if(iret.gt.0)goto 1001
c      endif
      call aafinal

      if(abs(ihacas).eq.1.and.nptl.gt.maprojxs+matargxs+1)then
        call hacas(1,ier)
        if(ier.gt.0)goto 1001
      endif

      if(ifragm.eq.0)then
c         Form nuclear fragments
        call emsfrag(2,ier)
        if(ier.gt.0)goto 1001
      endif

      if(ish.ge.2)call alistf('EPOS&')

      do is=1,nptl

        if(istptl(is).eq.0.or.is.le.maprojxs+matargxs)then
          nptlxs=nptlxs+1
          if(nptlxs.gt.mxptlxs)call cxstop('Epos: mxptlxs too small')
          id=idptl(is)
          if(id.gt.10000)id=mod(id,10000)/10*100           !proj A

          call cxidmass(id,am)

          istptlxs(nptlxs)=istptl(is)
c          if ( is .le. maprojxs  .and.
c     *          iorptl(is) .eq. 0  .and.  istptl(is) .eq. 0 ) then
c            if ( ifragm .ne. 0 ) then
cc  compose projectile spectators to remaining nucleus
c              istptlxs(nptlxs)=1
c              idrest = nptlxs
c              if     ( id .eq. 1120 ) then
c                inew  = inew + 101
c                irest = irest - 101
c              elseif ( id .eq. 1220 ) then
c                inew  = inew + 100
c                irest = irest - 100
c              endif
c            endif
c          elseif( is .le. maprojxs  .and.
c     *          iorptl(is) .eq. 0  .and.  istptl(is) .eq. 1 ) then
c              jorptl(is)=1
c          endif
          xsptl(1,nptlxs)=dble(pptl(1,is))
          xsptl(2,nptlxs)=dble(pptl(2,is))
          xsptl(3,nptlxs)=dble(pptl(3,is))
          xsptl(4,nptlxs)=dble(pptl(4,is))
          xsptl(5,nptlxs)=am    !mass
          ityptlxs(nptlxs)=ityptl(is)
          iorptlxs(nptlxs)=iorptl(is)
          jorptlxs(nptlxs)=jorptl(is)
          ifrptlxs(1,nptlxs)=ifrptl(1,is)
          ifrptlxs(2,nptlxs)=ifrptl(2,is)
          xsorptl(1,nptlxs)=dble(xorptl(1,is))
          xsorptl(2,nptlxs)=dble(xorptl(2,is))
          xsorptl(3,nptlxs)=dble(xorptl(3,is))
          xsorptl(4,nptlxs)=dble(xorptl(4,is))
          xstivptl(1,nptlxs)=dble(tivptl(1,is))
          xstivptl(2,nptlxs)=dble(tivptl(2,is))
          idptlxs(nptlxs)=id


#ifdef __CXDEBUG__
          if(isx.ge.5)write(ifck,'(a,i5,a,i5,a,4(e11.4,1x),f6.3)')
     $       ' particle from EPOS ',nptlxs,' id :',idptlxs(nptlxs)
     $  , ' momentum :',(xsptl(k,nptlxs),k=1,5)
#endif

        endif


      enddo
c      if(inew.eq.0)goto 1000
c
c      nptlxsa=nptlxs
c
c      if( inew .eq. 100 .or. inew .eq. 101 ) then
cc  remaining nucleus is single neutron or proton
c        istptlxs(idrest)=0
c        goto 1000
c
c      elseif ( ifragm .ge. 2 ) then
cc  remaining nucleus is evaporating nucleons and alpha particles
c        jfin  = 0
c        call cxvapor( maprojxs,inew,jfin,ityp,pfrx,pfry )
c        if ( jfin .eq. 0 ) goto 1000
cc loop to treat the remanents of the desintegrated fragment
c        do  135  j = 1, jfin
c          if(mod(ityp(j),100).eq.0)then
c            inucl= ityp(j)/100
c            idnucl=100*inucl
c          else
c            inucl=1
c            idnucl=ityp(j)
c          endif
c          ea = dble(inucl) * dble(pptl(4,idrest))
c#ifdef __CXDEBUG__
c          if (isx.ge.6) write(ifck,*) 'fragment: j,id,ea=',
c     *                                       j,idnucl,ea
c#endif
cc  momenta squared
c          call cxidmass(idnucl,am)
c          ptm = ( ea - dble(am) ) * ( ea + dble(am) )
c          pt2 = pfrx(j)**2 + pfry(j)**2
c          if ( pt2 .ge. ptm ) then
c#ifdef __CXDEBUG__
c            if (isx.ge.2) write(ifck,*) 'emsepo: pt reject particle',j
c#endif
c            pfrx(j)=0.d0
c            pfry(j)=0.d0
c          endif
c          plong=ptm-pt2
c          if ( plong .ge. 0.d0)then
c            plong  = sqrt( plong )
c          else
c#ifdef __CXDEBUG__
c            if (isx.ge.2) write(ifck,*) 'emsepo: ptm reject particle',j
c#endif
c            do is=1,inucl
c              if(istptlxs(is).eq.1.and.jorptlxs(is).eq.0)istptlxs(is)=0
c            enddo
c            goto 135
c          endif
c          nptlxs=nptlxs+1
c          istptlxs(nptlxs)=0
c          xsptl(1,nptlxs)=pfrx(j)
c          xsptl(2,nptlxs)=pfry(j)
c          xsptl(3,nptlxs)=plong
c          xsptl(4,nptlxs)=ea
c          xsptl(5,nptlxs)=am    !mass
c          ityptlxs(nptlxs)=0
c          iorptlxs(nptlxs)=1
c          jorptlxs(nptlxs)=maprojxs
c          ifrptlxs(1,nptlxs)=0
c          ifrptlxs(2,nptlxs)=0
c          xsorptl(1,nptlxs)=xsorptl(1,idrest)
c          xsorptl(2,nptlxs)=xsorptl(2,idrest)
c          xsorptl(3,nptlxs)=xsorptl(3,idrest)
c          xsorptl(4,nptlxs)=xsorptl(4,idrest)
c          xstivptl(1,nptlxs)=xstivptl(1,idrest)
c          xstivptl(2,nptlxs)=xstivptl(2,idrest)
c          idptlxs(nptlxs)=idnucl
c 135    continue
c
c        elseif ( ifragm .eq. 1 ) then
cc  remaining nucleus is one fragment
c          nptlxs=nptlxs+1
c          istptlxs(nptlxs)=0
c          xsptl(1,nptlxs)=0.d0
c          xsptl(2,nptlxs)=0.d0
c          xsptl(4,nptlxs)=0.d0
c          inucl=0
c          do is=1,maprojxs
c            if(iorptl(is).eq.0.and.jorptl(is).eq.0)then
c              inucl=inucl+1
c              xsptl(4,nptlxs)=xsptl(4,nptlxs)+dble(pptl(4,is))
c            endif
c          enddo
c          idnucl=100*inucl
c          call cxidmass(idnucl,am)
c          xsptl(5,nptlxs)=am    !mass
c          ptot=(xsptl(4,nptlxs)+am)*(xsptl(4,nptlxs)-am)
c          xsptl(3,nptlxs)=sqrt(ptot)
c          ityptlxs(nptlxs)=0
c          istptlxs(nptlxs)=0
c          iorptlxs(nptlxs)=1
c          jorptlxs(nptlxs)=maprojxs
c          ifrptlxs(1,nptlxs)=0
c          ifrptlxs(2,nptlxs)=0
c          xsorptl(1,nptlxs)=xsorptl(1,idrest)
c          xsorptl(2,nptlxs)=xsorptl(2,idrest)
c          xsorptl(3,nptlxs)=xsorptl(3,idrest)
c          xsorptl(4,nptlxs)=xsorptl(4,idrest)
c          xstivptl(1,nptlxs)=xstivptl(1,idrest)
c          xstivptl(2,nptlxs)=xstivptl(2,idrest)
c          idptlxs(nptlxs)=idnucl
c        endif
c
c#ifdef __CXDEBUG__
c      do is=nptlxsa+1,nptlxs
c          if(isx.ge.5)write(ifck,'(a,i5,a,i5,a,4(e11.4,1x),f6.3)')
c     $       ' particle from EPOS ',is,' id :',idptlxs(is)
c     $  , ' momentum :',(xsptl(k,is),k=1,5)
c      enddo
c#endif


 1000 call utprix('emsepo',ish,ishini,4)
      return


1001  iret=1
      goto 1000

      end

