CDECK  ID>, PHO_CONN0
      DOUBLE PRECISION FUNCTION PHO_CONN0(BETA)
C***********************************************************************
C
C    auxiliary function to determine parameters of soft
C    pt distribution  dNs/dP_t = P_t * AAS * EXP(-BETA*P_t**2)
C
C    internal factors: FS  number of soft partons in soft Pomeron
C                      FH  number of soft partons in hard Pomeron
C
C***********************************************************************

      IMPLICIT NONE

      SAVE

C  input/output channels
      INTEGER LI,LO ,LPRI
      COMMON /POINOU/ LI,LO ,LPRI

C  average number of cut soft and hard ladders (obsolete)
      DOUBLE PRECISION AVERI,AVERK,AVERL,AVERM,AVERN
      COMMON /POINT2/ AVERI,AVERK,AVERL,AVERM,AVERN

C  data needed for soft-pt calculation
      DOUBLE PRECISION SIGS,DSIGHP,SIGH,FS,FH,BETAS,AAS,PTCON
      COMMON /POINT3/ SIGS,DSIGHP,SIGH,FS,FH,BETAS(3),AAS,PTCON

      DOUBLE PRECISION BETA,XX,FF

      XX = BETA*PTCON**2
      IF(ABS(XX).LT.1.D-3) THEN
        FF = FS*SIGS+FH*SIGH
     &       - DSIGHP*(PTCON/2.D0+PTCON**3*BETA/4.D0)
      ELSE
        FF = FS*SIGS+FH*SIGH
     &       - DSIGHP/(2.D0*PTCON*BETA)*(EXP(XX)-1.D0)
      ENDIF
      PHO_CONN0 = FF

*     WRITE(LO,'(1X,A,3E12.3)') 'PHO_CONN0:BETA,AAS,FF',BETA,AAS,FF
*     WRITE(LO,'(1X,A,3E12.3)') 'PHO_CONN0:SIGS,SIGH,DSIGH',SIGS,SIGH,DSIGHP

      END


 
 


CDECK  ID>, PHO_CONN1
      DOUBLE PRECISION FUNCTION PHO_CONN1(BETA)
C***********************************************************************
C
C    auxiliary function to determine parameters of soft
C    pt distribution  dNs/dP_t = P_t * AAS * EXP(-BETA*P_t)
C
C    internal factors: FS  number of soft partons in soft Pomeron
C                      FH  number of soft partons in hard Pomeron
C
C***********************************************************************

      IMPLICIT NONE

      SAVE

C  input/output channels
      INTEGER LI,LO ,LPRI
      COMMON /POINOU/ LI,LO ,LPRI

C  average number of cut soft and hard ladders (obsolete)
      DOUBLE PRECISION AVERI,AVERK,AVERL,AVERM,AVERN
      COMMON /POINT2/ AVERI,AVERK,AVERL,AVERM,AVERN

C  data needed for soft-pt calculation
      DOUBLE PRECISION SIGS,DSIGHP,SIGH,FS,FH,BETAS,AAS,PTCON
      COMMON /POINT3/ SIGS,DSIGHP,SIGH,FS,FH,BETAS(3),AAS,PTCON

      DOUBLE PRECISION BETA,XX,FF

      XX = BETA*PTCON
      IF(ABS(XX).LT.1.D-3) THEN
        FF = FS*SIGS+FH*SIGH
     &       - DSIGHP*(PTCON/2.D0+PTCON**2*BETA/6.D0)
      ELSE
        FF = FS*SIGS+FH*SIGH
     &       - DSIGHP/(PTCON*BETA**2)*(EXP(XX)-1.D0-BETA*PTCON)
      ENDIF
      PHO_CONN1 = FF

*     WRITE(LO,'(1X,A,3E12.3)') 'PHO_CONN1:BETA,AAS,FF',BETA,AAS,FF
*     WRITE(LO,'(1X,A,3E12.3)') 'PHO_CONN1:SIGS,SIGH,DSIGH',SIGS,SIGH,DSIGHP

      END


 
 


CDECK  ID>, pho_cpcini
      SUBROUTINE PHO_CPCINI(Nrows,Number,List)
C***********************************************************************
C
C     initialization of particle hash table
C
C     input:   Number     vector with Nrows entries according to PDG
C                         convention
C
C     output:  List       vector with hash table
C
C     (this code is based on the function initpns written by
C      Gerry Lynch, LBL, January 1990)
C
C***********************************************************************

      IMPLICIT NONE

      SAVE

C  input/output channels
      INTEGER LI,LO ,LPRI
      COMMON /POINOU/ LI,LO ,LPRI

      INTEGER Number(*),List(*),Nrows

      INTEGER Nin,Nout,Ip,I

      do I = 1,577
        List(I) = 0
      enddo

C    Loop over all of the elements in the Number vector

        Do 500 Ip = 1,Nrows
            Nin = Number(Ip)

C    Calculate a list number for this particle id number
            If(Nin.Gt.99999.or.Nin.Le.0) Then
                 Nout = -1
            Else If(Nin.Le.577) Then
                 Nout = Nin
            Else
                 Nout = Mod(Nin,577)

            End If
 200        continue

            If(Nout.Lt.0) Then
C    Count the bad entries
                IF (LPRI.GT.4)
     &          WRITE(LO,'(1x,a,i10)')
     &            'PHO_CPCINI: invalid particle ID',Nin
                Go to 500
            End If
            If(List(Nout).eq.0) Then
                List(Nout) = Ip
            Else
                If(Nin.eq.Number(List(Nout))) Then
                  IF (LPRI.GT.4)
     &            WRITE(LO,'(1x,a,i10)')
     &              'PHO_CPCINI: double particle ID',Nin
                End If
                Nout = Nout + 5
                If(Nout.Gt.577) Nout = Mod(Nout, 577)

                Go to 200
            End If
 500      Continue

      END


 
 


CDECK  ID>, PHO_CSDIFF
      SUBROUTINE PHO_CSDIFF(Id1,Id2,SS,Xi_min,Xi_max,
     &  sig_sd1,sig_sd2,sig_dd)
C***********************************************************************
C
C     cross section for diffraction dissociation according to
C     Goulianos' parametrization (Ref: PL B358 (1995) 379)
C
C     in addition rescaling for different particles is applied using
C     internal rescaling tables (not implemented yet)
C
C     input:     Id1/2       PDG ID's of incoming particles
C                SS          squared c.m. energy (GeV**2)
C                Xi_min      min. diff mass (squared) = Xi_min*SS
C                Xi_max      max. diff mass (squared) = Xi_max*SS
C
C     output:    sig_sd1     cross section for diss. of particle 1 (mb)
C                sig_sd2     cross section for diss. of particle 2 (mb)
C                sig_dd      cross section for diss. of both particles
C
C***********************************************************************

      IMPLICIT NONE

      SAVE

      INTEGER Id1,Id2
      DOUBLE PRECISION SS,Xi_min,Xi_max,sig_sd1,sig_sd2,sig_dd

C  input/output channels
      INTEGER LI,LO ,LPRI
      COMMON /POINOU/ LI,LO ,LPRI

C  some constants
      DOUBLE PRECISION PI,PI2,PI4,GEV2MB,Q_ch,Q_ch2,Q_ch4
      COMMON /POCONS/ PI,PI2,PI4,GEV2MB,
     &  Q_ch(-6:6),Q_ch2(-6:6),Q_ch4(-6:6)

      DOUBLE PRECISION xpos1(96),xwgh1(96),xpos2(96),xwgh2(96)
      DOUBLE PRECISION delta,alphap,beta0,gpom0,xm_p,x_rad2,xm4_p2,
     &  fac,tt,t1,t2,tl,tu,Xnorm,xi,xil,xiu,w_xi,alpha_t,f2_t,
     &  xms_1,xms_2,CSdiff

      INTEGER Ngau1,Ngau2,i1,i2

C  model parameters
      DATA delta    / 0.104d0 /
      DATA alphap   / 0.25d0 /
      DATA beta0    / 6.56d0 /
      DATA gpom0    / 1.21d0 /
      DATA xm_p     / 0.938d0 /
      DATA x_rad2   / 0.71d0 /

C  integration precision
      DATA Ngau1    / 96 /
      DATA Ngau2    / 96 /

      sig_sd1 = 0.d0
      sig_sd2 = 0.d0
      sig_dd  = 0.d0

      IF ((ABS(id1).EQ.2212).AND.(ABS(id2).EQ.2212)) THEN

        xm4_p2 = 4.D0*xm_p**2
        fac = beta0**2/(16.D0*PI)

        t1 = -5.D0
        t2 = 0.D0
        tl = x_rad2/3.D0/(1.D0-t1/x_rad2)**3
        tu = x_rad2/3.D0/(1.D0-t2/x_rad2)**3

C  flux renormalization and cross section

        Xnorm  = 0.d0

        xil = log(1.5d0/SS)
        xiu = log(0.1d0)

        IF(xiu.LE.xil) goto 1000

        CALL PHO_GAUSET(xil,xiu,Ngau1,xpos1,xwgh1)
        CALL PHO_GAUSET(tl,tu,Ngau2,xpos2,xwgh2)

        do i1=1,Ngau1

          xi = exp(xpos1(i1))
          w_xi = Xwgh1(i1)

          do i2=1,Ngau2

            tt = x_rad2-x_rad2*(x_rad2/(3.D0*xpos2(i2)))**(1.D0/3.D0)

            alpha_t =  1.D0+delta+alphap*tt
            f2_t = ((xm4_p2-2.8D0*tt)/(xm4_p2-tt))**2

            Xnorm = Xnorm
     &        + f2_t*xi**(2.D0-2.d0*alpha_t)*Xwgh2(i2)*w_xi

          enddo
        enddo

        Xnorm = Xnorm*fac

 1000   continue

        XIL = LOG(Xi_min)
        XIU = LOG(Xi_max)

        T1 = -5.D0
        T2 = 0.D0

        TL = x_rad2/3.D0/(1.D0-t1/x_rad2)**3
        TU = x_rad2/3.D0/(1.D0-t2/x_rad2)**3

C  single diffraction diss. cross section

        CSdiff = 0.d0

        IF(XIU.LE.XIL) goto 2000

        CALL PHO_GAUSET(XIL,XIU,NGAU1,XPOS1,XWGH1)
        CALL PHO_GAUSET(TL,TU,NGAU2,XPOS2,XWGH2)

        do i1=1,Ngau1

          xi = exp(xpos1(i1))
          w_xi = Xwgh1(i1)*beta0*gpom0*(xi*ss)**delta

          do i2=1,Ngau2

            tt = x_rad2-x_rad2*(x_rad2/(3.D0*xpos2(i2)))**(1.D0/3.D0)

            alpha_t =  1.D0+delta+alphap*tt
            f2_t = ((xm4_p2-2.8D0*tt)/(xm4_p2-tt))**2

            CSdiff = CSdiff
     &        + f2_t*xi**(2.D0-2.d0*alpha_t)*Xwgh2(i2)*w_xi

          enddo
        enddo

        CSdiff = CSdiff*fac*GEV2MB/MAX(1.d0,Xnorm)

*       WRITE(LO,'(1x,1p,4e14.3)')
*    &    sqrt(SS),Xnorm,2.*CSdiff*MAX(1.d0,Xnorm),2.*CSdiff

        sig_sd1 = CSdiff
        sig_sd2 = CSdiff

 2000   continue

C  double diffraction dissociation cross section

        CSdiff = 0.d0

        xil = log(1.5d0/SS)
        xiu = log(Xi_max/1.5d0)

        IF(xiu.LE.xil) goto 3000

        fac = (beta0*gpom0*SS**delta
     &         /(4.d0*sqrt(PI)*MAX(1.d0,Xnorm)))**2
     &       /(2.d0*alphap)

        CALL PHO_GAUSET(xil,xiu,ngau1,xpos1,xwgh1)

        do i1=1,Ngau1

          xi = exp(xpos1(i1))
          xms_1 = xi*SS

          xiu = log(Xi_max/(xi*SS))

          if(xil.lt.xiu) then

            CALL PHO_GAUSET(xil,xiu,Ngau2,xpos2,xwgh2)

            do i2=1,Ngau2

              xms_2 = exp(xpos2(i2))*SS
              CSdiff = CSdiff
     &          + 1.d0/((xms_1*xms_2)**delta*log(SS/(xms_1*xms_2)))
     &            *xwgh1(i1)*xwgh2(i2)

            enddo

          endif

        enddo

        sig_dd = CSdiff*fac*GEV2MB

 3000   continue

      ELSE

        IF (LPRI.GT.4)
     &  WRITE(LO,'(1x,2a,2I8)') 'PHO_CSDIFF: ',
     &    'invalid particle combination (Id1/2)',Id1,Id2

      ENDIF

      END


 
 


CDECK  ID>, PHO_CSINT
      SUBROUTINE PHO_CSINT(IP,IFPA,IFPB,IHLA,IHLB,ECM,PVIR2A,PVIR2B)
C********************************************************************
C
C     calculate cross sections by interpolation
C
C     input:   IP          particle combination
C              IFPA/B      particle PDG number
C              IHLA/B      particle helicity (photons only)
C              ECM         c.m. energy (GeV)
C              PVIR2A      virtuality of particle A (GeV**2, positive)
C              PVIR2B      virtuality of particle B (GeV**2, positive)
C
C     output:  cross sections stored in /POCSEC/
C
C********************************************************************
      IMPLICIT DOUBLE PRECISION (A-H,O-Z)
      SAVE

      PARAMETER ( EPS    =  1.D-5,
     &            DEPS   =  1.D-15 )

C  input/output channels
      INTEGER LI,LO ,LPRI
      COMMON /POINOU/ LI,LO ,LPRI

C  current beam selection
      INTEGER IDXMPAR, MPARMAX, MPARCONF, NMPAR, IKNOWN
      INTEGER MPMAPP, MAXMAPPS, NMAPP, MPAR, IPAVAIL
      DOUBLE PRECISION SQSGLOBMAX
      PARAMETER (MPARMAX=40)
      PARAMETER (MAXMAPPS=40)
      PARAMETER (IKNOWN=9)
      DIMENSION IPAVAIL(IKNOWN)
      DATA IPAVAIL /2212, 211, 111, 22, 2112, 3122, 3112, 321, 311/
      COMMON /POBEAM/ MPARCONF(2, MPARMAX), MPMAPP(2,MAXMAPPS),
     &           MPAR(2), SQSGLOBMAX, NMPAR, IDXMPAR, NMAPP

C  some constants
      DOUBLE PRECISION PI,PI2,PI4,GEV2MB,Q_ch,Q_ch2,Q_ch4
      COMMON /POCONS/ PI,PI2,PI4,GEV2MB,
     &  Q_ch(-6:6),Q_ch2(-6:6),Q_ch4(-6:6)

C  event debugging information
      INTEGER NMAXD
      PARAMETER (NMAXD=100)
      INTEGER IDEB,KSPOM,KHPOM,KSREG,KHDIR,KACCEP,KSTRG,KHTRG,KSLOO,
     &        KHLOO,KSDPO,KHDPO,KEVENT,KSOFT,KHARD
      COMMON /PODEBG/ IDEB(NMAXD),KSPOM,KHPOM,KSREG,KHDIR,KACCEP,KSTRG,
     &                KHTRG,KSLOO,KHLOO,KSDPO,KHDPO,KEVENT,KSOFT,KHARD

C  model switches and parameters
      CHARACTER*8 MDLNA
      INTEGER ISWMDL,IPAMDL
      DOUBLE PRECISION PARMDL
      COMMON /POMDLS/ MDLNA(50),ISWMDL(50),PARMDL(400),IPAMDL(400)

C  energy-interpolation table
      INTEGER IEETA2
      PARAMETER ( IEETA2 = 20 )
      INTEGER ISIMAX
      DOUBLE PRECISION SIGTAB,SIGECM, ECMF
      COMMON /POTABL/ SIGTAB(80, IEETA2, 4, MPARMAX),
     &                SIGECM(IEETA2, 4, MPARMAX), ECMF(4, MPARMAX),
     &                ISIMAX(MPARMAX)

C  cross sections
      INTEGER IPFIL,IFAFIL,IFBFIL
      DOUBLE PRECISION SIGTOT,SIGELA,SIGVM,SIGINE,SIGNDF,SIGDIR,
     &                 SIGLSD,SIGHSD,SIGLDD,SIGHDD,SIGCDF,
     &                 SIGPOM,SIGREG,SIGHAR,SIGTR1,SIGTR2,SIGLOO,
     &                 SIGDPO,SIG1SO,SIG1HA,SLOEL,SLOVM,SIGCOR,
     &                 FSUP,FSUD,FSUH,ECMFIL,P2AFIL,P2BFIL
      COMMON /POCSEC/ SIGTOT,SIGELA,SIGVM(0:4,0:4),SIGINE,SIGNDF,SIGDIR,
     &                SIGLSD(2),SIGHSD(2),SIGLDD,SIGHDD,SIGCDF(0:4),
     &                SIGPOM,SIGREG,SIGHAR,SIGTR1(2),SIGTR2(2),SIGLOO,
     &                SIGDPO(4),SIG1SO,SIG1HA,SLOEL,SLOVM(4,4),SIGCOR,
     &                FSUP(2),FSUD(2),FSUH(2),ECMFIL,P2AFIL,P2BFIL,
     &                IPFIL,IFAFIL,IFBFIL

C  hard cross sections and MC selection weights
      INTEGER Max_pro_2
      PARAMETER ( Max_pro_2 = 16 )
      INTEGER IHa_last,IHb_last,MH_pro_on,MH_tried,
     &  MH_acc_1,MH_acc_2
      DOUBLE PRECISION HFAC, HWGX, HSIG, HDPT, HECM_LAST, 
     &   HQ2A_LAST, HQ2B_LAST
      COMMON /POHRCS/HFAC(-1:MAX_PRO_2, MPARMAX), 
     &   HWGX(-1:MAX_PRO_2, MPARMAX),
     &   HSIG(-1:MAX_PRO_2, MPARMAX), HDPT(-1:MAX_PRO_2, MPARMAX), 
     &   HECM_LAST, HQ2A_LAST, HQ2B_LAST, IHA_LAST, IHB_LAST, 
     &   MH_PRO_ON(-1:MAX_PRO_2, 0:4, MPARMAX),
     &   MH_TRIED(-1:MAX_PRO_2, 0:4, MPARMAX), 
     &   MH_ACC_1(-1:MAX_PRO_2, 0:4, MPARMAX),
     &   MH_ACC_2(-1:MAX_PRO_2, 0:4, MPARMAX) 

C  obsolete cut-off information
      DOUBLE PRECISION PTCUT,PTANO,FPS,FPH,PSOMIN,XSOMIN
      COMMON /POCUT1/ PTCUT(4),PTANO(4),FPS(4),FPH(4),PSOMIN,XSOMIN
      
      DIMENSION PVIRT(2),SIGSRH(2),FSUT(2),FSUL(2),ILPAP(2),IHEL(2)

      DIMENSION PD(-6:6),FH_T(2),FH_L(2) 
      DOUBLE PRECISION PHO_PTCUT
      EXTERNAL         PHO_PTCUT
      DATA IPCOMB / 0 /

C  debug
      IF (LPRI.GT.4 .AND. IDEB(15).GE.10)
     &WRITE(LO,'(1X,A,/10X,I3,2I6,1P3E12.4)')
     &  'PHO_CSINT: called with IP, IFP1, IFP2, ECM, PVIR1, PVIR2',
     &  IP,IFPA,IFPB,ECM,PVIR2A,PVIR2B
C**anfe Initialize the ptcut common block information
      ptcut(ip) = PHO_PTCUT(ecm, ip)
C  check currently stored cross sections
      IF((IP.EQ.IPFIL).AND.(ECM.EQ.ECMFIL)
     &   .AND.(PVIR2A.EQ.P2AFIL).AND.(PVIR2B.EQ.P2BFIL)
     &   .AND.(IFPA.EQ.IFAFIL).AND.(IFPB.EQ.IFBFIL).AND.
     &   (IPCOMB==IDXMPAR)) THEN
C  nothing to calculate
        IF(IDEB(15).GE.20 .AND. LPRI.GT.4)
     &    WRITE(LO,'(1X,A)') 'PHO_CSINT: nothing done'
        RETURN
      ELSE

C  copy to local fields
        ILPAP(1) = IFPA
        ILPAP(2) = IFPB
        IHEL(1)  = IHLA
        IHEL(2)  = IHLB
        PVIRT(1) = PVIR2A
        PVIRT(2) = PVIR2B
C  load cross sections from interpolation table
        IF(ECM.LE.SIGECM(1,IP,IDXMPAR)) THEN
          I1 = 1
          I2 = 2
        ELSE IF(ECM.LE.SIGECM(ISIMAX(IDXMPAR),IP,IDXMPAR)) THEN
          DO 50 I=2,ISIMAX(IDXMPAR)
            IF(ECM.LE.SIGECM(I,IP,IDXMPAR)) GOTO 200
 50       CONTINUE
 200      CONTINUE
          I1 = I-1
          I2 = I
        ELSE
          IF (LPRI.GT.4)
     &    WRITE(LO,'(/1X,A,2E12.3)')
     &      'PHO_CSINT: too high energy',ECM,
     &      SIGECM(ISIMAX(IDXMPAR),IP,IDXMPAR)
          CALL PHO_PREVNT(-1)
          I1 = ISIMAX(IDXMPAR)-1
          I2 = ISIMAX(IDXMPAR)
        ENDIF
        FAC2=0.D0
        IF(I1.NE.I2) FAC2=LOG(ECM/SIGECM(I1,IP,IDXMPAR))
     &                    /LOG(SIGECM(I2,IP,IDXMPAR)/
     &                    SIGECM(I1,IP,IDXMPAR))
        FAC1=1.D0-FAC2

C  cross section dependence on photon virtualities
        DO 140 K=1,2
          FSUP(K) = 1.D0
          FSUD(K) = 1.D0
          FSUH(K) = 1.D0
          IF(ILPAP(K).EQ.22) THEN
            IF(ISWMDL(10).GE.1) THEN
              FSUP(K) = 0.D0
              FSUT(K) = 0.D0
              FSUL(K) = 0.D0
              FSUH(K) = 0.D0
C  GVDM factors for transverse/longitudinal photons
              DO 150 I=1,3
                FSUT(K) = FSUT(K)+PARMDL(26+I)
     &                   /(1.D0+PVIRT(K)/PARMDL(30+I))**2
                FSUL(K) = FSUL(K)
     &                   +PARMDL(26+I)*PVIRT(K)/(4.D0*PARMDL(30+I))
     &                   /(1.D0+PVIRT(K)/PARMDL(30+I))**2
 150          CONTINUE
              FSUT(K) = FSUT(K)+PARMDL(30)/(1.D0+PVIRT(K)/PARMDL(34))
C  transverse part
              IF((ABS(IHEL(K)).EQ.1).OR.(ISWMDL(10).EQ.1)) THEN
                FSUP(K) = FSUT(K)
                FSUH(K) = FSUT(K)/(FSUT(K)+FSUL(K))
C  diffraction of trans. photons corresponds mainly to leading twist
                FSUD(K) = 1.D0
              ENDIF
C  longitudinal (scalar) part
              IF((IHEL(K).LE.0).OR.(ISWMDL(10).EQ.1)) THEN
                FSUP(K) = FSUP(K)+FSUL(K)
                FSUH(K) = FSUH(K)+FSUL(K)/(FSUT(K)+FSUL(K))
C  diffraction of long. photons corresponds mainly to higher twist
                FSUD(K) = 0.5D0*LOG(((ECM*PARMDL(45))**2+PVIRT(K))
     &                   /((0.765D0+PARMDL(46))**2+PVIRT(K)))
     &                   /LOG(ECM*PARMDL(45)/(0.765D0+PARMDL(46)))
              ENDIF
C  debug output
              if(ideb(15).ge.10) then
                IF (LPRI.GT.4)
     &          WRITE(LO,'(1x,2a,2i3,/,5x,1p5e12.4)') 'PHO_CSINT: ',
     &            'side,helicity,F_tran,F_long,F_eff,F_hard,F_diff',
     &            K,IHEL(K),FSUT(K),FSUL(K),FSUP(K),FSUH(K),FSUD(K)
              endif
            ENDIF
          ENDIF
 140    CONTINUE

        FACP = FSUP(1)*FSUP(2)
        FACH = FSUH(1)*FSUH(2)
        FACD = FSUD(1)*FSUD(2)

C  matching of model cross section to F2(x,Q2,P2) in limit of Q2 >> P2

        if((ILPAP(1).eq.22).and.(ILPAP(2).eq.22)
     &     .and.(IPAMDL(117).gt.0)) then
C  check kinematic limit
          Q2_max = max(PVIRT(1),PVIRT(2))
          Q2_min = min(PVIRT(1),PVIRT(2))
          if((Q2_max.gt.1.D0).and.(Q2_min.lt.1.D0)) then

C  calculate F2 from current parton density
            if(PVIRT(1).gt.PVIRT(2)) then
              K = 2
            else
              K = 1
            endif
            Q2 = Q2_max
            P2 = Q2_min
            X = Q2/(ECM**2+Q2+P2)
            CALL PHO_ACTPDF(ILPAP(K),K)
            CALL PHO_PDF(K,X,Q2,P2,PD)
C  light quark contribution
            F2_light = 0.D0
            do j=1,3
              F2_light = F2_light+Q_ch2(j)*(PD(j)+PD(-j))
            enddo
C  heavy quark contribution
            CALL PHO_QPMPDF(4,X,Q2,0.D0,P2,xpdf_c)
            F2_c = 2.D0*4.D0/9.D0*xpdf_c
            F2 = (F2_light+F2_c)

C  calculate model prediction
            SIGTOT = FAC2*SIGTAB(1,I2,IP,IDXMPAR)+
     &               FAC1*SIGTAB(1,I1,IP,IDXMPAR)
            SIGINE = FAC2*SIGTAB(28,I2,IP,IDXMPAR)+
     &               FAC1*SIGTAB(28,I1,IP,IDXMPAR)
            CALL PHO_HARINT(IP,ECM,0.D0,0.D0,0,Max_pro_2,3,4,1)

            if(ISWMDL(10).ge.2) then

C  calculate all helicity combinations
              if(IPAMDL(115).eq.0) then
                SIGDIH    = HSig(14,IDXMPAR)
                SIGSRH(1) = HSig(10,IDXMPAR)+HSig(11,IDXMPAR)
                SIGSRH(2) = HSig(12,IDXMPAR)+HSig(13,IDXMPAR)
                SIGtmp = SIGTOT-SIGDIH-SIGSRH(1)-SIGSRH(2)
C  photon helicity factors
                FH_T(1) = FSUT(1)/(FSUT(1)+FSUL(1))
                FH_L(1) = 1.D0-FH_T(1)
                FH_T(2) = FSUT(2)/(FSUT(2)+FSUL(2))
                FH_L(2) = 1.D0-FH_T(2)
                SIG_TT = SIGtmp*FSUT(1)*FSUT(2)
     &                  + SIGDIH*FH_T(1)*FH_T(2)
     &                  + SIGSRH(1)*FH_T(1)*FSUT(2)
     &                  + SIGSRH(2)*FSUT(1)*FH_T(2)
                SIG_TL = SIGtmp*FSUT(1)*FSUL(2)
     &                  + SIGDIH*FH_T(1)*FH_L(2)
     &                  + SIGSRH(1)*FH_T(1)*FSUL(2)
     &                  + SIGSRH(2)*FSUT(1)*FH_L(2)
                SIG_LT = SIGtmp*FSUL(1)*FSUT(2)
     &                  + SIGDIH*FH_L(1)*FH_T(2)
     &                  + SIGSRH(1)*FH_L(1)*FSUT(2)
     &                  + SIGSRH(2)*FSUL(1)*FH_T(2)
                SIG_LL = SIGtmp*FSUL(1)*FSUL(2)
     &                  + SIGDIH*FH_L(1)*FH_L(2)
     &                  + SIGSRH(1)*FH_L(1)*FSUL(2)
     &                  + SIGSRH(2)*FSUL(1)*FH_L(2)
              else
C  use explicit PDF virtuality dependence (pre-tabulated)
                SIGDIH    = HSig(14,IDXMPAR)
                SIGSRH(1) = HSig(10,IDXMPAR)+HSig(11,IDXMPAR)
                SIGSRH(2) = HSig(12,IDXMPAR)+HSig(13,IDXMPAR)
                SIGtmp = SIGTOT-SIGDIH-SIGSRH(1)-SIGSRH(2)
                IF (LPRI.GT.4)
     &          WRITE(LO,*)' PHO_CSINT: invalid option for F2 matching'
                stop
*               CALL PHO_HARINT(IP,ECM,PVIRT(1),PVIRT(2),0,
*    &                          Max_pro_2,3,4,1)
*               SIG_TT = SIGtmp*FSUT(1)*FSUT(2)
*    &            + HSig(10,IDXMPAR)+HSig(12,IDXMPAR)+
*    &            +HSig(14,IDXMPAR)+HSig(16,IDXMPAR)+HSig(18,IDXMPAR)
*               SIG_TL = SIGtmp*FSUT(1)*FSUL(2)
*    &            + HSig(10,IDXMPAR)+HSig(12,IDXMPAR)+
*    &            + HSig(14,IDXMPAR)+HSig(16,IDXMPAR)+HSig(19,IDXMPAR)
*               SIG_LT = SIGtmp*FSUL(1)*FSUT(2)
*    &            + HSig(11,IDXMPAR)+HSig(13,IDXMPAR)+
*    &            + HSig(15,IDXMPAR)+HSig(17,IDXMPAR)+HSig(20,IDXMPAR)
*               SIG_LL = SIGtmp*FSUL(1)*FSUL(2)
*    &            + HSig(11,IDXMPAR)+HSig(13,IDXMPAR)+
*    &            + HSig(15,IDXMPAR)+HSig(17,IDXMPAR)+HSig(21,IDXMPAR)
              endif
              Xnu = Ecm*Ecm+Q2+P2
              F2_fac = Q2*Xnu/sqrt(Xnu*Xnu-Q2*P2)/(4.D0*Pi*Pi)
     &             *137.D0/GeV2mb
              if(K.eq.2) then
                F2m = F2_fac*(SIG_TT+SIG_LT-0.5D0*SIG_TL-0.5D0*SIG_LL)
                F2s = F2_fac*SIGtmp*(FSUT(1)*FSUT(2)+FSUL(1)*FSUT(2)
     &               -0.5D0*FSUT(1)*FSUL(2)-0.5D0*FSUL(1)*FSUL(2))
              else
                F2m = F2_fac*(SIG_TT+SIG_TL-0.5D0*SIG_LT-0.5D0*SIG_LL)
                F2s = F2_fac*SIGtmp*(FSUT(1)*FSUT(2)+FSUT(1)*FSUL(2)
     &               -0.5D0*FSUL(1)*FSUT(2)-0.5D0*FSUL(1)*FSUL(2))
              endif

            else

C  assume sig_eff = sigtot
              SIGDIH    = HSig(14,IDXMPAR)
              SIGSRH(1) = HSig(10,IDXMPAR)+HSig(11,IDXMPAR)
              SIGSRH(2) = HSig(12,IDXMPAR)+HSig(13,IDXMPAR)
              SIGtmp = SIGTOT-SIGSRH(1)-SIGSRH(2)-SIGDIH
              SIGeff = SIGtmp*FSUP(1)*FSUP(2)
     &                +SIGSRH(1)*FSUP(2)+SIGSRH(2)*FSUP(1)+SIGDIH
              Xnu = Ecm*Ecm+Q2+P2
              F2_fac = Q2*Xnu/sqrt(Xnu*Xnu-Q2*P2)/(4.D0*Pi*Pi)
     &             *137.D0/GeV2mb
              F2m = F2_fac*SIGeff
              F2s = F2_fac*SIGtmp*FSUP(1)*FSUP(2)
            endif
*           WRITE(LO,*)' PHO_CSINT: Q2_1,Q2_2,W ',PVIRT(1),PVIRT(2),Ecm
*           WRITE(LO,*)' PHO_CSINT: F2_mod,F2_pdf,mod/pdf ',
*    &                    F2m,F2,F2m/F2

C  global factor to re-scale suppression of soft contributions
            Fcorr = (F2-F2m+F2s)/F2s
*          WRITE(LO,*)' PHO_CSINT: re-scaling factor: ',Fcorr,FACP*Fcorr
            FACP = FACP*Fcorr

          endif
        endif

        SIGTOT = (FAC2*SIGTAB(1,I2,IP,IDXMPAR)+
     &            FAC1*SIGTAB(1,I1,IP,IDXMPAR))*FACP
        SIGINE = (FAC2*SIGTAB(28,I2,IP,IDXMPAR)+
     &            FAC1*SIGTAB(28,I1,IP,IDXMPAR))*FACP
        SIGELA = (FAC2*SIGTAB(2,I2,IP,IDXMPAR)+
     &            FAC1*SIGTAB(2,I1,IP,IDXMPAR))*FACP
        J = 2
        DO 5 I=0,4
          DO 6 K=0,4
            J = J+1
            SIGVM(I,K) = (FAC2*SIGTAB(J,I2,IP,IDXMPAR)+
     &                    FAC1*SIGTAB(J,I1,IP,IDXMPAR))*FACP**2
 6        CONTINUE
 5      CONTINUE

        SIGDIR = FAC2*SIGTAB(29,I2,IP,IDXMPAR)+
     &           FAC1*SIGTAB(29,I1,IP,IDXMPAR)
        SIGHAR = FAC2*SIGTAB(58,I2,IP,IDXMPAR)+
     &           FAC1*SIGTAB(58,I1,IP,IDXMPAR)
C  suppression of multi-pomeron graphs (diffraction)
        SIGLSD(1) = (FAC2*SIGTAB(30,I2,IP,IDXMPAR)+
     &               FAC1*SIGTAB(30,I1,IP,IDXMPAR))*FACP*FSUP(2)*FSUD(1)
        SIGLSD(2) = (FAC2*SIGTAB(31,I2,IP,IDXMPAR)+
     &               FAC1*SIGTAB(31,I1,IP,IDXMPAR))*FACP*FSUP(1)*FSUD(2)
        SIGHSD(1) = (FAC2*SIGTAB(32,I2,IP,IDXMPAR)+
     &               FAC1*SIGTAB(32,I1,IP,IDXMPAR))*FACP*FSUP(2)*FSUD(1)
        SIGHSD(2) = (FAC2*SIGTAB(33,I2,IP,IDXMPAR)+
     &               FAC1*SIGTAB(33,I1,IP,IDXMPAR))*FACP*FSUP(1)*FSUD(2)
        SIGLDD    = (FAC2*SIGTAB(34,I2,IP,IDXMPAR)+
     &               FAC1*SIGTAB(34,I1,IP,IDXMPAR))*FACP**2*FACD
        SIGHDD    = (FAC2*SIGTAB(35,I2,IP,IDXMPAR)+
     &               FAC1*SIGTAB(35,I1,IP,IDXMPAR))*FACP
        SIGCDF(0) = (FAC2*SIGTAB(36,I2,IP,IDXMPAR)+
     &               FAC1*SIGTAB(36,I1,IP,IDXMPAR))*FACP**2
        SIGTR1(1) = (FAC2*SIGTAB(60,I2,IP,IDXMPAR)+
     &               FAC1*SIGTAB(60,I1,IP,IDXMPAR))*FACP*FSUP(2)*FSUD(1)
        SIGTR1(2) = (FAC2*SIGTAB(61,I2,IP,IDXMPAR)+
     &               FAC1*SIGTAB(61,I1,IP,IDXMPAR))*FACP*FSUP(2)*FSUD(1)
        SIGTR2(1) = (FAC2*SIGTAB(62,I2,IP,IDXMPAR)+
     &               FAC1*SIGTAB(62,I1,IP,IDXMPAR))*FACP*FSUP(1)*FSUD(2)
        SIGTR2(2) = (FAC2*SIGTAB(63,I2,IP,IDXMPAR)+
     &               FAC1*SIGTAB(63,I1,IP,IDXMPAR))*FACP*FSUP(1)*FSUD(2)
        SIGLOO    = (FAC2*SIGTAB(64,I2,IP,IDXMPAR)+
     &               FAC1*SIGTAB(64,I1,IP,IDXMPAR))*FACP
        SIGDPO(1) = (FAC2*SIGTAB(65,I2,IP,IDXMPAR)+
     &               FAC1*SIGTAB(65,I1,IP,IDXMPAR))*FACP**2
        SIGDPO(2) = (FAC2*SIGTAB(66,I2,IP,IDXMPAR)+
     &               FAC1*SIGTAB(66,I1,IP,IDXMPAR))*FACP**2
        SIGDPO(3) = (FAC2*SIGTAB(67,I2,IP,IDXMPAR)+
     &               FAC1*SIGTAB(67,I1,IP,IDXMPAR))*FACP**2
        SIGDPO(4) = (FAC2*SIGTAB(68,I2,IP,IDXMPAR)+
     &               FAC1*SIGTAB(68,I1,IP,IDXMPAR))*FACP**2

C  corrections due to photon virtuality dependence of PDFs
        if(iswmdl(2).eq.1) then
          CALL PHO_HARINT(IP,ECM,0.D0,0.D0,0,Max_pro_2,3,4,1)
C  minimum bias event generation
          IF(IPAMDL(115).GE.1) THEN
C  all the virtuality dependence is given by PDF parametrization
            SIGHIN = FAC2*SIGTAB(80,I2,IP,IDXMPAR)+
     &               FAC1*SIGTAB(80,I1,IP,IDXMPAR)
            IF(IPAMDL(116).GE.2) THEN
C  direct interaction according to full QPM calculation
              SIGDIH = HSig(14,IDXMPAR)
              SIGSRH(1) = HSig(10,IDXMPAR)+HSig(11,IDXMPAR)
              SIGSRH(2) = HSig(12,IDXMPAR)+HSig(13,IDXMPAR)
            ELSE
C  direct interaction suppressed according to helicity factor
              SIGDIH = HSig(14,IDXMPAR)*FACH
              SIGSRH(1) = (HSig(10,IDXMPAR)+HSig(11,IDXMPAR))*FSUH(1)
              SIGSRH(2) = (HSig(12,IDXMPAR)+HSig(13,IDXMPAR))*FSUH(2)
            ENDIF
            IF (LPRI.GT.4)
     &      WRITE(LO,*)' PHO_CSINT: option not supported yet'
            stop
          ELSE
C  rescale relevant hard processes
            SIGDIH    = HSig(14,IDXMPAR)
            SIGSRH(1) = HSig(10,IDXMPAR)+HSig(11,IDXMPAR)
            SIGSRH(2) = HSig(12,IDXMPAR)+HSig(13,IDXMPAR)
            SIGtmp = SIGINE-(SIGDIH+SIGSRH(1)+SIGSRH(2))*FACP
            SIGDIR = HSig(14,IDXMPAR)*FACH+SIGSRH(1)*FSUH(1)*FSUP(2)
     &              +SIGSRH(2)*FSUP(1)*FSUH(2)
            SIGINE = SIGtmp+SIGDIR
            SIGTOT = SIGINE+SIGELA
          ENDIF
        else
C  only hard interactions
          CALL PHO_HARINT(IP,ECM,0.D0,0.D0,0,Max_pro_2,3,4,1)
          SIGSRH(1) = (HSig(10,IDXMPAR)+HSig(11,IDXMPAR))*FSUH(1)
          SIGSRH(2) = (HSig(12,IDXMPAR)+HSig(13,IDXMPAR))*FSUH(2)
          SIGDIR = HSig(14,IDXMPAR)+SIGSRH(1)+SIGSRH(2)
          SIGHAR = HSig(9,IDXMPAR)*FACH
        endif

        SIG1SO = (FAC2*SIGTAB(37,I2,IP,IDXMPAR)+
     &            FAC1*SIGTAB(37,I1,IP,IDXMPAR))*FACP
        SIG1HA = (FAC2*SIGTAB(38,I2,IP,IDXMPAR)+
     &            FAC1*SIGTAB(38,I1,IP,IDXMPAR))*FACH
        SLOEL = FAC2*SIGTAB(39,I2,IP,IDXMPAR)+
     &          FAC1*SIGTAB(39,I1,IP,IDXMPAR)
        J = 39
        DO 9 I=1,4
          DO 10 K=1,4
            J = J+1
            SLOVM(I,K) = FAC2*SIGTAB(J,I2,IP,IDXMPAR)+
     &                   FAC1*SIGTAB(J,I1,IP,IDXMPAR)
 10       CONTINUE
 9      CONTINUE
        SIGPOM = (FAC2*SIGTAB(56,I2,IP,IDXMPAR)+
     &            FAC1*SIGTAB(56,I1,IP,IDXMPAR))*FACP
        SIGREG = (FAC2*SIGTAB(57,I2,IP,IDXMPAR)+
     &            FAC1*SIGTAB(57,I1,IP,IDXMPAR))*FACP

        IPFIL  = IP
        IFAFIL = IFPA
        IFBFIL = IFPB
        ECMFIL = ECM
        ipcomb = idxmpar
        P2AFIL = PVIR2A
        P2BFIL = PVIR2B

        IF(IDEB(15).GE.20 .AND. LPRI.GT.4)
     &    WRITE(LO,'(1X,A)') 'PHO_CSINT: cross sections calculated'

      ENDIF

      END



      DOUBLE PRECISION FUNCTION PHO_CT14ALPHAS (QQ)

      IMPLICIT DOUBLE PRECISION (A-H,O-Z)

      PARAMETER (MXX = 201, MXQ = 40, MXF = 6, MaxVal=4)
      PARAMETER (MXPQX = (MXF+1+MaxVal) * MXQ * MXX)
      DOUBLE PRECISION Alsout
      
      COMMON
     > / CtqPar1 / qBase,XV(0:MXX), TV(0:MXQ), UPD(MXPQX),AlsCTEQ(0:mxq)
     > / CtqPar2 / Nx, Nt, NfMx, MxVal
     > / XQrange / Qini, Qmax, Xmin
     > /Setchange/ Isetch, ipdsset, ipdsformat

      DATA Q, JQ /-1D0, 0/
      SAVE

      if (ipdsset.ne.1) 
     >  STOP 'PHO_CT14ALPHAS: the PDF table was not initialized'

      
      if (ipdsformat.lt.11) then
        IF (LPRI.GT.4)
     &   WRITE(LO,*)  
     >  'STOP in PHO_CT14ALPHAS: the PDF table file has an older format'
        IF (LPRI.GT.4)
     &   WRITE(LO,*) 
     >    'and does not include the table of QCD coupling values.'
        IF (LPRI.GT.4)
     &   WRITE(LO,*) 
     >    'You can still compute the PDFs, but do not call'
        IF (LPRI.GT.4)
     &   WRITE(LO,*) 
     >   'the pho_CT14alphas function for the interpolation of alpha_s.'
        stop
      endif

      Q = QQ
      tt = log(log(Q/qBase))

c         --------------   Find lower end of interval containing Q, i.e.,
c                          get jq such that qv(jq) .le. q .le. qv(jq+1)...
      JLq = -1
      JU = NT+1
 13   If (JU-JLq .GT. 1) Then
        JM = (JU+JLq) / 2
        If (tt .GE. TV(JM)) Then
            JLq = JM
          Else
            JU = JM
          Endif
          Goto 13
       Endif

      If     (JLq .LE. 0) Then
         Jq = 0
      Elseif (JLq .LE. Nt-2) Then
C                                  keep q in the middle, as shown above
         Jq = JLq - 1
      Else
C                         JLq .GE. Nt-1 case:  Keep at least 4 points >= Jq.
        Jq = Nt - 3

      Endif
C                                 This is the interpolation variable in Q
      CALL PHO_POlINT4F (TV(jq), AlsCTEQ(jq), tt, Alsout)
      
      PHO_CT14ALPHAS = Alsout
      
      Return
      End



      SUBROUTINE PHO_CT14GETPARS(xmin,Qini,Qmax,Nloops,Nfl)
c**********************************************************************
c Get various parameters associated with the PDF grid
c Output: xmin  is the minimal value of x 
c         Qmin  is the initial Q scale  
c         Qmax  is the maximal Q scale
c         Nloop is the number of QCD loops
c         Nfl   is the maximal number of quark flavors
c**********************************************************************
      IMPLICIT NONE
      SAVE
      DOUBLE PRECISION QINI0, Qmax0, Xmin0, xmin, Qini, Qmax
      INTEGER Nloops, Ipk, Iorder, Nfl, Nfl0
      DOUBLE PRECISION AlfaQ, Qalfa

      COMMON / XQrange / Qini0, Qmax0, Xmin0
      COMMON / QCDtbl /  AlfaQ, Qalfa, Ipk, Iorder, Nfl0
     
      Qini=Qini0; Qmax=Qmax0; Xmin=Xmin0
      Nloops=Iorder-1; Nfl=Nfl0
      
      return 
      end



      DOUBLE PRECISION FUNCTION PHO_CT14MASS(i)
c**********************************************************************
c     Returns the value of the quark mass for the i-th flavor 
c     The flavors are:
c     1  2  3  4  5  6
c     u  d  s  c  b  t
c**********************************************************************
      IMPLICIT NONE
      SAVE
      DOUBLE PRECISION Amass
      INTEGER  Isetch, ipdsset, i, ipdsformat
      COMMON/Setchange/ Isetch, ipdsset, ipdsformat
     >  / Masstbl / Amass(6)


      if (ipdsset.ne.1) 
     >  STOP 'PHO_CT14MASS: the PDF table was not initialized'

      PHO_CT14MASS = Amass(i)

      RETURN 
      END


C============================================================================
C                CTEQ-TEA Parton Distribution Functions: version 2014
C                       May 14, 2015
C
C   Reference: S. Dulat, T.-J. Hou, J. Gao, M. Guzzi, J. Huston, P. M.
C   Nadolsky, J. Pumplin, C. Schmidt, D. Stump, C.-P. Yuan,  arXiv:
C
C   This package provides a standard interface for CT10 and CT14 
C   parton distribution functions.

C   The following sets of CTEQ PDF table files can be computed 
C    with this program: 
C   (1) 1+50 sets of CT10 NNLO PDF's;
C   (2) 1+52 sets of CT10 NLO PDF's;
C   (3) 4 sets of CT10 NNLO and NLO PDF's with alternative alpha_s values;
C   (4) 1+56 sets of CT14 NNLO PDF's;
C   (5) 1+56 sets of CT14 NLO PDF's;
C   (6) 2 sets of CT14 LO PDF's;

C ===========================================================================
C   The table grids are generated for 
C       10^-9 < x < 1 and 1.3 < Q < 10^5 (GeV).
C
C   PDF values outside of the above range are returned using extrapolation.
C
C   The Table_Files are assumed to be in the working directory.
C
C   Before using the PDF, it is necessary to do the initialization by
C       Call SetCT14(Iset)
C   where Tablefile is a 40-character text string with the name of the
c   the desired PDF specified in the above table.table (.pds) file
C
C   Other provided functions include:
C   The function pho_CT14Pdf (Iparton, X, Q)
C     returns the parton distribution inside the proton for parton [Iparton]
C     at [X] Bjorken_X and scale [Q] (GeV) in PDF set [Iset].
C     Iparton  is the parton label (5, 4, 3, 2, 1, 0, -1, ......, -5)
C                              for (b, c, s, d, u, g, u_bar, ..., b_bar),
C
C   The function CT14Alphas (Q) 
C     returns the value of the QCD coupling strength alpha_s(Q) at
C     an energy scale Q. The alpha_s value is obtained from the interpolation
C     of a numerical table of alpha_s included in each .pds file. 
C     In the PDF fit, the alpha_s values are obtained at each momentum
c     scale by evolution in the HOPPET program at the respective QCD order 
C     (NLO or NNLO). The table of alpha_s values at discrete Q values
C     is included in the input .pds file. The function CT14Alphas
c     estimates alpha_s at an arbitrary Q value, which agrees
c     with the direct evolution by HOPPET within a fraction of percent
c     point at typical Q. 
C 
C   The function CT14Mass(i)
c     returns the value of the quark mass for the i-th flavor.
c     The flavors are:
c     1  2  3  4  5  6
c     u  d  s  c  b  t
c
C   Values of various PDF parameters assumed in the computation of the
c    PDFs can be obtained by 
C     Call CT14GetPars( xmin,Qini,Qmax,Nloops,Nfl), 
C   which returns
c     xmin, the minimal value of x;
c     Qmin,  the initial Q scale for the PDF evolution;  
c     Qmax,  the maximal Q scale included in the PDF table;
c     Nloop, the number of QCD loops (order of the PDF in the QCD coupling);
c     Nfl,   the maximal number of quark flavors assumed in the PDF and 
c            alpha_s evolution.

C   These programs, as provided, are in double precision.  By removing the
C   "Implicit Double Precision" lines, they can also be run in single
C   precision.
C   If you have detailed questions concerning these CT14 distributions,
C   or if you find problems/bugs using this package, direct inquires to
C   nadolsky@physics.smu.edu.
C
C===========================================================================

      FUNCTION PHO_CT14PDF (IPARTON, X, Q)
      IMPLICIT DOUBLE PRECISION (A-H,O-Z)
C  input/output channels
      INTEGER LI,LO ,LPRI
      COMMON /POINOU/ LI,LO ,LPRI
      
      LOGICAL WARN
      INTEGER isetch, ipdsformat
      COMMON
     > / CtqPar2 / Nx, Nt, NfMx, MxVal
     > / QCDtbl /  AlfaQ, Qalfa, Ipk, Iorder, Nfl !for external use
     >  /Setchange/ Isetch, ipdsset, ipdsformat
      SAVE 

      DATA WARN /.true./
      DATA QSML /.3d0/


      if (ipdsset.ne.1) 
     >  STOP 'PHO_CT14PDF: the PDF table was not initialized'

      If (X .lt. 0.d0 .or. X .gt. 1.D0) Then
        IF (LPRI.GT.4)
     &   WRITE(LO,*) 'X out of range in PHO_CT14PDF: ', X
        PHO_CT14PDF = 0.D0
        Return
      Endif

      If (Q .lt. Qsml) Then
        IF (LPRI.GT.4)
     &   WRITE(LO,*) 'Q out of range in PHO_CT14PDF: ', Q, Qsml
        Stop
      Endif

      If (abs(Iparton).gt. NfMx) Then
        If (Warn) Then
C        print a warning for calling extra flavor
          Warn = .false.
          IF (LPRI.GT.4)
     &    WRITE(LO,*) 'Warning: Iparton out of range in pho_CT14Pdf! '
          IF (LPRI.GT.4)
     &    WRITE(LO,*) 'Iparton, MxFlvN0: ', Iparton, NfMx
        Endif
        pho_CT14Pdf = 0D0
      else

        PHO_CT14PDF = PHO_PARTONX12 (IPARTON, X, Q)
        if (PHO_CT14PDF.lt.0D0) PHO_CT14PDF = 0D0
      endif                     !if (abs(Iparton...

      Return

      End


 
 


CDECK  ID>, PHO_DATINI
      SUBROUTINE PHO_DATINI
C*********************************************************************
C
C     initialization of variables and switches
C
C*********************************************************************
      IMPLICIT DOUBLE PRECISION (A-H,O-Z)
      SAVE

C  input/output channels
      INTEGER LI,LO ,LPRI
      COMMON /POINOU/ LI,LO ,LPRI

C  some constants
      DOUBLE PRECISION PI,PI2,PI4,GEV2MB,Q_ch,Q_ch2,Q_ch4
      COMMON /POCONS/ PI,PI2,PI4,GEV2MB,
     &  Q_ch(-6:6),Q_ch2(-6:6),Q_ch4(-6:6)

C  event debugging information
      INTEGER NMAXD
      PARAMETER (NMAXD=100)
      INTEGER IDEB,KSPOM,KHPOM,KSREG,KHDIR,KACCEP,KSTRG,KHTRG,KSLOO,
     &        KHLOO,KSDPO,KHDPO,KEVENT,KSOFT,KHARD
      COMMON /PODEBG/ IDEB(NMAXD),KSPOM,KHPOM,KSREG,KHDIR,KACCEP,KSTRG,
     &                KHTRG,KSLOO,KHLOO,KSDPO,KHDPO,KEVENT,KSOFT,KHARD

C  event weights and generated cross section
      INTEGER IPOWGC,ISWCUT,IVWGHT
      DOUBLE PRECISION SIGGEN,HSWGHT,HSWCUT,EVWGHT
      COMMON /POWGHT/ SIGGEN(4),HSWGHT(0:10),HSWCUT(20),EVWGHT(0:10),
     &                IPOWGC(0:10),ISWCUT(20),IVWGHT(0:10)

C  scale parameters for parton model calculations
      INTEGER NQQAL,NQQALI,NQQALF,NQQPD
      DOUBLE PRECISION AQQAL,AQQALI,AQQALF,AQQPD
      COMMON /POHSCL/ AQQAL,AQQALI,AQQALF,AQQPD,
     &                NQQAL,NQQALI,NQQALF,NQQPD

C  integration precision for hard cross sections (obsolete)
      INTEGER NGAUP1,NGAUP2,NGAUET,NGAUIN,NGAUSO
      COMMON /POGAUP/ NGAUP1,NGAUP2,NGAUET,NGAUIN,NGAUSO

C  hard scattering parameters used for most recent hard interaction
      INTEGER NFbeta,NF
      DOUBLE PRECISION ALQCD2,BQCD
      COMMON /POHAPA/ ALQCD2(3,4),BQCD(4),NFbeta,NF

C  current beam selection
      INTEGER IDXMPAR, MPARMAX, MPARCONF, NMPAR, IKNOWN
      INTEGER MPMAPP, MAXMAPPS, NMAPP, MPAR, IPAVAIL
      DOUBLE PRECISION SQSGLOBMAX
      PARAMETER (MPARMAX=40)
      PARAMETER (MAXMAPPS=40)
      PARAMETER (IKNOWN=9)
      DIMENSION IPAVAIL(IKNOWN)
      DATA IPAVAIL /2212, 211, 111, 22, 2112, 3122, 3112, 321, 311/
      COMMON /POBEAM/ MPARCONF(2, MPARMAX), MPMAPP(2,MAXMAPPS),
     &           MPAR(2), SQSGLOBMAX, NMPAR, IDXMPAR, NMAPP

C  cut probability distribution
      INTEGER IEETA1,IIMAX,KKMAX
      PARAMETER( IEETA1=20, IIMAX=20, KKMAX=500 )
      INTEGER IEEMAX,IMAX,KMAX
      DOUBLE PRECISION EPTAB, PROB
      COMMON /POPROB/ PROB(IEETA1, 0:IIMAX, 0:KKMAX, 4, MPARMAX),
     &          EPTAB(IEETA1, 4, MPARMAX), IEEMAX, IMAX, KMAX

C  gamma-lepton or gamma-hadron vertex information
      INTEGER IGHEL,IDPSRC,IDBSRC
      DOUBLE PRECISION PINI,PFIN,PGAM,GYY,GQ2,GGECM,GAIMP,PFTHE,PFPHI,
     &                 RADSRC,AMSRC,GAMSRC
      COMMON /POFSRC/ PINI(5,2),PFIN(5,2),PGAM(5,2),IGHEL(2),
     &                GYY(2),GQ2(2),GGECM,GAIMP(2),PFTHE(2),PFPHI(2),
     &                IDPSRC(2),IDBSRC(2),RADSRC(2),AMSRC(2),GAMSRC(2)

C  photon flux kinematics and cuts
      DOUBLE PRECISION ECMIN,ECMAX,EEMIN1,EEMIN2,
     &                 YMIN1,YMAX1,YMIN2,YMAX2,
     &                 Q2MIN1,Q2MAX1,Q2MIN2,Q2MAX2,
     &                 THMIN1,THMAX1,THMIN2,THMAX2
      INTEGER          ITAG1,ITAG2
      COMMON /POFCUT/ ECMIN,ECMAX,EEMIN1,EEMIN2,
     &                YMIN1,YMAX1,YMIN2,YMAX2,
     &                Q2MIN1,Q2MAX1,Q2MIN2,Q2MAX2,
     &                THMIN1,THMAX1,THMIN2,THMAX2,
     &                ITAG1,ITAG2

C  obsolete cut-off information
      DOUBLE PRECISION PTCUT,PTANO,FPS,FPH,PSOMIN,XSOMIN
      COMMON /POCUT1/ PTCUT(4),PTANO(4),FPS(4),FPH(4),PSOMIN,XSOMIN

C  global event kinematics and particle IDs
      INTEGER IFPAP,IFPAB
      DOUBLE PRECISION ECM,PCM,PMASS,PVIRT
      COMMON /POGCMS/ ECM,PCM,PMASS(2),PVIRT(2),IFPAP(2),IFPAB(2)

C  nucleon-nucleus / nucleus-nucleus interface to DPMJET
      INTEGER IDEQP,IDEQB,IHFLD,IHFLS
      DOUBLE PRECISION ECMN,PCMN,SECM,SPCM,XPSUB,XTSUB
      COMMON /POHDFL/ ECMN,PCMN,SECM,SPCM,XPSUB,XTSUB,
     &                IDEQP(2),IDEQB(2),IHFLD(2,2),IHFLS(2)

C  some hadron information, will be deleted in future versions
      INTEGER NFS
      DOUBLE PRECISION QMASS,BET,PCOUDI,PNORM,VALPRG
      COMMON /POHDRN/ QMASS(6),BET,PCOUDI,PNORM,VALPRG(2),NFS

C  model switches and parameters
      CHARACTER*8 MDLNA
      INTEGER ISWMDL,IPAMDL
      DOUBLE PRECISION PARMDL
      COMMON /POMDLS/ MDLNA(50),ISWMDL(50),PARMDL(400),IPAMDL(400)

C  general process information
      INTEGER IPROCE,IDNODF,IDIFR1,IDIFR2,IDDPOM,IPRON
      COMMON /POPRCS/ IPROCE,IDNODF,IDIFR1,IDIFR2,IDDPOM,IPRON(15,4)

C  parameters of the "simple" Vector Dominance Model
      DOUBLE PRECISION VMAS,GAMM,RMIN,RMAX,VMSL,VMFA
      COMMON /POSVDM/ VMAS(4),GAMM(4),RMIN(4),RMAX(4),VMSL(4),VMFA(4)

C  parameters for DGLAP backward evolution in ISR
      INTEGER NFSISR
      DOUBLE PRECISION Q2MISR,PMISR,ZMISR,AL2ISR
      COMMON /PODGL1/ Q2MISR(2),PMISR(2),ZMISR(2),AL2ISR(2),NFSISR

C  particles created by initial state evolution
      INTEGER MXISR1,MXISR2
      PARAMETER ( MXISR1 = 150, MXISR2 = 1000 )
      INTEGER IFLISR,IPOISR,IMXISR
      DOUBLE PRECISION PHISR
      COMMON /POPISR/ IFLISR(2,MXISR1),PHISR(2,4,MXISR1),
     &                IPOISR(2,2,MXISR2),IMXISR(2)

C  names of hard scattering processes
      INTEGER Max_pro_1
      PARAMETER ( Max_pro_1 = 16 )
      CHARACTER*18 PROC
      COMMON /POHPRO/ PROC(0:Max_pro_1)

C  hard cross sections and MC selection weights
      INTEGER Max_pro_2
      PARAMETER ( Max_pro_2 = 16 )
      INTEGER IHa_last,IHb_last,MH_pro_on,MH_tried,
     &  MH_acc_1,MH_acc_2
      DOUBLE PRECISION HFAC, HWGX, HSIG, HDPT, HECM_LAST, 
     &   HQ2A_LAST, HQ2B_LAST
      COMMON /POHRCS/HFAC(-1:MAX_PRO_2, MPARMAX), 
     &   HWGX(-1:MAX_PRO_2, MPARMAX),
     &   HSIG(-1:MAX_PRO_2, MPARMAX), HDPT(-1:MAX_PRO_2, MPARMAX), 
     &   HECM_LAST, HQ2A_LAST, HQ2B_LAST, IHA_LAST, IHB_LAST, 
     &   MH_PRO_ON(-1:MAX_PRO_2, 0:4, MPARMAX),
     &   MH_TRIED(-1:MAX_PRO_2, 0:4, MPARMAX), 
     &   MH_ACC_1(-1:MAX_PRO_2, 0:4, MPARMAX),
     &   MH_ACC_2(-1:MAX_PRO_2, 0:4, MPARMAX) 

C  interpolation tables for hard cross section and MC selection weights
      INTEGER Max_tab_E,Max_tab_Q2,Max_pro_tab
      PARAMETER ( Max_tab_E = 20, Max_tab_Q2 = 10, Max_pro_tab = 16 )
      INTEGER IH_Q2a_up,IH_Q2b_up,IH_Ecm_up
      DOUBLE PRECISION Hfac_tab,HWgx_tab,HSig_tab,Hdpt_tab,
     &  HQ2a_tab,HQ2b_tab,HEcm_tab
      COMMON /POHTAB/
     &  Hfac_tab(-1:Max_pro_tab,Max_tab_E,
     &           Max_tab_Q2,Max_tab_Q2,0:4,MPARMAX),
     &  HWgx_tab(-1:Max_pro_tab,Max_tab_E,
     &           Max_tab_Q2,Max_tab_Q2,0:4,MPARMAX),
     &  HSig_tab(-1:Max_pro_tab,Max_tab_E,
     &           Max_tab_Q2,Max_tab_Q2,0:4,MPARMAX),
     &  Hdpt_tab(-1:Max_pro_tab,Max_tab_E,
     &           Max_tab_Q2,Max_tab_Q2,0:4,MPARMAX),
     &  HQ2a_tab(1:Max_tab_Q2,0:4,MPARMAX),
     &  HQ2b_tab(1:Max_tab_Q2,0:4,MPARMAX),
     &  HEcm_tab(1:Max_tab_E,0:4,MPARMAX),
     &  IH_Q2a_up(0:4,MPARMAX),IH_Q2b_up(0:4,MPARMAX),
     &  IH_Ecm_up(0:4,MPARMAX)


C  initialize /POCONS/
      PI   = ATAN(1.D0)*4.D0
      PI2  = 2.D0*PI
      PI4  = 2.D0*PI2
C  GeV**-2 --> millibarn (multiply by GEV2MB to get mb as units)
      GEV2MB = 0.389365D0
C  precalculate quark charges
      do i=1,6
        Q_ch(i) = dble(2-3*mod(i,2))/3.D0
        Q_ch(-i) = -Q_ch(i)

        Q_ch2(i) = Q_ch(i)**2
        Q_ch2(-i) = Q_ch2(i)

        Q_ch4(i) = Q_ch2(i)**2
        Q_ch4(-i) = Q_ch4(i)
      enddo
      Q_ch(0)  = 0.D0
      Q_ch2(0) = 0.D0
      Q_ch4(0) = 0.D0

C  initialize /GLOCMS/
      ECM    = 50.D0
      PMASS(1) = 0.D0
      PVIRT(1) = 0.D0
      PMASS(2) = 0.D0
      PVIRT(2) = 0.D0
      IFPAP(1) = 22
      IFPAP(2) = 22
C  initialize /HADVAL/
      IHFLD(1,1) = 0
      IHFLD(1,2) = 0
      IHFLD(2,1) = 0
      IHFLD(2,2) = 0
      IHFLS(1) = 1
      IHFLS(2) = 1
C  initialize /MODELS/
      ISWMDL(1)  = 3
      MDLNA(1)  = 'AMPL MOD'
      ISWMDL(2)  = 1
      MDLNA(2)  = 'MIN-BIAS'
      ISWMDL(3)  = 1
      MDLNA(3)  = 'PTS DISH'
      ISWMDL(4)  = 1
      MDLNA(4)  = 'PTS DISP'
      ISWMDL(5)  = 2
      MDLNA(5)  = 'PTS ASSI'
      ISWMDL(6)  = 3
      MDLNA(6)  = 'HADRONIZ'
      ISWMDL(7)  = 2
      MDLNA(7)  = 'MASS COR'
      ISWMDL(8)  = 3
      MDLNA(8)  = 'PAR SHOW'
      ISWMDL(9)  = 0
      MDLNA(9)  = 'GLU SPLI'
      ISWMDL(10) = 2
      MDLNA(10) = 'VIRT PHO'
      ISWMDL(11) = 0
      MDLNA(11) = 'LARGE NC'
      ISWMDL(12) = 0
      MDLNA(12) = 'LIPA POM'
      ISWMDL(13) = 1
      MDLNA(13) = 'QELAS VM'
      ISWMDL(14) = 2
      MDLNA(14) = 'ENHA GRA'
      ISWMDL(15) = 4
      MDLNA(15) = 'MULT SCA'
      ISWMDL(16) = 4
      MDLNA(16) = 'MULT DIF'
      ISWMDL(17) = 4
      MDLNA(17) = 'MULT CDF'
      ISWMDL(18) = 0
