      IPAMDL(6)  = 2
C  energy-dependent cutoff for hard scattering
      IPAMDL(7)  = 3
C  intercept used for the calculation of enhanced graphs
      IPAMDL(8)  = 1
C  effective slope of hard scattering amplitde
      IPAMDL(9)  = 3
C  mass dependence of slope parameters
