         X = 0.99D-09
*        STOP
      ENDIF

      Q2 = Q2inp
      IF ( (Q2.LT.0.799D+00) .OR. (Q2.GT.1.D+06) ) THEN
*        WRITE(LO,92) Q2
* 92     FORMAT (2X,'GRV98: Q2 out of range',1p,E12.4)
         Q2 = 0.99D+06
