C     RETURN
* put partons again on mass shell
      XM1 = 0.0D0
      XM2 = 0.0D0
      IF (IMSHL.EQ.1) THEN

         XM1 = PYMASS(IF1)
         XM2 = PYMASS(IF2)

      ENDIF
C     WRITE(6,*)'effect of mashel'
      PPPT=PP(1)**2+PP(2)**2
      PTPT=PT(1)**2+PT(2)**2
