            MINT(22)=IUEDEQ(472)
            MINT(21)=KCS*IUEDEQ(KKFLMI+ABS(MINT(15)))
          ENDIF
          IF(MINT(16).NE.21)THEN
            KCS=SIGN(1,MINT(16))
            MUED(2)=KCS*(KKFLMI+ABS(MINT(16)))
