            MUED(1)=SIGN(1,KCS)*(KKFLMI+4)
            MINT(21)=SIGN(1,KCS)*IUEDEQ(KKFLMI+4)
          ELSE
            MUED(1)=SIGN(1,KCS)*(KKFLMI+5)
            MINT(21)=SIGN(1,KCS)*IUEDEQ(KKFLMI+5)
          ENDIF
          MINT(22)=-MINT(21)
          MUED(2)=-MUED(1)
          KCC=MINT(2)+10
        ELSEIF(ISUB.EQ.315)THEN
C...q + qbar -> q*_D + q*_D_bar, q*_S + q*_S_bar
C...The two channels have the same cross section
          KKFLMI=450
          IF(PYR(0).GT.0.5)KKFLMI=456
          MUED(1)=SIGN(1,MINT(15))*(KKFLMI+ABS(MINT(15)))
          MUED(2)=-MINT(21)
          MINT(21)=SIGN(1,MINT(15))*IUEDEQ(KKFLMI+ABS(MINT(15)))
          MINT(22)=-MINT(21)
          KCC=4
        ELSEIF(ISUB.EQ.316)THEN
