          MUED(2)=SIGN(1,MINT(16))*(450+ABS(MINT(16)))               
          MINT(21)=SIGN(1,MINT(15))*IUEDEQ(456+ABS(MINT(15)))
          MINT(22)=SIGN(1,MINT(16))*IUEDEQ(450+ABS(MINT(16)))
        ELSEIF(ISUB.EQ.319)THEN
