              ELSE
                JS=2
                MINT(21)=KFF2
                MINT(22)=KFF1
              ENDIF
              IF(MCOL.EQ.0) THEN
        
              ELSE
                KCC=4
              ENDIF
            ENDIF
          ELSEIF((ICOL1.EQ.2.AND.(ICOL2.EQ.1.OR.ICOL2.EQ.-1)).OR.
